import React from 'react'
import { getLogger } from '@/lib/logger'
import { eventBus } from '@/lib/eventBus'
import { widgetRegistry } from './widgetRegistry'
import { defaultWidgetBuilder } from '../defaultWidgetBuilder'
import type { MarketData } from '@/types/modules/widget.types'

const logger = getLogger()

const componentCache = new Map<string, React.ComponentType<{ config: unknown; data?: MarketData }>>()

/**
 * WidgetEngine
 */
export class WidgetEngine {
  constructor() {
    logger.info('[WidgetEngine] Initializing...')
  }

  async loadComponent(widgetId: string): Promise<React.ComponentType<{ config: unknown; data?: MarketData }> | null> {
    const startTs = Date.now()
    logger.debug(`[WidgetEngine] loadComponent() called: widgetId="${widgetId}"`)

    const cached = componentCache.get(widgetId)
    if (cached) {
      logger.debug(`[WidgetEngine] loadComponent() cache hit: widgetId="${widgetId}"`)
      return cached
    }

    const template = widgetRegistry.getTemplate(widgetId)
    if (!template) {
      logger.error(`[WidgetEngine] loadComponent failed: Template "${widgetId}" not found`)
      eventBus.emit('WIDGET_LOAD_ERROR', { widgetId, error: 'Template not found' })
      return null
    }

    try {
      logger.debug(`[WidgetEngine] Loading component module: widgetId="${widgetId}"`)
      const module = await template.component()
      const component = module.default as React.ComponentType<{ config: unknown; data?: MarketData }>

      if (component == null) {
        throw new Error(`Widget "${widgetId}" component is empty`)
      }

      // P0-2 全局防御：包裹所有 widget 组件，防止 props 为 null 时解构崩溃
      const SafeWrapper = (props: { config: unknown; data?: MarketData }): React.JSX.Element | null => {
        if (props?.config == null) {
          logger.warn(`[WidgetEngine] Widget "${widgetId}" received null props, rendering fallback`)
          return null
        }
        return React.createElement(component, props)
      }
      SafeWrapper.displayName = `Safe(${component.displayName ?? component.name ?? 'Widget'})`

      componentCache.set(widgetId, SafeWrapper)
      const duration = Date.now() - startTs

      logger.info(`[WidgetEngine] Component loaded: widgetId="${widgetId}", duration=${duration}ms`)
      eventBus.emit('WIDGET_LOAD_SUCCESS', { widgetId })
      return SafeWrapper
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      logger.error(`[WidgetEngine] Failed to load component: widgetId="${widgetId}", error="${errorMsg}"`)
      eventBus.emit('WIDGET_LOAD_ERROR', { widgetId, error: errorMsg })
      throw err
    }
  }

  async mountInstance(instanceId: string): Promise<boolean> {
    const startTs = Date.now()
    logger.debug(`[WidgetEngine] mountInstance() called: instanceId="${instanceId}"`)

    const config = widgetRegistry.getInstance(instanceId)
    if (!config) {
      logger.error(`[WidgetEngine] mountInstance failed: Instance "${instanceId}" not found`)
      return false
    }

    logger.info(`[WidgetEngine] Mounting instance: instanceId="${instanceId}", widgetId="${config.widgetId}"`)
    widgetRegistry.updateRuntimeState(instanceId, { status: 'loading' })
    eventBus.emit('WIDGET_MOUNT_START', { instanceId, widgetId: config.widgetId })

    try {
      const component = await this.loadComponent(config.widgetId)
      if (!component) {
        const errorMsg = `Widget "${config.widgetId}" component not found in registry`
        const fallbackState = defaultWidgetBuilder.buildFallbackRuntimeState(instanceId, config.widgetId, errorMsg)
        widgetRegistry.updateRuntimeState(instanceId, fallbackState)
        logger.error(`[WidgetEngine] Failed to mount instance: instanceId="${instanceId}", error="${errorMsg}"`)
        eventBus.emit('WIDGET_MOUNT_ERROR', { instanceId, widgetId: config.widgetId, error: errorMsg })
        return false
      }
      widgetRegistry.updateRuntimeState(instanceId, { status: 'ready', lastRefresh: Date.now() })

      const duration = Date.now() - startTs
      logger.info(`[WidgetEngine] Instance mounted: instanceId="${instanceId}", duration=${duration}ms`)
      eventBus.emit('WIDGET_MOUNT_SUCCESS', { instanceId, widgetId: config.widgetId })
      return true
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      const fallbackState = defaultWidgetBuilder.buildFallbackRuntimeState(instanceId, config.widgetId, errorMsg)
      widgetRegistry.updateRuntimeState(instanceId, fallbackState)

      logger.error(`[WidgetEngine] Failed to mount instance: instanceId="${instanceId}", error="${errorMsg}"`)
      eventBus.emit('WIDGET_MOUNT_ERROR', { instanceId, widgetId: config.widgetId, error: errorMsg })
      return false
    }
  }

  unmountInstance(instanceId: string): void {
    logger.debug(`[WidgetEngine] unmountInstance() called: instanceId="${instanceId}"`)

    const config = widgetRegistry.getInstance(instanceId)
    widgetRegistry.updateRuntimeState(instanceId, { status: 'idle' })

    logger.info(`[WidgetEngine] Instance unmounted: instanceId="${instanceId}", widgetId="${config?.widgetId}"`)
    eventBus.emit('WIDGET_UNMOUNT', { instanceId, widgetId: config?.widgetId })
  }

  async refreshInstance(instanceId: string): Promise<boolean> {
    const startTs = Date.now()
    logger.debug(`[WidgetEngine] refreshInstance() called: instanceId="${instanceId}"`)

    const config = widgetRegistry.getInstance(instanceId)
    if (!config) {
      logger.error(`[WidgetEngine] refreshInstance failed: Instance "${instanceId}" not found`)
      return false
    }

    logger.info(`[WidgetEngine] Refreshing instance: instanceId="${instanceId}", widgetId="${config.widgetId}"`)
    widgetRegistry.updateRuntimeState(instanceId, { status: 'loading' })
    eventBus.emit('WIDGET_REFRESH_START', { instanceId, widgetId: config.widgetId })

    try {
      const component = await this.loadComponent(config.widgetId)
      if (!component) {
        const errorMsg = `Widget "${config.widgetId}" component not found in registry`
        widgetRegistry.updateRuntimeState(instanceId, { status: 'error', error: errorMsg })
        logger.error(`[WidgetEngine] Failed to refresh instance: instanceId="${instanceId}", error="${errorMsg}"`)
        eventBus.emit('WIDGET_REFRESH_ERROR', { instanceId, widgetId: config.widgetId, error: errorMsg })
        return false
      }
      widgetRegistry.updateRuntimeState(instanceId, { status: 'ready', lastRefresh: Date.now() })

      const duration = Date.now() - startTs
      logger.info(`[WidgetEngine] Instance refreshed: instanceId="${instanceId}", duration=${duration}ms`)
      eventBus.emit('WIDGET_REFRESH_SUCCESS', { instanceId, widgetId: config.widgetId })
      return true
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err)
      widgetRegistry.updateRuntimeState(instanceId, { status: 'error', error: errorMsg })

      logger.error(`[WidgetEngine] Failed to refresh instance: instanceId="${instanceId}", error="${errorMsg}"`)
      eventBus.emit('WIDGET_REFRESH_ERROR', { instanceId, widgetId: config.widgetId, error: errorMsg })
      return false
    }
  }

  preloadComponent(widgetId: string): void {
    if (componentCache.has(widgetId)) {
      logger.debug(`[WidgetEngine] preloadComponent() skipped: widgetId="${widgetId}" already cached`)
      return
    }

    logger.debug(`[WidgetEngine] Preloading component: widgetId="${widgetId}"`)
    this.loadComponent(widgetId).catch((err) => {
      logger.warn(`[WidgetEngine] Preload failed: widgetId="${widgetId}"`, { error: err })
    })
  }

  preloadComponents(widgetIds: string[], concurrent: number = 3): void {
    const pending = widgetIds.filter((id) => !componentCache.has(id))
    if (pending.length === 0) {
      logger.debug('[WidgetEngine] preloadComponents() skipped: all widgets already cached')
      return
    }

    logger.info(`[WidgetEngine] Preloading ${pending.length} components (concurrent=${concurrent})`)

    let index = 0
    const loadNext = () => {
      if (index >= pending.length) return

      const batch = pending.slice(index, index + concurrent)
      index += concurrent

      Promise.all(
        batch.map((widgetId) =>
          this.loadComponent(widgetId).catch((err) => {
            logger.warn(`[WidgetEngine] Preload batch failed: widgetId="${widgetId}"`, { error: err })
            return null
          }),
        ),
      ).then(() => {
        loadNext()
      })
    }

    loadNext()
  }

  clearCache(widgetId?: string): void {
    const id = widgetId ?? ''
    if (id !== '') {
      const existed = componentCache.has(id)
      componentCache.delete(id)
      logger.info(`[WidgetEngine] Cache cleared for: widgetId="${id}", existed=${existed}`)
    } else {
      const prevSize = componentCache.size
      componentCache.clear()
      logger.info(`[WidgetEngine] All cache cleared: ${prevSize} components`)
    }
  }

  getStats() {
    const stats = {
      cachedComponents: componentCache.size,
    }
    logger.debug(`[WidgetEngine] getStats(): ${JSON.stringify(stats)}`)
    return stats
  }
}

/**
 * widgetEngine
 */
export const widgetEngine = new WidgetEngine()

/**
 * @module cockpit/layout/CockpitCrossLayout
 * @description 驾驶舱纵横交叉布局骨架
 *
 * 纵轴（业务域）：research | market | ai | portfolio
 * 横轴（视角）：overview | analysis | signal | risk
 *
 * 引用现有组件：
 * - Tabs / TabsList / TabsTrigger（`@/components/molecules/Tabs`）→ 视角切换
 * - COCKPIT_LAYOUT 间距令牌（`@/constants/cockpit.constants`）
 * - WidgetDomain / WidgetPerspective 类型（`@/types/modules/widget.types`）
 *
 * 设计原则：不重写原子组件，仅做排列组合与重新引用
 */

import { useMemo, useState, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Tabs, TabsList, TabsTrigger } from '@/components/molecules/Tabs'
import { COCKPIT_LAYOUT, COCKPIT_CROSS_DOMAINS, COCKPIT_CROSS_PERSPECTIVES, DRAWER_WIDGETS } from '@/constants/cockpit.constants'
import type { WidgetConfig, WidgetDomain, WidgetPerspective } from '@/types/modules/widget.types'
import { widgetRegistry } from '@/cockpit/core/widgetRegistry'
import { CrossMatrixOverview } from './CrossMatrixOverview'
import { WidgetSheetDrawer } from './WidgetSheetDrawer'

// ============================================================
// 常量定义
// ============================================================

// 业务域/视角展示元数据统一从 cockpit.constants.ts 导入（COCKPIT_CROSS_DOMAINS / COCKPIT_CROSS_PERSPECTIVES），
// 避免与 CrossMatrixOverview 双处定义漂移

// ============================================================
// 组件 Props
// ============================================================

export interface CockpitCrossLayoutProps {
  /** 全部 Widget 实例 */
  instances: WidgetConfig[]
  /** 单个 Widget 渲染回调（由 CockpitShell 传入 WidgetWrapper） */
  renderWidget: (instance: WidgetConfig) => ReactNode
  /** 是否显示矩阵总览首屏（默认 true） */
  showMatrixOverview?: boolean
  /** 矩阵单元格点击回调 */
  onMatrixCellClick?: (domain: WidgetDomain, perspective: WidgetPerspective) => void
  /** 自定义类名 */
  className?: string
}

// ============================================================
// 主组件
// ============================================================

/**
 * CockpitCrossLayout
 *
 * 纵横交叉布局：左轨业务域 × 顶部视角 Tab → 交叉点 Widget 网格
 */
export function CockpitCrossLayout({
  instances,
  renderWidget,
  showMatrixOverview = true,
  onMatrixCellClick,
  className,
}: CockpitCrossLayoutProps) {
  const [activeDomain, setActiveDomain] = useState<WidgetDomain>('market')
  const [activePerspective, setActivePerspective] = useState<WidgetPerspective>('overview')
  const [matrixVisible, setMatrixVisible] = useState(showMatrixOverview)

  /** 从 widgetRegistry 获取每个实例的 domain/perspective 元数据 */
  const instanceMetaMap = useMemo(() => {
    const map = new Map<string, { domain?: WidgetDomain; perspective?: WidgetPerspective }>()
    for (const inst of instances) {
      const template = widgetRegistry.getTemplate(inst.widgetId)
      map.set(inst.instanceId, {
        domain: template?.meta.domain,
        perspective: template?.meta.perspective,
      })
    }
    return map
  }, [instances])

  /** 按域×视角分组的实例计数（用于矩阵总览） */
  const matrixCounts = useMemo(() => {
    const counts = new Map<string, number>()
    for (const inst of instances) {
      const meta = instanceMetaMap.get(inst.instanceId)
      if (meta?.domain && meta?.perspective) {
        const key = `${meta.domain}:${meta.perspective}`
        counts.set(key, (counts.get(key) ?? 0) + 1)
      }
    }
    return counts
  }, [instances, instanceMetaMap])

  /** 按域×视角分组的实例标题（用于矩阵单元格 tooltip 一眼洞悉） */
  const matrixTitles = useMemo(() => {
    const titles = new Map<string, string[]>()
    for (const inst of instances) {
      const meta = instanceMetaMap.get(inst.instanceId)
      if (meta?.domain && meta?.perspective) {
        const key = `${meta.domain}:${meta.perspective}`
        const arr = titles.get(key) ?? []
        arr.push(inst.title)
        titles.set(key, arr)
      }
    }
    return titles
  }, [instances, instanceMetaMap])

  /** 各业务域 Widget 计数（左轨徽标，预计算避免每次 render 重算） */
  const domainCounts = useMemo(() => {
    const counts = new Map<WidgetDomain, number>()
    for (const inst of instances) {
      const meta = instanceMetaMap.get(inst.instanceId)
      if (meta?.domain) {
        counts.set(meta.domain, (counts.get(meta.domain) ?? 0) + 1)
      }
    }
    return counts
  }, [instances, instanceMetaMap])

  /** 当前交叉点的 Widget 实例 */
  const crossInstances = useMemo(() => {
    return instances.filter((inst) => {
      const meta = instanceMetaMap.get(inst.instanceId)
      return meta?.domain === activeDomain && meta?.perspective === activePerspective
    })
  }, [instances, instanceMetaMap, activeDomain, activePerspective])

  /** 抽屉型 Widget（重型 Widget 收为 Sheet 触发卡片） */
  const drawerInstances = useMemo(() => {
    return crossInstances.filter((inst) => DRAWER_WIDGETS.has(inst.widgetId))
  }, [crossInstances])

  /** 网格型 Widget（在网格中直接渲染） */
  const gridInstances = useMemo(() => {
    return crossInstances.filter((inst) => !DRAWER_WIDGETS.has(inst.widgetId))
  }, [crossInstances])

  /** 处理矩阵单元格点击 */
  const handleMatrixClick = (domain: WidgetDomain, perspective: WidgetPerspective) => {
    setActiveDomain(domain)
    setActivePerspective(perspective)
    setMatrixVisible(false)
    onMatrixCellClick?.(domain, perspective)
  }

  return (
    <div className={cn('flex h-full', className)}>
      {/* ───── 左轨：业务域 Rail ───── */}
      <aside
        className="flex w-48 shrink-0 flex-col border-r bg-card/50"
        style={{ paddingTop: COCKPIT_LAYOUT.SECTION_GAP }}
      >
        {/* 矩阵总览切换 */}
        <button
          type="button"
          aria-pressed={matrixVisible}
          onClick={() => setMatrixVisible((v) => !v)}
          className={cn(
            'mx-3 mb-3 rounded-md px-3 py-2 text-left text-xs font-medium transition-colors',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
            matrixVisible
              ? 'bg-primary/10 text-primary'
              : 'text-muted-foreground hover:bg-muted',
          )}
        >
          {matrixVisible ? '◉ 矩阵总览' : '○ 矩阵总览'}
        </button>

        {/* 域列表 */}
        <nav className="flex flex-col gap-1 px-3">
          {COCKPIT_CROSS_DOMAINS.map((domain) => {
            const isActive = activeDomain === domain.id
            const domainCount = domainCounts.get(domain.id) ?? 0

            return (
              <button
                key={domain.id}
                type="button"
                aria-pressed={isActive}
                onClick={() => setActiveDomain(domain.id)}
                className={cn(
                  'flex items-center justify-between rounded-md px-3 py-2.5 text-left text-sm transition-all',
                  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                  isActive
                    ? 'bg-primary text-primary-foreground shadow-sm'
                    : 'text-foreground hover:bg-muted',
                )}
              >
                <span className="flex items-center gap-2">
                  <span className="text-base">{domain.icon}</span>
                  {domain.label}
                </span>
                <span
                  className={cn(
                    'rounded-full px-1.5 py-0.5 text-xs',
                    isActive ? 'bg-primary-foreground/20' : 'bg-muted',
                  )}
                >
                  {domainCount}
                </span>
              </button>
            )
          })}
        </nav>

        {/* 底部说明 */}
        <div className="mt-auto p-3 text-xs text-muted-foreground">
          <p>纵轴：业务域</p>
          <p>横轴：视角</p>
          <p className="mt-1">点击矩阵总览可快速定位</p>
        </div>
      </aside>

      {/* ───── 主内容区 ───── */}
      <div
        className="flex flex-1 flex-col overflow-hidden"
        style={{ paddingLeft: COCKPIT_LAYOUT.ZONE_PADDING }}
      >
        {/* 视角 Tab（横轴） */}
        <Tabs
          value={activePerspective}
          onValueChange={(v) => setActivePerspective(v as WidgetPerspective)}
          className="shrink-0"
        >
          <TabsList className="h-9">
            {COCKPIT_CROSS_PERSPECTIVES.map((p) => {
              const key = `${activeDomain}:${p.id}`
              const count = matrixCounts.get(key) ?? 0
              return (
                <TabsTrigger
                  key={p.id}
                  value={p.id}
                  disabled={count === 0}
                  className="gap-1.5 text-xs"
                >
                  {p.label}
                  {count > 0 && (
                    <span className="rounded-full bg-muted-foreground/20 px-1 text-[10px]">
                      {count}
                    </span>
                  )}
                </TabsTrigger>
              )
            })}
          </TabsList>
        </Tabs>

        {/* 内容区域：矩阵总览 or Widget 网格 */}
        <div
          className="flex-1 overflow-y-auto"
          style={{ paddingTop: COCKPIT_LAYOUT.SECTION_HEADER_GAP }}
        >
          {matrixVisible ? (
            <CrossMatrixOverview
              matrixCounts={matrixCounts}
              matrixTitles={matrixTitles}
              activeDomain={activeDomain}
              activePerspective={activePerspective}
              onCellClick={handleMatrixClick}
            />
          ) : crossInstances.length === 0 ? (
            <div className="flex h-full items-center justify-center text-muted-foreground">
              <div className="text-center">
                <p className="text-lg font-medium">当前交叉点无 Widget</p>
                <p className="mt-1 text-sm">
                  {COCKPIT_CROSS_DOMAINS.find((d) => d.id === activeDomain)?.label} ×{' '}
                  {COCKPIT_CROSS_PERSPECTIVES.find((p) => p.id === activePerspective)?.label}
                </p>
                <button
                  type="button"
                  onClick={() => setMatrixVisible(true)}
                  className="mt-3 text-sm text-primary hover:underline"
                >
                  查看矩阵总览选择其他交叉点
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-3">
              {/* 网格型 Widget */}
              {gridInstances.length > 0 && (
                <div
                  className="grid grid-cols-1 gap-4 lg:grid-cols-2"
                  style={{ gap: COCKPIT_LAYOUT.WIDGET_GAP }}
                >
                  {gridInstances.map((instance) => (
                    <div key={instance.instanceId} className="min-h-0">
                      {renderWidget(instance)}
                    </div>
                  ))}
                </div>
              )}

              {/* 抽屉型 Widget 触发卡片 */}
              {drawerInstances.length > 0 && (
                <div
                  className="grid grid-cols-1 gap-3 sm:grid-cols-2"
                  style={{ gap: COCKPIT_LAYOUT.WIDGET_GAP }}
                >
                  {drawerInstances.map((instance) => (
                    <WidgetSheetDrawer
                      key={instance.instanceId}
                      instance={instance}
                      renderWidget={renderWidget}
                    />
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

/**
 * @module cockpit/layout/CrossMatrixOverview
 * @description 域×视角 热力矩阵总览
 *
 * 首屏渲染 4×4 矩阵，每个单元格显示对应交叉点的 Widget 数量。
 * 点击单元格跳转到该交叉点的 Widget 网格视图。
 *
 * 参照模式：IndustryHeatmap 的密度矩阵渲染（`src/components/chart/industry/IndustryHeatmap.tsx`）
 * 但不直接引用 IndustryHeatmap（数据结构不同），仅借鉴其视觉模式。
 */

import { cn } from '@/lib/utils'
import { COCKPIT_LAYOUT, COCKPIT_CROSS_DOMAINS, COCKPIT_CROSS_PERSPECTIVES } from '@/constants/cockpit.constants'
import type { WidgetDomain, WidgetPerspective } from '@/types/modules/widget.types'

// ============================================================
// 常量
// ============================================================

// 业务域/视角展示元数据统一从 cockpit.constants.ts 导入（COCKPIT_CROSS_DOMAINS / COCKPIT_CROSS_PERSPECTIVES），
// 与 CockpitCrossLayout 共用单一真相源，避免双处定义漂移

// ============================================================
// Props
// ============================================================

export interface CrossMatrixOverviewProps {
  /** 域×视角的 Widget 计数，key 格式: "domain:perspective" */
  matrixCounts: Map<string, number>
  /** 域×视角的 Widget 标题列表，key 格式: "domain:perspective"（用于单元格 tooltip） */
  matrixTitles: Map<string, string[]>
  /** 当前选中的域 */
  activeDomain: WidgetDomain
  /** 当前选中的视角 */
  activePerspective: WidgetPerspective
  /** 单元格点击回调 */
  onCellClick: (domain: WidgetDomain, perspective: WidgetPerspective) => void
}

// ============================================================
// 辅助函数
// ============================================================

/** 根据数量返回单元格颜色深度 */
function getCellIntensity(count: number): string {
  if (count === 0) return 'bg-muted/30 text-muted-foreground/50'
  if (count === 1) return 'bg-primary/20 text-foreground hover:bg-primary/30'
  if (count === 2) return 'bg-primary/40 text-foreground hover:bg-primary/50'
  return 'bg-primary/60 text-primary-foreground hover:bg-primary/70'
}

// ============================================================
// 组件
// ============================================================

/**
 * CrossMatrixOverview
 *
 * 4×4 热力矩阵，行=业务域，列=视角，单元格显示 Widget 数量
 */
export function CrossMatrixOverview({
  matrixCounts,
  matrixTitles,
  activeDomain,
  activePerspective,
  onCellClick,
}: CrossMatrixOverviewProps) {
  const totalWidgets = Array.from(matrixCounts.values()).reduce((a, b) => a + b, 0)
  const activeCells = Array.from(matrixCounts.values()).filter((c) => c > 0).length

  return (
    <div className="mx-auto max-w-4xl">
      {/* 标题栏 */}
      <div className="mb-4 flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold">矩阵总览</h2>
          <p className="text-sm text-muted-foreground">
            {totalWidgets} 个 Widget 分布在 {activeCells} 个交叉点 — 点击任意单元格进入详情
          </p>
        </div>
      </div>

      {/* 矩阵网格 */}
      <div
        className="grid"
        style={{
          gridTemplateColumns: `120px repeat(${COCKPIT_CROSS_PERSPECTIVES.length}, 1fr)`,
          gap: COCKPIT_LAYOUT.MATRIX_CELL_GAP,
        }}
      >
        {/* 表头行 */}
        <div />
        {COCKPIT_CROSS_PERSPECTIVES.map((p) => (
          <div
            key={p.id}
            className={cn(
              'flex items-center justify-center rounded-md py-2 text-xs font-medium',
              activePerspective === p.id
                ? 'bg-primary/10 text-primary'
                : 'bg-muted/50 text-muted-foreground',
            )}
          >
            {p.label}
          </div>
        ))}

        {/* 数据行 */}
        {COCKPIT_CROSS_DOMAINS.map((domain) => (
          <FragmentRow
            key={domain.id}
            domain={domain}
            matrixCounts={matrixCounts}
            matrixTitles={matrixTitles}
            isActiveRow={activeDomain === domain.id}
            activePerspective={activePerspective}
            onCellClick={onCellClick}
          />
        ))}
      </div>

      {/* 图例 */}
      <div className="mt-4 flex items-center gap-4 text-xs text-muted-foreground">
        <span>密度：</span>
        <span className="flex items-center gap-1">
          <span className="h-3 w-3 rounded bg-muted/30" /> 空
        </span>
        <span className="flex items-center gap-1">
          <span className="h-3 w-3 rounded bg-primary/20" /> 1
        </span>
        <span className="flex items-center gap-1">
          <span className="h-3 w-3 rounded bg-primary/40" /> 2
        </span>
        <span className="flex items-center gap-1">
          <span className="h-3 w-3 rounded bg-primary/60" /> 3+
        </span>
      </div>
    </div>
  )
}

// ============================================================
// 子组件：矩阵行
