interface FragmentRowProps {
  domain: { id: WidgetDomain; label: string; icon: string }
  matrixCounts: Map<string, number>
  matrixTitles: Map<string, string[]>
  isActiveRow: boolean
  activePerspective: WidgetPerspective
  onCellClick: (domain: WidgetDomain, perspective: WidgetPerspective) => void
}

function FragmentRow({
  domain,
  matrixCounts,
  matrixTitles,
  isActiveRow,
  activePerspective,
  onCellClick,
}: FragmentRowProps) {
  return (
    <>
      {/* 行标题 */}
      <div
        className={cn(
          'flex items-center gap-1.5 rounded-md px-2 py-3 text-xs font-medium',
          isActiveRow ? 'bg-primary/10 text-primary' : 'bg-muted/50 text-muted-foreground',
        )}
      >
        <span>{domain.icon}</span>
        {domain.label}
      </div>

      {/* 单元格 */}
      {COCKPIT_CROSS_PERSPECTIVES.map((p) => {
        const key = `${domain.id}:${p.id}`
        const count = matrixCounts.get(key) || 0
        const titles = matrixTitles.get(key) ?? []
        const isActiveCell = isActiveRow && activePerspective === p.id
        const tooltip =
          count > 0
            ? `${domain.label} × ${p.label}：${count} 个 Widget\n${titles.join('、')}`
            : `${domain.label} × ${p.label}：暂无 Widget`

        return (
          <button
            key={p.id}
            type="button"
            disabled={count === 0}
            aria-label={`${domain.label} × ${p.label}：${count} 个 Widget`}
            title={tooltip}
            onClick={() => onCellClick(domain.id, p.id)}
            className={cn(
              'flex flex-col items-center justify-center rounded-md py-4 transition-all',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
              getCellIntensity(count),
              isActiveCell && 'ring-2 ring-primary ring-offset-1',
              count > 0 && 'cursor-pointer',
            )}
          >
            <span className="text-lg font-bold">{count}</span>
            <span className="text-[10px]">{count === 0 ? '—' : 'Widget'}</span>
          </button>
        )
      })}
    </>
  )
}

import React, { createContext, useEffect, useRef, useState, useCallback } from 'react'
import { getLogger } from '@/lib/logger'
import type { MarketData, CollectionResultCallback, ChatMessage } from '@/types/modules/widget.types'
import { taskScheduler } from '@/services/data-collector/TaskScheduler'
import { marketDataAdapter } from '@/services/data-collector/MarketDataAdapter'
import { widgetRegistry } from '@/cockpit/core/widgetRegistry'
import { MockStockAnalysisProvider } from '@/services/stock-analysis/mockStockAnalysisProvider'
import { streamingChat } from '@/services/llm/llmGateway'
import type { LlmStreamCallback } from '@/services/llm/llmTypes'
import { nanoid } from 'nanoid'
import {
  ACTIVE_DATA_SOURCE,
  DATA_SOURCE_TYPE,
} from '@/constants/cockpit.constants'
import { useMarketDataStore } from '@/store/marketDataStore'

const logger = getLogger()

interface MarketDataContextValue {
  data: MarketData
  loadingMap: Record<string, boolean>
  errorMap: Record<string, string | null>
  refreshWidget: (instanceId: string) => void
  getTaskStats: () => { total: number; running: number; error: number }
  /** 发送个股/市场分析聊天消息（新增）
   * @remarks 用户主动触发的对话行为，不走轮询 TaskScheduler，直接调用对应 Collector
   */
  sendChatMessage: (target: string, question: string) => Promise<ChatMessage>
}

const MarketDataContext = createContext<MarketDataContextValue | null>(null)

interface MarketDataProviderProps {
  children: React.ReactNode
}

/**
 * MarketDataProvider
 *
 * @convergence 数据流桥接（Phase 1）：
 *   当前 Widget 通过 Context 消费数据，Page 通过 marketDataStore 消费数据。
 *   两条路径独立订阅 taskScheduler，各自维护合并状态。
 *   桥接方案：Provider 适配后同步写入 marketDataStore.mergedData，
 *   使 Page 也能读取 Widget 采集的数据。后续 Phase 2 将 Widget 改为直接从 Store 读取。
 */
export function MarketDataProvider({ children }: MarketDataProviderProps): React.JSX.Element {
  const [data, setData] = useState<MarketData>(() => marketDataAdapter.merge())
  const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({})
  const [errorMap, setErrorMap] = useState<Record<string, string | null>>({})

  const taskMapRef = useRef<Record<string, string>>({})
  const isMountedRef = useRef(false)
  const subscribeRef = useRef<(() => void) | null>(null)

  const updateInstanceStatus = useCallback((instanceId: string | undefined, error: string | null) => {
    const id = instanceId ?? ''
    if (id === '') return
    setErrorMap((prev) => ({ ...prev, [id]: error }))
    setLoadingMap((prev) => ({ ...prev, [id]: false }))
  }, [])

  const handleCollectionResult: CollectionResultCallback = useCallback((taskId, rawData, error) => {
    if (!isMountedRef.current) return

    if (error) {
      const instanceId = Object.entries(taskMapRef.current).find(([, tid]) => tid === taskId)?.[0]
      updateInstanceStatus(instanceId, error.message)
      return
    }

    if (rawData) {
      const instanceId = Object.entries(taskMapRef.current).find(([, tid]) => tid === taskId)?.[0]
      updateInstanceStatus(instanceId, null)

      const adapted = marketDataAdapter.adapt(rawData)
      setData((prev) => marketDataAdapter.merge(prev, adapted))
      // Phase 1 桥接: 同步写入 Store，使 Page 也能读取 Widget 采集的数据
      useMarketDataStore.getState().mergeAdaptedData(adapted)
    }
  }, [updateInstanceStatus])

  useEffect(() => {
    isMountedRef.current = true
    logger.info('[MarketDataProvider] 初始化数据采集...')

    subscribeRef.current = taskScheduler.subscribe(handleCollectionResult)

    const instances = widgetRegistry.getAllInstances()
    logger.info(`[MarketDataProvider] 发现 ${instances.length} 个 Widget 实例`)

    instances.forEach((instance) => {
      const { instanceId, widgetId, dataSource } = instance

      if (dataSource?.enabled !== true) {
        logger.warn(`[MarketDataProvider] Widget ${instanceId} 未配置数据源，跳过`)
        return
      }

      if ((taskMapRef.current[instanceId] ?? '') !== '') {
        logger.warn(`[MarketDataProvider] Widget ${instanceId} 已有采集任务，跳过重复注册`)
        return
      }

      setLoadingMap((prev) => ({ ...prev, [instanceId]: true }))

      const taskId = taskScheduler.registerTask(widgetId, instanceId, dataSource)
      taskMapRef.current[instanceId] = taskId
      void taskScheduler.startTask(taskId)
    })

    return () => {
      logger.info('[MarketDataProvider] 组件卸载，清理数据采集任务...')
      isMountedRef.current = false

      if (subscribeRef.current) {
        subscribeRef.current()
        subscribeRef.current = null
      }

      Object.values(taskMapRef.current).forEach((taskId) => {
        taskScheduler.unregisterTask(taskId)
      })
      taskMapRef.current = {}
    }
  }, [handleCollectionResult])

  const refreshWidget = useCallback((instanceId: string) => {
    const taskId = taskMapRef.current[instanceId]
    if (!taskId || taskId === '') {
      logger.warn(`[MarketDataProvider] 未找到实例 ${instanceId} 对应的任务`)
      return
    }

    setLoadingMap((prev) => ({ ...prev, [instanceId]: true }))
    setErrorMap((prev) => ({ ...prev, [instanceId]: null }))

    void taskScheduler.stopTask(taskId)
    void taskScheduler.startTask(taskId)

    logger.info(`[MarketDataProvider] 手动刷新: ${instanceId}`)
  }, [])

  const getTaskStats = useCallback(() => {
    const tasks = taskScheduler.getAllTasks()
    return {
      total: tasks.length,
      running: tasks.filter((t) => t.status === 'running').length,
      error: tasks.filter((t) => t.status === 'error').length,
    }
  }, [])

  /**
   * 发送聊天消息
   * @description Mock 模式直接调用 MockStockAnalysisProvider；REST 模式使用 SSE 流式 LLM 推理接口
   * @remarks 这是用户主动触发的行为，不经过 TaskScheduler 轮询，返回的 ChatMessage 由 Widget 自行追加到本地会话
   */
  const sendChatMessage = useCallback(async (target: string, question: string): Promise<ChatMessage> => {
    logger.info(`[MarketDataProvider] 发送聊天消息: target=${target}`)

    if (ACTIVE_DATA_SOURCE === DATA_SOURCE_TYPE.MOCK) {
      return MockStockAnalysisProvider.sendChatMessage(target, question)
    }

    const messages = [
      { role: 'system' as const, content: `你是一位专业的股票分析助手，正在分析标的：${target}。请提供详细、专业的分析。` },
      { role: 'user' as const, content: question },
    ]

    let fullContent = ''
    const startTime = Date.now()

    const chunkCallback: LlmStreamCallback = (chunk) => {
      if (!chunk.isDone) {
        fullContent += chunk.content
        logger.debug('[MarketDataProvider] LLM stream chunk received', { length: chunk.content.length, total: fullContent.length })
      }
    }

    try {
      await streamingChat(messages, chunkCallback)
      logger.info('[MarketDataProvider] LLM streaming chat completed', { contentLength: fullContent.length, duration: Date.now() - startTime })
    } catch (err) {
      logger.error('[MarketDataProvider] LLM streaming chat failed', { error: err instanceof Error ? err.message : String(err) })
      throw err
    }

    return {
      id: `assistant_${nanoid(8)}`,
      role: 'assistant',
      content: fullContent,
      timestamp: Date.now(),
    }
  }, [])

  const value: MarketDataContextValue = {
    data,
    loadingMap,
    errorMap,
    refreshWidget,
    getTaskStats,
    sendChatMessage,
  }

  return <MarketDataContext.Provider value={value}>{children}</MarketDataContext.Provider>
}


/**
 * useMarketData
 * @convergence Phase 2: 内部切换为从 marketDataStore 读取，不再依赖 MarketDataProvider Context。
 *   Widget 无需修改 import 路径即可获取 Store 数据。
 * @returns MarketDataContextValue
 */
export function useMarketData(): MarketDataContextValue {
  const mergedData = useMarketDataStore((s) => s.mergedData)
  const loadingMap = useMarketDataStore((s) => s.loadingMap)
  const errorMap = useMarketDataStore((s) => s.errorMap)
  const refreshWidget = useMarketDataStore((s) => s.refreshWidget)
  const getTaskStats = useMarketDataStore((s) => s.getTaskStats)
  const sendChatMessage = useMarketDataStore((s) => s.sendChatMessage)

  return {
    data: mergedData,
    loadingMap,
    errorMap,
    refreshWidget,
    getTaskStats,
    sendChatMessage,
  }
}

/**
 * useOptionalMarketData
 * @convergence Phase 2: 内部切换为从 marketDataStore 读取。
 * @returns MarketDataContextValue | undefined
 */
export function useOptionalMarketData(): MarketDataContextValue | undefined {
  const mergedData = useMarketDataStore((s) => s.mergedData)
  const loadingMap = useMarketDataStore((s) => s.loadingMap)
  const errorMap = useMarketDataStore((s) => s.errorMap)
  const refreshWidget = useMarketDataStore((s) => s.refreshWidget)
  const getTaskStats = useMarketDataStore((s) => s.getTaskStats)
  const sendChatMessage = useMarketDataStore((s) => s.sendChatMessage)

  return {
    data: mergedData,
    loadingMap,
    errorMap,
    refreshWidget,
    getTaskStats,
    sendChatMessage,
  }
}

import React from 'react'
import { ArrowUpCircle, ArrowDownCircle } from 'lucide-react'
import { cn } from '@/lib/utils'
import { WidgetStateShell } from './components/WidgetStateShell'
import { Skeleton } from '@/components/molecules/states'
import type { WidgetConfig, FundFlowData } from '@/types/modules/widget.types'
import { useMarketData } from '@/cockpit/providers/MarketDataProvider'
import { COLOR_TOKENS, STOCK_COLOR_TOKENS } from '@/constants/theme.tokens'

interface FundFlowWidgetProps {
  config: WidgetConfig
}

/**
 * FundFlowWidget
 * @description 资金流向 Widget。数据经 MarketDataProvider 统一采集（fundFlow dataSource），
 * 不再直读 MockMarketDataProvider，保持 cockpit 数据通道单一（与其他 widget 一致）。
 */
export default function FundFlowWidget(props: FundFlowWidgetProps): React.JSX.Element {
  const { data, loadingMap, errorMap, refreshWidget } = useMarketData()
  // 防御性 guard：防止 props 为 null 时解构崩溃（hooks 之后条件返回）
  if (!props?.config) return <div className={cn('p-4 text-sm', 'text-muted-foreground/70')}>配置未就绪</div>
  const { config } = props
  const flows = data.fundFlows
  const loading = loadingMap[config.instanceId] ?? true
  const error = errorMap[config.instanceId]

  // 资金流向图标色（A股惯例：北向资金流入=红涨，流出=绿跌；主力资金=info 蓝）
  const getIcon = (type: FundFlowData['type'], value: number) => {
    if (value > 0) {
      switch (type) {
        case 'main':
          return <ArrowUpCircle className={cn('h-6 w-6', COLOR_TOKENS.info.tailwind)} />
        case 'north':
          return <ArrowUpCircle className={cn('h-6 w-6', STOCK_COLOR_TOKENS.up.tailwind)} />
        default:
          return <ArrowDownCircle className={cn('h-6 w-6', 'text-muted-foreground')} />
      }
    }
    switch (type) {
      case 'main':
        return <ArrowDownCircle className={cn('h-6 w-6', COLOR_TOKENS.info.tailwind)} />
      case 'north':
        return <ArrowDownCircle className={cn('h-6 w-6', STOCK_COLOR_TOKENS.down.tailwind)} />
      default:
        return <ArrowUpCircle className={cn('h-6 w-6', 'text-muted-foreground')} />
    }
  }

  // 资金流向数值色（A股惯例：净流入=红，净流出=绿）
  const getValueColor = (value: number) => {
    return value >= 0 ? STOCK_COLOR_TOKENS.up.tailwind : STOCK_COLOR_TOKENS.down.tailwind
  }

  let visualState: 'ready' | 'loading' | 'empty' | 'error' = 'ready'
  if (error) {
    visualState = 'error'
  } else if (loading) {
    visualState = 'loading'
  } else if (flows.length === 0) {
    visualState = 'empty'
  }

  return (
    <WidgetStateShell
      title={config.title}
      visualState={visualState}
      error={error}
      onRetry={() => refreshWidget(config.instanceId)}
      loadingLabel="加载资金流向…"
      emptyTitle="暂无资金流向数据"
      emptyDescription="当前未获取到主力资金、北向资金等流向数据"
      skeleton={
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="flex items-center gap-4">
              <Skeleton variant="circle" className={cn('h-8 w-8', 'bg-muted')} />
              <div className="flex-1 space-y-2">
                <Skeleton variant="text" className={cn('bg-muted', 'w-24')} />
                <Skeleton variant="text" className={cn('bg-muted', 'h-6 w-16')} />
              </div>
            </div>
          ))}
        </div>
      }
    >
      <div className="space-y-4">
        {flows.map((flow) => (
          <div key={flow.type} className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              {getIcon(flow.type, flow.value)}
              <span className="text-sm font-medium">{flow.name}</span>
            </div>
            <span className={cn('text-lg font-bold', getValueColor(flow.value))}>
              {flow.value >= 0 ? '+' : ''}{flow.value}{flow.unit}
            </span>
          </div>
        ))}
      </div>
    </WidgetStateShell>
  )
}

import { getSafeNumber } from '@/lib/safeCoerce'
import React, { memo } from 'react'
import { Flame, TrendingUp, Smile, Activity, DollarSign, Globe } from 'lucide-react'
