 * @fileoverview 机制健康常驻监控 Widget（桌面板块）
 *
 * 归属：驾驶舱（Cockpit）常驻展示面，对应"桌面板块"的 always-on 状态。
 * 仅从 `mechanismHealthStore` 读数据并触发扫描，不直接跑检测逻辑（分层）。
 * "时刻提醒"通过订阅 eventBus 的 `mechanism:alert` 事件推送全局 Toast（跨切面）。
 *
 * @module cockpit/widgets/MechanismHealthWidget
 */

import React, { useEffect, useState } from 'react'
import { cn } from '@/lib/utils'
import type { WidgetConfig } from '@/types/modules/widget.types'
import {
  useMechanismHealthStore,
} from '@/store/mechanismHealthStore'
import { useToast } from '@/hooks/useToast'
import { eventBus } from '@/lib/eventBus'
import {
  MECHANISM_ALERT_EVENT,
  type MechanismCategory,
  type MechanismHealthSnapshot,
} from '@/services/system/mechanismMonitorService'
import { COLOR_SHADES } from '@/constants/theme.tokens'

interface MechanismHealthWidgetProps {
  config: WidgetConfig
}

const CATEGORY_LABELS: Record<MechanismCategory, string> = {
  sop: 'SOP 自动触发',
  doc: '文档自动更新',
  log: '日志自动更新',
}

const CATEGORY_ORDER: MechanismCategory[] = ['sop', 'doc', 'log']

/**
 * MechanismHealthWidget
 * @param props
 */
export default function MechanismHealthWidget(props: MechanismHealthWidgetProps): React.JSX.Element {
  const latest = useMechanismHealthStore((s) => s.latest)
  const isMonitoring = useMechanismHealthStore((s) => s.isMonitoring)
  const runScan = useMechanismHealthStore((s) => s.runScan)
  const startMonitoring = useMechanismHealthStore((s) => s.startMonitoring)
  const stopMonitoring = useMechanismHealthStore((s) => s.stopMonitoring)
  const { toast } = useToast()
  const [expanded, setExpanded] = useState(false)

  useEffect(() => {
    // 挂载即扫描一次
    runScan()

    // 订阅告警事件 → 全局 Toast（时刻提醒，跨切面）
    const off = eventBus.on(MECHANISM_ALERT_EVENT, (payload) => {
      const snap = payload as MechanismHealthSnapshot
      toast({
        title: '机制健康告警',
        description: `已激活 ${snap.summary.active}/${snap.summary.total}，存在失活机制，建议核查 SOP / 文档 / 日志链路`,
        variant: 'warning',
      })
    })

    return off
  }, [runScan, toast])

  // hooks 调用完毕后再做防御性 guard（遵循现有 Widget 惯例）
  if (!props?.config) {
    return <div className={cn('p-4 text-sm', 'text-muted-foreground/70')}>配置未就绪</div>
  }

  const summary = latest?.summary
  const active = summary?.active ?? 0
  const total = summary?.total ?? 0
  const ratio = summary?.activatedRatio ?? 0
  const allActive = active === total && total > 0

  const headerColor = allActive ? 'text-success' : 'text-warning'
  const headerBg = allActive ? 'bg-success/10' : 'bg-warning/10'

  return (
    <div className="flex flex-col gap-3 p-3">
      {/* 概览头部 */}
      <div className={cn('flex items-center justify-between rounded-lg p-3', headerBg)}>
        <div>
          <div className={cn('text-xs', 'text-muted-foreground')}>机制健康</div>
          <div className={cn('text-2xl font-bold', headerColor)}>
            {active}
            <span className={cn('text-sm font-normal', 'text-muted-foreground/70')}>/{total}</span>
          </div>
        </div>
        <div className="text-right">
          <div className={cn('text-xs', 'text-muted-foreground')}>激活率</div>
          <div className={cn('text-lg font-semibold', headerColor)}>
            {(ratio * 100).toFixed(0)}%
          </div>
        </div>
      </div>

      {/* 分类明细 */}
      <div className="flex flex-col gap-1.5">
        {CATEGORY_ORDER.map((cat) => {
          const stat = summary?.byCategory[cat]
          const catActive = stat?.active ?? 0
          const catTotal = stat?.total ?? 0
          const catOk = catActive === catTotal && catTotal > 0
          return (
            <div
              key={cat}
              className={cn(
                'flex items-center justify-between rounded-md px-2 py-1.5',
                COLOR_SHADES.gray[50],
              )}
            >
              <span className={cn('text-xs', 'text-muted-foreground')}>{CATEGORY_LABELS[cat]}</span>
              <span
                className={cn(
                  'flex items-center gap-1.5 text-xs font-medium',
                  catOk ? 'text-success' : 'text-destructive',
                )}
              >
                <span className={cn('h-2 w-2 rounded-full', catOk ? 'bg-success' : 'bg-destructive')} />
                {catActive}/{catTotal}
              </span>
            </div>
          )
        })}
      </div>

      {/* 控制区 */}
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={() => runScan()}
          className={cn(
            'rounded-md px-2.5 py-1 text-xs font-medium',
            'bg-info/10',
            'text-info',
          )}
        >
          立即扫描
        </button>
        <button
          type="button"
          onClick={() => (isMonitoring ? stopMonitoring() : startMonitoring())}
          className={cn(
            'rounded-md px-2.5 py-1 text-xs font-medium',
            isMonitoring ? 'bg-destructive/10' : 'bg-success/10',
            isMonitoring ? 'text-destructive' : 'text-success',
          )}
        >
          {isMonitoring ? '停止监控' : '开启监控'}
        </button>
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          className={cn('rounded-md px-2.5 py-1 text-xs font-medium', COLOR_SHADES.gray[100], 'text-muted-foreground')}
        >
          {expanded ? '收起' : '明细'}
        </button>
      </div>

      {/* 探针明细 */}
      {expanded && latest && (
        <div className="flex max-h-48 flex-col gap-1 overflow-y-auto">
          {latest.probes.map((p) => (
            <div key={p.id} className="flex items-start justify-between gap-2 text-xs">
              <span className={cn('flex items-center gap-1.5', 'text-muted-foreground')}>
                <span
                  className={cn(
                    'h-1.5 w-1.5 rounded-full',
                    p.status === 'active' ? 'bg-success' : 'bg-destructive',
                  )}
                />
                {p.label}
              </span>
              <span className={p.status === 'active' ? 'text-success' : 'text-destructive'}>
                {p.status === 'active' ? '正常' : '失活'}
              </span>
            </div>
          ))}
        </div>
      )}

      {/* 最后更新时间 */}
      {latest && (
        <div className={cn('text-[10px]', 'text-muted-foreground/70')}>
          最后扫描：{new Date(latest.timestamp).toLocaleTimeString('zh-CN')}
          {isMonitoring && ' · 监控中'}
        </div>
      )}
    </div>
  )
}

import React, { memo, useEffect, useMemo } from 'react'
import { TrendingUp, BarChart3, Calendar } from 'lucide-react'
import { Badge } from '@/components/atoms/Badge'
import { Skeleton } from '@/components/molecules/states'
import type { WidgetConfig } from '@/types/modules/widget.types'
import { getLogger } from '@/lib/logger'
import { useOrderStore, initOrderStoreSubscriptions } from '@/store/orderStore'
import { COLOR_TOKENS, COLOR_SHADES } from '@/constants/theme.tokens'
import { WidgetStateShell } from './components/WidgetStateShell'

const logger = getLogger()

interface PnLAnalysisWidgetProps {
  config: WidgetConfig
}

const PnLAnalysisWidget = memo(function PnLAnalysisWidget({ config }: PnLAnalysisWidgetProps): React.JSX.Element {
  const { orders, tradePairs, pnlSummary, loading, error, refresh } = useOrderStore()

  useEffect(() => {
    let cancelled = false
    logger.info('[PnLAnalysisWidget] 加载盈亏数据')
    const cleanup = initOrderStoreSubscriptions()
    const doRefresh = async () => {
      try {
        await useOrderStore.getState().refresh()
      } catch (err) {
        if (!cancelled) {
          logger.error('[PnLAnalysisWidget] 刷新盈亏数据失败', {
            error: err instanceof Error ? err.message : String(err),
          })
        }
      }
    }
    void doRefresh()
    return () => { cancelled = true; cleanup() }
  }, [])

  // 盈亏曲线最近 20 个点及最大绝对值（避免在 map 内重复计算）
  const dailyCurveSlice = useMemo(
    () => pnlSummary.dailyCurve.slice(-20),
    [pnlSummary.dailyCurve],
  )
  const dailyCurveMaxAbs = useMemo(
    () => Math.max(...dailyCurveSlice.map((p) => Math.abs(p.cumulativePnL)), 1),
    [dailyCurveSlice],
  )

  const visualState = error ? 'error' : loading ? 'loading' : orders.length === 0 || tradePairs.length === 0 ? 'empty' : 'ready'

  return (
    <WidgetStateShell
      title={config.title}
      visualState={visualState}
      error={error}
      onRetry={refresh}
      emptyTitle="暂无盈亏数据"
      emptyDescription="完成交易后将自动生成盈亏分析与收益曲线"
      skeleton={(
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-16" />
            ))}
          </div>
          <Skeleton className="h-32" />
        </div>
      )}
    >
      <div className="space-y-4">
        {/* 核心指标 */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div className={`${COLOR_SHADES.gray[50]} rounded-lg p-3 text-center`}>
            <div className="flex justify-center mb-1">
              <BarChart3 className="h-5 w-5" style={{ color: pnlSummary.totalRealizedPnl >= 0 ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex }} />
            </div>
            <div className="text-xl font-bold" style={{ color: pnlSummary.totalRealizedPnl >= 0 ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex }}>
              {pnlSummary.totalRealizedPnl >= 0 ? '+' : ''}{pnlSummary.totalRealizedPnl}%
            </div>
            <div className={`text-xs ${COLOR_SHADES.gray[400]}`}>总盈亏</div>
          </div>
          <div className={`${COLOR_SHADES.gray[50]} rounded-lg p-3 text-center`}>
            <div className="flex justify-center mb-1">
              <TrendingUp className="h-5 w-5" style={{ color: COLOR_TOKENS.success.hex }} />
            </div>
            <div className="text-xl font-bold" style={{ color: COLOR_TOKENS.success.hex }}>{pnlSummary.winRate}%</div>
            <div className={`text-xs ${COLOR_SHADES.gray[400]}`}>胜率</div>
          </div>
          <div className={`${COLOR_SHADES.gray[50]} rounded-lg p-3 text-center`}>
            <div className="flex justify-center mb-1">
              <TrendingUp className="h-5 w-5 text-warning" />
            </div>
            <div className="text-xl font-bold text-warning">{pnlSummary.profitFactor}</div>
            <div className={`text-xs ${COLOR_SHADES.gray[400]}`}>盈亏比</div>
          </div>
        </div>

        {/* 盈亏曲线（简化柱状图） */}
        <div>
          <h4 className="text-sm font-semibold mb-2 flex items-center gap-1">
            <TrendingUp className="h-4 w-4" /> 盈亏曲线
          </h4>
          <div className="h-24 flex items-end gap-1">
            {dailyCurveSlice.map((point) => {
              const heightPct = Math.abs(point.cumulativePnL) / dailyCurveMaxAbs * 100
              const isPositive = point.cumulativePnL >= 0
              return (
                <div
                  key={point.date}
                  className="flex-1 relative group"
                  title={`${point.date}: ${isPositive ? '+' : ''}${point.cumulativePnL}%`}
                >
                  <div
                    className="absolute bottom-0 w-full rounded-t-sm transition-[height]"
                    style={{
                      height: `${Math.max(heightPct, 4)}%`,
                      backgroundColor: isPositive ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex,
                      opacity: 0.8,
                    }}
                  />
                </div>
              )
            })}
          </div>
        </div>

        {/* 月度盈亏 */}
        <div>
          <h4 className="text-sm font-semibold mb-2 flex items-center gap-1">
            <Calendar className="h-4 w-4" /> 月度盈亏
          </h4>
          <div className="space-y-1 max-h-32 overflow-y-auto">
            {pnlSummary.monthlyPnL.slice(-6).map((month) => (
              <div key={month.month} className="flex items-center justify-between text-xs">
                <span className={COLOR_SHADES.gray[500]}>{month.month}</span>
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="text-xs">{month.trades}笔</Badge>
                  <span
                    className="font-medium"
                    style={{ color: month.pnl >= 0 ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex }}
                  >
                    {month.pnl >= 0 ? '+' : ''}{month.pnl}%
                  </span>
                </div>
              </div>
            ))}
            {pnlSummary.monthlyPnL.length === 0 && (
              <p className={`text-xs ${COLOR_SHADES.gray[400]} text-center`}>暂无月度数据</p>
            )}
          </div>
        </div>

        {/* 交易统计 */}
        <div className={`flex items-center justify-between text-xs ${COLOR_SHADES.gray[500]} ${COLOR_SHADES.gray[50]} rounded-lg p-2`}>
          <span>盈利: <span className={`font-medium ${COLOR_TOKENS.success.tailwind}`}>{pnlSummary.profitTrades}笔</span></span>
          <span>亏损: <span className={`font-medium ${COLOR_TOKENS.danger.tailwind}`}>{pnlSummary.lossTrades}笔</span></span>
          <span>总计: <span className="font-medium">{pnlSummary.totalTrades}笔</span></span>
        </div>
      </div>
    </WidgetStateShell>
  )
})

export default PnLAnalysisWidget

import React from 'react'
import { TrendingUp, Wallet, Target, AlertTriangle, ArrowRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import { computeMaxDrawdown, computeSharpeRatio } from '@/lib/utils/portfolioMetrics'
import { WidgetStateShell } from './components/WidgetStateShell'
import { Skeleton } from '@/components/molecules/states'
import type { WidgetConfig, HoldingItem, RebalancePlanItem } from '@/types/modules/widget.types'
import { useMarketData } from '@/cockpit/providers/MarketDataProvider'
import { COLORS } from '@/constants/cockpit.constants'
import {
  STOCK_COLOR_TOKENS,
  COLOR_TOKENS,
  COLOR_SHADES,
} from '@/constants/theme.tokens'

/** 权重偏离阈值（百分比），超过此值视为需要调整 */
const WEIGHT_DEVIATION_THRESHOLD = 5

interface PortfolioOverviewWidgetProps {
  config: WidgetConfig
}

/** 计算权重偏离状态：overweight（超配）/ underweight（低配）/ balanced（平衡） */
function getWeightStatus(
  weight: number,
  targetWeight: number,
): 'overweight' | 'underweight' | 'balanced' {
  const deviation = weight - targetWeight
  if (deviation > WEIGHT_DEVIATION_THRESHOLD) return 'overweight'
  if (deviation < -WEIGHT_DEVIATION_THRESHOLD) return 'underweight'
  return 'balanced'
}

/** 获取权重显示的颜色令牌 */
function getWeightColorClass(status: 'overweight' | 'underweight' | 'balanced'): string {
  if (status === 'overweight') return 'text-destructive'
  if (status === 'underweight') return 'text-warning'
  return COLOR_SHADES.gray[500]
}

/** 获取再平衡动作的颜色令牌 */
function getActionColorClass(action: RebalancePlanItem['action']): string {
  if (action === 'buy') return STOCK_COLOR_TOKENS.up.tailwind
  if (action === 'sell') return STOCK_COLOR_TOKENS.down.tailwind
  return COLOR_SHADES.gray[500]
}

/** 渲染单个持仓项 */
function HoldingRow({ holding }: { holding: HoldingItem }): React.JSX.Element {
  const weightStatus = getWeightStatus(holding.weight, holding.targetWeight)
  const weightColor = getWeightColorClass(weightStatus)
  const pnlPositive = holding.pnlPercent >= 0

  return (
    <div className={cn('flex items-center justify-between py-2 border-b', 'border-border', 'last:border-0')}>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium truncate">{holding.name}</span>
          <span className={cn('text-xs', COLOR_SHADES.gray[400])}>{holding.symbol}</span>
        </div>
        <div className={cn('text-xs', COLOR_SHADES.gray[500], 'mt-0.5')}>
          {holding.shares}股 · {holding.price} · {holding.marketValue}
        </div>
      </div>
      <div className="flex items-center gap-3">
        <div className="text-right">
          <div className={cn('text-sm', weightColor)}>
            {holding.weight.toFixed(1)}%
            <ArrowRight className={cn('inline h-3 w-3 mx-1', COLOR_SHADES.gray[400])} />
            <span className={COLOR_SHADES.gray[500]}>{holding.targetWeight.toFixed(1)}%</span>
          </div>
          <div className={cn('text-xs', pnlPositive ? STOCK_COLOR_TOKENS.up.tailwind : STOCK_COLOR_TOKENS.down.tailwind)}>
            {holding.pnl} ({pnlPositive ? '+' : ''}{holding.pnlPercent}%)
          </div>
        </div>
      </div>
    </div>
  )
}

/** 渲染再平衡计划项 */
function RebalanceActionRow({ item }: { item: RebalancePlanItem }): React.JSX.Element {
  const actionColor = getActionColorClass(item.action)
  const actionLabel = item.action === 'buy' ? '买入' : item.action === 'sell' ? '卖出' : '持有'

  return (
    <div className="flex items-center justify-between py-1.5 text-sm">
      <div className="flex items-center gap-2">
        <span className={cn('font-medium', actionColor)}>{actionLabel}</span>
        <span className="truncate">{item.name}</span>
        <span className={cn('text-xs', COLOR_SHADES.gray[400])}>{item.symbol}</span>
      </div>
      <div className="flex items-center gap-2">
        <span className={cn('font-medium', actionColor)}>{item.shares}股</span>
        <span className={cn('text-xs', COLOR_SHADES.gray[500], 'truncate max-w-[120px]')} title={item.reason}>
          {item.reason}
        </span>
      </div>
    </div>
  )
}

/**
 * PortfolioOverviewWidget
 */
export default function PortfolioOverviewWidget({ config }: PortfolioOverviewWidgetProps): React.JSX.Element {
  const { data, loadingMap, errorMap, refreshWidget } = useMarketData()
  const portfolio = data?.portfolio
  const loading = loadingMap?.[config.instanceId] ?? true
  const error = errorMap?.[config.instanceId]

  // B1 修复：从真实权益曲线（equityCurve）计算风险指标，缺失时显式标注「数据不足」
  const equityCurve = portfolio?.equityCurve ?? []
  const hasEquityCurve = equityCurve.length >= 2
  const maxDrawdown = hasEquityCurve ? computeMaxDrawdown(equityCurve) : NaN
  const sharpe = hasEquityCurve ? computeSharpeRatio(equityCurve) : NaN

  let visualState: 'ready' | 'loading' | 'empty' | 'error' = 'ready'
  if ((error ?? '') !== '') {
    visualState = 'error'
  } else if ((loading ?? false) === true || portfolio == null) {
    visualState = 'loading'
  }

  return (
    <WidgetStateShell
      title={config.title}
      visualState={visualState}
      error={error}
      onRetry={() => refreshWidget(config.instanceId)}
      loadingLabel="加载持仓数据中…"
      skeleton={
        <div className="space-y-4">
          <Skeleton variant="text" className={cn('bg-muted', 'h-10 w-full')} />
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {[1, 2, 3, 4].map((i) => (
              <div key={i}>
                <Skeleton variant="text" className={cn('bg-muted', 'h-4 w-16')} />
                <Skeleton variant="text" className={cn('bg-muted', 'h-6 w-20 mt-1')} />
              </div>
            ))}
          </div>
        </div>
      }
    >
      {portfolio != null && (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <span className={cn('text-sm', COLOR_SHADES.gray[500])}>总资产</span>
          <span className="text-xl font-bold">{portfolio.totalAssets}</span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <div className="flex items-center gap-2">
              <Wallet className={cn('h-4 w-4', COLOR_SHADES.gray[400])} />
              <span className={cn('text-xs', COLOR_SHADES.gray[400])}>可用资金</span>
            </div>
            <span className="text-lg font-medium">{portfolio.availableFunds}</span>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <Target className={cn('h-4 w-4', COLOR_SHADES.gray[400])} />
              <span className={cn('text-xs', COLOR_SHADES.gray[400])}>持仓</span>
            </div>
            <span className="text-lg font-medium">{portfolio.holdings}只</span>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className={cn('rounded-lg p-3 border', 'bg-success/10')}>
            <div className={cn('text-xs', COLOR_SHADES.gray[500])}>当日盈亏</div>
            <div className="flex items-center gap-1">
              <TrendingUp className="h-4 w-4" style={{ color: COLORS.UP }} />
              <span className="text-lg font-bold" style={{ color: COLORS.UP }}>{portfolio.todayPnL}</span>
            </div>
            <span className="text-sm" style={{ color: COLORS.UP }}>+{portfolio.todayPnLPercent}%</span>
          </div>
          <div className="rounded-lg p-3 bg-card border">
            <div className={cn('text-xs', COLOR_SHADES.gray[500])}>累计盈亏</div>
            <div className="flex items-center gap-1">
              <TrendingUp className={cn('h-4 w-4', COLOR_TOKENS.info.tailwind)} />
              <span className={cn('text-lg font-bold', COLOR_TOKENS.info.tailwind)}>{portfolio.totalPnL}</span>
            </div>
            <span className={cn('text-sm', COLOR_TOKENS.info.tailwind)}>+{portfolio.totalPnLPercent}%</span>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <div className="flex items-center gap-2">
              <AlertTriangle className={cn('h-4 w-4', 'text-destructive')} />
              <span className={cn('text-xs', COLOR_SHADES.gray[400])}>最大回撤</span>
            </div>
            {hasEquityCurve ? (
              <span className="text-lg font-medium" style={{ color: COLORS.DOWN }}>{maxDrawdown.toFixed(1)}%</span>
            ) : (
              <span className={cn('text-sm', COLOR_SHADES.gray[400])}>数据不足</span>
            )}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <TrendingUp className="h-4 w-4" style={{ color: COLORS.UP }} />
              <span className={cn('text-xs', COLOR_SHADES.gray[400])}>夏普比率</span>
            </div>
            {hasEquityCurve ? (
              <span className="text-lg font-medium" style={{ color: COLORS.UP }}>{sharpe.toFixed(2)}</span>
            ) : (
              <span className={cn('text-sm', COLOR_SHADES.gray[400])}>数据不足</span>
            )}
          </div>
        </div>

        {/* 持仓列表 */}
        <div className="pt-2">
          <div className={cn('text-xs font-medium', COLOR_SHADES.gray[500], 'mb-2')}>持仓明细</div>
          {portfolio.holdingsList.length > 0 ? (
            <div data-testid="holdings-list">
              {portfolio.holdingsList.map((holding) => (
                <HoldingRow key={holding.symbol} holding={holding} />
              ))}
            </div>
          ) : (
            <div data-testid="holdings-empty" className={cn('text-center py-4 text-sm', COLOR_SHADES.gray[400])}>
              暂无持仓
            </div>
          )}
        </div>

        {/* 再平衡计划 */}
        <div className="pt-2">
          <div className={cn('text-xs font-medium', COLOR_SHADES.gray[500], 'mb-2')}>再平衡计划</div>
          {portfolio.rebalancePlan.length > 0 ? (
            <div data-testid="rebalance-plan" className="space-y-1">
              {portfolio.rebalancePlan.map((item) => (
                <RebalanceActionRow key={`${item.symbol}-${item.action}`} item={item} />
