  return (
    <WidgetStateShell
      title={config.title}
      visualState={visualState}
      error={error}
      onRetry={() => void refresh()}
      loadingLabel="加载仓位数据中…"
      skeleton={
        <div className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {[1, 2].map((i) => (
              <Skeleton key={i} variant="rect" className={cn('bg-muted', 'h-20')} />
