import React, { memo, useEffect } from 'react'
import { Zap, ArrowUpCircle, ArrowDownCircle, MinusCircle } from 'lucide-react'
import { Badge } from '@/components/atoms/Badge'
import { Skeleton } from '@/components/molecules/states'
import type { WidgetConfig } from '@/types/modules/widget.types'
import { useSignalStore, initSignalStoreSubscriptions } from '@/store/signalStore'
import { THEME_TOKENS, COLOR_TOKENS, STOCK_COLOR_TOKENS } from '@/constants/theme.tokens'
import { getLogger } from '@/lib/logger'
import { WidgetStateShell } from './components/WidgetStateShell'

const logger = getLogger()

interface SignalMonitorWidgetProps {
  config: WidgetConfig
}

const SignalMonitorWidget = memo(function SignalMonitorWidget({ config }: SignalMonitorWidgetProps): React.JSX.Element {
  const { loading, error, refresh, signals: allSignals } = useSignalStore()
  const signals = allSignals.slice(0, 10)

  useEffect(() => {
    let cancelled = false
    const cleanup = initSignalStoreSubscriptions()
    const doRefresh = async () => {
      try {
        await useSignalStore.getState().refresh()
      } catch (err) {
        if (!cancelled) {
          logger.error('[SignalMonitorWidget] 刷新信号数据失败', {
            error: err instanceof Error ? err.message : String(err),
          })
        }
      }
    }
    void doRefresh()
    return () => { cancelled = true; cleanup() }
  }, [])

  const visualState = error ? 'error' : loading ? 'loading' : signals.length === 0 ? 'empty' : 'ready'

  const getSignalIcon = (direction: string) => {
    if (direction === 'buy') return <ArrowUpCircle className={`h-5 w-5 ${COLOR_TOKENS.success.tailwind}`} />
    if (direction === 'sell') return <ArrowDownCircle className={`h-5 w-5 ${COLOR_TOKENS.danger.tailwind}`} />
    return <MinusCircle className="h-5 w-5 text-muted-foreground/70" />
  }

  const getSignalBadge = (direction: string) => {
    if (direction === 'buy') return <Badge className="text-xs" style={{ backgroundColor: THEME_TOKENS.color.successRaw, color: 'white' }}>买入</Badge>
    if (direction === 'sell') return <Badge className="text-xs" style={{ backgroundColor: THEME_TOKENS.color.destructiveRaw, color: 'white' }}>卖出</Badge>
    if (direction === 'hold') return <Badge variant="outline" className={`text-xs ${COLOR_TOKENS.info.tailwind} border-info/30`}>持有</Badge>
    return <Badge variant="outline" className="text-xs text-muted-foreground/70">观望</Badge>
  }

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 80) return COLOR_TOKENS.success.tailwind
    if (confidence >= 60) return COLOR_TOKENS.info.tailwind
    if (confidence >= 40) return COLOR_TOKENS.warning.tailwind
    return 'text-muted-foreground/70'
  }

  return (
    <WidgetStateShell
      title={config.title}
      titleIcon={<Zap className={`h-5 w-5 ${COLOR_TOKENS.warning.tailwind}`} />}
      visualState={visualState}
      error={error}
      onRetry={refresh}
      emptyTitle="暂无交易信号"
      emptyDescription="添加股票到观察池后将自动生成信号"
      skeleton={(
        <div className="space-y-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <Skeleton key={i} className="h-12" />
          ))}
        </div>
      )}
    >
      <div className="space-y-2">
        <div className="space-y-2 max-h-80 overflow-y-auto">
          {signals.map((signal) => (
            <div
              key={signal.symbol}
              className="flex items-center gap-3 bg-muted rounded-lg p-3 hover:bg-muted transition-colors"
            >
              <div className="shrink-0">
                {getSignalIcon(signal.direction)}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-muted-foreground">{signal.symbol}</span>
                    {getSignalBadge(signal.direction)}
                  </div>
                  <span className={`text-xs font-bold ${getConfidenceColor(signal.confidence)}`}>
                    {signal.confidence}
                  </span>
                </div>
                <p className={`text-xs ${COLOR_TOKENS.textMuted.tailwind} mt-0.5 truncate`}>
                  {signal.rationale}
                </p>
                {/* 置信度条 */}
                <div className="w-full bg-muted rounded-full h-1 mt-1.5">
                  <div
                    className="h-1 rounded-full"
                    style={{
                      width: `${signal.confidence}%`,
                      backgroundColor: signal.confidence >= 80
                        ? THEME_TOKENS.color.successRaw
                        : signal.confidence >= 60
                          ? THEME_TOKENS.color.infoRaw
                          : signal.confidence >= 40
                            ? THEME_TOKENS.color.warningRaw
                            : THEME_TOKENS.color.mutedRaw,
                    }}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* 信号统计 */}
        {signals.length > 0 && (
          <div className="flex items-center justify-between text-xs text-muted-foreground pt-2 border-t">
            <span>
              买入: <span className={`font-medium ${STOCK_COLOR_TOKENS.up.tailwind}`}>{signals.filter((s) => s.direction === 'buy').length}</span>
            </span>
            <span>
              卖出: <span className={`font-medium ${STOCK_COLOR_TOKENS.down.tailwind}`}>{signals.filter((s) => s.direction === 'sell').length}</span>
            </span>
            <span>
              持有/观望: <span className="font-medium text-muted-foreground">{signals.filter((s) => s.direction === 'hold' || s.direction === 'watch').length}</span>
            </span>
          </div>
        )}
      </div>
    </WidgetStateShell>
  )
})

export default SignalMonitorWidget

import React, { useEffect, useRef, useState } from 'react'
import { Send, Trash2 } from 'lucide-react'
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '@/components/atoms/Card'
import { Button } from '@/components/atoms/Button'
import { Select, SelectItem } from '@/components/atoms/Select'
import { Textarea } from '@/components/atoms/Textarea'
import { useMarketData } from '@/cockpit/providers/MarketDataProvider'
import type { WidgetConfig, MarketData, ChatMessage } from '@/types/modules/widget.types'
import { CHAT_DEMO_TARGETS, AI_DISCLAIMER_TEXT } from '@/constants/cockpit.constants'

import { nanoid } from 'nanoid'
interface StockChatWidgetProps {
  config: WidgetConfig
  data?: MarketData
}

/**
 * 轻量级 Markdown 渲染器
 * @description 支持标题、加粗、列表、代码块、引用、段落；未来可替换为 react-markdown
 * @remarks 禁止在组件中硬编码任何样式颜色
 */
function MarkdownRenderer({ content }: { content: string }): React.JSX.Element {
  const lines = content.split('\n')
  const elements: React.ReactNode[] = []
  let listBuffer: React.ReactNode[] | null = null
  let listOrdered = false

  const flushList = () => {
    if (!listBuffer || listBuffer.length === 0) return
    const ListTag = listOrdered ? 'ol' : 'ul'
    elements.push(
      <ListTag key={`list-${elements.length}`} className="list-inside pl-2 my-2 text-sm">
        {listBuffer}
      </ListTag>
    )
    listBuffer = null
    listOrdered = false
  }

  lines.forEach((rawLine, index) => {
    const line = rawLine.trimEnd()

    // 代码块
    if (line.startsWith('```')) {
      flushList()
      const codeLines: string[] = []
      let j = index + 1
      while (j < lines.length && !lines[j]?.trim().startsWith('```')) {
        codeLines.push(lines[j] ?? '')
        j++
      }
      elements.push(
        <pre key={`code-${index}`} className="bg-muted rounded-md p-2 my-2 text-xs overflow-auto">
          <code>{codeLines.join('\n')}</code>
        </pre>
      )
      return
    }

    // 标题
    const headerMatch = line.match(/^(#{1,3})\s+(.*)$/)
    if (headerMatch) {
      flushList()
      const level = headerMatch[1]!.length
      const text = headerMatch[2]!
      const Tag = `h${level}` as 'h1' | 'h2' | 'h3'
      const sizeClass = level === 1 ? 'text-base' : level === 2 ? 'text-sm' : 'text-xs'
      elements.push(
        <Tag key={`h-${index}`} className={`font-bold mt-3 mb-1 ${sizeClass}`}>
          {renderInline(text)}
        </Tag>
      )
      return
    }

    // 无序列表
    const ulMatch = line.match(/^[-*]\s+(.*)$/)
    if (ulMatch) {
      if (!listBuffer || listOrdered) flushList()
      listBuffer ??= []
      listOrdered = false
      listBuffer.push(<li key={`li-${index}`}>{renderInline(ulMatch[1]!)}</li>)
      return
    }

    // 有序列表
    const olMatch = line.match(/^\d+\.\s+(.*)$/)
    if (olMatch) {
      if (!listBuffer || !listOrdered) flushList()
      listBuffer ??= []
      listOrdered = true
      listBuffer.push(<li key={`li-${index}`}>{renderInline(olMatch[1]!)}</li>)
      return
    }

    // 空行
    if (line.trim() === '') {
      flushList()
      return
    }

    // 引用
    if (line.startsWith('>')) {
      flushList()
      elements.push(
        <blockquote key={`quote-${index}`} className="border-l-2 border-muted-foreground pl-3 my-2 text-xs text-muted-foreground">
          {renderInline(line.slice(1).trim())}
        </blockquote>
      )
      return
    }

    // 普通段落
    flushList()
    elements.push(
      <p key={`p-${index}`} className="text-sm my-1 leading-relaxed">
        {renderInline(line)}
      </p>
    )
  })

  flushList()
  return <div className="markdown-body">{elements}</div>
}

function renderInlineToken(token: string, key: number): React.ReactNode {
  if (token.startsWith('**') && token.endsWith('**')) {
    return <strong key={key}>{token.slice(2, -2)}</strong>
  }
  if (token.startsWith('*') && token.endsWith('*')) {
    return <em key={key}>{token.slice(1, -1)}</em>
  }
  if (token.startsWith('`') && token.endsWith('`')) {
    return (
      <code key={key} className="bg-muted px-1 rounded text-xs">
        {token.slice(1, -1)}
      </code>
    )
  }
  return token
}

/**
 * 行内 Markdown 渲染（加粗、斜体、行内代码）
 */
function renderInline(text: string): React.ReactNode {
  const parts: React.ReactNode[] = []
  const regex = /(\*\*.*?\*\*|\*.*?\*|`.*?`)/g
  let lastIndex = 0
  let match: RegExpExecArray | null

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      parts.push(text.slice(lastIndex, match.index))
    }

    parts.push(renderInlineToken(match[0], match.index))
    lastIndex = regex.lastIndex
  }

  if (lastIndex < text.length) {
    parts.push(text.slice(lastIndex))
  }

  return parts
}

/**
 * 个股深度分析与市场分析聊天 Widget
 * @description 类似 ChatGPT 的交互界面，支持选择标的、清空上下文、发送问题并渲染 Markdown 回复
 * @remarks 历史数据来自 MarketData.chatHistory；发送消息通过 MarketDataProvider.sendChatMessage
 */
export default function StockChatWidget({ config, data }: StockChatWidgetProps): React.JSX.Element {
  const marketData = useMarketData()
  const sourceData = data ?? marketData.data
  const initialChat = sourceData.chatHistory

  const [target, setTarget] = useState(initialChat.target || CHAT_DEMO_TARGETS[0]!.code)
  const [messages, setMessages] = useState<ChatMessage[]>(initialChat.messages)
  const [input, setInput] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' })
  }, [messages])

  const handleClear = () => {
    setMessages([])
  }

  const handleSend = async () => {
    if (!input.trim() || isLoading) return

    const userMessage: ChatMessage = {
      id: `user_${nanoid(8)}`,
      role: 'user',
      content: input.trim(),
      timestamp: Date.now(),
    }

    setMessages((prev) => [...prev, userMessage])
    setInput('')
    setIsLoading(true)

    try {
      // 通过 MarketDataProvider 统一发送，避免组件直接调用后端
      const reply = await marketData.sendChatMessage(target, userMessage.content)
      setMessages((prev) => [...prev, reply])
    } catch {
      setMessages((prev) => [
        ...prev,
        {
          id: `error_${nanoid(8)}`,
          role: 'assistant',
          content: '消息发送失败，请稍后重试。',
          timestamp: Date.now(),
        },
      ])
    } finally {
      setIsLoading(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      void handleSend()
    }
  }

  return (
    <Card className="h-full flex flex-col">
      <CardHeader className="pb-3 flex flex-row items-center justify-between">
        <CardTitle className="text-base font-semibold">{config.title}</CardTitle>
        <div className="flex items-center gap-2">
          <Select value={target} onChange={(e) => setTarget(e.target.value)} className="w-48 text-xs">
            {CHAT_DEMO_TARGETS.map((item) => (
              <SelectItem key={item.code} value={item.code}>
                {item.name} ({item.type === 'market' ? '市场' : item.code})
              </SelectItem>
            ))}
          </Select>
          <Button variant="ghost" size="sm" onClick={handleClear} title="清空上下文">
            <Trash2 className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="flex-1 overflow-hidden">
        <div
          ref={scrollRef}
          className="h-full overflow-y-auto space-y-4 pr-2"
        >
          {messages.length === 0 && (
            <div className="text-center text-sm text-muted-foreground py-8">
              请选择标的并输入问题，开始个股/市场深度分析
            </div>
          )}
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[80%] rounded-lg px-4 py-2 text-sm ${
                  msg.role === 'user'
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted'
                }`}
              >
                {msg.role === 'assistant' ? (
                  <MarkdownRenderer content={msg.content} />
                ) : (
                  <p className="whitespace-pre-wrap">{msg.content}</p>
                )}
                <div className="text-[10px] opacity-60 mt-1 text-right">
                  {new Date(msg.timestamp).toLocaleTimeString()}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-muted rounded-lg px-4 py-2 text-sm">
                <span className="animate-pulse">AI 正在分析...</span>
              </div>
            </div>
          )}
        </div>
      </CardContent>

      <CardFooter className="pt-0 flex flex-col gap-2">
        <p className="text-[11px] leading-tight text-muted-foreground w-full">
          {AI_DISCLAIMER_TEXT}
        </p>
        <div className="flex w-full items-start gap-2">
          <Textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="输入个股深度分析的问题，或输入市场分析的问题..."
            className="min-h-[56px] flex-1 resize-none"
            disabled={isLoading}
          />
          <Button size="sm" onClick={() => void handleSend()} disabled={isLoading || !input.trim()} className="h-14 px-4">
            <Send className="h-4 w-4" />
          </Button>
        </div>
      </CardFooter>
    </Card>
  )
}

/**
 * Button 组件单元测试
 *
 * 覆盖场景：
 * 1. 默认渲染：使用 primary variant + md size
 * 2. 6 种 variant 样式生效
 * 3. 3 种 size 样式生效
 * 4. asChild 透传 children className/ref
 * 5. click 事件冒泡
 * 6. disabled 状态
 * 7. ref 转发
 * 8. 自定义 className 合并
 * 9. isLoading 状态
 */

import { describe, expect, it, vi } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { createRef } from 'react'
import { Button } from '@/components/atoms/Button'

describe('Button', () => {
  it('默认渲染：primary variant + md size', () => {
    render(<Button>点击</Button>)
    const btn = screen.getByRole('button', { name: '点击' })
    expect(btn).toBeInTheDocument()
    expect(btn).toHaveClass('bg-primary')
    expect(btn).toHaveClass('h-10')
  })

  it('variant=secondary 应用 secondary 样式', () => {
    render(<Button variant="secondary">次要</Button>)
    expect(screen.getByRole('button')).toHaveClass('bg-secondary')
  })

  it('variant=outline 应用 outline 样式', () => {
    render(<Button variant="outline">轮廓</Button>)
    expect(screen.getByRole('button')).toHaveClass('border')
  })

  it('variant=ghost 应用 ghost 样式', () => {
    render(<Button variant="ghost">幽灵</Button>)
    expect(screen.getByRole('button')).toHaveClass('hover:bg-accent')
  })

  it('variant=danger 应用主题感知的 destructive 语义令牌', () => {
    render(<Button variant="danger">危险</Button>)
    // 迁移后：改用语义令牌 bg-destructive + text-destructive-foreground（明暗一致）
    const btn = screen.getByRole('button')
    expect(btn).toHaveClass('bg-destructive')
    expect(btn).toHaveClass('text-destructive-foreground')
  })

  it('variant=success 应用主题感知的 success 语义令牌', () => {
    render(<Button variant="success">成功</Button>)
    // 迁移后：改用语义令牌 bg-success + text-success-foreground（明暗一致）
    const btn = screen.getByRole('button')
    expect(btn).toHaveClass('bg-success')
    expect(btn).toHaveClass('text-success-foreground')
  })

  it('size=sm 应用 sm 样式', () => {
    render(<Button size="sm">小</Button>)
    expect(screen.getByRole('button')).toHaveClass('h-8')
  })

  it('size=md 应用 md 样式', () => {
    render(<Button size="md">中</Button>)
    expect(screen.getByRole('button')).toHaveClass('h-10')
  })

  it('size=lg 应用 lg 样式', () => {
    render(<Button size="lg">大</Button>)
    expect(screen.getByRole('button')).toHaveClass('h-12')
  })

  it('asChild=true 时透传 children className/ref/事件', () => {
    const handleClick = vi.fn()
    const ref = createRef<HTMLAnchorElement>()
    render(
      // asChild 时 Button 实际渲染 children，ref 指向 anchor
      <Button asChild variant="primary" size="md" onClick={handleClick} ref={ref as any}>
        <a href="/test" className="custom-link">
          链接
        </a>
      </Button>,
    )
    const anchor = screen.getByText('链接')
    expect(anchor.tagName).toBe('A')
    // Button 的 className 应合并到 a 上
    expect(anchor).toHaveClass('bg-primary')
    expect(anchor).toHaveClass('custom-link')
    expect(anchor).toHaveAttribute('href', '/test')
    // ref 应当指向 anchor
    expect(ref.current).toBeInstanceOf(HTMLAnchorElement)
    // onClick 应当透传
    fireEvent.click(anchor)
    expect(handleClick).toHaveBeenCalledTimes(1)
  })

  it('asChild=true 但 children 不是 element 时仍渲染 button', () => {
    render(
      <Button asChild>
        plain text
      </Button>,
    )
    // 当 children 不是 valid element 时，仍然渲染 button
    expect(screen.getByRole('button')).toBeInTheDocument()
  })

  it('disabled 时不可点击并应用 disabled 样式', () => {
    const handleClick = vi.fn()
    render(
      <Button disabled onClick={handleClick}>
        禁用
      </Button>,
    )
    const btn = screen.getByRole('button')
    expect(btn).toBeDisabled()
    expect(btn).toHaveClass('disabled:opacity-50')
    fireEvent.click(btn)
    expect(handleClick).not.toHaveBeenCalled()
  })

  it('普通模式触发 onClick 事件', () => {
    const handleClick = vi.fn()
    render(<Button onClick={handleClick}>触发</Button>)
    fireEvent.click(screen.getByRole('button'))
    expect(handleClick).toHaveBeenCalledTimes(1)
  })

  it('自定义 className 与默认 className 合并', () => {
    render(<Button className="my-custom">自定义</Button>)
    const btn = screen.getByRole('button')
    expect(btn).toHaveClass('my-custom')
    expect(btn).toHaveClass('inline-flex') // 默认 class 仍存在
  })

  it('额外 props（如 type、aria-label）正确透传', () => {
    render(
      <Button type="submit" aria-label="提交按钮">
        提交
      </Button>,
    )
    const btn = screen.getByRole('button')
    expect(btn).toHaveAttribute('type', 'submit')
    expect(btn).toHaveAttribute('aria-label', '提交按钮')
  })

  it('ref 正确转发到 button 元素', () => {
    const ref = createRef<HTMLButtonElement>()
    render(<Button ref={ref}>ref 测试</Button>)
    expect(ref.current).toBeInstanceOf(HTMLButtonElement)
  })

  it('isLoading 时显示加载状态', () => {
    render(<Button isLoading>加载中</Button>)
    const btn = screen.getByRole('button')
    // isLoading 只是透传到 button 元素，不会自动设置 disabled
    expect(btn).toBeInTheDocument()
    expect(btn).toHaveTextContent('加载中')
  })
})

import {
  forwardRef,
  memo,
  useEffect,
  useRef,
  useCallback,
} from 'react'
import {
  createSeriesMarkers,
  type IChartApi,
  type ISeriesApi,
  type ISeriesMarkersPluginApi,
  type SeriesMarker,
  type Time,
} from 'lightweight-charts'
import { CHART_PALETTE_PRO, STOCK_COLOR_TOKENS } from '@/constants/theme.tokens'
import { KDJ_COLORS } from './indicators/kdj'
import { MACD_COLORS } from './indicators/macd'
import { RSI_COLORS } from './indicators/rsi'
import type { KDJResult } from './indicators/kdj'
import type { MACDResult } from './indicators/macd'
import type { RSIResult } from './indicators/rsi'
import { getLogger } from '@/lib/logger'
import type { TooltipData, ChartTooltipProps, MultiPaneChartProps } from './multiPaneChart.types'
import { PERIOD_OPTIONS, ADJUST_OPTIONS } from './multiPaneChart.config'
import {
  buildTooltipValuesHtml,
  createMainChartPane,
  createMacdChartPane,
  createKdjChartPane,
  createRsiChartPane,
  createCrosshairHandler,
  syncTimeScales,
} from './multiPaneChart.utils'

const logger = getLogger()

/** 独立的 Tooltip 组件（使用 React.memo 优化） */
const ChartTooltip = memo<ChartTooltipProps>(({ data, positiveColor, negativeColor }) => {
  if ((data?.visible ?? false) !== true) return null
  const d = data!

  return (
    <div
      style={{
        position: 'absolute',
        top: 8,
        right: 8,
        zIndex: 6,
        minWidth: 150,
        padding: '8px 10px',
        borderRadius: '8px',
        background: 'rgba(19,23,34,0.88)',
        backdropFilter: 'blur(6px)',
        border: `1px solid ${CHART_PALETTE_PRO.grid}`,
        boxShadow: '0 4px 16px rgba(0,0,0,0.35)',
        fontSize: '0.74rem',
        fontFeatureSettings: 'tnum',
        color: CHART_PALETTE_PRO.axis,
        pointerEvents: 'none',
      }}
    >
      <div style={{ fontWeight: 600, marginBottom: 4, color: CHART_PALETTE_PRO.contrast }}>
        {d.time}
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '2px 10px' }}>
        <span style={{ color: CHART_PALETTE_PRO.axis }}>开</span>
        <span style={{ textAlign: 'right' }}>{d.open.toFixed(2)}</span>
        <span style={{ color: CHART_PALETTE_PRO.axis }}>高</span>
        <span style={{ textAlign: 'right' }}>{d.high.toFixed(2)}</span>
        <span style={{ color: CHART_PALETTE_PRO.axis }}>低</span>
        <span style={{ textAlign: 'right' }}>{d.low.toFixed(2)}</span>
        <span style={{ color: CHART_PALETTE_PRO.axis }}>收</span>
        <span style={{ textAlign: 'right', fontWeight: 600, color: d.close >= d.open ? positiveColor : negativeColor }}>
          {d.close.toFixed(2)}
        </span>
        {d.volume !== undefined && (
          <>
            <span style={{ color: CHART_PALETTE_PRO.axis }}>量</span>
            <span style={{ textAlign: 'right' }}>{d.volume.toLocaleString('zh-CN')}</span>
          </>
        )}
        {d.macd && (
          <>
            <span style={{ color: MACD_COLORS.dif }}>DIF</span>
            <span style={{ textAlign: 'right' }}>{d.macd.dif.toFixed(3)}</span>
            <span style={{ color: MACD_COLORS.dea }}>DEA</span>
            <span style={{ textAlign: 'right' }}>{d.macd.dea.toFixed(3)}</span>
            <span style={{ color: d.macd.histogram >= 0 ? STOCK_COLOR_TOKENS.up.hex : STOCK_COLOR_TOKENS.down.hex }}>MACD</span>
            <span style={{ textAlign: 'right' }}>{d.macd.histogram.toFixed(3)}</span>
          </>
        )}
        {d.kdj && (
          <>
            <span style={{ color: KDJ_COLORS.k }}>K</span>
            <span style={{ textAlign: 'right' }}>{d.kdj.k.toFixed(2)}</span>
            <span style={{ color: KDJ_COLORS.d }}>D</span>
            <span style={{ textAlign: 'right' }}>{d.kdj.d.toFixed(2)}</span>
            <span style={{ color: KDJ_COLORS.j }}>J</span>
            <span style={{ textAlign: 'right' }}>{d.kdj.j.toFixed(2)}</span>
          </>
        )}
        {d.rsi !== undefined && (() => {
          const rsiColor = d.rsi >= 70 ? RSI_COLORS.overbought : d.rsi <= 30 ? RSI_COLORS.oversold : RSI_COLORS.line
          return (
            <>
              <span style={{ color: rsiColor }}>RSI</span>
              <span style={{ textAlign: 'right', fontWeight: 600, color: rsiColor }}>{d.rsi.toFixed(1)}</span>
            </>
          )
        })()}
      </div>
    </div>
  )
})

ChartTooltip.displayName = 'ChartTooltip'

const MultiPaneChart = forwardRef<HTMLDivElement, MultiPaneChartProps>(
  (
    {
      data,
      height = 600,
      upColor,
      downColor,
      markers,
      showToolbar = false,
      showMACD = false,
      showKDJ = false,
      showRSI = false,
      macdParams,
      kdjParams,
      rsiParams,
      period = 'daily',
      adjust = 'qfq',
      onPeriodChange,
      onAdjustChange,
      ...divProps
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const mainChartRef = useRef<IChartApi | null>(null)
    const macdChartRef = useRef<IChartApi | null>(null)
    const kdjChartRef = useRef<IChartApi | null>(null)
    const rsiChartRef = useRef<IChartApi | null>(null)

    const mainSeriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null)
    const mainMarkersRef = useRef<ISeriesMarkersPluginApi<Time> | null>(null)
    const maSeriesRefs = useRef<Array<ISeriesApi<'Line'> | null>>([])

    const macdResultRef = useRef<MACDResult | null>(null)
    const kdjResultRef = useRef<KDJResult | null>(null)
    const rsiResultRef = useRef<RSIResult | null>(null)

    const positiveColor = upColor ?? CHART_PALETTE_PRO.upColor
    const negativeColor = downColor ?? CHART_PALETTE_PRO.downColor

    // 使用 ref 存储 tooltip 数据，避免 React 重渲染
    const tooltipRef = useRef<TooltipData | null>(null)
    const tooltipElementRef = useRef<HTMLDivElement | null>(null)

    // 直接操作 DOM 更新 tooltip，不触发 React re-render
    const updateTooltip = useCallback((data: TooltipData | null) => {
      tooltipRef.current = data
      const el = tooltipElementRef.current
      if (!el) return

      if ((data?.visible ?? false) !== true) {
        el.style.display = 'none'
        return
      }

      const d = data!
      el.style.display = 'block'
      // 更新内容
      const timeEl = el.querySelector('[data-tooltip-time]')
      if (timeEl) timeEl.textContent = d.time

      const valuesEl = el.querySelector('[data-tooltip-values]')
      if (valuesEl) {
        valuesEl.innerHTML = buildTooltipValuesHtml(d, positiveColor, negativeColor)
      }
    }, [positiveColor, negativeColor])

    const isDailyPeriod = period === 'daily' || period === 'weekly' || period === 'monthly'

    // 计算各 pane 高度
    const toolbarHeight = showToolbar ? 40 : 0
    const availableHeight = height - toolbarHeight
    const subPaneCount = (showMACD ? 1 : 0) + (showKDJ ? 1 : 0) + (showRSI ? 1 : 0)
    const mainPaneRatio = subPaneCount > 0 ? 0.55 : 1
    const subPaneRatio = subPaneCount > 0 ? (1 - mainPaneRatio) / subPaneCount : 0
    const mainPaneHeight = Math.floor(availableHeight * mainPaneRatio)
    const subPaneHeight = Math.floor(availableHeight * subPaneRatio)

    useEffect(() => {
      if (!containerRef.current) return

      logger.info('[MultiPaneChart] 初始化多窗格图表', {
        showMACD,
        showKDJ,
        dataLength: data.length,
      })

      // ===== 主 K 线图 =====
      const mainPane = createMainChartPane(
        containerRef.current, mainPaneHeight, data, positiveColor, negativeColor,
      )
      const { mainChart, mainSeries } = mainPane
      maSeriesRefs.current = mainPane.maSeriesList

      // ===== MACD 副图 =====
      let macdChart: IChartApi | null = null
      const macdSeriesList: Array<ISeriesApi<'Line' | 'Histogram'> | null> = []

      if (showMACD) {
        logger.info('[MultiPaneChart] 创建 MACD 副图窗格', {
          dataLength: data.length,
          macdParams,
        })

        const macdPane = createMacdChartPane(containerRef.current, subPaneHeight, data, macdParams)
        macdChart = macdPane.macdChart
        macdResultRef.current = macdPane.macdResult
        macdSeriesList.push(...macdPane.macdSeriesList)

        logger.info('[MultiPaneChart] MACD 副图创建完成', {
          difCount: macdPane.macdResult.dif.filter(d => d !== null).length,
          deaCount: macdPane.macdResult.dea.filter(d => d !== null).length,
          histogramCount: macdPane.macdResult.histogram.filter(d => d !== null).length,
        })
      }

      // ===== KDJ 副图 =====
      let kdjChart: IChartApi | null = null
      const kdjSeriesList: Array<ISeriesApi<'Line'> | null> = []

      if (showKDJ) {
        logger.info('[MultiPaneChart] 创建 KDJ 副图窗格', {
          dataLength: data.length,
          kdjParams,
        })

        const kdjPane = createKdjChartPane(containerRef.current, subPaneHeight, data, kdjParams)
        kdjChart = kdjPane.kdjChart
        kdjResultRef.current = kdjPane.kdjResult
        kdjSeriesList.push(...kdjPane.kdjSeriesList)

        logger.info('[MultiPaneChart] KDJ 副图创建完成', {
          kCount: kdjPane.kdjResult.k.filter(d => d !== null).length,
          dCount: kdjPane.kdjResult.d.filter(d => d !== null).length,
          jCount: kdjPane.kdjResult.j.filter(d => d !== null).length,
        })
      }

      // ===== RSI 副图 =====
      let rsiChart: IChartApi | null = null
      const rsiSeriesList: Array<ISeriesApi<'Line'> | null> = []

      if (showRSI) {
        logger.info('[MultiPaneChart] 创建 RSI 副图窗格', {
          dataLength: data.length,
          rsiParams,
        })

        const rsiPane = createRsiChartPane(containerRef.current, subPaneHeight, data, rsiParams)
        rsiChart = rsiPane.rsiChart
        rsiResultRef.current = rsiPane.rsiResult
        rsiSeriesList.push(...rsiPane.rsiSeriesList)

        logger.info('[MultiPaneChart] RSI 副图创建完成', {
          rsiCount: rsiPane.rsiResult.rsi.filter(d => d !== null).length,
          last: rsiPane.rsiResult.rsi.filter(d => d !== null).pop()?.value,
        })
      }

      // ===== 十字光标联动（带节流） =====
      const dataIndex = new Map(data.map((d, i) => [String(d.time), i]))

      const onMainCrosshair = createCrosshairHandler({
        mainSeries,
        data,
        dataIndex,
        showMACD,
        showKDJ,
        showRSI,
        macdResultRef,
        kdjResultRef,
        rsiResultRef,
        macdChart,
        kdjChart,
        rsiChart,
        macdSeriesList,
        kdjSeriesList,
        rsiSeriesList,
        updateTooltip,
      })

      mainChart.subscribeCrosshairMove(onMainCrosshair)

      // ===== TimeScale 同步 =====
      syncTimeScales(mainChart, macdChart, kdjChart, rsiChart)

      mainChart.timeScale().fitContent()
      if (macdChart) macdChart.timeScale().fitContent()
      if (kdjChart) kdjChart.timeScale().fitContent()
      if (rsiChart) rsiChart.timeScale().fitContent()

      // ── 高 DPI 自适应：监听容器尺寸变化 ──
      const resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const { width: w, height: h } = entry.contentRect
          if (w <= 0 || h <= 0) continue
          mainChart.applyOptions({ width: w, height: mainPaneHeight })
          if (macdChart) macdChart.applyOptions({ width: w, height: subPaneHeight })
          if (kdjChart) kdjChart.applyOptions({ width: w, height: subPaneHeight })
          if (rsiChart) rsiChart.applyOptions({ width: w, height: subPaneHeight })
        }
      })
      resizeObserver.observe(containerRef.current)

      mainChartRef.current = mainChart
      mainSeriesRef.current = mainSeries
      macdChartRef.current = macdChart
      kdjChartRef.current = kdjChart
      rsiChartRef.current = rsiChart

      logger.info('[MultiPaneChart] 多窗格图表初始化完成', {
        mainPaneHeight,
        subPaneHeight,
        macdEnabled: showMACD,
        kdjEnabled: showKDJ,
        rsiEnabled: showRSI,
      })

      return () => {
        resizeObserver.disconnect()
        mainChart.remove()
        if (macdChart) macdChart.remove()
        if (kdjChart) kdjChart.remove()
        if (rsiChart) rsiChart.remove()
        mainChartRef.current = null
        mainSeriesRef.current = null
        macdChartRef.current = null
        kdjChartRef.current = null
        rsiChartRef.current = null
        maSeriesRefs.current = []
        macdResultRef.current = null
        kdjResultRef.current = null
        rsiResultRef.current = null
      }
    }, [data, positiveColor, negativeColor, showMACD, showKDJ, showRSI, macdParams, kdjParams, rsiParams])

    // Markers
    useEffect(() => {
      if (!mainSeriesRef.current) return

      if (!markers || markers.length === 0) {
        if (mainMarkersRef.current) {
          mainMarkersRef.current.setMarkers([])
        } else {
          mainMarkersRef.current = createSeriesMarkers(mainSeriesRef.current, [])
        }
        return
      }

      if (!mainMarkersRef.current) {
        mainMarkersRef.current = createSeriesMarkers(mainSeriesRef.current, [])
      }

      const chartMarkers: SeriesMarker<Time>[] = markers.map((m) => ({
        time: m.time,
        position: m.position,
        shape: m.shape,
        color: m.color,
        text: m.text,
        size: m.size,
      }))
      mainMarkersRef.current.setMarkers(chartMarkers)
    }, [markers])

    if (ref) {
      if (typeof ref === 'function') {
        ref(containerRef.current)
      } else {
        ;(ref as { current: HTMLDivElement | null }).current = containerRef.current
      }
    }

    return (
      <div {...divProps}>
        {showToolbar && (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.75rem',
              padding: '0.5rem 0',
              flexWrap: 'wrap',
            }}
          >
            <div style={{ display: 'flex', gap: '2px', background: CHART_PALETTE_PRO.bgLight, borderRadius: '6px', padding: '2px' }}>
              {PERIOD_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => onPeriodChange?.(opt.value)}
                  style={{
                    padding: '4px 10px',
                    fontSize: '0.78rem',
                    fontWeight: 500,
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    background: period === opt.value
                      ? 'rgba(255,255,255,0.1)'
                      : 'transparent',
                    color: period === opt.value
                      ? CHART_PALETTE_PRO.contrast
                      : CHART_PALETTE_PRO.axis,
                    transition: 'all 0.15s ease',
                  }}
                >
                  {opt.label}
                </button>
              ))}
            </div>

            {isDailyPeriod && (
              <div style={{ display: 'flex', gap: '2px', background: CHART_PALETTE_PRO.bgLight, borderRadius: '6px', padding: '2px' }}>
                {ADJUST_OPTIONS.map((opt) => (
                  <button
                    key={opt.value || 'none'}
                    onClick={() => onAdjustChange?.(opt.value)}
                    style={{
                      padding: '4px 10px',
                      fontSize: '0.78rem',
                      fontWeight: 500,
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      background: adjust === opt.value
                        ? 'rgba(255,255,255,0.1)'
                        : 'transparent',
                      color: adjust === opt.value
                        ? CHART_PALETTE_PRO.contrast
                        : CHART_PALETTE_PRO.axis,
                      transition: 'all 0.15s ease',
                    }}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        <div ref={containerRef} style={{ position: 'relative' }}>
          <div
            ref={tooltipElementRef}
            style={{
              position: 'absolute',
              top: 8,
              right: 8,
              zIndex: 6,
              minWidth: 150,
              padding: '8px 10px',
              borderRadius: '8px',
              background: 'rgba(19,23,34,0.88)',
              backdropFilter: 'blur(6px)',
              border: `1px solid ${CHART_PALETTE_PRO.grid}`,
              boxShadow: '0 4px 16px rgba(0,0,0,0.35)',
              fontSize: '0.74rem',
              fontFeatureSettings: 'tnum',
              color: CHART_PALETTE_PRO.axis,
              pointerEvents: 'none',
              display: 'none',
            }}
          >
            <div data-tooltip-time style={{ fontWeight: 600, marginBottom: 4, color: CHART_PALETTE_PRO.contrast }} />
            <div data-tooltip-values style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '2px 10px' }} />
          </div>
        </div>
      </div>
    )
  }
)

MultiPaneChart.displayName = 'MultiPaneChart'

const MultiPaneChartMemo = memo(MultiPaneChart)
MultiPaneChartMemo.displayName = 'MultiPaneChart'

export const MultiPaneChartComponent = MultiPaneChartMemo
export { MultiPaneChartComponent as MultiPaneChart }
export type { TooltipData, MultiPaneChartProps } from './multiPaneChart.types'

export default MultiPaneChartMemo

import { forwardRef, memo, type ComponentPropsWithoutRef } from 'react'
import {
  LineChart as RechartsLine,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  ReferenceLine,
} from 'recharts'
import { CHART_PALETTE } from '@/constants/theme.tokens'
