/**
 * @module ScoreFactorWaterfall
 * @description V6 评分因子贡献瀑布图组件。
 * - 数据只读：优先 V6ScoreEngine.audit().factorContributions；audit 缺失时从维度分 DimensionScore[] 派生
 * - 零硬编码：颜色、阈值均来自主题令牌与引擎配置
 * - 处理 loading / empty / data 三态
 */

import { useMemo } from 'react'
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts'
import { LoadingState } from '@/components/molecules/LoadingState'
import { EmptyState } from '@/components/molecules/EmptyState'
import { ErrorState } from '@/components/molecules/ErrorState'
import { COLOR_TOKENS } from '@/constants/theme.tokens'
import type { FactorContribution, ScoreAuditTrail } from '@/services/scoring/v6-engine'
import type { DimensionScore } from '@/data/types'

// ============================================================
// Types
// ============================================================

export interface ScoreFactorWaterfallProps {
  /** V6ScoreEngine.audit() 输出；组件只读，优先级高于 dimensionScores */
  audit?: ScoreAuditTrail | null
  /** 评分维度分（DimensionScore[]）；当 audit 缺失时，从维度分派生瀑布 */
  dimensionScores?: DimensionScore[]
  /** 加载态 */
  loading?: boolean
  /** 错误信息 */
  error?: string | null
  /** 图表高度 */
  height?: number
}

interface WaterfallRow {
  label: string
  base: number
  value: number
  isTotal: boolean
  contribution?: FactorContribution
  dimensionInfo?: { score: number; weight: number }
}

// ============================================================
// Helpers
// ============================================================

function getScale(contribution: FactorContribution): number {
  const denominator = contribution.score * contribution.normalizedWeight
  return denominator > 0 ? contribution.contribution / denominator : 20
}

function buildWaterfallData(contributions: FactorContribution[]): WaterfallRow[] {
  if (contributions.length === 0) return []

  const firstContribution = contributions[0]
  if (!firstContribution) return []

  const scale = getScale(firstContribution)
  const start = firstContribution.baseline * scale

  const rows: WaterfallRow[] = []
  let cumulative = start

  for (const c of contributions) {
    const base = cumulative
    const value = c.signedContribution
    rows.push({
      label: c.label,
      base,
      value,
      isTotal: false,
      contribution: c,
    })
    cumulative += value
  }

  rows.push({
    label: '综合得分',
    base: 0,
    value: cumulative,
    isTotal: true,
  })

  return rows
}

/**
 * 当 audit 缺失时，从评分维度分（DimensionScore[]）派生瀑布数据。
 * 每个维度贡献 = score * weight，终点为各维度加权得分之和。
 */
function buildWaterfallFromDimensions(dimensions: DimensionScore[]): WaterfallRow[] {
  const valid = dimensions.filter(
    (d) => typeof d.score === 'number' && Number.isFinite(d.score),
  )
  if (valid.length === 0) return []

  const rows: WaterfallRow[] = []
  let cumulative = 0
  for (const d of valid) {
    const score = d.score as number
    const value = score * d.weight
    rows.push({
      label: d.name,
      base: cumulative,
      value,
      isTotal: false,
      dimensionInfo: { score, weight: d.weight },
    })
    cumulative += value
  }

  rows.push({
    label: '维度加权总分',
    base: 0,
    value: cumulative,
    isTotal: true,
  })

  return rows
}

function formatPercent(value: number): string {
  return `${(value * 100).toFixed(1)}%`
}

function formatScore(value: number): string {
  return `${value.toFixed(1)} 分`
}

// ============================================================
// Components
// ============================================================

function WaterfallTooltip({ active, payload }: { active?: boolean; payload?: Array<{ payload?: WaterfallRow }> }) {
  if (!active || !payload || payload.length === 0) return <></>

  const row = payload[0]?.payload
  if (!row) return <></>
  if (row.isTotal) {
    return (
      <div className="rounded-md border p-2 shadow-sm text-xs bg-muted">
        <div className="font-medium">{row.label}</div>
        <div className="text-muted-foreground">{formatScore(row.value)}</div>
      </div>
    )
  }

  const c = row.contribution
  if (!c) {
    if (row.dimensionInfo) {
      const { score, weight } = row.dimensionInfo
      return (
        <div className="rounded-md border p-2 shadow-sm text-xs space-y-1 bg-muted">
          <div className="font-medium">{row.label}</div>
          <div className="text-muted-foreground">维度得分: {score.toFixed(2)}</div>
          <div className="text-muted-foreground">权重: {formatPercent(weight)}</div>
          <div className="text-muted-foreground">
            加权贡献: {score.toFixed(2)} × {formatPercent(weight)} = {(score * weight).toFixed(3)}
          </div>
        </div>
      )
    }
    return <></>
  }

  return (
    <div className="rounded-md border p-2 shadow-sm text-xs space-y-1 bg-muted">
      <div className="font-medium">{c.label}</div>
      <div className="text-muted-foreground">原始得分: {c.score.toFixed(2)}</div>
      <div className="text-muted-foreground">权重: {formatPercent(c.normalizedWeight)}</div>
      <div className={c.signedContribution >= 0 ? 'text-success' : 'text-destructive'}>
        {c.signedContribution >= 0 ? '正向贡献' : '负向贡献'}: {c.signedContribution >= 0 ? '+' : ''}
        {c.signedContribution.toFixed(2)} 分
      </div>
      <div className="text-muted-foreground">绝对贡献: {c.contribution.toFixed(2)} 分 ({formatPercent(c.contributionRate)})</div>
    </div>
  )
}

/**
 * ScoreFactorWaterfall
 */
export function ScoreFactorWaterfall({
  audit,
  dimensionScores,
  loading = false,
  error = null,
  height = 360,
}: ScoreFactorWaterfallProps) {
  const contributions = useMemo(() => audit?.factorContributions ?? [], [audit?.factorContributions])

  const rows = useMemo(() => {
    if (contributions.length > 0) return buildWaterfallData(contributions)
    if (dimensionScores && dimensionScores.length > 0) return buildWaterfallFromDimensions(dimensionScores)
    return []
  }, [contributions, dimensionScores])

  if (loading) {
    return <LoadingState message="正在计算因子贡献..." />
  }

  if (error) {
    return <ErrorState error={error} variant="card" title="因子贡献加载失败" />
  }

  if ((contributions.length === 0 && (dimensionScores?.length ?? 0) === 0) || rows.length === 0) {
    return <EmptyState title="暂无因子贡献数据" description="请先生成或刷新 V6 评分" />
  }

  return (
    <div className="space-y-4" data-testid="score-factor-waterfall">
      <div className="flex flex-wrap items-center gap-4 text-xs text-muted-foreground">
        <div className="flex items-center gap-1">
          <span className="inline-block h-3 w-3 rounded-sm" style={{ backgroundColor: COLOR_TOKENS.success.hex }} />
          <span>正向贡献</span>
        </div>
        <div className="flex items-center gap-1">
          <span className="inline-block h-3 w-3 rounded-sm" style={{ backgroundColor: COLOR_TOKENS.danger.hex }} />
          <span>负向贡献</span>
        </div>
        <div className="flex items-center gap-1">
          <span className="inline-block h-3 w-3 rounded-sm" style={{ backgroundColor: COLOR_TOKENS.info.hex }} />
          <span>综合得分</span>
        </div>
      </div>

      <ResponsiveContainer width="100%" height={height}>
        <BarChart data={rows} margin={{ top: 8, right: 16, bottom: 64, left: 8 }}>
          <CartesianGrid strokeDasharray="3 3" stroke={COLOR_TOKENS.border.hex} vertical={false} />
          <XAxis
            dataKey="label"
            angle={-30}
            textAnchor="end"
            height={80}
            interval={0}
            tick={{ fill: COLOR_TOKENS.textSecondary.hex, fontSize: 11 }}
            axisLine={{ stroke: COLOR_TOKENS.border.hex }}
            tickLine={false}
          />
          <YAxis
            tick={{ fill: COLOR_TOKENS.textSecondary.hex, fontSize: 11 }}
            axisLine={false}
            tickLine={false}
            label={{ value: '得分', angle: -90, position: 'insideLeft', fill: COLOR_TOKENS.textSecondary.hex, fontSize: 11 }}
          />
          <Tooltip content={WaterfallTooltip as never} cursor={{ fill: 'transparent' }} />
          <Bar dataKey="base" stackId="waterfall" fill="transparent" isAnimationActive={false} />
          <Bar dataKey="value" stackId="waterfall" isAnimationActive={false}>
            {rows.map((row, index) => {
              if (row.isTotal) {
                return <Cell key={`cell-${index}`} fill={COLOR_TOKENS.info.hex} />
              }
              const isPositive = (row.value ?? 0) >= 0
              return <Cell key={`cell-${index}`} fill={isPositive ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex} />
            })}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  )
}

export default ScoreFactorWaterfall

/**
 * @module SectorRotationHeatmap
 * @description 板块轮动热力图：支持日线/周线/月线切换，按涨跌幅、换手率、资金流向着色。
 * 参考 SectorHeatmapWidget 风格，使用 DataState 处理 loading/empty/error 三态。
 */

import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router'
import { useDataSource, useMarketDataStore } from '@/store/marketDataStore'
import { DataState } from '@/components/molecules/DataState'
import { Select, SelectItem } from '@/components/atoms/Select'
import type { SectorHeatmapData } from '@/types/modules/widget.types'
import type { DataSourceConfig } from '@/types/modules/widget.types'
import {
  SECTOR_HEATMAP_COLUMNS,
  SECTOR_HEATMAP_INTENSITY_REFERENCE,
  SECTOR_HEATMAP_METRICS,
  SECTOR_HEATMAP_OPACITY,
  SECTOR_HEATMAP_RANK_LIMIT,
  SECTOR_HEATMAP_TEXT_COLORS,
  SECTOR_HEATMAP_TIME_WINDOWS,
  SECTOR_HEATMAP_COLORS,
  type SectorHeatmapMetric,
  type SectorHeatmapTimeWindow,
} from '@/config/sectorHeatmapConfig'
import { WIDGET_DEFAULT_DATA_SOURCE } from '@/constants/cockpit.constants'
import { hexToRgba, cn } from '@/lib/utils'

export interface SectorRotationHeatmapProps {
  title?: string
}

export interface HeatmapCell {
  code: string
  name: string
  changePercent: number
  turnover: number | null
  fundFlow: number | null
}

function parsePercentString(value: string | number | undefined): number | null {
  if (value === undefined) return null
  if (typeof value === 'number') return value
  const parsed = Number.parseFloat(value.replace('%', ''))
  return Number.isNaN(parsed) ? null : parsed
}

/**
 * adaptHeatmapData
 * @param sectors
 * @returns HeatmapCell[]
/**
 * adaptHeatmapData
 * @param sectors
 * @returns HeatmapCell[]
 */
export function adaptHeatmapData(sectors: SectorHeatmapData[]): HeatmapCell[] {
  return sectors.map((sector) => ({
    code: sector.code,
    name: sector.name,
    changePercent: sector.changePercent,
    turnover: parsePercentString(sector.turnover),
    fundFlow: sector.fundFlow ?? null,
  }))
}

/**
 * getMetricValue
 * @param cell
 * @param metric
 * @returns number | null
/**
 * getMetricValue
 * @param cell
 * @param metric
 * @returns number | null
 */
export function getMetricValue(cell: HeatmapCell, metric: SectorHeatmapMetric): number | null {
  if (metric === 'changePercent') return cell.changePercent
  if (metric === 'turnover') return cell.turnover
  return cell.fundFlow
}

function computeCellStyle(metric: SectorHeatmapMetric, value: number | null) {
  if (value === null) {
    return {
      backgroundColor: hexToRgba(SECTOR_HEATMAP_COLORS[metric].neutral, SECTOR_HEATMAP_OPACITY.min),
      color: SECTOR_HEATMAP_TEXT_COLORS.onLight,
    }
  }

  const reference = SECTOR_HEATMAP_INTENSITY_REFERENCE[metric]
  const ratio = Math.abs(value) / reference
  const opacity = Math.min(SECTOR_HEATMAP_OPACITY.max, SECTOR_HEATMAP_OPACITY.min + ratio * (SECTOR_HEATMAP_OPACITY.max - SECTOR_HEATMAP_OPACITY.min))

  const colorSet = SECTOR_HEATMAP_COLORS[metric]
  const baseColor = value > 0 ? colorSet.positive : value < 0 ? colorSet.negative : colorSet.neutral
  const textColor = opacity > SECTOR_HEATMAP_OPACITY.textThreshold ? SECTOR_HEATMAP_TEXT_COLORS.onDark : SECTOR_HEATMAP_TEXT_COLORS.onLight

  return {
    backgroundColor: hexToRgba(baseColor, opacity),
    color: textColor,
  }
}

function formatMetricValue(value: number | null, metric: SectorHeatmapMetric): string {
  if (value === null) return 'N/A'
  const unit = SECTOR_HEATMAP_METRICS.find((m) => m.value === metric)?.unit ?? ''
  const sign = value > 0 ? '+' : ''
  return `${sign}${value.toFixed(2)}${unit}`
}

function sortCellsByMetric(cells: HeatmapCell[], metric: SectorHeatmapMetric): HeatmapCell[] {
  return [...cells].filter((cell) => getMetricValue(cell, metric) !== null).sort((a, b) => {
    const va = getMetricValue(a, metric) ?? 0
    const vb = getMetricValue(b, metric) ?? 0
    return vb - va
  })
}

/**
 * SectorRotationHeatmap
 */
export function SectorRotationHeatmap({ title = '板块轮动热力图' }: SectorRotationHeatmapProps) {
  const navigate = useNavigate()
  const { data, loading, error } = useDataSource('sectorHeatmap')
  const fetchDataSource = useMarketDataStore((state) => state.fetchDataSource)

  const [timeWindow, setTimeWindow] = useState<SectorHeatmapTimeWindow>('day')
  const [metric, setMetric] = useState<SectorHeatmapMetric>('changePercent')

  useEffect(() => {
    const baseConfig = WIDGET_DEFAULT_DATA_SOURCE.sectorHeatmap as DataSourceConfig
    void fetchDataSource('sectorHeatmap', {
      ...baseConfig,
      mode: 'once',
      params: { timeWindow },
    })
  }, [fetchDataSource, timeWindow])

  const cells = useMemo(() => adaptHeatmapData(data?.sectors ?? []), [data?.sectors])

  const rankedCells = useMemo(() => sortCellsByMetric(cells, metric), [cells, metric])
  const topGainers = useMemo(() => rankedCells.slice(0, SECTOR_HEATMAP_RANK_LIMIT), [rankedCells])
  const topLosers = useMemo(
    () =>
      metric === 'changePercent' || metric === 'fundFlow'
        ? [...rankedCells].reverse().slice(0, SECTOR_HEATMAP_RANK_LIMIT)
        : [],
    [metric, rankedCells],
  )

  const handleCellClick = (code: string) => {
    void navigate(`/analysis/industry-score?sector=${encodeURIComponent(code)}`)
  }

  const errorMessage = error ?? '操作失败'

  return (
    <section className="rounded-xl border border-border bg-card p-4 shadow-sm">
      <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <h2 className="text-lg font-semibold text-foreground">{title}</h2>
        <div className="flex flex-wrap items-center gap-2">
          <Select
            value={timeWindow}
            onChange={(e) => setTimeWindow(e.target.value as SectorHeatmapTimeWindow)}
            className="w-28"
          >
            {SECTOR_HEATMAP_TIME_WINDOWS.map((window) => (
              <SelectItem key={window.value} value={window.value}>
                {window.label}
              </SelectItem>
            ))}
          </Select>

          <Select
            value={metric}
            onChange={(e) => setMetric(e.target.value as SectorHeatmapMetric)}
            className="w-36"
          >
            {SECTOR_HEATMAP_METRICS.map((m) => (
              <SelectItem key={m.value} value={m.value}>
                {m.label}
              </SelectItem>
            ))}
          </Select>
        </div>
      </div>

      <DataState
        isLoading={loading}
        isError={error !== null}
        isEmpty={cells.length === 0}
        data={cells}
        errorProps={{ error: errorMessage }}
      >
        <div className="space-y-4">
          <div
            className={cn('grid gap-2')}
            style={{ gridTemplateColumns: `repeat(${SECTOR_HEATMAP_COLUMNS}, minmax(0, 1fr))` }}
          >
            {cells.map((cell) => {
              const value = getMetricValue(cell, metric)
              const style = computeCellStyle(metric, value)
              return (
                <button
                  key={cell.code}
                  type="button"
                  onClick={() => handleCellClick(cell.code)}
                  className="flex flex-col items-center justify-center rounded-lg border border-transparent p-3 text-center transition hover:ring-ring focus:outline-none focus:ring-2 border-input"
                  style={style}
                  aria-label={`${cell.name} ${formatMetricValue(value, metric)}`}
                >
                  <span className="text-sm font-medium">{cell.name}</span>
                  <span className="text-xs opacity-90">{formatMetricValue(value, metric)}</span>
                </button>
              )
            })}
          </div>

          <div className="grid gap-4 md:grid-cols-2">
            <div>
              <h3 className="mb-2 text-sm font-semibold text-card-foreground">
                {metric === 'changePercent' ? '领涨板块' : metric === 'fundFlow' ? '资金流入' : '高换手板块'}
              </h3>
              <ul className="space-y-1">
                {topGainers.map((cell) => (
                  <li
                    key={`top-${cell.code}`}
                    className="flex justify-between rounded bg-muted px-3 py-2 text-sm"
                  >
                    <span>{cell.name}</span>
                    <span className="font-medium">
                      {formatMetricValue(getMetricValue(cell, metric), metric)}
                    </span>
                  </li>
                ))}
              </ul>
            </div>

            {topLosers.length > 0 && (
              <div>
                <h3 className="mb-2 text-sm font-semibold text-card-foreground">
                  {metric === 'changePercent' ? '领跌板块' : '资金流出'}
                </h3>
                <ul className="space-y-1">
                  {topLosers.map((cell) => (
                    <li
                      key={`bottom-${cell.code}`}
                      className="flex justify-between rounded bg-muted px-3 py-2 text-sm"
                    >
                      <span>{cell.name}</span>
                      <span className="font-medium">
                        {formatMetricValue(getMetricValue(cell, metric), metric)}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </DataState>
    </section>
  )
}

/**
 * ApiTestDialog 组件单元测试
 * @vitest-environment jsdom
 *
 * 覆盖场景：
 * 1. 基础渲染 & HTMLDialogElement patch（jsdom 不原生支持 <dialog>，同 ConfirmDialog 模式）
 * 2. 初始 idle 状态：5 个 source 卡片，badge="待测试"，无 latency/message
 * 3. getStatusBadge 四分支 Switch：idle/testing/success/error 对应不同 Badge 文案与颜色
 * 4. probeEndpoint 四分支：
 *    a) response.ok=true → success + latency
 *    b) response.ok=false HTTP 500 → error + message="HTTP 500"
 *    c) AbortController 超时 (5s) → error + aborted message
 *    d) fetch 抛 TypeError(网络错误) → error + 通用 message
 * 5. handleTestSingle：单 source 按钮点击 → 状态 testing→结果，disabled=testing 判断
 * 6. handleTestAll：点击"测试全部" → 所有 source status=testing → 全部 resolve 后写回结果
 * 7. 条件渲染：latency 存在才显示 ms；message 存在才显示文本；error 状态 message 用红色，success 用绿色
 * 8. 防御分支：TEST_SOURCES.find(id) 未找到 → return（handleTestSingle 不更新 state，不抛错）
 * 9. Dialog 受控：open/onOpenChange 触发，不抛异常
 * 10. memo + displayName 存在（ApiTestDialog.displayName === 'ApiTestDialog'）
 * 11. className/透传属性 + 多次 rerender 稳定性
 *
 * @note 使用 vi.useFakeTimers() 触发 AbortController setTimeout，结束后 restore
 */

import { describe, expect, it, vi, beforeAll, afterAll, beforeEach, afterEach } from 'vitest'
import { render, screen, fireEvent, act, waitFor } from '@testing-library/react'
import { ApiTestDialog } from './ApiTestDialog'

// ===========================
// Mock 数据结构（规范化，5 条 endpoints 对应 TEST_API_ENDPOINTS 配置）
// vi.mock 会提升至文件顶部，因此 mock 数据需用 vi.hoisted 包裹（避免 ReferenceError: Cannot access '...' before initialization）
// ===========================
const { mockTestEndpoints } = vi.hoisted(() => ({
  mockTestEndpoints: [
    { id: 'akshare', name: 'AKShare', testApi: '/api/test/akshare' },
    { id: 'ifind', name: 'iFinD', testApi: '/api/test/ifind' },
    { id: 'yahoo', name: 'Yahoo', testApi: '/api/test/yahoo' },
    { id: 'tianyancha', name: '天眼查', testApi: '/api/test/tianyancha' },
    { id: 'scholar', name: '学术', testApi: '/api/test/scholar' },
  ]
}))

vi.mock('@/config/collectConfig', async () => {
  const actual = await vi.importActual('@/config/collectConfig')
  return {
    ...(actual as any),
    TEST_API_ENDPOINTS: mockTestEndpoints,
  }
})

describe('ApiTestDialog', () => {
  // ============ HTMLDialogElement monkey-patch（同 ConfirmDialog 模式） ============
  let originalShowModal: typeof HTMLDialogElement.prototype.showModal | undefined
  let originalClose: typeof HTMLDialogElement.prototype.close | undefined

  beforeAll(() => {
    if (typeof HTMLDialogElement !== 'undefined') {
      originalShowModal = HTMLDialogElement.prototype.showModal
      originalClose = HTMLDialogElement.prototype.close
      HTMLDialogElement.prototype.showModal = vi.fn(function (this: HTMLDialogElement) {
        ;(this as { open: boolean }).open = true
      })
      HTMLDialogElement.prototype.close = vi.fn(function (this: HTMLDialogElement) {
        ;(this as { open: boolean }).open = false
      })
    }
  })

  afterAll(() => {
    if (typeof HTMLDialogElement !== 'undefined') {
      if (originalShowModal) HTMLDialogElement.prototype.showModal = originalShowModal
      if (originalClose) HTMLDialogElement.prototype.close = originalClose
    }
  })

  // ============ Fake timers 管理 ============
  // 注意：仅「超时分支」测试需要 fake timers；其余异步测试使用 real timers
  // 否则 waitFor 内部 setTimeout 轮询被 fake 后永不触发，导致所有异步测试挂起
  beforeEach(() => {
    vi.clearAllMocks()
  })
  afterEach(() => {
    vi.useRealTimers()
  })

