      // 仅此测试使用 fake timers 以精确控制 5s 超时
      vi.useFakeTimers()

      const hangingFetch = vi.fn((_u: any, opts: any) => {
        return new Promise<Response>((_resolve, reject) => {
          // 挂起：直到 abort，立即监听 abort 事件
          opts?.signal?.addEventListener?.('abort', () => {
            const err = new Error('Aborted')
            err.name = 'AbortError'
            reject(err)
          })
