      })
      vi.stubGlobal('fetch', hangingFetch)

      render(<ApiTestDialog open onOpenChange={vi.fn()} />)
      const btn = screen.getAllByRole('button', { name: '测试' })[0]!
      await act(async () => {
        fireEvent.click(btn)
      })
      // 快进 6 秒触发 setTimeout
      await act(async () => {
        vi.advanceTimersByTime(6000)
