      await act(async () => {
        vi.runAllTicks()
      })
      expect(screen.getAllByText('异常').length).toBeGreaterThanOrEqual(1)
      const anyAbortMsg = screen.queryByText((t: string) => /abort/i.test(t) || /Aborted/.test(t))
