/**
 * @module CollectionSwimlane
 * @description 采集链路泳道图（甘特式）。
 *
 * 将单次采集 trace 中各数据源尝试、降级、写入等阶段按时间轴展开，
 * 每个数据源一条泳道，直观展示切换与耗时。
 */

import { useMemo } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/atoms/Card'
import { Badge } from '@/components/atoms/Badge'
import { getColorHex, getColorBgClass } from '@/constants/theme.tokens'
import type { ColorTokenKey } from '@/constants/theme.tokens'
import { DATA_SOURCE_ENDPOINT_MAP } from '@/config/dataSourceRegistry'
import type {
  CollectionTraceSpan,
  CollectionStageRecord,
  CollectionLifecycleStage,
  QuoteDataSourceId,
} from '@/types/modules/collection.types'

interface CollectionSwimlaneProps {
  spans: CollectionTraceSpan[]
  maxHeight?: string
}

const SOURCE_COLOR_ORDER: ColorTokenKey[] = [
  'info',
  'success',
  'warning',
  'danger',
  'purple',
  'cyan',
  'orange',
  'pink',
  'teal',
  'indigo',
]

function stageColor(stage: CollectionLifecycleStage, error?: string): ColorTokenKey {
  if (error) return 'danger'
  switch (stage) {
    case 'source:success':
    case 'write:success':
      return 'success'
    case 'source:fail':
    case 'write:fail':
      return 'danger'
    case 'fallback':
      return 'warning'
    case 'complete':
      return 'info'
    case 'transform':
      return 'cyan'
    default:
      return 'info'
  }
}

function stageLabel(stage: CollectionLifecycleStage): string {
  switch (stage) {
    case 'triggered':
      return '触发'
    case 'source:start':
      return '尝试'
    case 'source:success':
      return '成功'
    case 'source:fail':
      return '失败'
    case 'fallback':
      return '降级'
    case 'transform':
      return '适配'
    case 'write:start':
      return '写入开始'
    case 'write:success':
      return '写入成功'
    case 'write:fail':
      return '写入失败'
    case 'complete':
      return '完成'
    case 'task:status':
      return '任务状态'
    default:
      return stage
  }
}

function sourceName(sourceId?: QuoteDataSourceId): string {
  if (!sourceId) return '未知源'
  return DATA_SOURCE_ENDPOINT_MAP[sourceId]?.name ?? sourceId
}

function SwimlaneRow({ span }: { span: CollectionTraceSpan }): React.JSX.Element {
  const start = span.startedAt
  const end = span.completedAt ?? start + span.totalDurationMs
  const totalMs = Math.max(end - start, 1)

  const { lanes, sourceColorMap } = useMemo(() => {
    const sources = new Set<QuoteDataSourceId | undefined>()
    span.stages.forEach((stage) => sources.add(stage.sourceId))
    sources.add(span.finalSource)
    const sourceList = Array.from(sources).filter(Boolean) as QuoteDataSourceId[]
    const colorMap = new Map<QuoteDataSourceId, ColorTokenKey>()
    sourceList.forEach((src, index) => {
      const color = SOURCE_COLOR_ORDER[index % SOURCE_COLOR_ORDER.length] ?? 'info'
      colorMap.set(src, color)
    })

    const lanesMap = new Map<QuoteDataSourceId | 'global', CollectionStageRecord[]>()
    lanesMap.set('global', [])
    sourceList.forEach((src) => lanesMap.set(src, []))

    span.stages.forEach((stage) => {
      const key = stage.sourceId ?? 'global'
      if (!lanesMap.has(key)) lanesMap.set(key, [])
      lanesMap.get(key)!.push(stage)
    })

    return { lanes: lanesMap, sourceColorMap: colorMap }
  }, [span])

  const laneKeys = Array.from(lanes.keys())

  const getStagePosition = (
    stage: CollectionStageRecord,
    nextStage?: CollectionStageRecord,
  ): { left: number; width: number } => {
    const left = ((stage.timestamp - start) / totalMs) * 100
    const nextTimestamp = nextStage?.timestamp ?? end
    const width = Math.max(((nextTimestamp - stage.timestamp) / totalMs) * 100, 1)
    return { left: Math.max(0, left), width: Math.min(100, width) }
  }

  return (
    <div className="space-y-2 rounded-lg border p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <span className="text-sm font-semibold">{span.symbol}</span>
          <Badge variant="outline">{span.dimensionCode}</Badge>
        </div>
        <div className="text-xs text-muted-foreground">
          <span>{(span.totalDurationMs / 1000).toFixed(2)}s</span>
          <span className="mx-1">·</span>
          <span>{span.fallbackCount} 次降级</span>
        </div>
      </div>

      {laneKeys
        .filter((key) => (lanes.get(key) ?? []).length > 0)
        .map((key) => {
          const stageList = lanes.get(key) ?? []
          const label = key === 'global' ? '全局事件' : sourceName(key)
          const sourceColor = key === 'global' ? 'neutral' : (sourceColorMap.get(key) ?? 'info')
          return (
          <div key={key} className="grid grid-cols-[80px_1fr] items-center gap-2">
            <div className="flex items-center gap-1.5 truncate text-xs">
              <span
                className="inline-block h-2 w-2 shrink-0 rounded-full"
                style={{ backgroundColor: getColorHex(sourceColor) }}
              />
              <span className="truncate">{label}</span>
            </div>
            <div className="relative h-6 rounded bg-muted">
              {stageList.map((stage, index) => {
                const next = stageList[index + 1]
                const { left, width } = getStagePosition(stage, next)
                const colorKey = stageColor(stage.stage, stage.error)
                return (
                  <div
                    key={index}
                    className={`absolute top-1 h-4 rounded text-[9px] leading-4 text-white ${getColorBgClass(colorKey)}`}
                    style={{ left: `${left}%`, width: `${width}%` }}
                    title={`${stageLabel(stage.stage)}${stage.sourceId ? ` (${stage.sourceId})` : ''}: ${stage.message}`}
                  >
                    {width > 12 && stageLabel(stage.stage)}
                  </div>
                )
              })}
            </div>
          </div>
        )
      })}
    </div>
  )
}

/**
 * CollectionSwimlane
 */
export default function CollectionSwimlane({
  spans,
  maxHeight = '360px',
}: CollectionSwimlaneProps): React.JSX.Element {
  const orderedSpans = useMemo(
    () => [...spans].sort((a, b) => b.startedAt - a.startedAt),
    [spans],
  )

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-sm font-semibold">采集链路泳道图</CardTitle>
      </CardHeader>
      <CardContent>
        {orderedSpans.length === 0 ? (
          <p className="text-center text-sm text-muted-foreground">暂无采集链路</p>
        ) : (
          <div className="space-y-3 overflow-auto pr-1" style={{ maxHeight }}>
            {orderedSpans.map((span) => (
              <SwimlaneRow key={span.traceId} span={span} />
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * InputFlowErrorBoundary 单元测试
 *
 * 覆盖场景：
 *   1. 正常渲染子组件
 *   2. 子组件抛错时显示紧凑型错误 UI
 *   3. 点击"重试"调用 onReset 并清空错误态
 *   4. 自定义 fallback 渲染
 *   5. 错误经 captureError 上报
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import React from 'react'
import { InputFlowErrorBoundary } from './InputFlowErrorBoundary'

// ─── Mock 依赖 ──────────────────────────────────────────────

vi.mock('@/lib/logger', () => ({
  getLogger: () => ({
    error: vi.fn(),
    info: vi.fn(),
    warn: vi.fn(),
  }),
}))

const { mockCaptureError } = vi.hoisted(() => ({
  mockCaptureError: vi.fn(),
}))
vi.mock('@/services/errorBus', () => ({
  captureError: mockCaptureError,
}))

vi.mock('@/components/atoms/Button', () => ({
  Button: ({ children, onClick, ...rest }: any) => (
    <button onClick={onClick} {...rest}>
      {children}
    </button>
  ),
}))

// ─── 测试辅助组件 ───────────────────────────────────────────

function ThrowOnRender({ shouldThrow }: { shouldThrow: boolean }): React.ReactElement {
  if (shouldThrow) {
    throw new Error('模拟子组件渲染崩溃')
  }
  return <div data-testid="normal-content">正常渲染</div>
}

// ─── 测试 ───────────────────────────────────────────────────

describe('InputFlowErrorBoundary', () => {
  beforeEach(() => {
    mockCaptureError.mockReset()
    // 抑制 React 的 console.error 日志（错误边界测试会触发）
    vi.spyOn(console, 'error').mockImplementation(() => {})
  })

  it('正常渲染子组件', () => {
    render(
      <InputFlowErrorBoundary>
        <ThrowOnRender shouldThrow={false} />
      </InputFlowErrorBoundary>,
    )

    expect(screen.queryByTestId('normal-content')).toBeTruthy()
    expect(screen.queryByTestId('input-flow-error')).toBeNull()
  })

  it('子组件抛错时显示紧凑型错误 UI', () => {
    render(
      <InputFlowErrorBoundary label="TestInput">
        <ThrowOnRender shouldThrow={true} />
      </InputFlowErrorBoundary>,
    )

    // 应显示错误容器
    expect(screen.queryByTestId('input-flow-error')).toBeTruthy()
    // 应显示错误消息
    expect(screen.queryByText(/模拟子组件渲染崩溃/)).toBeTruthy()
    // 应显示"单只股票添加失败不影响其他功能"提示
    expect(screen.queryByText(/单只股票添加失败不影响其他功能/)).toBeTruthy()
    // 应显示重试按钮
    expect(screen.queryByRole('button', { name: '重试' })).toBeTruthy()
  })

  it('错误经 captureError 上报到错误总线', () => {
    render(
      <InputFlowErrorBoundary label="StockTable">
        <ThrowOnRender shouldThrow={true} />
      </InputFlowErrorBoundary>,
    )

    expect(mockCaptureError).toHaveBeenCalledTimes(1)
    const [err, context] = mockCaptureError.mock.calls[0]!
    expect(err).toBeInstanceOf(Error)
    expect(err.message).toBe('模拟子组件渲染崩溃')
    expect(context.source).toBe('StockTable')
    expect(context.operation).toBe('render')
    expect(context.meta).toHaveProperty('componentStack')
  })

  it('点击"重试"调用 onReset 并清空错误态', () => {
    const onReset = vi.fn()
    // 通过 key 变化强制 ErrorBoundary 重建实例，模拟父组件 resetKey 重置
    let boundaryKey = 0
    let shouldThrow = true

    const { rerender } = render(
      <InputFlowErrorBoundary
        key={boundaryKey}
        onReset={() => {
          onReset()
          shouldThrow = false
          boundaryKey++
        }}
      >
        <ThrowOnRender shouldThrow={shouldThrow} />
      </InputFlowErrorBoundary>,
    )

    // 错误态：显示错误 UI
    expect(screen.queryByTestId('input-flow-error')).toBeTruthy()

    // 点击重试，onReset 翻转 shouldThrow 并增加 key
    fireEvent.click(screen.getByRole('button', { name: '重试' }))

    // 用新 key 重新渲染（模拟父组件 onReset 后 key++ 触发重建）
    rerender(
      <InputFlowErrorBoundary
        key={boundaryKey}
        onReset={() => {
          onReset()
          shouldThrow = false
          boundaryKey++
        }}
      >
        <ThrowOnRender shouldThrow={shouldThrow} />
      </InputFlowErrorBoundary>,
    )

    // onReset 应被调用
    expect(onReset).toHaveBeenCalledTimes(1)
    // key 变化后 ErrorBoundary 是新实例，state 重置，正常内容出现
    expect(screen.queryByTestId('input-flow-error')).toBeNull()
    expect(screen.queryByTestId('normal-content')).toBeTruthy()
  })

  it('支持自定义 fallback', () => {
    const fallbackRender = vi.fn((error: Error, reset: () => void) => (
      <div data-testid="custom-fallback">
        自定义错误: {error.message}
        <button onClick={reset}>自定义重试</button>
      </div>
    ))

    render(
      <InputFlowErrorBoundary fallback={fallbackRender}>
        <ThrowOnRender shouldThrow={true} />
      </InputFlowErrorBoundary>,
    )

    // 应渲染自定义 fallback
    expect(screen.queryByTestId('custom-fallback')).toBeTruthy()
    expect(screen.queryByText(/自定义错误: 模拟子组件渲染崩溃/)).toBeTruthy()
    // 默认错误 UI 不应出现
    expect(screen.queryByTestId('input-flow-error')).toBeNull()

    // 点击自定义重试
    fireEvent.click(screen.getByRole('button', { name: '自定义重试' }))
    // fallback 应被调用过（包含初始渲染）
    expect(fallbackRender).toHaveBeenCalled()
  })

  it('未提供 label 时使用默认 "InputFlow" 作为 source', () => {
    render(
      <InputFlowErrorBoundary>
        <ThrowOnRender shouldThrow={true} />
      </InputFlowErrorBoundary>,
    )

    expect(mockCaptureError).toHaveBeenCalledTimes(1)
    const context = mockCaptureError.mock.calls[0]![1]
    expect(context.source).toBe('InputFlow')
  })
})

