function getMarketLabel(industry: string | undefined): { label: string; className: string } {
  if (!industry) return { label: '—', className: 'bg-muted text-muted-foreground' }
  const key = industry.toUpperCase()
  return MARKET_LABELS[key] ?? { label: industry, className: 'bg-muted text-muted-foreground' }
}

/**
 * StockSearch - A+H 股全市场搜索组件
 *
 * 支持本地字典搜索 + 腾讯 Smartbox API 回退。
 * 已录入意向候选池的股票展示"已导入"标记。
 */
export function StockSearch({
  onSelect,
  onAdded,
  mode = 'fill',
  placeholder = mode === 'add' ? '搜索并直接录入意向候选池' : '搜索代码 / 名称',
  className,
}: StockSearchProps): React.JSX.Element {
  const storeSearchStocks = useInputHubStore((s) => s.searchStocks)
  const storeAddStockFromSearch = useInputHubStore((s) => s.addStockFromSearch)
  const isAddingStock = useInputHubStore((s) => s.isAddingStock)
  const existingSymbols = useInputHubStore((s) => s.existingSymbols)
  const refreshExistingSymbols = useInputHubStore((s) => s.refreshExistingSymbols)

  // 初始化时拉取已导入的 symbol 集合
  useEffect(() => {
    refreshExistingSymbols()
  }, [refreshExistingSymbols])

  const [query, setQuery] = useState('')
  const [results, setResults] = useState<StockSearchResult[]>([])
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(-1)
  // 记录最后交互方式：'mouse' | 'keyboard'，用于 mouseEnter 不覆盖键盘选中（P-mouseEnter 修复）
  const lastInteractionRef = useRef<'mouse' | 'keyboard'>('mouse')
  const { toast } = useToast()
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const inputRef = useRef<HTMLInputElement | null>(null)
  // P-blur 修复：保存 blur timeout ref 以便 mousedown 选项时取消
  const blurTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const clearSearchDebounce = (): void => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current)
    }
  }

  useEffect(() => {
    clearSearchDebounce()

    const trimmed = query.trim()
    if (trimmed.length < INPUT_CONFIG.search.minQueryLength) {
      setResults([])
      setOpen(false)
      setActiveIndex(-1)
      return
    }

    debounceRef.current = setTimeout(async () => {
      const matches = await storeSearchStocks(trimmed)
      setResults(matches)
      // A1 修复：始终打开 listbox，由 listbox 内部根据 results.length 决定显示空态或选项
      setOpen(true)
      setActiveIndex(matches.length > 0 ? 0 : -1)
    }, INPUT_CONFIG.search.debounceMs)

    return () => {
      clearSearchDebounce()
    }
  }, [query, storeSearchStocks])

  const handleSelect = async (result: StockSearchResult): Promise<void> => {
    if (mode !== 'add') {
      onSelect?.(result)
      setQuery('')
      setResults([])
      setOpen(false)
      setActiveIndex(-1)
      inputRef.current?.blur()
      return
    }

    if (isAddingStock) return
    try {
      const addResult = await storeAddStockFromSearch(result, {
        fetchBasicAfterAdd: false,
        fetchKlineAfterAdd: false,
      })
      if (!addResult.success) {
        toast({
          variant: 'error',
          title: '录入失败',
          description: addResult.error ?? '无法录入标的',
        })
        return
      }
      toast({
        variant: 'success',
        title: '录入成功',
        description: `${result.symbol} ${result.name} 已加入意向候选池`,
      })
      onAdded?.(result)
      setQuery('')
      setResults([])
      setOpen(false)
      setActiveIndex(-1)
      inputRef.current?.blur()
    } catch (err) {
      toast({
        variant: 'error',
        title: '录入失败',
        description: err instanceof Error ? err.message : '无法录入标的',
      })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>): void => {
    if (!open || results.length === 0) return

    // P-mouseEnter 修复：键盘事件触发时标记最后交互为 keyboard
    lastInteractionRef.current = 'keyboard'

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setActiveIndex((prev) => (prev + 1) % results.length)
        break
      case 'ArrowUp':
        e.preventDefault()
        setActiveIndex((prev) => (prev - 1 + results.length) % results.length)
        break
      case 'Enter':
        e.preventDefault()
        if (activeIndex >= 0 && activeIndex < results.length) {
          void handleSelect(results[activeIndex]!)
        }
        break
      case 'Escape':
        e.preventDefault()
        setOpen(false)
        setActiveIndex(-1)
        break
    }
  }

  // P-blur 修复：点空白延迟关闭下拉（避免点选项时先 blur 关闭）
  const handleBlur = (): void => {
    if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current)
    blurTimeoutRef.current = setTimeout(() => {
      setOpen(false)
      setActiveIndex(-1)
    }, 120)
  }

  // P-blur 修复：mousedown 选项时取消 blur 关闭（让 click 正常触发）
  const handleOptionMouseDown = (): void => {
    if (blurTimeoutRef.current) {
      clearTimeout(blurTimeoutRef.current)
      blurTimeoutRef.current = null
    }
  }

  return (
    <div className={cn('relative', className)}>
      <Input
        ref={inputRef}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        onKeyDown={handleKeyDown}
        onFocus={() => {
          if (results.length > 0) setOpen(true)
        }}
        onBlur={handleBlur}
        placeholder={placeholder}
        aria-label={placeholder}
        disabled={isAddingStock}
        role="combobox"
        aria-expanded={open}
        aria-autocomplete="list"
        aria-controls={open ? 'stock-search-listbox' : undefined}
        aria-activedescendant={
          open && activeIndex >= 0 ? `stock-search-option-${activeIndex}` : undefined
        }
      />
      {open && (
        <div
          id="stock-search-listbox"
          role="listbox"
          className="absolute z-50 mt-1 max-h-60 w-full overflow-auto rounded-md border bg-popover shadow-md"
        >
          {/* A1 修复：搜索无匹配时显示"无匹配"提示 */}
          {results.length === 0 && query.trim().length >= INPUT_CONFIG.search.minQueryLength && (
            <div className="px-3 py-2 text-sm text-muted-foreground">无匹配结果</div>
          )}
          {results.map((result, index) => {
            const marketInfo = getMarketLabel(result.industry)
            return (
              <div
                key={result.symbol}
                id={`stock-search-option-${index}`}
                role="option"
                aria-selected={index === activeIndex}
                className={cn(
                  'cursor-pointer px-3 py-2 text-sm hover:bg-accent',
                  index === activeIndex && 'bg-accent',
                  isAddingStock && 'pointer-events-none opacity-50',
                )}
                onMouseDown={handleOptionMouseDown}
                onClick={() => void handleSelect(result)}
                onMouseEnter={() => {
                  // P-mouseEnter 修复：仅当最后交互是鼠标时才覆盖 activeIndex
                  if (lastInteractionRef.current === 'mouse') {
                    setActiveIndex(index)
                  } else {
                    // 首次 hover 标记为 mouse 模式（之后才能覆盖）
                    lastInteractionRef.current = 'mouse'
                  }
                }}
              >
                  <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-medium">{result.symbol}</span>
                    <span className={cn('rounded px-1.5 py-0.5 text-xs font-medium', marketInfo.className)}>
                      {marketInfo.label}
                    </span>
                    <span className="text-muted-foreground">{result.name}</span>
                  </div>
                  {existingSymbols.has(result.symbol) && (
                    <Badge variant="secondary" className="text-[10px]">已导入</Badge>
                  )}
                  </div>
                  {/* 申万行业面包屑：仅当 swL1 存在时渲染（港股/未覆盖 A 股不显示） */}
                  {result.swL1 && (
                    <div className="mt-0.5 text-xs text-muted-foreground">
                      {[result.swL1, result.swL2, result.swL3].filter(Boolean).join(' / ')}
                    </div>
                  )}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

/**
 * @module DataSourceConfigStep
 * @description 数据采集向导第一步：数据源配置
 *
 * 包含两部分：
 * 1. 已保存配置模板列表（加载/重命名/删除/导入/导出/搜索/筛选）
 * 2. 数据维度选择与 API 参数配置
 *
 * 拆分说明（P1-M2，2026-08-15）：
 *   - 常量/类型/工具函数 → dataSourceConfig.{config,types,utils}.ts
 *   - 状态与交互逻辑     → useDataSourceConfig.ts
 *   - 单条模板卡片       → ConfigTemplateCard.tsx
 *   本文件仅保留布局编排，从 605 行降至 ~200 行。
 */

import React from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent } from '@/components/atoms/Card'
import { Button } from '@/components/atoms/Button'
import { Input } from '@/components/atoms/Input'
import { COLOR_TOKENS } from '@/constants/theme.tokens'
import {
  ChevronDown,
  ChevronUp,
  FolderOpen,
  Search,
  Filter,
  XCircle,
  Upload,
} from 'lucide-react'
import { AVAILABLE_DIMENSIONS } from './dataSourceConfig.config'
import { ConfigTemplateCard } from './ConfigTemplateCard'
import { useDataSourceConfig } from './useDataSourceConfig'

/**
 * DataSourceConfigStep
 */
export function DataSourceConfigStep(): React.JSX.Element {
  const {
    selectedDimensions,
    toggleDimension,
    apiConfigs,
    updateApiConfig,
    savedConfigs,
    isTemplateListCollapsed,
    setIsTemplateListCollapsed,
    searchQuery,
    setSearchQuery,
    selectedFilterDimension,
    setSelectedFilterDimension,
    selectedFilterFrequency,
    setSelectedFilterFrequency,
    importError,
    importSuccess,
    filteredConfigs,
    hasActiveFilters,
    handleClearFilters,
    handleLoadConfig,
    handleDeleteConfig,
    handleRenameConfig,
    handleExportConfig,
    handleImportConfig,
    isConfigLoaded,
  } = useDataSourceConfig()

  return (
    <div className="space-y-4">
      {/* 配置模板列表 */}
      {savedConfigs.length > 0 && (
        <div>
          <div className="flex items-center justify-between mb-2">
            <button
              type="button"
              className={cn(
                'flex items-center gap-1.5 text-sm font-medium hover:opacity-80 transition-opacity',
                COLOR_TOKENS.textPrimary.tailwind,
              )}
              onClick={() => setIsTemplateListCollapsed(!isTemplateListCollapsed)}
            >
              {isTemplateListCollapsed ? (
                <ChevronDown className="h-4 w-4" />
              ) : (
                <ChevronUp className="h-4 w-4" />
              )}
              <FolderOpen className="h-4 w-4" />
              已保存的配置模板
              <span
                className={cn(
                  'text-xs px-1.5 py-0.5 rounded-full',
                  'bg-muted',
                  'text-muted-foreground',
                )}
              >
                {savedConfigs.length}
              </span>
            </button>

            <label className={cn(
              'flex items-center gap-1.5 text-xs font-medium px-2 py-1 rounded-md cursor-pointer',
              'bg-info/10',
              'text-info',
              'hover:opacity-80 transition-opacity',
            )}>
              <Upload className="h-3.5 w-3.5" />
              导入配置
              <input
                type="file"
                accept=".json"
                onChange={handleImportConfig}
                className="hidden"
              />
            </label>
          </div>

          {!isTemplateListCollapsed && (
            <div className="space-y-3">
              <div className="flex flex-wrap items-center gap-2">
                <div className="relative flex-1 min-w-[180px]">
                  <Search className={cn(
                    'absolute left-2 top-1/2 -translate-y-1/2 h-3.5 w-3.5',
                    COLOR_TOKENS.textMuted.tailwind,
                  )} />
                  <Input
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="搜索配置名称..."
                    className="pl-8 h-8 text-sm"
                  />
                </div>

                <div className="flex items-center gap-2">
                  <Filter className={cn('h-3.5 w-3.5', COLOR_TOKENS.textMuted.tailwind)} />
                  <select
                    value={selectedFilterDimension}
                    onChange={(e) => setSelectedFilterDimension(e.target.value)}
                    className={cn(
                      'h-8 px-2 text-xs rounded-md border border-border bg-background',
                      COLOR_TOKENS.textPrimary.tailwind,
                      'focus:outline-none focus:ring-2',
                      'focus:ring-primary/30',
                      'focus:border-primary',
                    )}
                  >
                    <option value="">全部维度</option>
                    {AVAILABLE_DIMENSIONS.map((dim) => (
                      <option key={dim.code} value={dim.code}>
                        {dim.name}
                      </option>
                    ))}
                  </select>

                  <select
                    value={selectedFilterFrequency}
                    onChange={(e) => setSelectedFilterFrequency(e.target.value)}
                    className={cn(
                      'h-8 px-2 text-xs rounded-md border border-border bg-background',
                      COLOR_TOKENS.textPrimary.tailwind,
                      'focus:outline-none focus:ring-2',
                      'focus:ring-primary/30',
                      'focus:border-primary',
                    )}
                  >
                    <option value="">全部频率</option>
                    <option value="realtime">实时</option>
                    <option value="hourly">每小时</option>
                    <option value="daily">每日</option>
                    <option value="custom">自定义</option>
                  </select>

                  {hasActiveFilters && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={handleClearFilters}
                      className="h-8 px-2 text-xs"
                    >
                      <XCircle className="h-3.5 w-3.5 mr-1" />
                      清除
                    </Button>
                  )}
                </div>
              </div>

              {importSuccess && (
                <div className={cn(
                  'text-center py-2 text-sm rounded-md',
                  'bg-success/10',
                  'text-success',
                )}>
                  {importSuccess}
                </div>
              )}
              {importError && (
                <div className={cn(
                  'text-center py-2 text-sm rounded-md',
                  'bg-destructive/10',
                  'text-destructive',
                )}>
                  {importError}
                </div>
              )}

              {filteredConfigs.length > 0 ? (
                <div className="space-y-2">
                  {filteredConfigs.map((config) => (
                    <ConfigTemplateCard
                      key={config.id}
                      config={config}
                      isLoaded={isConfigLoaded(config)}
                      onLoad={() => handleLoadConfig(config)}
                      onDelete={() => handleDeleteConfig(config.id)}
                      onRename={(newName) => handleRenameConfig(config.id, newName)}
                      onExport={() => handleExportConfig(config.id)}
                    />
                  ))}
                </div>
              ) : (
                <div className={cn(
                  'text-center py-8 text-sm',
                  COLOR_TOKENS.textMuted.tailwind,
                )}>
                  未找到匹配的配置模板
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* 数据维度选择 */}
      <div>
        <div className={cn('text-sm mb-3', COLOR_TOKENS.textMuted.tailwind)}>
          选择需要采集的数据维度，并为每个维度配置 API 参数。
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {AVAILABLE_DIMENSIONS.map((dim) => {
            const checked = selectedDimensions.includes(dim.code)
            return (
              <Card
                key={dim.code}
                className={cn(
                  'transition-shadow transition-colors duration-150 cursor-pointer',
                  checked
                    ? cn('ring-2 ring-primary')
                    : cn('hover:shadow-elevation-1 border-border'),
                )}
                onClick={() => toggleDimension(dim.code, !checked)}
              >
                <CardContent className="p-3">
                  <div className="flex items-start gap-3">
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={(e) => {
                        e.stopPropagation()
                        toggleDimension(dim.code, e.target.checked)
                      }}
                      onClick={(e) => e.stopPropagation()}
                      className="mt-0.5"
                    />
                    <div className="flex-1 min-w-0">
                      <div className="font-medium text-sm">{dim.name}</div>
                      <div className={cn('text-xs', COLOR_TOKENS.textMuted.tailwind)}>
                        {dim.description}
                      </div>
                    </div>
                  </div>
                  {checked && (
                    <div className="mt-2 pl-6" onClick={(e) => e.stopPropagation()}>
                      <Input
                        placeholder="API 基础地址（可选）"
                        value={apiConfigs[dim.code]?.baseUrl ?? ''}
                        onChange={(e) =>
                          updateApiConfig(dim.code, {
                            baseUrl: e.target.value,
                            timeoutMs: apiConfigs[dim.code]?.timeoutMs ?? 30000,
                          })
                        }
                        className="h-7 text-xs"
                      />
                    </div>
                  )}
                </CardContent>
              </Card>
            )
          })}
        </div>
      </div>
    </div>
  )
}

/**
 * @fileoverview 预测校验面板
 *
 * 展示因子预测列表，含方向/置信度/驱动因子/校验状态。
 *
 * @module components/organisms/output/prediction/PredictionPanel
 * @created 2026-07-15 - 输出模块补强
 */

import { usePredictionStore } from '@/store/predictionStore'
import { BADGE_COLORS, COLOR_TOKENS } from '@/constants/theme.tokens'
import type { FactorPrediction, PredictionDirection, PredictionStatus } from '@/types/modules/prediction.types'

const DIRECTION_LABELS: Record<PredictionDirection, { text: string; color: string }> = {
  bullish: { text: '看涨', color: BADGE_COLORS.direction.bullish },
  bearish: { text: '看跌', color: BADGE_COLORS.direction.bearish },
  neutral: { text: '中性', color: BADGE_COLORS.direction.neutral },
}

const STATUS_LABELS: Record<PredictionStatus, { text: string; color: string }> = {
  pending: { text: '待校验', color: BADGE_COLORS.predictionStatus.pending },
  verified: { text: '已校验', color: BADGE_COLORS.predictionStatus.verified },
  expired: { text: '已过期', color: BADGE_COLORS.predictionStatus.expired },
}

function PredictionCard({ prediction }: { prediction: FactorPrediction }): React.JSX.Element {
  const dir = DIRECTION_LABELS[prediction.direction] ?? { text: '中性', color: BADGE_COLORS.direction.neutral }
  const status = STATUS_LABELS[prediction.status] ?? { text: '未知', color: BADGE_COLORS.predictionStatus.unknown }
  const confidencePercent = Math.round(prediction.confidence * 100)

  return (
    <div className="rounded-lg border bg-card p-3 shadow-sm">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">{prediction.stockName}</span>
          <span className="text-xs text-muted-foreground">{prediction.symbol}</span>
        </div>
        <span className={`rounded px-2 py-0.5 text-xs font-medium ${status.color}`}>
          {status.text}
        </span>
      </div>

      <div className="mt-2 flex items-center gap-3">
        <span className={`text-lg font-bold ${dir.color}`}>{dir.text}</span>
        <span className="text-sm text-muted-foreground">
          预期 {prediction.predictedReturnRange.min.toFixed(1)}% ~ {prediction.predictedReturnRange.max.toFixed(1)}%
        </span>
        <span className="text-xs text-muted-foreground">{prediction.horizon}</span>
      </div>

      <div className="mt-2 flex items-center gap-2">
        <span className="text-xs text-muted-foreground">置信度</span>
        <div className="h-2 flex-1 rounded-full bg-muted">
          <div
            className="h-2 rounded-full bg-primary"
            style={{ width: `${confidencePercent}%` }}
          />
        </div>
        <span className="text-xs font-medium">{confidencePercent}%</span>
      </div>

      {prediction.sentimentDominant && (
        <span className={`mt-1 inline-block rounded px-1.5 py-0.5 text-xs ${BADGE_COLORS.sentimentDominant}`}>
          情绪主导
        </span>
      )}

      {prediction.status === 'verified' && prediction.actualReturn !== undefined && (
        <div className="mt-2 border-t pt-2 text-xs">
          <span className="text-muted-foreground">实际收益: </span>
          <span className={prediction.actualReturn >= 0 ? BADGE_COLORS.direction.bullish : BADGE_COLORS.direction.bearish}>
            {prediction.actualReturn >= 0 ? '+' : ''}{prediction.actualReturn.toFixed(2)}%
          </span>
          {(prediction.hitDirection ?? false) === true && <span className={`ml-2 ${BADGE_COLORS.hit}`}>✓ 方向命中</span>}
          {(prediction.hitRange ?? false) === true && <span className={`ml-1 ${BADGE_COLORS.hit}`}>✓ 幅度命中</span>}
        </div>
      )}

      {prediction.drivingFactors.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-1">
          {prediction.drivingFactors.slice(0, 3).map((f) => (
            <span key={f.factorId} className="rounded bg-muted px-1.5 py-0.5 text-xs text-muted-foreground">
              {f.factorId}: {f.factorScore.toFixed(1)}
            </span>
          ))}
        </div>
      )}
    </div>
  )
}

/**
 * 预测校验面板
 *
 * 展示预测列表与准确率统计。
 */
export function PredictionPanel(): React.JSX.Element {
  const predictions = usePredictionStore((s) => s.predictions)

  // 直接从 predictions 计算统计（避免 selector 返回函数调用）
  const verified = predictions.filter((p) => p.status === 'verified')
  const directionHits = verified.filter((p) => (p.hitDirection ?? false) === true).length
  const rangeHits = verified.filter((p) => (p.hitRange ?? false) === true).length
  const stats = {
    total: predictions.length,
    verified: verified.length,
    directionHitRate: verified.length > 0 ? directionHits / verified.length : 0,
    rangeHitRate: verified.length > 0 ? rangeHits / verified.length : 0,
  }

  return (
    <div className="space-y-4">
      {/* 统计卡片 */}
      <div className="grid grid-cols-4 gap-3">
        <div className="rounded-lg border bg-card p-3 text-center shadow-sm">
          <div className="text-2xl font-bold">{stats.total}</div>
          <div className="text-xs text-muted-foreground">总预测</div>
        </div>
        <div className="rounded-lg border bg-card p-3 text-center shadow-sm">
          <div className={`text-2xl font-bold ${COLOR_TOKENS.info.tailwind}`}>{stats.verified}</div>
          <div className="text-xs text-muted-foreground">已校验</div>
        </div>
        <div className="rounded-lg border bg-card p-3 text-center shadow-sm">
          <div className={`text-2xl font-bold ${COLOR_TOKENS.up.tailwind}`}>{(stats.directionHitRate * 100).toFixed(0)}%</div>
          <div className="text-xs text-muted-foreground">方向准确率</div>
        </div>
        <div className="rounded-lg border bg-card p-3 text-center shadow-sm">
          <div className={`text-2xl font-bold ${COLOR_TOKENS.down.tailwind}`}>{(stats.rangeHitRate * 100).toFixed(0)}%</div>
          <div className="text-xs text-muted-foreground">幅度准确率</div>
        </div>
      </div>

      {/* 预测列表 */}
      <div className="space-y-2">
        {predictions.length === 0 ? (
          <div className="py-8 text-center text-muted-foreground">暂无预测记录</div>
        ) : (
          predictions.slice(0, 20).map((p) => (
            <PredictionCard key={p.predictionId} prediction={p} />
          ))
        )}
      </div>
    </div>
  )
}

import React from 'react'
import { cn } from '@/lib/utils'
import type { CollectionProgress as ProgressType } from '@/services/pool/collectionProgressService'

interface BatchProgressDetail {
  symbol: string
  name: string
  percent: number
  completedDims: number
  totalDims: number
  dimStatuses: { name: string; status: string }[]
}

interface Props {
  collecting: boolean
  symbols: { symbol: string; name: string }[]
  progressMap: Map<string, ProgressType> | null
  refreshError: string | null
}

export function BatchCollectionPanel({
  collecting,
  symbols,
  progressMap,
  refreshError,
}: Props): React.JSX.Element | null {
  if (!collecting) return null

  let totalCompleted = 0
  let totalDims = 0
  const details: BatchProgressDetail[] = []

  for (const item of symbols) {
    const p = progressMap?.get(item.symbol)
    const completedDims = p?.completedCount ?? 0
    const totalD = p?.totalDimensions ?? 7
    totalCompleted += completedDims
    totalDims += totalD
    details.push({
      symbol: item.symbol,
      name: item.name,
      percent: p?.completionPercent ?? 0,
      completedDims,
      totalDims: totalD,
      dimStatuses: p?.dimensions?.map((d) => ({ name: d.name, status: d.status })) ?? [],
    })
  }

  const overallPercent = totalDims > 0 ? Math.round((totalCompleted / totalDims) * 100) : 0
  const isBroken = !!refreshError

  return (
    <div className={cn(
      'rounded-lg border-2 p-4',
      isBroken
        ? 'border-destructive/40 bg-destructive/5'
        : 'border-success/30 bg-success/5',
    )}>
      {/* Progress Bar */}
      <div className="flex items-center gap-3">
        {isBroken ? (
          <span className="text-sm text-destructive">⚠</span>
        ) : (
          <div className="h-3 w-3 animate-spin rounded-full border-2 border-success/40 border-t-success" />
        )}
        <span className={cn('text-sm font-medium', isBroken ? 'text-destructive' : 'text-success')}>
          {isBroken ? '采集断连，已停止进度更新' : '批量采集进行中'}
        </span>
        <div className={cn('flex-1 h-3 overflow-hidden rounded-full', isBroken ? 'bg-destructive/15' : 'bg-success/15')}>
          <div
            className={cn('h-full rounded-full transition-[width] duration-700 ease-out', isBroken ? 'bg-destructive/60' : 'bg-success')}
            style={{ width: `${overallPercent}%` }}
          />
        </div>
        <span className={cn('text-lg font-bold tabular-nums', isBroken ? 'text-destructive' : 'text-success')}>
          {overallPercent}%
        </span>
      </div>
      <p className="mt-1 text-xs text-muted-foreground">
        已完成 {totalCompleted} / {totalDims} 个维度 · 共 {symbols.length} 只标的
      </p>

      {refreshError && (
        <div className="mt-2 rounded-md border border-destructive/30 bg-muted/60 px-2 py-1.5 text-[11px] text-destructive">
          <span className="font-medium">断连原因：</span>
          <span className="font-mono break-all">{refreshError}</span>
        </div>
      )}

      <div className="mt-3 space-y-1.5 rounded-md border border-success/20 bg-surface-2/50 p-3">
        {details.map((d) => (
          <div key={d.symbol} className="flex items-center gap-2 text-xs">
            <span className="w-24 shrink-0 truncate font-mono text-muted-foreground" title={d.name}>
              {d.symbol}
            </span>
            <span className="w-16 shrink-0 truncate text-muted-foreground" title={d.name}>
              {d.name}
            </span>
            <div className="flex flex-1 items-center gap-1">
              {d.dimStatuses.map((dim, i) => {
                const dotClass =
                  dim.status === 'success' ? 'bg-success' :
                  dim.status === 'partial' ? 'bg-warning' :
                  dim.status === 'fail' ? 'bg-destructive' :
                  'bg-muted-foreground/40'
                return (
                  <div
                    key={i}
                    className={cn('h-2 w-2 rounded-full transition-colors duration-300', dotClass)}
                    title={`${dim.name}：${dim.status === 'success' ? '已完成' : dim.status === 'partial' ? '部分' : dim.status === 'fail' ? '失败' : '待采集'}`}
                  />
                )
              })}
            </div>
            <div className="flex items-center gap-1.5 w-20 shrink-0 justify-end">
              <div className="h-1.5 w-12 overflow-hidden rounded-full bg-muted">
                <div
                  className="h-full rounded-full bg-success transition-[width] duration-500"
                  style={{ width: `${d.percent}%` }}
                />
              </div>
              <span className="tabular-nums text-muted-foreground">
                {d.completedDims}/{d.totalDims}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

/**
 * @fileoverview 个股资讯统计展示组件
 *
 * 双维度展示：
 * - 时效性维度：近1周 / 近1月 / 近3月 / 全部
 * - 质量维度：总条数 / 高质量条数（sentimentConfidence >= 0.7）
 *
 * @module components/organisms/pool/StockNewsStats
 * @created 2026-07-19
 */

import React, { useEffect, useState } from 'react'
import {
  getStockNewsStats,
  type StockNewsStats as StatsType,
  type NewsTimeWindow,
} from '@/services/pool/newsStatsService'
import { cn } from '@/lib/utils'

export interface StockNewsStatsProps {
  symbol: string
  activeWindow?: NewsTimeWindow
  onWindowChange?: (window: NewsTimeWindow) => void
  compact?: boolean
}

const WINDOW_LABELS: Record<NewsTimeWindow, string> = {
  '1w': '近1周',
  '1m': '近1月',
  '3m': '近3月',
  all: '全部',
}

const WINDOW_ORDER: NewsTimeWindow[] = ['1w', '1m', '3m', 'all']

function getStatsForWindow(stats: StatsType, window: NewsTimeWindow): { total: number; highQuality: number } {
  switch (window) {
    case '1w': return stats.last1w
    case '1m': return stats.last1m
    case '3m': return stats.last3m
    default: return stats.all
  }
}

export function StockNewsStats({
  symbol,
  activeWindow = '1m',
  onWindowChange,
  compact = false,
}: StockNewsStatsProps): React.JSX.Element {
  const [stats, setStats] = useState<StatsType | null>(null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    void (async () => {
      const result = await getStockNewsStats(symbol)
      if (!cancelled) {
        setStats(result)
        setLoading(false)
      }
    })()
    return () => { cancelled = true }
  }, [symbol])

  if (loading) {
    return (
      <div className="flex items-center gap-1 text-xs text-muted-foreground">
        <div className="h-3 w-3 animate-spin rounded-full border border-border border-t-primary" />
        <span>加载中</span>
      </div>
    )
  }

  if (!stats || stats.all.total === 0) {
    return <span className="text-xs text-muted-foreground">暂无资讯</span>
  }

  const currentStats = getStatsForWindow(stats, activeWindow)

  if (compact) {
    return (
      <div className="flex flex-col gap-1">
        <div className="flex gap-1">
          {WINDOW_ORDER.map((w) => (
            <button
              key={w}
              onClick={() => onWindowChange?.(w)}
              className={cn(
                'rounded px-1.5 py-0.5 text-[10px] transition-colors',
                w === activeWindow
                  ? 'bg-primary/15 text-primary font-medium'
                  : 'text-muted-foreground hover:bg-muted',
              )}
            >
              {WINDOW_LABELS[w]}
            </button>
          ))}
        </div>
        <div className="flex items-center gap-2 text-xs">
          <span className="text-muted-foreground">
            共 <strong className="text-foreground">{currentStats.total}</strong> 条
          </span>
          {currentStats.highQuality > 0 && (
            <span className="text-success">
              高质量 <strong className="text-success">{currentStats.highQuality}</strong>
            </span>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-2">
      <div className="flex gap-1">
        {WINDOW_ORDER.map((w) => (
          <button
            key={w}
            onClick={() => onWindowChange?.(w)}
            className={cn(
              'rounded-md px-2 py-1 text-xs transition-colors',
              w === activeWindow
                ? 'bg-primary/15 text-primary font-medium'
                : 'text-muted-foreground hover:bg-muted',
            )}
          >
            {WINDOW_LABELS[w]}
            {w !== 'all' && (
              <span className="ml-1 text-[10px] text-muted-foreground">
                {getStatsForWindow(stats, w).total}
              </span>
            )}
          </button>
        ))}
      </div>
      <div className="flex items-center gap-4 rounded-md border border-border bg-surface-2 px-3 py-2">
        <div className="text-center">
          <p className="text-lg font-bold text-foreground">{currentStats.total}</p>
          <p className="text-[10px] text-muted-foreground">总条数</p>
        </div>
        <div className="h-8 w-px bg-border" />
        <div className="text-center">
          <p className="text-lg font-bold text-success">{currentStats.highQuality}</p>
          <p className="text-[10px] text-muted-foreground">高质量</p>
        </div>
        <div className="h-8 w-px bg-border" />
        <div className="text-center">
          <p className="text-lg font-bold text-warning">
            {currentStats.total > 0 ? Math.round((currentStats.highQuality / currentStats.total) * 100) : 0}%
          </p>
          <p className="text-[10px] text-muted-foreground">高质量占比</p>
        </div>
      </div>
    </div>
  )
}

