  { id: 'tencent', priority: 2, enabled: true },
  { id: 'sina', priority: 3, enabled: true },
  { id: 'mock', priority: 4, enabled: true },
]

/** 默认 K 线数据源优先级（Tushare Pro → 腾讯日 K 线 → 网易（已不可用） → Mock） */
