/**
 * @module ScoreCompletenessConfig
 * @description 评分因子完整性检查配置（P0 修复 R04：因子缺失默认 0 分）
 *
 * 定义每个评分因子对应的数据来源、必填字段和完整性判定规则。
 * 评分计算前需先检查各因子数据完整性，>30% 因子缺失直接跳过评分。
 *
 * @doc V9-DOC-QUALITY-004
 */

import { STORE_NAME } from '@/config/dbConfig'

/** 因子数据来源配置 */
export interface FactorSource {
  /** IndexedDB store 名称 */
  store: string
  /** 必填字段列表 */
  fields: string[]
  /** 最少需要的字段数 */
  minRequired: number
  /** 因子描述 */
  description: string
}

/** 因子完整性状态 */
export type FactorCompletenessStatus = 'complete' | 'partial' | 'insufficient'

/** 因子完整性检查结果 */
export interface FactorCompleteness {
  /** 因子名称 */
  factorName: string
  /** 需要的最少字段数 */
  required: number
  /** 实际可用字段数 */
  available: number
  /** 完整度百分比 (0-100) */
  completeness: number
  /** 完整性状态 */
  status: FactorCompletenessStatus
}

/** 评分完整性总体状态 */
export type ScoreCompletenessStatus = 'complete' | 'partial_data' | 'data_insufficient'

/** 评分完整性结果 */
export interface ScoreCompletenessResult {
  /** 总体状态 */
  status: ScoreCompletenessStatus
  /** 各因子完整性 */
  factors: FactorCompleteness[]
  /** 缺失因子数量 */
  insufficientCount: number
  /** 缺失因子比例 */
  insufficientRatio: number
  /** 是否应该计算评分 */
  shouldCalculate: boolean
  /** 状态消息 */
  message: string
}

/**
 * 因子 → 数据来源映射表
 *
 * V6 引擎 11 层 → 9 因子映射关系：
 * - 估值: L3v (价值层)
 * - 成长: L7 (成长层) + L5 (盈利层)
 * - 盈利: L3f (财务健康层)
 * - 质量: L1 (行业层) + L3f (财务健康层)
 * - 动量: L8 (技术筹码层)
 * - 波动: L8 (技术筹码层)
 * - 流动性: L8 (技术筹码层)
 * - 行业: L-1 (行业评分) + L0 (宏观层) + L2 (行业竞争层)
 * - 情绪: L6 (情绪层) + L4 (资金层)
 */
export const FACTOR_DATA_SOURCE: Record<string, FactorSource> = {
  '估值': {
    store: STORE_NAME.stocks,
    fields: ['pe', 'pb', 'ps', 'price'],
    minRequired: 2,
    description: '基本面估值指标',
  },
  '成长': {
    store: STORE_NAME.stocks,
    fields: ['revenueYoY', 'profitYoY', 'roe'],
    minRequired: 1,
    description: '营收/利润增长率',
  },
  '盈利': {
    store: STORE_NAME.stocks,
    fields: ['roe', 'netProfitMargin', 'grossMargin'],
    minRequired: 2,
    description: '盈利能力指标',
  },
  '质量': {
    store: STORE_NAME.stocks,
    fields: ['debtRatio', 'currentRatio', 'roe'],
    minRequired: 1,
    description: '财务质量指标',
  },
  '动量': {
    store: STORE_NAME.dailyQuotes,
    fields: ['close', 'changePct', 'volume'],
    minRequired: 2,
    description: '价格动量指标',
  },
  '波动': {
    store: STORE_NAME.dailyQuotes,
    fields: ['high', 'low', 'close'],
    minRequired: 2,
    description: '价格波动指标',
  },
  '流动性': {
    store: STORE_NAME.dailyQuotes,
    fields: ['volume', 'amount', 'turnoverRate'],
    minRequired: 1,
    description: '流动性指标',
  },
  '行业': {
    store: STORE_NAME.stocks,
    fields: ['industryCode', 'sector', 'marketCap'],
    minRequired: 1,
    description: '行业分类和竞争力指标',
  },
  '情绪': {
    store: STORE_NAME.stocks,
    fields: ['sentimentScore', 'changePct', 'volume'],
    minRequired: 1,
    description: '市场情绪指标',
  },
}

/** 因子缺失比例阈值：超过此值直接跳过评分 */
export const INSUFFICIENT_THRESHOLD = 0.3

/** 因子缺失比例阈值：低于此值正常评分，但标注 */
export const PARTIAL_THRESHOLD = 0.1

/**
 * 根据股票数据检查因子完整性
 *
 * @param stockData - 股票基础数据
 * @param quotesData - 行情数据（可选）
 * @returns 各因子完整性检查结果
 */
export function checkFactorCompleteness(
  stockData: Record<string, unknown> | null | undefined,
  quotesData?: Record<string, unknown> | null,
): FactorCompleteness[] {
  const results: FactorCompleteness[] = []

  for (const [factorName, source] of Object.entries(FACTOR_DATA_SOURCE)) {
    let record: Record<string, unknown> | null | undefined

    if (source.store === STORE_NAME.stocks) {
      record = stockData
    } else if (source.store === STORE_NAME.dailyQuotes) {
      record = quotesData
    }

    if (!record) {
      results.push({
        factorName,
        required: source.minRequired,
        available: 0,
        completeness: 0,
        status: 'insufficient',
      })
      continue
    }

    const available = source.fields.filter((f) => {
      const val = record?.[f]
      return val !== null && val !== undefined && val !== ''
    }).length

    const completeness = source.fields.length > 0
      ? available / source.fields.length
      : 0

    const status: FactorCompletenessStatus =
      available >= source.minRequired
        ? 'complete'
        : available > 0
          ? 'partial'
          : 'insufficient'

    results.push({
      factorName,
      required: source.minRequired,
      available,
      completeness: Math.round(completeness * 100),
      status,
    })
  }

  return results
}

/**
 * 根据因子完整性结果决定是否计算评分
 *
 * @param factors - 因子完整性检查结果
 * @returns 评分完整性总体结果
 */
export function evaluateCompleteness(factors: FactorCompleteness[]): ScoreCompletenessResult {
  const totalFactors = factors.length
  const insufficientFactors = factors.filter((f) => f.status === 'insufficient')
  const insufficientCount = insufficientFactors.length
  const insufficientRatio = totalFactors > 0 ? insufficientCount / totalFactors : 0

  let status: ScoreCompletenessStatus
  let shouldCalculate: boolean
  let message: string

  if (insufficientRatio > INSUFFICIENT_THRESHOLD) {
    status = 'data_insufficient'
    shouldCalculate = false
    message = `数据不足：${insufficientCount}/${totalFactors} 个因子无数据（${(insufficientRatio * 100).toFixed(0)}%），无法生成可信评分`
  } else if (insufficientRatio > PARTIAL_THRESHOLD) {
    status = 'partial_data'
    shouldCalculate = true
    message = `注意：${insufficientCount} 个因子数据不完整（${insufficientFactors.map((f) => f.factorName).join('、')}），评分仅供参考`
  } else {
    status = 'complete'
    shouldCalculate = true
    message = insufficientCount > 0
      ? `数据基本完整（${insufficientCount} 个因子数据部分缺失）`
      : '所有因子数据完整'
  }

  return {
    status,
    factors,
    insufficientCount,
    insufficientRatio,
    shouldCalculate,
    message,
  }
}

/**
 * 非LLM密钥的安全配置服务
 *
 * 管理数据源 Token（Tushare）和辅助 LLM Key（Qwen）的加密存储。
 * 采用与 {@link llmConfig.ts} 相同的 AES-GCM 256 加密方案，
 * 不再从 VITE_ 环境变量读取（VITE_ 前缀会暴露到前端 bundle）。
 *
 * v2 新增：密钥轮换机制
 * - 每个密钥维护独立的元数据（setAt / lastVerifiedAt）
 * - 默认 TTL 30 天，超期后 UI 层可提示用户轮换
 * - 提供 isExpired / getAge / markVerified API
 *
 * @doc [V9-DOC-BACK-012, V9-DOC-AI-006]
 */

import { defaultStorage } from '@/lib/localStorageManager'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 密钥轮换常量
// ============================================================

/** 默认密钥 TTL：30 天（毫秒） */
const SECRET_TTL_MS = 30 * 24 * 60 * 60 * 1000

/** 密钥元数据接口 */
export interface SecretMeta {
  /** 密钥写入时间戳 (ms) */
  setAt: number
  /** 最后一次验证时间戳 (ms)，用于记录用户确认密钥仍然有效的时间 */
  lastVerifiedAt: number
}

// ============================================================
// 元数据读写工具
// ============================================================

function getMetaStorageKey(secretKey: string): string {
  return `${secretKey}_meta`
}

function readMeta(secretKey: string): SecretMeta | null {
  try {
    const fullKey = `app:${getMetaStorageKey(secretKey)}`
    const raw = localStorage.getItem(fullKey)
    if (!raw) return null
    return JSON.parse(raw) as SecretMeta
  } catch {
    return null
  }
}

function writeMeta(secretKey: string, meta: SecretMeta): void {
  const fullKey = `app:${getMetaStorageKey(secretKey)}`
  localStorage.setItem(fullKey, JSON.stringify(meta))
}

function removeMeta(secretKey: string): void {
  try {
    const fullKey = `app:${getMetaStorageKey(secretKey)}`
    localStorage.removeItem(fullKey)
  } catch {
    // silent
  }
}

// ============================================================
// Tushare Token
// ============================================================

const TUSHARE_TOKEN_STORAGE = 'tushare_token'

/**
 * 异步读取加密存储的 Tushare Token。
 */
export async function getTushareTokenAsync(): Promise<string> {
  try {
    const token = await defaultStorage.getEncrypted<string>(TUSHARE_TOKEN_STORAGE)
    const result = token ? token : ''
    if (!result) {
      logger.debug('[secretConfig] Tushare Token 为空或未配置')
    } else {
      logger.info(`[secretConfig] Tushare Token 读取成功, 长度=${result.length}`)
    }
    return result
  } catch (err) {
    logger.warn('[secretConfig] 读取加密 Tushare Token 失败', { error: err })
    return ''
  }
}

/**
 * 异步保存 Tushare Token 到加密存储，同时记录元数据。
 */
export async function setTushareToken(token: string): Promise<void> {
  if (!token.trim()) {
    await defaultStorage.remove(TUSHARE_TOKEN_STORAGE)
    removeMeta(TUSHARE_TOKEN_STORAGE)
    logger.info('[secretConfig] 已清除 Tushare Token')
    return
  }
  const now = Date.now()
  await defaultStorage.setEncrypted(TUSHARE_TOKEN_STORAGE, token.trim())
  writeMeta(TUSHARE_TOKEN_STORAGE, { setAt: now, lastVerifiedAt: now })
  logger.info('[secretConfig] Tushare Token 已加密保存')
}

/**
 * 检查 Tushare Token 是否已配置（同步，仅检查条目是否存在）。
 */
export function isTushareTokenConfigured(): boolean {
  try {
    const fullKey = `app:${TUSHARE_TOKEN_STORAGE}`
    const raw = localStorage.getItem(fullKey)
    return !!(raw && raw.includes('__encrypted'))
  } catch {
    return false
  }
}

/**
 * 检查 Tushare Token 是否已超过 TTL（默认 30 天），建议轮换。
 * 未配置时返回 false（未配置不算过期，由 isConfigured 判断）。
 */
export function isTushareTokenExpired(ttlMs: number = SECRET_TTL_MS): boolean {
  if (!isTushareTokenConfigured()) return false
  const meta = readMeta(TUSHARE_TOKEN_STORAGE)
  if (!meta) return false
  return Date.now() - meta.setAt > ttlMs
}

/**
 * 获取 Tushare Token 的存活天数（自写入起）。
 * 未配置或无元数据时返回 0。
 */
export function getTushareTokenAgeDays(): number {
  const meta = readMeta(TUSHARE_TOKEN_STORAGE)
  if (!meta) return 0
  return Math.floor((Date.now() - meta.setAt) / (24 * 60 * 60 * 1000))
}

/**
 * 获取 Tushare Token 距离上次验证的天数。
 * 未验证过返回 -1。
 */
export function getTushareTokenDaysSinceVerification(): number {
  const meta = readMeta(TUSHARE_TOKEN_STORAGE)
  if (!meta || meta.lastVerifiedAt === meta.setAt) return -1
  return Math.floor((Date.now() - meta.lastVerifiedAt) / (24 * 60 * 60 * 1000))
}

/**
 * 标记 Tushare Token 已验证（用户确认密钥仍然有效）。
 */
export function markTushareTokenVerified(): void {
  const meta = readMeta(TUSHARE_TOKEN_STORAGE)
  if (!meta) return
  meta.lastVerifiedAt = Date.now()
  writeMeta(TUSHARE_TOKEN_STORAGE, meta)
  logger.info('[secretConfig] Tushare Token 已标记为已验证')
}

