import { describe, it, expect } from 'vitest'
import {
  getPoolTransitionOptions,
  getPoolLabel,
  isValidTransition,
  getTransitionLabel,
  transitionStatus,
  POOL_TRANSITIONS,
} from './poolTransitionEngine'
import { POOL_TYPE, INTENTION_STATUS, RESEARCH_STATUS, POSITION_STATUS } from '@/constants/pool.constants'

describe('poolTransitionEngine', () => {
  describe('POOL_TRANSITIONS 结构完整性', () => {
    it('包含三个池类型', () => {
      expect(POOL_TRANSITIONS[POOL_TYPE.intention]).toBeDefined()
      expect(POOL_TRANSITIONS[POOL_TYPE.research]).toBeDefined()
      expect(POOL_TRANSITIONS[POOL_TYPE.position]).toBeDefined()
    })
  })

  describe('getPoolTransitionOptions()', () => {
    it('intention.screening 有 3 个选项', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.intention, INTENTION_STATUS.screening)
      expect(options.length).toBe(3)
      expect(options.map(o => o.label)).toContain('加入观察')
      expect(options.map(o => o.label)).toContain('归档')
      expect(options.map(o => o.label)).toContain('晋升研究')
    })

    it('intention.watchlist 有 2 个选项', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.intention, INTENTION_STATUS.watchlist)
      expect(options.length).toBe(2)
    })

    it('intention.archived 可恢复筛选', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.intention, INTENTION_STATUS.archived)
      expect(options.length).toBe(1)
      expect(options[0]!.status).toBe(INTENTION_STATUS.screening)
    })

    it('research.candidate 有 2 个选项', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.research, RESEARCH_STATUS.candidate)
      expect(options.length).toBe(2)
      expect(options.map(o => o.status)).toContain(RESEARCH_STATUS.screened)
      expect(options.map(o => o.status)).toContain(RESEARCH_STATUS.archived)
    })

    it('research.watching 可买入持仓（跨池）', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.research, RESEARCH_STATUS.watching)
      const toPosition = options.find(o => o.pool === POOL_TYPE.position)
      expect(toPosition).toBeDefined()
      expect(toPosition?.status).toBe(POSITION_STATUS.holding)
    })

    it('position.holding 可减仓或清仓', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.position, POSITION_STATUS.holding)
      expect(options.length).toBe(2)
      expect(options.map(o => o.status)).toContain(POSITION_STATUS.partial)
      expect(options.map(o => o.status)).toContain(POSITION_STATUS.closed)
    })

    it('position.closed 归档到 research', () => {
      const options = getPoolTransitionOptions(POOL_TYPE.position, POSITION_STATUS.closed)
      expect(options.length).toBe(1)
      expect(options[0]!.pool).toBe(POOL_TYPE.research)
      expect(options[0]!.status).toBe(RESEARCH_STATUS.archived)
    })

    it('不存在的池/状态返回空数组', () => {
      const options = getPoolTransitionOptions('nonexistent' as any, 'unknown' as any)
      expect(options).toEqual([])
    })
  })

  describe('getPoolLabel()', () => {
    it('返回状态标签', () => {
      expect(getPoolLabel(POOL_TYPE.intention, INTENTION_STATUS.screening)).toBe('初步筛选')
      expect(getPoolLabel(POOL_TYPE.research, RESEARCH_STATUS.candidate)).toBe('研究候选')
      expect(getPoolLabel(POOL_TYPE.position, POSITION_STATUS.holding)).toBe('持仓中')
    })

    it('找不到时返回 pool:status', () => {
      const result = getPoolLabel('invalid' as any, 'unknown' as any)
      expect(result).toBe('invalid:unknown')
    })
  })

  describe('isValidTransition()', () => {
    it('合法流转返回 true', () => {
      expect(isValidTransition(
        POOL_TYPE.intention, INTENTION_STATUS.screening,
        POOL_TYPE.intention, INTENTION_STATUS.watchlist
      )).toBe(true)

      expect(isValidTransition(
        POOL_TYPE.research, RESEARCH_STATUS.watching,
        POOL_TYPE.position, POSITION_STATUS.holding
      )).toBe(true)
    })

    it('非法流转返回 false', () => {
      expect(isValidTransition(
        POOL_TYPE.intention, INTENTION_STATUS.screening,
        POOL_TYPE.position, POSITION_STATUS.holding
      )).toBe(false)
    })

    it('反向流转返回 false', () => {
      expect(isValidTransition(
        POOL_TYPE.intention, INTENTION_STATUS.watchlist,
        POOL_TYPE.intention, INTENTION_STATUS.screening
      )).toBe(false)
    })
  })

  describe('getTransitionLabel()', () => {
    it('合法流转返回标签', () => {
      const label = getTransitionLabel(
        POOL_TYPE.intention, INTENTION_STATUS.screening,
        POOL_TYPE.intention, INTENTION_STATUS.watchlist
      )
      expect(label).toBe('加入观察')
    })

    it('非法流转返回默认"流转"', () => {
      const label = getTransitionLabel(
        POOL_TYPE.intention, INTENTION_STATUS.screening,
        POOL_TYPE.position, POSITION_STATUS.holding
      )
      expect(label).toBe('流转')
    })
  })

  describe('transitionStatus()', () => {
    it('合法流转返回目标状态', () => {
      const result = transitionStatus(
        POOL_TYPE.intention, INTENTION_STATUS.screening,
        POOL_TYPE.intention, INTENTION_STATUS.watchlist
      )
      expect(result).toEqual({
        pool: POOL_TYPE.intention,
        status: INTENTION_STATUS.watchlist,
      })
    })

    it('跨池流转也能正确返回', () => {
      const result = transitionStatus(
        POOL_TYPE.research, RESEARCH_STATUS.watching,
        POOL_TYPE.position, POSITION_STATUS.holding
      )
      expect(result).toEqual({
        pool: POOL_TYPE.position,
        status: POSITION_STATUS.holding,
      })
    })

    it('非法流转返回 null', () => {
      const result = transitionStatus(
        POOL_TYPE.intention, INTENTION_STATUS.archived,
        POOL_TYPE.position, POSITION_STATUS.holding
      )
      expect(result).toBeNull()
    })
  })
})

/**
 * @doc [V9-DOC-PROJ-002, V9-DOC-BACK-010, V9-DOC-ARCH-008, V9-DOC-BACK-012, V9-DOC-PROJ-003]
 */
import { getLogger } from '@/lib/logger'
import {
  INTENTION_STATUS,
  POSITION_STATUS,
  RESEARCH_STATUS,
  POOL_TYPE,
  type PoolType,
  type PoolStatus,
} from '@/constants/pool.constants'
import type { PoolTransitionTarget } from '@/types/modules/pool.types'

const logger = getLogger()

/**
 * POOL_TRANSITIONS
 *
 * 三分拆后流转规则：
 * - intention: screening → watchlist → archived
 * - research: candidate → screened → deepDive → watching → archived
 * - position: holding → partial → closed
 * - 跨池：research.watching → position.holding（买入）
 *        position.closed → research.archived（清仓后归档）
 */
export const POOL_TRANSITIONS: Record<
  PoolType,
  Partial<Record<PoolStatus, { next: PoolTransitionTarget[]; label: string }>>
> = {
  [POOL_TYPE.intention]: {
    [INTENTION_STATUS.screening]: {
      next: [
        { pool: POOL_TYPE.intention, status: INTENTION_STATUS.watchlist, label: '加入观察' },
        { pool: POOL_TYPE.intention, status: INTENTION_STATUS.archived, label: '归档' },
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.candidate, label: '晋升研究' },
      ],
      label: '初步筛选',
    },
    [INTENTION_STATUS.watchlist]: {
      next: [
        { pool: POOL_TYPE.intention, status: INTENTION_STATUS.archived, label: '归档' },
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.candidate, label: '晋升研究' },
      ],
      label: '观察列表',
    },
    [INTENTION_STATUS.archived]: {
      next: [
        { pool: POOL_TYPE.intention, status: INTENTION_STATUS.screening, label: '恢复筛选' },
      ],
      label: '已归档',
    },
  },
  [POOL_TYPE.research]: {
    [RESEARCH_STATUS.candidate]: {
      next: [
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.screened, label: '精选研究' },
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.archived, label: '归档' },
      ],
      label: '研究候选',
    },
    [RESEARCH_STATUS.screened]: {
      next: [
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.deepDive, label: '深度研究' },
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.archived, label: '归档' },
      ],
      label: '精选研究',
    },
    [RESEARCH_STATUS.deepDive]: {
      next: [
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.watching, label: '加入观察' },
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.archived, label: '归档' },
      ],
      label: '深度研究',
    },
    [RESEARCH_STATUS.watching]: {
      next: [
        { pool: POOL_TYPE.position, status: POSITION_STATUS.holding, label: '买入持仓' },
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.archived, label: '归档' },
      ],
      label: '观察池',
    },
    [RESEARCH_STATUS.archived]: {
      next: [
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.candidate, label: '恢复候选' },
      ],
      label: '已归档',
    },
  },
  [POOL_TYPE.position]: {
    [POSITION_STATUS.holding]: {
      next: [
        { pool: POOL_TYPE.position, status: POSITION_STATUS.partial, label: '减仓' },
        { pool: POOL_TYPE.position, status: POSITION_STATUS.closed, label: '清仓' },
      ],
      label: '持仓中',
    },
    [POSITION_STATUS.partial]: {
      next: [
        { pool: POOL_TYPE.position, status: POSITION_STATUS.closed, label: '清仓' },
      ],
      label: '部分减仓',
    },
    [POSITION_STATUS.closed]: {
      next: [
        { pool: POOL_TYPE.research, status: RESEARCH_STATUS.archived, label: '归档研究' },
      ],
      label: '已清仓',
    },
  },
}

/**
 * 获取指定池/状态的下一跳选项。
 */
export function getPoolTransitionOptions(
  pool: PoolType,
  status: PoolStatus,
): PoolTransitionTarget[] {
  const transitions = POOL_TRANSITIONS[pool]?.[status]
  if (!transitions) {
    logger.warn(`[PoolTransition] 未找到流转定义: pool="${pool}", status="${status}"`)
    return []
  }
  return transitions.next
}

/**
 * 获取池/状态标签。
 */
export function getPoolLabel(pool: PoolType, status: PoolStatus): string {
  const label = POOL_TRANSITIONS[pool]?.[status]?.label
  if (!label) {
    logger.warn(`[PoolTransition] 未找到标签: pool="${pool}", status="${status}"`)
    return `${pool}:${status}`
  }
  return label
}

/**
 * 校验流转是否合法。
 */
export function isValidTransition(
  fromPool: PoolType,
  fromStatus: PoolStatus,
  toPool: PoolType,
  toStatus: PoolStatus,
): boolean {
  const options = getPoolTransitionOptions(fromPool, fromStatus)
  const isValid = options.some(
    (opt) => opt.pool === toPool && opt.status === toStatus,
  )
  if (isValid) {
    logger.info(
      `[PoolTransition] isValidTransition: valid, from="${fromPool}:${fromStatus}" → to="${toPool}:${toStatus}"`,
    )
  } else {
    logger.warn(
      `[PoolTransition] isValidTransition: invalid, from="${fromPool}:${fromStatus}" → to="${toPool}:${toStatus}", allowed=${JSON.stringify(options)}`,
    )
  }
  return isValid
}

/**
 * 获取流转标签。
 */
export function getTransitionLabel(
  fromPool: PoolType,
  fromStatus: PoolStatus,
  toPool: PoolType,
  toStatus: PoolStatus,
): string {
  const options = getPoolTransitionOptions(fromPool, fromStatus)
  const match = options.find(
    (opt) => opt.pool === toPool && opt.status === toStatus,
  )
  return match?.label ?? '流转'
}

/**
 * 执行状态流转（纯计算函数）。
 */
export function transitionStatus(
  fromPool: PoolType,
  fromStatus: PoolStatus,
  toPool: PoolType,
  toStatus: PoolStatus,
): { pool: PoolType; status: PoolStatus } | null {
  logger.debug(
    `[PoolTransition] transitionStatus() called: from="${fromPool}:${fromStatus}" → to="${toPool}:${toStatus}"`,
  )

  if (!isValidTransition(fromPool, fromStatus, toPool, toStatus)) {
    logger.error(
      `[PoolTransition] transitionStatus() failed: Invalid transition from="${fromPool}:${fromStatus}" to="${toPool}:${toStatus}"`,
    )
    return null
  }

  logger.info(
    `[PoolTransition] transitionStatus() success: from="${fromPool}:${fromStatus}" → to="${toPool}:${toStatus}"`,
  )
  return { pool: toPool, status: toStatus }
}

/**
 * @module core/routeGuard
 * @lifecycle @Global
 * @description 模块化边界检查器 — 提供路由级舱室隔离和按钮级敏感操作防护
 *
 * ⚠️ 架构定位：这是**模块化边界检查器**，不是完整的 RBAC 权限系统。
 * - 路由级：确保路由属于已注册的舱室类别（防止非法路径注入）
 * - 按钮级：保护各舱室的敏感操作（导出/删除/重置等）
 * - 无用户身份概念：所有检查对所有访问者一视同仁（静态白名单）
 *
 * 与其他访问控制体系的关系（三层防护）：
 *   L1 路由守卫  ← 本文件（前端舱室边界 + 敏感按钮防护）
 *   L2 数据 ACL  ← acl.ts / ACL_MATRIX（DataBridge 层模块-存储-操作矩阵）
 *   L3 RBAC 体系  ← services/rbac/（用户-角色-权限，服务层可用，前端待集成）
 *
 * 安全原则：
 * - 默认拒绝：未注册的模块/按钮一律拒绝访问
 * - 白名单模式：仅显式注册的操作才放行
 * - 深度防御：路由守卫是第一道防线，数据 ACL 是核心防线
 *
 * 使用方式：
 * 1. 在 App.tsx 中用 <GuardedRoute> 替换 <Route>
 * 2. 在组件中调用 hasPermission({ module: 'trading', level: 'button', action: 'export' })
 * 3. 新模块接入时调用 registerButtonPermission() 注册敏感操作
 *
 * @doc [V9-DOC-SEC-001, V9-DOC-ARCH-008, V9-DOC-BACK-012]
 */

import React, { type ReactNode } from 'react'
import { Navigate, Route, useLocation } from 'react-router'
import { getLogger } from '@/lib/logger'
import { ROUTE_WHITELIST } from '@/config/routes'

const logger = getLogger()

// ============================================================================
// 权限类型定义
// ============================================================================

export type PermissionLevel = 'route' | 'module' | 'button' | 'crud'
export type CrudAction = 'create' | 'read' | 'update' | 'delete'

export interface PermissionContext {
  module: string
  level: PermissionLevel
  action?: string
  storeName?: string
}

export type PermissionChecker = (ctx: PermissionContext) => boolean

// ============================================================================
// 按钮级权限注册表
// ============================================================================

/** 按钮级权限规则：module → action[]（白名单模式） */
const buttonPermissionRegistry: Record<string, Set<string>> = {}

/**
 * 注册按钮级权限规则
/**
 * registerButtonPermission
 * @param module
 * @param actions
 * @returns void
 */
export function registerButtonPermission(module: string, actions: string[]): void {
  buttonPermissionRegistry[module] = new Set(actions)
  logger.debug(`[routeGuard] 注册按钮权限: module=${module}, actions=${actions.join(',')}`)
}

/**
 * 路由级白名单 — 与 routes.ts 的 RouteCategory 保持一致
 * 不使用 MODULE_ID（数据库模块ID），因为路由类别与数据库模块是不同概念
 */
const ALLOWED_ROUTE_CATEGORIES: ReadonlyArray<string> = [
  'portal',
  'input',
  'analysis',
  'trading',
  'output',
  'command',
  'system',
  'other',
]

/**
 * 检查是否拥有指定权限
/**
 * hasPermission
 */
export const hasPermission: PermissionChecker = (ctx): boolean => {
  // Route 级：检查模块是否在路由白名单中，同时验证路径合法性
  if (ctx.level === 'route') {
    if (!ALLOWED_ROUTE_CATEGORIES.includes(ctx.module)) return false
    // 若提供了 storeName（此处复用为路径前缀），检查是否在 ROUTE_WHITELIST 中
    const sn = ctx.storeName ?? ''
    if (sn !== '' && ROUTE_WHITELIST.size > 0 && !ROUTE_WHITELIST.has(sn)) {
      return false
    }
    return true
  }

  // Module 级：检查模块是否已注册
  if (ctx.level === 'module') {
    return Object.keys(buttonPermissionRegistry).includes(ctx.module)
  }

  // Button 级：检查 action 是否在模块白名单中
  if (ctx.level === 'button') {
    const act = ctx.action ?? ''
    if (act === '') return false
    const actions = buttonPermissionRegistry[ctx.module]
    if (!actions) return false // 未注册的模块默认拒绝（安全优先）
    return actions.has(act)
  }

  // CRUD 级：委托给 ACL_MATRIX（已在 acl.ts 中实现）
  if (ctx.level === 'crud') {
    return true // ACL_MATRIX 已处理
  }

  return true
}

/**
 * React Hook：在组件中检查按钮级权限
 *
 * @example
 * const canExport = usePermission('trading', 'button', 'export')
 * if (!canExport) return <Button disabled>导出（无权限）</Button>
/**
 * usePermission
 */
export function usePermission(
  module: string,
  level: PermissionLevel = 'button',
  action?: string,
): boolean {
  return hasPermission({ module, level, action })
}

// ============================================================================
// 路由守卫组件
// ============================================================================

export interface RouteGuardProps {
  children: ReactNode
  /** 模块ID，用于路由级鉴权 */
  module?: string
  /** 未授权时重定向到哪个路径 */
  redirectTo?: string
}

/**
 * 路由守卫组件 — 包裹在 Route element 中使用
 *
 * @example
 * <Route path="/trading" element={
 *   <RouteGuard module="trading">
 *     <TradingApp />
 *   </RouteGuard>
 * } />
 */
export function RouteGuard({
  children,
  module,
  redirectTo = '/',
}: RouteGuardProps): React.JSX.Element | null {
  const location = useLocation()

  // 如果指定了模块，检查路由级权限
  if ((module ?? '') !== '' && !hasPermission({ module: module!, level: 'route' })) {
    logger.warn(`[RouteGuard] 访问被拒绝: path="${location.pathname}", module="${module}"`)
    return <Navigate to={redirectTo} replace state={{ from: location }} />
  }

  return <>{children}</>
}

/**
 * 受保护的路由组件 — 替代原有的 <Route> 直接渲染
 *
 * @example
 * <GuardedRoute path="/trading" module="trading" component={TradingApp} />
 */
export interface GuardedRouteProps {
  path: string
  component: React.ComponentType
  module?: string
  redirectTo?: string
}

/**
 * GuardedRoute
 */
export function GuardedRoute({
  path,
  component: Component,
  module,
  redirectTo,
}: GuardedRouteProps): React.JSX.Element {
  return (
    <Route
      path={path}
      element={
        <RouteGuard module={module} redirectTo={redirectTo}>
          <Component />
        </RouteGuard>
      }
    />
  )
}

