/**
 * @module debugToolkit
 * @description 统一的 Debug 日志工具类。
 *
 * 核心能力：
 * 1. **命名空间隔离**：每个模块用 `createDebugLogger('HotSector')` 创建独立实例，
 *    日志自动带 `[HotSector]` 前缀，方便控制台筛选。
 * 2. **日志收集**：所有日志写入 `window.__debugLogs` 环形缓冲区（默认 500 条），
 *    支持在控制台用 `getDebugLogs('HotSector')` 快速检索。
 * 3. **计时器**：`time(label)` / `timeEnd(label)` 测量异步耗时（如并发采集）。
 * 4. **按命名空间开关**：`enableNamespace()` / `disableNamespace()` 精确控制。
 * 5. **生产环境静默**：`setEnabled(false)` 一键关闭所有 debug 输出。
 *
 * @example
 * ```ts
 * const debug = createDebugLogger('CollectBadge')
 * debug.log('handleCollectAll 开始', { symbols: ['000001.SZ'] })
 * // → console: [CollectBadge] handleCollectAll 开始 { symbols: ['000001.SZ'] }
 *
 * debug.time('collect-all')
 * await fetchAll()
 * debug.timeEnd('collect-all')  // → [CollectBadge] collect-all: 1234ms
 *
 * // 控制台检索：
 * getDebugLogs('CollectBadge')  // → 返回该命名空间的所有日志
 * ```
 */

/* eslint-disable no-console */

// ──────────────────────────────────────────────
// 类型定义
// ──────────────────────────────────────────────

export type DebugLevel = 'log' | 'info' | 'warn' | 'error' | 'debug'

export interface DebugLogEntry {
  /** 命名空间，如 'HotSector'、'CollectBadge' */
  namespace: string
  /** 日志级别 */
  level: DebugLevel
  /** 时间戳（ms） */
  ts: number
  /** 日志消息 */
  message: string
  /** 附加上下文对象 */
  context?: unknown
  /** 计时器标记（仅 timeEnd 条目有值） */
  durationMs?: number
}

export interface DebugLogger {
  log(message: string, context?: unknown): void
  info(message: string, context?: unknown): void
  warn(message: string, context?: unknown): void
  error(message: string, context?: unknown): void
  debug(message: string, context?: unknown): void
  /** 启动计时器 */
  time(label: string): void
  /** 结束计时器并输出耗时 */
  timeEnd(label: string): void
  /** 当前命名空间（用于动态判断） */
  readonly namespace: string
}

// ──────────────────────────────────────────────
// 内部状态
// ──────────────────────────────────────────────

/** 全局开关，false 时所有 debug 日志静默 */
let globalEnabled = true

/** 命名空间黑名单（被禁用的命名空间不输出） */
const disabledNamespaces = new Set<string>()

/** 环形缓冲区最大容量 */
const MAX_LOGS = 500

/** 日志缓冲区（挂在 window 上方便控制台检索） */
interface WindowWithDebug extends Window {
  __debugLogs?: DebugLogEntry[]
}
const win = typeof window !== 'undefined' ? (window as WindowWithDebug) : undefined

if (win && !win.__debugLogs) {
  win.__debugLogs = []
}

/** 计时器存储：key = `${namespace}:${label}` */
const timers = new Map<string, number>()

// ──────────────────────────────────────────────
// 核心实现
// ──────────────────────────────────────────────

/**
 * 将日志写入环形缓冲区
 */
function pushLog(entry: DebugLogEntry): void {
  if (!win?.__debugLogs) return
  const logs = win.__debugLogs
  if (logs.length >= MAX_LOGS) {
    logs.shift() // 超出容量，丢弃最旧的
  }
  logs.push(entry)
}

/**
 * 格式化上下文对象为可读字符串
 */
function formatContext(context: unknown): string {
  if (context === undefined || context === null) return ''
  if (typeof context === 'string') return context
  try {
    return JSON.stringify(context)
  } catch {
    if (typeof context === 'object') return '[object Object]'
    // context is primitive (number/boolean/bigint/symbol/function), String() is safe
    // eslint-disable-next-line @typescript-eslint/no-base-to-string
    return String(context)
  }
}

/**
 * 判断指定命名空间是否应该输出日志
 */
function shouldOutput(namespace: string): boolean {
  if (!globalEnabled) return false
  if (disabledNamespaces.has(namespace)) return false
  return true
}

/**
 * 输出日志到 console 并写入缓冲区
 */
function emit(namespace: string, level: DebugLevel, message: string, context?: unknown): void {
  const ts = Date.now()
  const ctxStr = formatContext(context)
  const prefix = `[${namespace}]`

  // 写入缓冲区（即使全局关闭也记录，方便事后检索）
  pushLog({ namespace, level, ts, message, context })

  // 控制台输出（受开关控制）
  if (!shouldOutput(namespace)) return

  const logFn = console[level] ?? console.log
  if (ctxStr) {
    logFn(`${prefix} ${message}`, context ?? '')
  } else {
    logFn(`${prefix} ${message}`)
  }
}

// ──────────────────────────────────────────────
// 公开 API
// ──────────────────────────────────────────────

/**
 * 创建带命名空间的 Debug Logger。
 *
 * @param namespace - 命名空间，如 'HotSector'、'CollectBadge'
 * @returns DebugLogger 实例
 *
 * @example
 * ```ts
 * const debug = createDebugLogger('HotSector')
 * debug.log('加入板块', { code: '半导体' })
 * // → [HotSector] 加入板块 { code: '半导体' }
 * ```
 */
export function createDebugLogger(namespace: string): DebugLogger {
  return {
    namespace,
    log(message: string, context?: unknown) {
      emit(namespace, 'log', message, context)
    },
    info(message: string, context?: unknown) {
      emit(namespace, 'info', message, context)
    },
    warn(message: string, context?: unknown) {
      emit(namespace, 'warn', message, context)
    },
    error(message: string, context?: unknown) {
      emit(namespace, 'error', message, context)
    },
    debug(message: string, context?: unknown) {
      emit(namespace, 'debug', message, context)
    },
    time(label: string) {
      const key = `${namespace}:${label}`
      timers.set(key, Date.now())
    },
    timeEnd(label: string) {
      const key = `${namespace}:${label}`
      const start = timers.get(key)
      if (start === undefined) {
        emit(namespace, 'warn', `timeEnd("${label}") 未找到对应 time() 调用`)
        return
      }
      timers.delete(key)
      const durationMs = Date.now() - start
      pushLog({ namespace, level: 'log', ts: Date.now(), message: `${label}: ${durationMs}ms`, durationMs })
      if (shouldOutput(namespace)) {
        console.log(`[${namespace}] ${label}: ${durationMs}ms`)
      }
    },
  }
}

// ──────────────────────────────────────────────
// 全局控制函数
// ──────────────────────────────────────────────

/**
 * 全局开关。设为 false 后所有 debug 日志停止控制台输出（缓冲区仍记录）。
 * @param enabled - 是否启用
 */
export function setDebugEnabled(enabled: boolean): void {
  globalEnabled = enabled
}

/**
 * 禁用指定命名空间的控制台输出。
 * @param namespace - 命名空间
 */
export function disableDebugNamespace(namespace: string): void {
  disabledNamespaces.add(namespace)
}

/**
 * 重新启用指定命名空间。
 * @param namespace - 命名空间
 */
export function enableDebugNamespace(namespace: string): void {
  disabledNamespaces.delete(namespace)
}

/**
 * 从缓冲区检索日志。
 *
 * @param namespace - 可选，传则只返回该命名空间的日志；不传则返回全部
 * @param level - 可选，按级别过滤
 * @returns 日志条目数组
 *
 * @example
 * ```ts
 * // 在浏览器控制台执行：
 * getDebugLogs('CollectBadge')  // 获取采集相关日志
 * getDebugLogs('HotSector', 'warn')  // 获取热门板块的 warn 日志
 * ```
 */
export function getDebugLogs(namespace?: string, level?: DebugLevel): DebugLogEntry[] {
  const logs = win?.__debugLogs ?? []
  return logs.filter((entry) => {
    if ((namespace ?? '') !== '' && entry.namespace !== namespace) return false
    if (level && entry.level !== level) return false
    return true
  })
}

/**
 * 清空日志缓冲区。
 */
export function clearDebugLogs(): void {
  if (win?.__debugLogs) {
    win.__debugLogs.length = 0
  }
}

/**
 * 将日志缓冲区导出为可读的文本格式（方便复制分享）。
 *
 * @param namespace - 可选，仅导出该命名空间
 * @returns 格式化的日志文本
 */
export function exportDebugLogs(namespace?: string): string {
  const logs = getDebugLogs(namespace)
  return logs
    .map((entry) => {
      const time = new Date(entry.ts).toLocaleTimeString('zh-CN', { hour12: false })
      const ctx = formatContext(entry.context)
      const dur = (entry.durationMs ?? 0) !== 0 ? ` (${entry.durationMs}ms)` : ''
      return `[${time}] [${entry.namespace}] [${entry.level.toUpperCase()}] ${entry.message}${dur}${ctx ? ' ' + ctx : ''}`
    })
    .join('\n')
}
// 控制台全局暴露（浏览器环境直接 window.getDebugLogs 可用）
if (typeof window !== 'undefined') {
  const w = window as unknown as Record<string, unknown>
  if (w.getDebugLogs === undefined) w.getDebugLogs = getDebugLogs
  if (w.exportDebugLogs === undefined) w.exportDebugLogs = exportDebugLogs
  if (w.clearDebugLogs === undefined) w.clearDebugLogs = clearDebugLogs
  if (w.setDebugEnabled === undefined) w.setDebugEnabled = setDebugEnabled
  if (w.enableDebugNamespace === undefined) w.enableDebugNamespace = enableDebugNamespace
  if (w.disableDebugNamespace === undefined) w.disableDebugNamespace = disableDebugNamespace
  if (w.createDebugLogger === undefined) w.createDebugLogger = createDebugLogger
  if (w.__debugLogs === undefined) w.__debugLogs = []
}

/**
 * 派生查询记忆化缓存工具（v2 带 VERBOSE 日志埋点）
 *
 * 用于缓存 Store 派生查询结果，避免每次渲染重算。
 * 三种缓存策略：
 *   1. memoizeByRef：基于输入引用的记忆化（适用于 Zustand 状态数组）
 *   2. memoizeByKey：基于参数 hash 的记忆化（适用于带参数派生）
 *   3. buildIndex：列表转 Map 索引（O(1) 查找替代 O(n) filter）
 *
 * v2 增强：memoizeByRef 添加 VERBOSE 日志埋点，记录缓存命中与失效
 *   启用方式：环境变量 AUDIT_VERBOSE=1 或 VERBOSE=1 或 window.__DEBUG_DERIVED__=true
 *   日志格式：[DerivedCache] hit/miss fnName inputRef=0x... resultRef=0x...
 *
 * @module lib/derivedCache
 * @since v2.2.0
 * @updated v2.3.0 添加 VERBOSE 日志埋点
 * @compliance AGENTS.md §一 lib 层依赖规则：仅依赖 core/ 和 config/
  * @doc [V9-DOC-FRONT-037]
*/

// ═══════════════════════════════════════════════════════════════
// VERBOSE 模式开关
// ═══════════════════════════════════════════════════════════════

const VERBOSE =
  (typeof import.meta !== 'undefined' && import.meta.env?.VITE_AUDIT_VERBOSE === '1') ||
  (typeof import.meta !== 'undefined' && import.meta.env?.VITE_VERBOSE === '1') ||
  (typeof globalThis !== 'undefined' && (globalThis as { __DEBUG_DERIVED__?: boolean }).__DEBUG_DERIVED__ === true)

/**
 * 缓存统计计数器（用于性能分析）
 */
interface CacheStats {
  hits: number
  misses: number
  totalCalls: number
}

const cacheStatsMap = new Map<string, CacheStats>()

/**
 * memoizeByRef 实例重置函数列表（用于测试隔离）
 * 每次创建 memoizeByRef 时注册一个 reset 函数，resetAllMemoCaches() 调用所有 reset
 */
const memoResetFns: Array<() => void> = []

/**
 * 获取或创建缓存统计计数器
 */
function getCacheStats(name: string): CacheStats {
  let stats = cacheStatsMap.get(name)
  if (!stats) {
    stats = { hits: 0, misses: 0, totalCalls: 0 }
    cacheStatsMap.set(name, stats)
  }
  return stats
}

/**
 * 获取对象引用的短哈希（用于日志展示）
 */
function refHash(obj: unknown): string {
  if (obj === null || obj === undefined) return 'null'
  // 利用 Object.prototype.toString 获取内部属性
  const str = Object.prototype.toString.call(obj)
  // 取后 8 位作为短哈希
  let hash = 0
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i)
    hash |= 0
  }
  return '0x' + (hash >>> 0).toString(16).padStart(8, '0')
}

/**
 * VERBOSE 日志输出
 */
function logVerbose(msg: string): void {
  if (VERBOSE) {
    // eslint-disable-next-line no-console
    console.log(`\x1b[36m[DerivedCache]\x1b[0m ${msg}`)
  }
}

/**
 * 重置所有缓存统计（用于测试）
 */
export function resetCacheStats(): void {
  cacheStatsMap.clear()
}

/**
 * 重置所有 memoizeByRef 实例的内部缓存（用于测试隔离）
 * 清除所有 memoizeByRef 的 lastInput/lastResult/hasCached 状态，
 * 确保下次调用必定 miss，从而保证测试间缓存状态隔离。
 */
export function resetAllMemoCaches(): void {
  for (const reset of memoResetFns) {
    reset()
  }
}

/**
 * 获取所有缓存统计快照（用于测试断言）
 */
export function getCacheStatsSnapshot(): Record<string, CacheStats> {
  const result: Record<string, CacheStats> = {}
  for (const [name, stats] of cacheStatsMap) {
    result[name] = { ...stats }
  }
  return result
}

// ═══════════════════════════════════════════════════════════════
// memoizeByRef：基于引用的记忆化（带 VERBOSE 日志埋点）
// ═══════════════════════════════════════════════════════════════

/**
 * 基于引用的记忆化函数
 *
 * 当输入引用未变时（Zustand 保证未修改时引用不变），直接返回缓存结果。
 * 适用于无参数或单参数派生查询。
 *
 * v2 增强：添加 VERBOSE 日志埋点
 *   - 命中时输出：[DerivedCache] hit <fnName> inputRef=0x... resultRef=0x...
 *   - 失效时输出：[DerivedCache] miss <fnName> inputRef=0x... (was 0x...) computing...
 *
 * @param fn 原始计算函数
 * @param name 函数名（用于日志标识，默认从 fn.name 推断）
 *
 * @example
 * const memoizedDistribution = memoizeByRef(
 *   (scores: V6Score[]) => scores.filter(s => s.total >= 80).length,
 *   'scoreLevelDistribution'
 * )
 * // scores 引用未变时，直接返回缓存结果
/**
 * memoizeByRef
 */
export function memoizeByRef<TInput, TResult>(
  fn: (input: TInput) => TResult,
  name?: string,
): (input: TInput) => TResult {
  const fnName = name ?? fn.name ?? 'anonymous'
  let lastInput: TInput | undefined
  let lastResult: TResult | undefined
  let hasCached = false

  // 注册重置函数，供 resetAllMemoCaches() 调用（测试隔离用）
  memoResetFns.push(() => {
    lastInput = undefined
    lastResult = undefined
    hasCached = false
  })

  return (input: TInput): TResult => {
    const stats = getCacheStats(fnName)
    stats.totalCalls++

    if (hasCached && input === lastInput && lastResult !== undefined) {
      // 缓存命中
      stats.hits++
      logVerbose(
        `hit ${fnName} inputRef=${refHash(input)} resultRef=${refHash(lastResult)} ` +
        `(hits=${stats.hits}/${stats.totalCalls})`
      )
      return lastResult
    }

    // 缓存未命中（引用变化或首次调用）
    stats.misses++
    const wasRef = hasCached ? refHash(lastInput) : 'none'
    logVerbose(
      `miss ${fnName} inputRef=${refHash(input)} (was ${wasRef}) computing... ` +
      `(misses=${stats.misses}/${stats.totalCalls})`
    )

    lastInput = input
    lastResult = fn(input)
    hasCached = true

    logVerbose(`computed ${fnName} resultRef=${refHash(lastResult)}`)
    return lastResult
  }
}

// ═══════════════════════════════════════════════════════════════
// memoizeByKey：基于参数 hash 的记忆化
// ═══════════════════════════════════════════════════════════════

/**
 * 基于参数 hash 的记忆化函数
 *
 * 适用于带参数的派生查询，如 bySymbol(symbol)。
 * 注意：hash 基于 JSON.stringify，参数需可序列化。
 */
export function memoizeByKey<TArgs extends unknown[], TResult>(
  fn: (...args: TArgs) => TResult,
  name?: string,
): (...args: TArgs) => TResult {
  const fnName = name ?? fn.name ?? 'anonymousByKey'
  const cache = new Map<string, TResult>()

  return (...args: TArgs): TResult => {
    const stats = getCacheStats(fnName)
    stats.totalCalls++

    const key = JSON.stringify(args)
    const cached = cache.get(key)
    if (cached !== undefined) {
      stats.hits++
      logVerbose(`hit ${fnName} key=${key.slice(0, 50)} (hits=${stats.hits}/${stats.totalCalls})`)
      return cached
    }

    stats.misses++
    logVerbose(`miss ${fnName} key=${key.slice(0, 50)} computing... (misses=${stats.misses}/${stats.totalCalls})`)
    const result = fn(...args)
    cache.set(key, result)
    return result
  }
}

// ═══════════════════════════════════════════════════════════════
// buildIndex：列表转 Map 索引
// ═══════════════════════════════════════════════════════════════

/**
 * 列表转 Map 索引（按指定 key）
 * 用于高频字段查找优化，将 O(n) filter 降为 O(1) Map.get。
 */
export function buildIndex<T, K extends string | number>(
  list: readonly T[],
  keyFn: (item: T) => K,
): Map<K, T> {
  const map = new Map<K, T>()
  for (const item of list) {
    map.set(keyFn(item), item)
  }
  return map
}

/**
 * 列表转 Map 索引（按 key 分组，一对多）
 */
export function buildGroupIndex<T, K extends string | number>(
  list: readonly T[],
  keyFn: (item: T) => K,
): Map<K, T[]> {
  const map = new Map<K, T[]>()
  for (const item of list) {
    const key = keyFn(item)
    const group = map.get(key)
    if (group) {
      group.push(item)
    } else {
      map.set(key, [item])
    }
  }
  return map
}

// ═══════════════════════════════════════════════════════════════
// 辅助函数
// ═══════════════════════════════════════════════════════════════

/**
 * 安全访问数组长度（null/undefined 返回 0）
 */
export function safeLength<T>(arr: readonly T[] | null | undefined): number {
  return arr?.length ?? 0
}

/**
 * 安全除法（除数为 0 返回 0）
 */
export function safeDivide(numerator: number, denominator: number): number {
  if (denominator === 0) return 0
  return numerator / denominator
}

/**
 * 数组平均值（空数组返回 0）
 */
export function average(values: readonly number[]): number {
  if (values.length === 0) return 0
  let sum = 0
  for (const v of values) {
    sum += v
  }
  return sum / values.length
}

/**
 * @module LocalStorageManager
 * @description 统一 localStorage 封装，支持命名空间隔离、JSON 序列化、TTL 过期、
 *              容量监控与批量操作。解决原生 localStorage 的以下痛点：
 *              - 无命名空间，key 容易冲突
 *              - 仅支持字符串，需手动序列化/反序列化
 *              - 无过期机制，数据永久残留
 *              - 无容量监控，超出配额静默失败
 *
 * v0.9.16 安全增强（audit-b4-4-security STOR-001 / STOR-003）：
 * - 新增 setEncrypted / getEncrypted 方法，使用 Web Crypto API (AES-GCM) 加密敏感字段
 * - 加密 key 派生自设备指纹（浏览器+origin），防止跨站攻击
 * - 加密失败时降级为不存储，避免明文回退
  * @doc [V9-DOC-FRONT-037]
*/

import { getLogger } from '@/lib/logger'
import {
  type EncryptedPayload,
  getOrCreateCryptoKey,
  generateIv,
  arrayBufferToBase64,
  base64ToArrayBuffer,
} from './localStorageCrypto'

const logger = getLogger()

// ============================================================
// 常量
// ============================================================

/** localStorage 标准容量上限 (5MB = 5,242,880 bytes) */
const STORAGE_MAX_BYTES = 5_242_880

/** 默认命名空间前缀分隔符 */
const NS_SEPARATOR = ':'

/** 默认过期时间（毫秒），0 表示永不过期 */
const DEFAULT_TTL = 0

// ============================================================
// 类型定义
// ============================================================

/** 存储条目包装结构 */
interface StorageEntry<T = unknown> {
  /** 命名空间 */
  ns: string
  /** 实际数据 */
  value: T
  /** 创建时间戳 (ms) */
  createdAt: number
  /** 过期时间戳 (ms)，0 表示永不过期 */
  expiresAt: number
  /** 数据版本号 */
  version: number
}

/** LocalStorageManager 配置选项 */
export interface LocalStorageOptions {
  /** 命名空间，用于 key 前缀隔离 */
  namespace?: string
  /** 默认 TTL 毫秒数，默认 0（永不过期） */
  defaultTTL?: number
  /** 容量警告阈值（0-1），默认 0.8（占用超过 80% 时发出警告） */
  capacityWarningThreshold?: number
}

/** 存储容量信息 */
export interface StorageCapacity {
  /** 已使用字节数 */
  usedBytes: number
  /** 总容量字节数 */
  totalBytes: number
  /** 使用率（0-1） */
  usageRatio: number
  /** 是否超过警告阈值 */
  isWarning: boolean
}

/** 命名空间信息 */
export interface NamespaceInfo {
  namespace: string
  keyCount: number
  totalBytes: number
  oldestEntry: string | null
  newestEntry: string | null
}

// ============================================================
// 工具函数
// ============================================================

function utf8ByteCount(code: number): number {
  if (code < 0x80) return 1
  if (code < 0x800) return 2
  return 3
}

/**
 * 计算字符串的 UTF-8 字节长度。
 */
function byteLength(str: string): number {
  // 使用 Blob API 精确计算，回退到估算
  try {
    return new Blob([str]).size
  } catch {
    // 回退：英文 1 字节，中文 3 字节，其他 2 字节
    let len = 0
    for (let i = 0; i < str.length; i++) {
      len += utf8ByteCount(str.charCodeAt(i))
    }
    return len
  }
}

// ============================================================
// LocalStorageManager 实现
// ============================================================

/**
 * LocalStorageManager
 */
export class LocalStorageManager {
  private namespace: string
  private defaultTTL: number
  private capacityWarningThreshold: number

  constructor(options: LocalStorageOptions = {}) {
    this.namespace = options.namespace ?? 'app'
    this.defaultTTL = options.defaultTTL ?? DEFAULT_TTL
    this.capacityWarningThreshold = options.capacityWarningThreshold ?? 0.8

    logger.debug(`[LocalStorageManager:${this.namespace}] 初始化完成，TTL=${this.defaultTTL}ms, capacityThreshold=${this.capacityWarningThreshold}`)
  }

  // ============================================================
  // 公共 API：基础 CRUD
  // ============================================================

  /**
   * 读取存储值。
   * 自动检测过期，过期条目删除并返回 null。
   */
  get<T = unknown>(key: string): T | null {
    const fullKey = this.makeKey(key)
    const raw = localStorage.getItem(fullKey)

    if (raw === null) {
      return null
    }

    try {
      const entry = JSON.parse(raw) as StorageEntry<T>

      // 检查过期
      if (entry.expiresAt > 0 && Date.now() > entry.expiresAt) {
        localStorage.removeItem(fullKey)
        logger.debug(`[LocalStorageManager:${this.namespace}] EXPIRED: key="${key}"`)
        return null
      }

      return entry.value
    } catch (err) {
      logger.warn(`[LocalStorageManager:${this.namespace}] 反序列化失败: key="${key}"`, { error: err })
      // 损坏的数据直接删除
      localStorage.removeItem(fullKey)
      return null
    }
  }

  /**
   * 写入存储值。
   */
  set<T = unknown>(key: string, value: T, ttl?: number): void {
    const effectiveTTL = ttl ?? this.defaultTTL
    const entry: StorageEntry<T> = {
      ns: this.namespace,
      value,
      createdAt: Date.now(),
      expiresAt: effectiveTTL > 0 ? Date.now() + effectiveTTL : 0,
      version: 1,
    }

    const fullKey = this.makeKey(key)
    const raw = JSON.stringify(entry)

    try {
      localStorage.setItem(fullKey, raw)
      logger.debug(`[LocalStorageManager:${this.namespace}] SET: key="${key}", size=${byteLength(raw)}B, TTL=${effectiveTTL}ms`)

      // 写入后检查容量
      this.checkCapacity()
    } catch (err) {
      if (err instanceof DOMException && err.name === 'QuotaExceededError') {
        logger.error(`[LocalStorageManager:${this.namespace}] 存储配额已满，写入失败: key="${key}"`)
        throw new Error(`localStorage 配额已满，无法写入 key="${key}"。请清理过期数据或减少存储量。`)
      }
      throw err
    }
  }

  /**
   * 删除指定存储条目。
   */
  remove(key: string): void {
    const fullKey = this.makeKey(key)
    localStorage.removeItem(fullKey)
    logger.debug(`[LocalStorageManager:${this.namespace}] REMOVE: key="${key}"`)
  }

  // ============================================================
  // 公共 API：加密存储（v0.9.16 STOR-001）
  // ============================================================

  /**
   * 写入加密存储值。
   *
   * 使用 Web Crypto API (AES-GCM) 对 value 进行加密后存储。
   * 加密 key 派生自命名空间 + 浏览器 origin，避免跨站攻击。
   * 若 Web Crypto API 不可用（如非 HTTPS 环境），降级为不存储并抛出错误。
   *
   * @param key 存储 key
   * @param value 待加密的值
   * @param ttl 过期时间（毫秒）
   */
  async setEncrypted<T = unknown>(key: string, value: T, ttl?: number): Promise<void> {
    const cryptoKey = await getOrCreateCryptoKey(this.namespace)
    const plaintext = JSON.stringify(value)
    const iv = generateIv()

    const ciphertext = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv },
      cryptoKey,
      new TextEncoder().encode(plaintext),
    )

    const payload: EncryptedPayload = {
      __encrypted: true,
      iv: arrayBufferToBase64(iv),
      data: arrayBufferToBase64(ciphertext),
      createdAt: Date.now(),
      expiresAt: (ttl ?? this.defaultTTL) > 0 ? Date.now() + (ttl ?? this.defaultTTL) : 0,
      version: 1,
    }

    const fullKey = this.makeKey(key)
    const raw = JSON.stringify(payload)

    try {
      localStorage.setItem(fullKey, raw)
      logger.debug(`[LocalStorageManager:${this.namespace}] SET(encrypted): key="${key}", size=${byteLength(raw)}B`)
      this.checkCapacity()
    } catch (err) {
      if (err instanceof DOMException && err.name === 'QuotaExceededError') {
        logger.error(`[LocalStorageManager:${this.namespace}] 存储配额已满，加密写入失败: key="${key}"`)
        throw new Error(`localStorage 配额已满，无法写入 key="${key}"。`)
      }
      throw err
    }
  }

  /**
   * 读取加密存储值。
   *
   * 自动解密并返回原始值。若条目未加密、已过期或解密失败，返回 null。
   *
   * @param key 存储 key
   */
  async getEncrypted<T = unknown>(key: string): Promise<T | null> {
    const fullKey = this.makeKey(key)
    const raw = localStorage.getItem(fullKey)

    if (raw === null) return null

    try {
      const payload = JSON.parse(raw) as EncryptedPayload

      // 兼容旧版非加密条目：直接返回 null（不降级为明文读取，防止明文回退攻击）
      if (!payload.__encrypted) {
        logger.warn(`[LocalStorageManager:${this.namespace}] 检测到明文条目，已忽略: key="${key}"`)
        localStorage.removeItem(fullKey)
        return null
      }

      // 过期检查
      if (payload.expiresAt > 0 && Date.now() > payload.expiresAt) {
        localStorage.removeItem(fullKey)
        logger.debug(`[LocalStorageManager:${this.namespace}] EXPIRED(encrypted): key="${key}"`)
        return null
      }

      const cryptoKey = await getOrCreateCryptoKey(this.namespace)
      const iv = base64ToArrayBuffer(payload.iv)
      const ciphertext = base64ToArrayBuffer(payload.data)

      const plaintext = await crypto.subtle.decrypt(
        { name: 'AES-GCM', iv },
        cryptoKey,
        ciphertext,
      )

      return JSON.parse(new TextDecoder().decode(plaintext)) as T
    } catch (err) {
      logger.warn(`[LocalStorageManager:${this.namespace}] 加密条目解密失败: key="${key}"`, { error: err })
      localStorage.removeItem(fullKey)
      return null
    }
  }

  /**
   * 检查指定 key 是否存在且未过期。
   */
  has(key: string): boolean {
    return this.get(key) !== null
  }

  /**
   * 获取当前命名空间下的所有 key 列表。
   */
  keys(): string[] {
    const prefix = this.getPrefix()
    const result: string[] = []

    for (let i = 0; i < localStorage.length; i++) {
      const fullKey = localStorage.key(i)
      if (fullKey !== null && fullKey.startsWith(prefix)) {
        result.push(fullKey.slice(prefix.length))
      }
    }

    return result
  }

  // ============================================================
  // 公共 API：批量操作
  // ============================================================

  /**
   * 批量获取当前命名空间下的所有有效条目。
   */
  getAll<T = unknown>(): Record<string, T> {
    const result: Record<string, T> = {}
    const keys = this.keys()

    for (const key of keys) {
      const value = this.get<T>(key)
      if (value !== null) {
        result[key] = value
      }
    }

    return result
  }

  /**
   * 清除当前命名空间下的所有条目（包括过期条目）。
   */
  clearNamespace(): void {
    const keys = this.getAllKeysInNamespace()
    for (const fullKey of keys) {
      localStorage.removeItem(fullKey)
    }
    logger.info(`[LocalStorageManager:${this.namespace}] 已清除命名空间下 ${keys.length} 条数据`)
  }

  /**
   * 清除当前命名空间下的过期条目。
   * @returns 清理的条目数
   */
  purgeExpired(): number {
    const keys = this.keys()
    let count = 0

    for (const key of keys) {
      if (this.get(key) === null) {
        // get 方法内部已自动删除过期条目
        count++
      }
    }

    if (count > 0) {
      logger.debug(`[LocalStorageManager:${this.namespace}] 清理了 ${count} 条过期数据`)
    }
    return count
  }

  // ============================================================
  // 公共 API：容量监控
  // ============================================================

  /**
   * 获取当前存储容量信息。
   */
  getCapacity(): StorageCapacity {
    let usedBytes = 0

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if ((key ?? '') !== '') {
        usedBytes += LocalStorageManager.accumulateKeyBytes(key!)
      }
    }

    const usageRatio = usedBytes / STORAGE_MAX_BYTES

    return {
      usedBytes,
      totalBytes: STORAGE_MAX_BYTES,
      usageRatio,
      isWarning: usageRatio >= this.capacityWarningThreshold,
    }
  }

  /**
   * 获取当前命名空间统计信息。
   */
  getNamespaceInfo(): NamespaceInfo {
    const keys = this.getAllKeysInNamespace()
    let totalBytes = 0
    let oldestEntry: string | null = null
    let newestEntry: string | null = null
    let oldestTime = Infinity
    let newestTime = 0

    for (const fullKey of keys) {
      const raw = localStorage.getItem(fullKey)
      if (raw === null || raw === '') {
        continue
      }

      totalBytes += byteLength(fullKey) + byteLength(raw)

      try {
        const entry = JSON.parse(raw) as StorageEntry
        const updated = this.computeOldestNewest(entry, fullKey, oldestTime, newestTime, oldestEntry, newestEntry)
        oldestTime = updated.oldestTime
        newestTime = updated.newestTime
        oldestEntry = updated.oldestEntry
        newestEntry = updated.newestEntry
      } catch { console.warn('[localStorageManager.ts] 忽略解析失败, using fallback') }
    }

    return {
      namespace: this.namespace,
      keyCount: keys.length,
      totalBytes,
      oldestEntry,
      newestEntry,
    }
  }

  private computeOldestNewest(
    entry: StorageEntry,
    fullKey: string,
    oldestTime: number,
    newestTime: number,
    oldestEntry: string | null,
    newestEntry: string | null,
  ): { oldestTime: number; newestTime: number; oldestEntry: string | null; newestEntry: string | null } {
    const prefixLength = this.getPrefix().length
    if (entry.createdAt < oldestTime) {
      oldestTime = entry.createdAt
      oldestEntry = fullKey.slice(prefixLength)
    }
    if (entry.createdAt > newestTime) {
      newestTime = entry.createdAt
      newestEntry = fullKey.slice(prefixLength)
    }
    return { oldestTime, newestTime, oldestEntry, newestEntry }
  }

  // ============================================================
  // 静态方法：全局操作
  // ============================================================

  /**
   * 累计单个 key 在 localStorage 中占用的字节数（含 key 与 value）。
   */
  private static accumulateKeyBytes(key: string): number {
    const value = localStorage.getItem(key)
    if (value === null || value === '') return 0
    return byteLength(key) + byteLength(value)
  }

  /**
   * 从完整 key 中提取命名空间前缀；无分隔符或前缀为空时返回 null。
   */
  private static extractNamespace(key: string): string | null {
    const sepIndex = key.indexOf(NS_SEPARATOR)
    return sepIndex > 0 ? key.slice(0, sepIndex) : null
  }

  /**
   * 列出所有已知命名空间。
   */
  static listNamespaces(): string[] {
    const nsSet = new Set<string>()

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if ((key ?? '') !== '') {
        const ns = LocalStorageManager.extractNamespace(key!)
        if (ns !== null) nsSet.add(ns)
      }
    }

    return Array.from(nsSet).sort()
  }

  /**
   * 清除所有命名空间的数据。
   */
  static clearAll(): void {
    const count = localStorage.length
    localStorage.clear()
    logger.info(`[LocalStorageManager] 已清除全部 ${count} 条数据`)
  }

  /**
   * 获取全局容量信息。
   */
  static getGlobalCapacity(): StorageCapacity {
    let usedBytes = 0

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if ((key ?? '') !== '') {
        usedBytes += LocalStorageManager.accumulateKeyBytes(key!)
      }
    }

    const usageRatio = usedBytes / STORAGE_MAX_BYTES

    return {
      usedBytes,
      totalBytes: STORAGE_MAX_BYTES,
      usageRatio,
      isWarning: usageRatio >= 0.8,
    }
  }

  // ============================================================
  // 私有方法
  // ============================================================

  /**
   * 拼接命名空间前缀与 key。
   */
  private makeKey(key: string): string {
    return `${this.getPrefix()}${key}`
  }

  /**
   * 获取命名空间前缀。
   */
  private getPrefix(): string {
    return `${this.namespace}${NS_SEPARATOR}`
  }

  /**
   * 获取当前命名空间下所有 key（含前缀的完整 key）。
   */
  private getAllKeysInNamespace(): string[] {
    const prefix = this.getPrefix()
    const result: string[] = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if ((key ?? '') !== '' && key!.startsWith(prefix)) {
        result.push(key!)
      }
    }

    return result
  }

  /**
   * 检查容量并在超过阈值时发出警告。
   */
  private checkCapacity(): void {
    const cap = this.getCapacity()
    if (cap.isWarning) {
      logger.warn(
        `[LocalStorageManager:${this.namespace}] 容量警告: ` +
        `已使用 ${(cap.usedBytes / 1024).toFixed(1)}KB / ${(cap.totalBytes / 1024).toFixed(0)}KB ` +
        `(${(cap.usageRatio * 100).toFixed(1)}%)`,
      )
    }
  }
}

