// Fallback 日志查询与 CSV 导出
// ============================================================

export interface FallbackLogCsvRow {
  timestamp: string
  traceId: string
  actor: string
  action: string
  targetType: string
  targetCode: string
  event: string
  fallbackFrom: string
  fallbackTo: string
  reason: string
  payload: string
}

export async function queryFallbackLogs(days = 7): Promise<ResearchLog[]> {
  const allLogs = await queryList<ResearchLog>(STORE_NAME.researchLogs)
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000
  return allLogs
    .filter((log) => log.action?.startsWith('fallback:') && log.timestamp >= cutoff)
    .sort((a, b) => b.timestamp - a.timestamp)
}

export async function exportFallbackLogsToCsv(days = 7): Promise<number> {
  const LOGGER = getLogger()
  const logs = await queryFallbackLogs(days)
  if (logs.length === 0) {
    LOGGER.warn('[logHelpers] exportFallbackLogsToCsv: 最近 {days} 天无 fallback 日志', { days })
    return 0
  }

  const rows: FallbackLogCsvRow[] = logs.map((log) => {
    let payload: Record<string, unknown> = {}
    try {
      payload = log.payload ? (JSON.parse(log.payload) as Record<string, unknown>) : {}
    } catch {
      payload = { rawPayload: log.payload ?? '' }
    }
    return {
      timestamp: new Date(log.timestamp).toISOString(),
      traceId: log.traceId,
      actor: log.actor,
      action: log.action,
      targetType: log.targetType,
      targetCode: log.targetCode,
      event: (payload.event as string) ?? log.action.replace('fallback:', ''),
      fallbackFrom: safeStr(payload.fallbackFrom),
      fallbackTo: safeStr(payload.fallbackTo),
      reason: safeStr(payload.reason),
      payload: log.payload ?? '',
    }
  })

  const headers = [
    'timestamp', 'traceId', 'actor', 'action', 'targetType', 'targetCode',
    'event', 'fallbackFrom', 'fallbackTo', 'reason', 'payload',
  ]
  const DANGEROUS_PREFIX = /^[=+\-@]/
  const escape = (val: unknown): string => {
    if (val == null) return ''
    let str: string
    if (typeof val === 'string') str = val
    else if (typeof val === 'number' || typeof val === 'boolean') str = val.toString()
    else { str = safeStr(val) }
    if (DANGEROUS_PREFIX.test(str)) str = `'${str}`
    if (str.includes(',') || str.includes('"') || str.includes('\n')) {
      return `"${str.replace(/"/g, '""')}"`
    }
    return str
  }
  const csvLines = [headers.join(',')]
  for (const row of rows) {
    csvLines.push(headers.map((h) => escape((row as unknown as Record<string, unknown>)[h])).join(','))
  }
  const csvContent = `${String.fromCharCode(0xfeff)}${csvLines.join('\n')}`

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  const dateStr = new Date().toISOString().slice(0, 10)
  link.download = `fallback-logs-${dateStr}-${days}d.csv`
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)

  LOGGER.info('[logHelpers] exportFallbackLogsToCsv 导出完成', { days, rows: rows.length })
  return rows.length
}

/**
 * @doc [V9-DOC-FRONT-037]
 */
export interface LogContext {
  [key: string]: unknown
}

export type LogLevel = 'debug' | 'info' | 'warn' | 'error'
export type LogFormat = 'pretty' | 'json'

const LOG_LEVEL_PRIORITY: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
}

const LOG_LEVEL_TAG: Record<LogLevel, string> = {
  debug: 'DEBUG',
  info: 'INFO',
  warn: 'WARN',
  error: 'ERROR',
}

let globalLevel: LogLevel = 'debug'
// 浏览器环境无 process 全局，必须 typeof 守卫，否则模块顶层抛 ReferenceError 导致整应用白屏（E2E P0）
let globalFormat: LogFormat =
  (typeof process !== 'undefined' && process.env.LOG_FORMAT as LogFormat) || 'pretty'

const LOG_FORMAT_SYMBOLS: Record<LogLevel, string> = {
  debug: '🔍',
  info: 'ℹ️',
  warn: '⚠️',
  error: '❌',
}

function shouldLog(level: LogLevel): boolean {
  return LOG_LEVEL_PRIORITY[level] >= LOG_LEVEL_PRIORITY[globalLevel]
}

function formatJson(level: LogLevel, message: string, context?: LogContext): string {
  const entry: Record<string, unknown> = {
    timestamp: new Date().toISOString(),
    level: LOG_LEVEL_TAG[level],
    message,
  }
  if (context && Object.keys(context).length > 0) {
    for (const [key, value] of Object.entries(context)) {
      if (value !== undefined) {
        entry[key] = value
      }
    }
  }
  try {
    return JSON.stringify(entry)
  } catch {
    return JSON.stringify({
      timestamp: new Date().toISOString(),
      level: LOG_LEVEL_TAG[level],
      message,
      _parseError: true,
    })
  }
}

function formatPretty(level: LogLevel, message: string, context?: LogContext): string {
  const now = new Date()
  const timeStr = now.toLocaleTimeString('zh-CN', { hour12: false })
  const symbol = LOG_FORMAT_SYMBOLS[level]
  if (context && Object.keys(context).length > 0) {
    return `${symbol} [${timeStr}] [${LOG_LEVEL_TAG[level]}] ${message} ${JSON.stringify(context)}`
  }
  return `${symbol} [${timeStr}] [${LOG_LEVEL_TAG[level]}] ${message}`
}

/* eslint-disable no-console */
export function getLogger() {
  return {
    debug(message: string, context?: LogContext): void {
      if (shouldLog('debug')) {
        if (globalFormat === 'json') {
          console.debug(formatJson('debug', message, context))
        } else {
          console.debug(formatPretty('debug', message), context ?? {})
        }
      }
    },
    info(message: string, context?: LogContext): void {
      if (shouldLog('info')) {
        if (globalFormat === 'json') {
          console.log(formatJson('info', message, context))
        } else {
          console.log(formatPretty('info', message), context ?? {})
        }
      }
    },
    warn(message: string, context?: LogContext): void {
      if (shouldLog('warn')) {
        if (globalFormat === 'json') {
          console.warn(formatJson('warn', message, context))
        } else {
          console.warn(formatPretty('warn', message), context ?? {})
        }
      }
    },
    error(message: string, context?: LogContext): void {
      if (shouldLog('error')) {
        if (globalFormat === 'json') {
          console.error(formatJson('error', message, context))
        } else {
          console.error(formatPretty('error', message), context ?? {})
        }
      }
    },
  }
}

/**
 * setLogLevel
 * @param level
 * @returns void
 */
export function setLogLevel(level: LogLevel): void {
  globalLevel = level
}

/**
 * setLogFormat
 * @param format 'pretty'（默认，人可读）| 'json'（ELK 结构化日志）
 * @returns void
 */
export function setLogFormat(format: LogFormat): void {
  globalFormat = format
}

/**
 * getLogFormat
 * @returns 当前日志格式
 */
export function getLogFormat(): LogFormat {
  return globalFormat
}

/**
 * 金融数值精度工具
 * v0.9.11 P2-TS002
 * 用途：统一处理股票价格、涨跌幅、百分比等数值的精度控制
  * @doc [V9-DOC-FRONT-037]
*/

// 小数位精度常量
/**
 * 小数位精度常量：统一控制价格、涨跌幅、百分比、成交量等精度。
 */
export const PRECISION = {
  PRICE: 2,       // 股票价格：2位小数
  CHANGE: 2,      // 涨跌额：2位小数
  CHANGE_RATE: 2, // 涨跌幅：2位小数（百分比）
  PERCENT: 1,     // 百分比：1位小数
  VOLUME: 0,      // 成交量：整数
  AMOUNT: 2,      // 成交额：2位小数
} as const

/**
 * 格式化价格（自动处理精度）
 * @param value 数值
 * @param decimals 小数位数，默认2位
 * @returns 格式化后的价格字符串，无效值返回 '--'
 */
export function formatPrice(value: number | undefined | null, decimals: number = PRECISION.PRICE): string {
  if (value == null || isNaN(value)) return '--'
  return value.toFixed(decimals)
}

/**
 * 格式化涨跌幅（%）
 * @param value 涨跌幅数值（如 5.23 表示 5.23%）
 * @returns 带正负号和百分号的字符串，无效值返回 '--'
 */
export function formatChangeRate(value: number | undefined | null): string {
  if (value == null || isNaN(value)) return '--'
  const sign = value >= 0 ? '+' : ''
  return `${sign}${value.toFixed(PRECISION.CHANGE_RATE)}%`
}

/**
 * 格式化涨跌额
 * @param value 涨跌额数值
 * @returns 带正负号的字符串，无效值返回 '--'
 */
export function formatChange(value: number | undefined | null): string {
  if (value == null || isNaN(value)) return '--'
  const sign = value >= 0 ? '+' : ''
  return `${sign}${value.toFixed(PRECISION.CHANGE)}`
}

/**
 * 格式化成交量（万/亿单位）
 * @param value 成交量数值
 * @param unit 显示单位，'auto'自动选择，'wan'万，'yi'亿
 * @returns 格式化后的成交量字符串
 */
export function formatVolume(value: number | undefined | null, unit: 'auto' | 'wan' | 'yi' = 'auto'): string {
  if (value == null || isNaN(value)) return '--'

  if (unit === 'wan' || (unit === 'auto' && value < 100000000)) {
    const wan = value / 10000
    return `${wan.toFixed(PRECISION.VOLUME)}万`
  }

  const yi = value / 100000000
  return `${yi.toFixed(2)}亿`
}

/**
 * 格式化成交额（万/亿单位）
 * @param value 成交额数值（元）
 * @param unit 显示单位，'auto'自动选择，'wan'万，'yi'亿
 * @returns 格式化后的成交额字符串
 */
export function formatAmount(value: number | undefined | null, unit: 'auto' | 'wan' | 'yi' = 'auto'): string {
  if (value == null || isNaN(value)) return '--'

  if (unit === 'wan' || (unit === 'auto' && value < 100000000)) {
    const wan = value / 10000
    return `${wan.toFixed(PRECISION.AMOUNT)}万`
  }

  const yi = value / 100000000
  return `${yi.toFixed(PRECISION.AMOUNT)}亿`
}

/**
 * 格式化百分比
 * @param value 0-1之间的小数或数值
 * @param decimals 小数位数
 * @returns 带百分号的字符串
 */
export function formatPercent(value: number | undefined | null, decimals: number = PRECISION.PERCENT): string {
  if (value == null || isNaN(value)) return '--'
  // 如果值大于1，假设是百分比形式（如 50 表示 50%）
  const percentValue = value > 1 ? value : value * 100
  return `${percentValue.toFixed(decimals)}%`
}

/**
 * 安全数组索引访问（配合 noUncheckedIndexedAccess）
 * @param arr 数组
 * @param index 索引
 * @param fallback 越界时的默认值
 * @returns 数组元素或默认值
 */
export function safeArrayGet<T>(arr: T[], index: number): T | undefined
/**
 * 安全获取数组元素（配合 noUncheckedIndexedAccess），支持越界返回 fallback。
 * @param arr 数组
 * @param index 索引
 * @param fallback 越界时的默认值
 * @returns 数组元素或默认值
 */
export function safeArrayGet<T>(arr: T[], index: number, fallback: T): T
/**
 * 安全获取数组元素（配合 noUncheckedIndexedAccess），无 fallback 重载。
 * @param arr 数组
 * @param index 索引
 * @returns 数组元素或 undefined
 */
export function safeArrayGet<T>(arr: T[], index: number, fallback?: T): T | undefined {
  return arr[index] ?? fallback
}

/**
 * 安全获取数组第一个元素（配合 noUncheckedIndexedAccess）
 * @param arr 数组
 * @returns 第一个元素或 undefined
 */
export function safeFirst<T>(arr: T[]): T | undefined {
  return arr[0]
}

/**
 * 安全获取数组最后一个元素（配合 noUncheckedIndexedAccess）
 * @param arr 数组
 * @returns 最后一个元素或 undefined
 */
export function safeLast<T>(arr: T[]): T | undefined {
  return arr[arr.length - 1]
}

/**
 * 安全获取对象属性（链式访问）
 * @param obj 对象
 * @param keyPath 属性路径，如 'a.b.c'
 * @param fallback 默认值
 * @returns 属性值或默认值
 */
export function safeGet<T>(obj: Record<string, unknown> | null | undefined, keyPath: string, fallback: T): T {
  if (obj == null) return fallback

  const keys = keyPath.split('.')
  let current: unknown = obj

  for (const key of keys) {
    if (current == null || typeof current !== 'object') return fallback
    current = (current as Record<string, unknown>)[key]
  }

  return (current as T) ?? fallback
}

/**
 * 补充：金融数值格式化
 * v0.9.11 P2-DATA003
 */

// 大数格式化（万/亿）
/**
 * 格式化大数：值 >= 1 亿转"亿"单位，>= 1 万转"万"单位。
 * @param value 数值
 * @param _unit 基础单位（默认"万"）
 * @returns 格式化字符串，如"12.34亿"
 */
export function formatLargeNumber(value: number | undefined | null, _unit = '万'): string {
  if (value == null || isNaN(value)) return '--'
  if (Math.abs(value) >= 100000000) {
    return `${(value / 100000000).toFixed(2)}亿`
  }
  if (Math.abs(value) >= 10000) {
    return `${(value / 10000).toFixed(2)}万`
  }
  return value.toFixed(2)
}

// 涨跌幅颜色（配合 COLOR_TOKENS）
/**
 * 根据涨跌幅值返回颜色标识（配合 COLOR_TOKENS）。
 * @param value 涨跌幅值
 * @returns 'up' | 'down' | 'neutral'
 */
export function getChangeColor(value: number): 'up' | 'down' | 'neutral' {
  if (value > 0) return 'up'
  if (value < 0) return 'down'
  return 'neutral'
}

// 格式化市值
/**
 * 格式化市值为可读字符串。
 * @param value 市值数值
 * @returns 格式化字符串
 */
export function formatMarketCap(value: number | undefined | null): string {
  return formatLargeNumber(value, '万')
}

// 格式化成交量
/**
 * 格式化成交量为可读字符串。
 * @param value 成交量数值
 * @returns 格式化字符串
 */
export function formatShares(value: number | undefined | null): string {
  if (value == null || isNaN(value)) return '--'
  return formatLargeNumber(value, '股')
}

