  operation: DbOperation,
): boolean {
  const allowedModules = getUserRoleAllowedModules(role)
  if (!allowedModules.includes(module)) {
    return false
  }
  const modulePermission = ACL_MATRIX[module]
  if (!modulePermission) {
    return false
  }
  if (!modulePermission.actions.includes(operation)) {
    return false
  }
  return true
}

/**
 * checkDeveloperRolePermission
 */
export function checkDeveloperRolePermission(
  role: DeveloperRole,
  module: ModuleId,
  operation: DbOperation,
): boolean {
  const allowedModules = getDeveloperRoleAllowedModules(role)
  if (!allowedModules.includes(module)) {
    return false
  }
  const modulePermission = ACL_MATRIX[module]
  if (!modulePermission) {
    return false
  }
  if (!modulePermission.actions.includes(operation)) {
    return false
  }
  return true
}

/**
 * checkUserRoleDbOperation
 */
export function checkUserRoleDbOperation(
  role: UserRole,
  module: ModuleId,
  action: string,
): boolean {
  let operation: DbOperation
  if (action.includes('INSERT') || action.includes('SAVE') || action.includes('INGEST')) {
    operation = DB_OPERATION.insert
  } else if (action.includes('UPDATE')) {
    operation = DB_OPERATION.update
  } else if (action.includes('DELETE') || action.includes('CLEAR')) {
    operation = DB_OPERATION.delete
  } else {
    operation = DB_OPERATION.select
  }
  return checkUserRolePermission(role, module, operation)
}

/**
 * checkDeveloperRoleDbOperation
 */
export function checkDeveloperRoleDbOperation(
  role: DeveloperRole,
  module: ModuleId,
  action: string,
): boolean {
  let operation: DbOperation
  if (action.includes('INSERT') || action.includes('SAVE') || action.includes('INGEST')) {
    operation = DB_OPERATION.insert
  } else if (action.includes('UPDATE')) {
    operation = DB_OPERATION.update
  } else if (action.includes('DELETE') || action.includes('CLEAR')) {
    operation = DB_OPERATION.delete
  } else {
    operation = DB_OPERATION.select
  }
  return checkDeveloperRolePermission(role, module, operation)
}

/**
 * @fileoverview 简单可播种的伪随机数生成器（mulberry32）
 *
 * 用于性能压测等需要可重复结果的场景。未传 seed 时使用 Math.random。
 *
 * @module lib/seededRandom
 * @created 2026-07-13
/** 创建一个可播种的随机数生成器，返回 [0,1) 之间的数  * @doc [V9-DOC-FRONT-037]
*/
export function createSeededRandom(seed: number): () => number {
  let s = seed | 0
  return () => {
    s = (s + 0x6d2b79f5) | 0
    let t = Math.imul(s ^ (s >>> 15), 1 | s)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** 在 [min, max] 之间取随机整数 */
export function randInt(min: number, max: number, rng: () => number = Math.random): number {
  return Math.floor(rng() * (max - min + 1)) + min
}

/** Fisher-Yates 洗牌 */
export function shuffle<T>(arr: T[], rng: () => number = Math.random): T[] {
  const sh = [...arr]
  for (let i = sh.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    const si = sh[i]
    const sj = sh[j]
    if (si == null || sj == null) continue
    sh[i] = sj
    sh[j] = si
  }
  return sh
}

/** 随机选取 N 个元素 */
export function pickRandom<T>(arr: T[], count: number, rng?: () => number): T[] {
  return shuffle(arr, rng).slice(0, count)
}

/**
 * 数据验证工具
 * v0.9.11 P2-DATA
 * 用途：确保数据流入符合数据类型和范围约束
 *
 * v0.9.16 安全增强（audit-b4-4-security）：
 * - 新增 LLM 配置字段格式校验（VAL-001）
 * - 新增股票代码严格校验（A股/港股/美股）（VAL-003）
 * - 新增 URL 协议白名单校验（XSS-003）
