*/

import { safeRegex } from './safeRegex'

// ============================================================
// 配置名称验证
// ============================================================

/** 配置名称最大长度 */
const CONFIG_NAME_MAX_LENGTH = 50

/** 配置名称最小长度 */
const CONFIG_NAME_MIN_LENGTH = 1

/** 配置名称禁止的字符（文件系统敏感字符 + XSS 相关字符） */
const CONFIG_NAME_FORBIDDEN_CHARS = /[<>{}[\]|\\:*?"`]/

/** 配置名称禁止的控制字符 */
function containsControlChars(name: string): boolean {
  return name.split('').some((char) => {
    const code = char.charCodeAt(0)
    return (code >= 0x00 && code <= 0x1f) || code === 0x7f
  })
}

/**
 * 配置名称校验结果
 */
export interface ConfigNameValidationResult {
  valid: boolean
  error?: string
}

/**
 * 校验配置模板名称的合法性。
 *
 * 规则：
 * 1. 不能为空或纯空格
 * 2. 长度在 1-50 字符之间
 * 3. 禁止文件系统敏感字符（<>{}[]|\\:*?"`）
 * 4. 禁止控制字符
 * 5. 禁止 HTML 标签注入（<script>、<img> 等）
 * 6. 禁止危险协议（javascript:、data: 等）
 *
 * @param name 待校验的配置名称
 * @returns 校验结果（valid + 可选 error 信息）
 */
export function validateConfigName(name: string): ConfigNameValidationResult {
  if (typeof name !== 'string') {
    return { valid: false, error: '名称必须为字符串' }
  }

  const trimmed = name.trim()

  if (trimmed.length === 0) {
    return { valid: false, error: '名称不能为空' }
  }

  if (trimmed.length < CONFIG_NAME_MIN_LENGTH) {
    return { valid: false, error: `名称长度不能少于 ${CONFIG_NAME_MIN_LENGTH} 个字符` }
  }

  if (trimmed.length > CONFIG_NAME_MAX_LENGTH) {
    return { valid: false, error: `名称长度不能超过 ${CONFIG_NAME_MAX_LENGTH} 个字符` }
  }

  if (CONFIG_NAME_FORBIDDEN_CHARS.test(trimmed)) {
    return { valid: false, error: '名称不能包含特殊字符（<>{}[]|\\:*?"`）' }
  }

  if (containsControlChars(trimmed)) {
    return { valid: false, error: '名称不能包含控制字符' }
  }

  // XSS 防护：检测 HTML 标签
  if (/<[a-zA-Z][^>]*>/.test(trimmed)) {
    return { valid: false, error: '名称不能包含 HTML 标签' }
  }

  // XSS 防护：检测危险协议
  if (/^(javascript|vbscript|data|file):/i.test(trimmed)) {
    return { valid: false, error: '名称不能以危险协议开头' }
  }

  return { valid: true }
}

// ============================================================
// 股票代码相关验证
// ============================================================

/** A股代码：6位数字（含 SH/SZ/BJ 交易所） */
const A_SHARE_CODE_REGEX = /^\d{6}$/

/** 港股代码：5位数字 */
const HK_SHARE_CODE_REGEX = /^\d{5}$/

/** 美股代码：1-5 位字母，可选 .交易所后缀（1-2 位，如 AAPL.US） */
const US_SHARE_CODE_REGEX = /^[A-Z]{1,5}(?:\.[A-Z]{1,2})?$/

/** 股票代码格式验证（6位数字，兼容 A 股） */
export function isValidStockCode(code: string): boolean {
  return A_SHARE_CODE_REGEX.test(code)
}

/** 股票代码格式化（补零，仅适用于 A 股纯数字代码） */
export function formatStockCode(code: string | number): string {
  const str = String(code)
  // 非纯数字（如港股 00700.HK、美股 AAPL）原样返回，避免被错误补零成 '0AAPL'
  if (!/^\d+$/.test(str)) return str
  return str.padStart(6, '0')
}

/**
 * 严格的股票代码格式校验，支持 A 股 / 港股 / 美股。
 *
 * @param code 股票代码
 * @param market 市场类型，未指定时仅校验 A 股 6 位数字
 * @returns 是否合法
 */
export function isValidStockCodeStrict(
  code: string,
  market?: 'A' | 'HK' | 'US',
): boolean {
  if (typeof code !== 'string' || code.length === 0) return false
  const trimmed = code.trim()

  switch (market) {
    case 'A':
      return A_SHARE_CODE_REGEX.test(trimmed)
    case 'HK':
      return HK_SHARE_CODE_REGEX.test(trimmed)
    case 'US':
      return US_SHARE_CODE_REGEX.test(trimmed.toUpperCase())
    default:
      // 默认仅校验 A 股 6 位数字
      return A_SHARE_CODE_REGEX.test(trimmed)
  }
}

/**
 * 验证带交易所后缀的股票代码（如 600519.SH、00700.HK、AAPL.US）。
 */
export function isValidSymbolWithExchange(symbol: string): boolean {
  if (typeof symbol !== 'string' || symbol.length === 0) return false
  // 格式：CODE.EXCHANGE，如 600519.SH、000001.SZ、00700.HK
  return /^\d{6}\.(SH|SZ|BJ)$/i.test(symbol.trim())
}

// ============================================================
// 数值范围验证
// ============================================================

/** 百分比范围验证（0-100） */
export function isValidPercent(value: number): boolean {
  if (typeof value !== 'number' || isNaN(value)) return false
  return value >= 0 && value <= 100
}

/** 评分范围验证（0-100） */
export function isValidScore(value: number): boolean {
  if (typeof value !== 'number' || isNaN(value)) return false
  return value >= 0 && value <= 100
}

/** 价格正数验证 */
export function isValidPrice(value: number): boolean {
  if (typeof value !== 'number' || isNaN(value)) return false
  return value > 0 && isFinite(value)
}

/** 空值处理 */
export function safeValue<T>(value: T | null | undefined, fallback: T): T {
  return value ?? fallback
}

/**
 * 安全数字解析：返回有效数字或默认值，过滤 NaN/Infinity。
 *
 * @param value 原始值（string/number）
 * @param fallback 默认值
 * @param min 最小值（可选）
 * @param max 最大值（可选）
 */
export function safeParseNumber(
  value: unknown,
  fallback: number,
  min?: number,
  max?: number,
): number {
  if (value === null || value === undefined || value === '') return fallback
  const num = typeof value === 'number' ? value : Number(value)
  if (!isFinite(num) || isNaN(num)) return fallback
  if (min !== undefined && num < min) return min
  if (max !== undefined && num > max) return max
  return num
}

// ============================================================
// LLM 配置校验（VAL-001 / XSS-003）
// ============================================================

/** 允许的 URL 协议白名单 */
const ALLOWED_URL_PROTOCOLS = ['http:', 'https:']

/** 危险的 URL 协议黑名单（明确禁止） */
const DANGEROUS_URL_PROTOCOLS = ['javascript:', 'data:', 'vbscript:', 'file:']

/**
 * 验证 LLM baseURL 是否为合法 URL 且协议在白名单内。
 *
 * - 必须是合法 URL
 * - 协议必须为 http: 或 https:
 * - 禁止 javascript:、data:、vbscript: 等危险协议
 * - 开发环境允许 http://localhost
 *
 * @param baseURL 待校验的 baseURL
 */
export function isValidLlmBaseURL(baseURL: string): boolean {
  if (typeof baseURL !== 'string' || baseURL.trim().length === 0) return false

  const trimmed = baseURL.trim()

  // 明确拒绝危险协议
  const lower = trimmed.toLowerCase()
  if (DANGEROUS_URL_PROTOCOLS.some((p) => lower.startsWith(p))) {
    return false
  }

  try {
    const url = new URL(trimmed)
    if (!ALLOWED_URL_PROTOCOLS.includes(url.protocol)) {
      return false
    }
    return true
  } catch (err) { console.warn('[validation.ts]', err);
    return false
  }
}

/**
 * 验证 LLM API Key 格式。
 *
 * 规则：
 * - 长度 8-256
 * - 仅允许字母、数字、连字符、下划线、点
 * - 不包含空白字符、引号、尖括号
 *
 * @param apiKey 待校验的 API Key
 */
export function isValidLlmApiKey(apiKey: string): boolean {
  if (typeof apiKey !== 'string' || apiKey.length === 0) return false
  const trimmed = apiKey.trim()
  if (trimmed.length < 8 || trimmed.length > 256) return false
  // 仅允许字母、数字、连字符、下划线、点、斜杠（部分厂商 key 包含）
  return /^[A-Za-z0-9._\-/]+$/.test(trimmed)
}

/**
 * 验证 LLM 模型名称格式。
 *
 * 规则：
 * - 长度 1-128
 * - 仅允许字母、数字、连字符、下划线、点、斜杠、冒号
 *
 * @param model 待校验的模型名称
 */
export function isValidLlmModel(model: string): boolean {
  if (typeof model !== 'string' || model.length === 0) return false
  const trimmed = model.trim()
  if (trimmed.length < 1 || trimmed.length > 128) return false
  return /^[A-Za-z0-9._\-/:]+$/.test(trimmed)
}

// ============================================================
// 敏感信息脱敏（LEAK-004）
// ============================================================

/**
 * 对 API Key 进行脱敏显示。
 *
 * 规则：
 * - 长度 ≤ 8：全部替换为 ****
 * - 长度 > 8：保留前 4 位 + **** + 后 4 位
 *
 * @param apiKey 原 API Key
 * @returns 脱敏后的字符串
/**
 * 脱敏通用实现：长度 ≤ 8 全替换，否则保留前 4 后 4。
 */
function maskSecret(secret: string): string {
  if (secret.length <= 8) return '****'
  return `${secret.slice(0, 4)}****${secret.slice(-4)}`
}

/**
 * 脱敏 API Key：仅保留首尾 4 位，中间替换为 ****。
 * @param apiKey 原始 API Key
 * @returns 脱敏后的字符串
 */
export function maskApiKey(apiKey: string): string {
  if (typeof apiKey !== 'string' || apiKey.length === 0) return '(empty)'
  return maskSecret(apiKey)
}

/**
 * 对 token 进行脱敏显示。
 *
 * @param token 原 token
 * @returns 脱敏后的字符串
 */
export function maskToken(token: string): string {
  if (typeof token !== 'string' || token.length === 0) return '(empty)'
  return maskSecret(token)
}

/**
 * 敏感字段名集合（小写匹配）。
 * 用于日志上下文的自动脱敏。
 */
export const SENSITIVE_FIELD_NAMES = [
  'apikey',
  'api_key',
  'api-key',
  'token',
  'accesstoken',
  'access_token',
  'refreshtoken',
  'refresh_token',
  'password',
  'passwd',
  'pwd',
  'secret',
  'authorization',
  'auth',
  'cookie',
  'session',
  'sessionid',
  'session_id',
] as const

/**
 * 判断字段名是否为敏感字段（大小写不敏感）。
 */
export function isSensitiveField(fieldName: string): boolean {
  if (typeof fieldName !== 'string') return false
  const lower = fieldName.toLowerCase()
  return SENSITIVE_FIELD_NAMES.some((sensitive) => {
    // 精确匹配
    if (lower === sensitive) return true
    // 词边界匹配，避免 "author" 误判为 "auth"、"tokenize" 误判为 "token"
    return safeRegex(`(^|[^a-z0-9_])${sensitive}([^a-z0-9_]|$)`, 'i').test(lower)
  })
}

function sanitizeValue(key: string, value: unknown, maxDepth: number, seen: WeakSet<object>): unknown {
  if (isSensitiveField(key) && typeof value === 'string') {
    return maskApiKey(value)
  }
  if (typeof value === 'object' && value !== null) {
    return sanitizeObject(value, maxDepth - 1, seen)
  }
  return value
}

/**
 * 对任意对象进行脱敏处理，递归遍历所有字段。
 *
 * 使用 WeakSet 记录已访问对象，防止循环引用导致无限递归 / 栈溢出
 * （日志上下文对象常含环引用，如事件对象互指）。
 *
 * @param obj 原始对象
 * @param maxDepth 最大递归深度（默认 5）
 * @param seen 内部使用：已访问对象集合（循环引用保护）
 * @returns 脱敏后的新对象（不修改原对象）
 */
export function sanitizeObject<T>(
  obj: T,
  maxDepth = 5,
  seen: WeakSet<object> = new WeakSet<object>(),
): T {
  if (maxDepth < 0 || obj === null || obj === undefined || typeof obj !== 'object') return obj

  // 循环引用保护：已访问过则直接返回原引用，避免栈溢出
  if (seen.has(obj)) return obj
  seen.add(obj)

  if (Array.isArray(obj)) {
    return obj.map((item: unknown) => sanitizeObject(item, maxDepth - 1, seen)) as unknown as T
  }

  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
    result[key] = sanitizeValue(key, value, maxDepth, seen)
  }
  return result as unknown as T
}

/**
 * 行情数据契约校验（Market Data Contract Validation）
 *
 * 与数据来源无关的**结构不变量**校验：OHLC 一致性、价格/量为正、
 * 日期单调递增、财务字段有限且 report_date 合法、涨跌幅区间、
 * 时间戳可信、source 合法。
 *
 * 设计目标：Mock 与真实数据走**同一套契约**，使强制 Mock 环境下
 * 仍可发现数据形态缺陷（如 OHLC 不自洽），避免 Mock 掩盖真实源解析器 bug。
 *
 * 纯函数、零服务层依赖（仅使用结构化 duck-type，不引入 services 依赖，
 * 保持 lib 层合规，可被 fetcher / data-collector 等所有 services 引用）。
 *
 * 使用方式：写入路径以 warn-only 调用（仅记日志/统计，不阻断写入）。
 *
 * @module lib/validation/marketDataContract
  * @doc [V9-DOC-FRONT-037]
*/

// ── 结构化入参（duck-type，兼容 fetcher.StockQuote / data-collector.RealtimeQuote 等）──

/** 行情结构（开放字段，兼容多种 Quote 类型） */
export interface QuoteLike {
  price?: number
  open?: number
  high?: number
  low?: number
  /** 收盘价（行情通常无此字段，缺省时以 price 作为收盘等价） */
  close?: number
  volume?: number
  amount?: number
  timestamp?: number
  changePercent?: number
  source?: string
}

/** 单根 K 线结构 */
export interface KlineBarLike {
  date?: string
  open: number
  high: number
  low: number
  close: number
  volume: number
  amount?: number
}

/** 财务结构（开放索引，兼容多种 Financial 类型） */
export interface FinancialLike {
  report_date?: string
  revenue?: number
  net_profit?: number
  gross_margin?: number
  net_margin?: number
  revenue_yoy?: number
  net_profit_yoy?: number
  rd_ratio?: number
  inventory_turnover_days?: number
  shareholder_pledge?: number
  [key: string]: unknown
}

/** 校验问题 */
export interface ValidationIssue {
  field: string
  rule: string
  severity: 'error' | 'warn'
  message: string
}

/** 校验结果 */
export interface ContractCheckResult {
  ok: boolean
  issues: ValidationIssue[]
}

// ── 常量（零硬编码）──

/** 价格比较容差 */
const PRICE_EPSILON = 1e-6
/** 合法数据源标识 */
const VALID_SOURCES = ['tencent', 'sina', 'netease', 'akshare', 'mock', 'unknown']
/** 涨跌幅合理区间（%） */
const CHANGE_PERCENT_MIN = -20
const CHANGE_PERCENT_MAX = 20
/** 时间戳偏差：未来超过 7 天即异常 */
const MAX_FUTURE_SKEW_MS = 7 * 24 * 60 * 60 * 1000
/** 时间戳过旧阈值：超过 1 年视为异常 */
const MAX_PAST_AGE_MS = 365 * 24 * 60 * 60 * 1000

const isFiniteNumber = (v: unknown): v is number =>
  typeof v === 'number' && Number.isFinite(v)

function pushIssue(
  issues: ValidationIssue[],
  field: string,
  rule: string,
  message: string,
  severity: ValidationIssue['severity'] = 'error',
): void {
  issues.push({ field, rule, severity, message })
}

/**
 * 校验单条行情。
 * 覆盖：价格为正、量/额非负、OHLC 一致性、涨跌幅区间、时间戳可信、source 合法。
 */
export function validateQuote(q: QuoteLike): ContractCheckResult {
  const issues: ValidationIssue[] = []

  if (!isFiniteNumber(q.price) || q.price <= 0) {
    pushIssue(issues, 'price', 'positive', `价格必须为正数，实际：${JSON.stringify(q.price)}`)
  }
  if (q.volume !== undefined && (!isFiniteNumber(q.volume) || q.volume < 0)) {
    pushIssue(issues, 'volume', 'nonnegative', `成交量必须非负，实际：${JSON.stringify(q.volume)}`)
  }
  if (q.amount !== undefined && (!isFiniteNumber(q.amount) || q.amount < 0)) {
    pushIssue(issues, 'amount', 'nonnegative', `成交额必须非负，实际：${JSON.stringify(q.amount)}`)
  }

  // OHLC 一致性（行情无 close 字段，以 price 作为收盘等价）
  const o = q.open
  const h = q.high
  const l = q.low
  const c = q.close ?? q.price
  if ([o, h, l, c].some((v) => !isFiniteNumber(v))) {
    pushIssue(issues, 'ohlc', 'finite', `OHLC 含非有限数：open=${o} high=${h} low=${l} close=${c}`)
  } else {
    const open = o as number
    const high = h as number
    const low = l as number
    const close = c as number
    if (high + PRICE_EPSILON < low) pushIssue(issues, 'ohlc', 'high>=low', `最高价低于最低价（high=${high} < low=${low}）`)
    if (high + PRICE_EPSILON < open) pushIssue(issues, 'ohlc', 'high>=open', `最高价低于开盘价（high=${high} < open=${open}）`)
    if (high + PRICE_EPSILON < close) pushIssue(issues, 'ohlc', 'high>=close', `最高价低于收盘价（high=${high} < close=${close}）`)
    if (low - PRICE_EPSILON > open) pushIssue(issues, 'ohlc', 'low<=open', `最低价高于开盘价（low=${low} > open=${open}）`)
    if (low - PRICE_EPSILON > close) pushIssue(issues, 'ohlc', 'low<=close', `最低价高于收盘价（low=${low} > close=${close}）`)
  }

  if (q.changePercent !== undefined && isFiniteNumber(q.changePercent)) {
    if (q.changePercent < CHANGE_PERCENT_MIN || q.changePercent > CHANGE_PERCENT_MAX) {
      pushIssue(issues, 'changePercent', 'range', `涨跌幅超出合理区间 [${CHANGE_PERCENT_MIN},${CHANGE_PERCENT_MAX}]%，实际：${q.changePercent}`)
    }
  }

  if (q.timestamp !== undefined && isFiniteNumber(q.timestamp)) {
    const now = Date.now()
    if (q.timestamp > now + MAX_FUTURE_SKEW_MS) {
      pushIssue(issues, 'timestamp', 'future', `行情时间戳在未来（${new Date(q.timestamp).toISOString()}）`)
    }
    if (q.timestamp < now - MAX_PAST_AGE_MS) {
      pushIssue(issues, 'timestamp', 'too_old', `行情时间戳超过 1 年（${new Date(q.timestamp).toISOString()}）`)
    }
  }

  if (q.source !== undefined && !VALID_SOURCES.includes(q.source)) {
    pushIssue(issues, 'source', 'valid', `未知数据源标识：${JSON.stringify(q.source)}`, 'warn')
  }

  return { ok: issues.every((i) => i.severity !== 'error'), issues }
}

/**
 * 校验单根 K 线。
 * 覆盖：OHLC 一致性、成交量非负、日期格式。
 */
export function validateKline(k: KlineBarLike): ContractCheckResult {
  const issues: ValidationIssue[] = []
  const finiteAll = [k.open, k.high, k.low, k.close].every(isFiniteNumber)
  if (!finiteAll) {
    pushIssue(issues, 'ohlc', 'finite', `K 线 OHLC 含非有限数：open=${k.open} high=${k.high} low=${k.low} close=${k.close}`)
    return { ok: false, issues }
  }
  if (k.high + PRICE_EPSILON < k.low) pushIssue(issues, 'ohlc', 'high>=low', `最高价低于最低价（high=${k.high} < low=${k.low}）`)
  if (k.high + PRICE_EPSILON < k.open) pushIssue(issues, 'ohlc', 'high>=open', `最高价低于开盘价（high=${k.high} < open=${k.open}）`)
  if (k.high + PRICE_EPSILON < k.close) pushIssue(issues, 'ohlc', 'high>=close', `最高价低于收盘价（high=${k.high} < close=${k.close}）`)
  if (k.low - PRICE_EPSILON > k.open) pushIssue(issues, 'ohlc', 'low<=open', `最低价高于开盘价（low=${k.low} > open=${k.open}）`)
  if (k.low - PRICE_EPSILON > k.close) pushIssue(issues, 'ohlc', 'low<=close', `最低价高于收盘价（low=${k.low} > close=${k.close}）`)
  if (!isFiniteNumber(k.volume) || k.volume < 0) {
    pushIssue(issues, 'volume', 'nonnegative', `成交量必须非负，实际：${JSON.stringify(k.volume)}`)
  }
  if (k.date !== undefined && !/^\d{4}-\d{2}-\d{2}$/.test(k.date)) {
    pushIssue(issues, 'date', 'format', `K 线日期格式非法（期望 YYYY-MM-DD），实际：${k.date}`, 'warn')
  }
  return { ok: issues.every((i) => i.severity !== 'error'), issues }
}

/**
 * 校验财务数据。
 * 覆盖：百分比字段有限且区间合理、存货周转天数（单位：天）单独放宽、
 * 营收为正、净利润有限、report_date 格式与年份合法。
 */
export function validateFinancial(f: FinancialLike): ContractCheckResult {
  const issues: ValidationIssue[] = []
  const finiteOrUndef = (v: unknown): v is number | undefined =>
    v === undefined || (typeof v === 'number' && Number.isFinite(v))

  // 百分比区间字段（[-200,200]）
  const pctFields = [
    'gross_margin',
    'net_margin',
    'revenue_yoy',
    'net_profit_yoy',
    'rd_ratio',
    'shareholder_pledge',
  ] as const
  for (const fld of pctFields) {
    const v = (f as Record<string, unknown>)[fld]
    if (!finiteOrUndef(v)) {
      pushIssue(issues, fld, 'finite', `${fld} 必须为有限数或 undefined，实际：${JSON.stringify(v)}`)
    } else if (typeof v === 'number' && (v < -200 || v > 200)) {
      pushIssue(issues, fld, 'range', `${fld} 超出合理区间 [-200,200]，实际：${JSON.stringify(v)}`)
    }
  }

  // 单位：天，单独放宽到 [0,2000]
  const itd = (f as Record<string, unknown>)['inventory_turnover_days']
  if (!finiteOrUndef(itd)) {
    pushIssue(issues, 'inventory_turnover_days', 'finite', `存货周转天数必须为有限数或 undefined，实际：${JSON.stringify(itd)}`)
  } else if (typeof itd === 'number' && (itd < 0 || itd > 2000)) {
    pushIssue(issues, 'inventory_turnover_days', 'range', `存货周转天数超出合理区间 [0,2000]，实际：${JSON.stringify(itd)}`)
  }

  if (f.revenue !== undefined && (!isFiniteNumber(f.revenue) || f.revenue <= 0)) {
    pushIssue(issues, 'revenue', 'positive', `营收应为正数，实际：${JSON.stringify(f.revenue)}`)
  }
  if (f.net_profit !== undefined && !isFiniteNumber(f.net_profit)) {
    pushIssue(issues, 'net_profit', 'finite', `净利润必须为有限数，实际：${JSON.stringify(f.net_profit)}`)
  }

  if (f.report_date !== undefined) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(f.report_date)) {
      pushIssue(issues, 'report_date', 'format', `报告期格式非法（期望 YYYY-MM-DD），实际：${f.report_date}`)
    } else {
      const yr = Number(f.report_date.slice(0, 4))
      const nowYear = new Date().getFullYear()
      if (yr < 1990 || yr > nowYear + 1) {
        pushIssue(issues, 'report_date', 'range', `报告期年份异常：${f.report_date}`)
      }
    }
  }

  return { ok: issues.every((i) => i.severity !== 'error'), issues }
}

/** 组合校验入参 */
export interface MarketDataContractInput {
  quote?: QuoteLike
  klines?: KlineBarLike[]
  financial?: FinancialLike
}

/**
 * 组合校验：行情 + K 线（含日期单调递增）+ 财务。
 * 任一子项失败即整体不通过（ok=false）。
 */
export function checkMarketDataContract(input: MarketDataContractInput): ContractCheckResult {
  const issues: ValidationIssue[] = []
  if (input.quote) issues.push(...validateQuote(input.quote).issues)
  if (input.financial) issues.push(...validateFinancial(input.financial).issues)
  if (input.klines && input.klines.length > 0) {
    for (let i = 0; i < input.klines.length; i++) {
      const r = validateKline(input.klines[i]!)
      for (const iss of r.issues) issues.push({ ...iss, field: `klines[${i}].${iss.field}` })
    }
    // 日期单调递增校验
    for (let i = 1; i < input.klines.length; i++) {
      const prev = input.klines[i - 1]!.date
      const cur = input.klines[i]!.date
      if (prev && cur && cur < prev) {
        pushIssue(issues, `klines[${i}].date`, 'monotonic', `K 线日期非单调递增：${prev} -> ${cur}`)
      }
    }
  }
  return { ok: issues.every((i) => i.severity !== 'error'), issues }
}

/**
 * zIndexDebugLogger.ts — 全局 z-index 调试日志工具
 *
 * 设计目标：
 *  - 在组件挂载/卸载、状态变化、弹窗显隐等阶段，快速记录真实 z-index 值
 *  - 日志格式严格对齐需求：[ISO时间戳] [Z-INDEX] 组件= 元素ID= zIndex= 阶段= 描述=?
 *  - MutationObserver 追加器：监控 root 下所有元素的 style/class 变化，
 *    若变化涉及 stacking context（zIndex / position / transform / opacity / filter / isolation）
 *    自动打日志，无需每个组件手动埋点。
 *
 * 用法（埋点示例）：
 *   import { logZIndex, logZIndexChange, installZIndexDebugAppender } from '@/lib/zIndexDebugLogger'
 *
 *   useEffect(() => {
 *     logZIndex('PortalShell', shellRef.current, 'create', 'Portal 根容器创建')
 *     const beforeZ = logZIndex('PortalShell.Header', headerRef.current, 'create')
 *     const uninstall = installZIndexDebugAppender(shellRef.current, 'PortalShell')
 *     return () => {
 *       uninstall?.()
 *       logZIndexChange('PortalShell.Header', headerRef.current, beforeZ, 'Header 生命周期 z-index 对比')
 *       logZIndex('PortalShell', shellRef.current, 'destroy')
 *     }
 *   }, [])
 */
import { getLogger } from './logger'

const logger = getLogger()

export type ZIndexLogPhase =
  | 'mount'
  | 'unmount'
  | 'before-change'
  | 'after-change'
  | 'create'
  | 'destroy'
  | 'render'
  | 'positioned'
  | 'show'
  | 'hide'
  | 'auto-change' // MutationObserver 自动检测的变更

const STACKING_TRIGGERS: ReadonlyArray<string> = [
  'z-index',
  'position',
  'transform',
  'opacity',
  'filter',
  'isolation',
  'contain',
  'will-change',
  'backdrop-filter',
]

/* ============================================================
 * 辅助：从元素读取最终 z-index（auto / 数字字符串 / unknown）
 * ========================================================== */
function readComputedZIndex(
  element: HTMLElement | SVGElement | null | undefined,
): number | string {
  if (!element) return 'none'
  if (typeof window === 'undefined' || typeof window.getComputedStyle !== 'function') return 'ssr'
  try {
    const cs = window.getComputedStyle(element)
    const z = cs.zIndex
    if (z === '' || z === null || z === undefined) return 'auto'
    return z
  } catch {
    return 'unknown'
  }
}

/* ============================================================
 * 核心 1：记录单点 z-index 快照
 * ========================================================== */
export function logZIndex(
  component: string,
  element: HTMLElement | SVGElement | null | undefined,
  phase: ZIndexLogPhase,
  description = '',
): number | string {
  const ts = new Date().toISOString()
  const id = element?.id ?? 'none'
  const zIndex = readComputedZIndex(element)
  const line =
    `[${ts}] [Z-INDEX] 组件=${component} 元素ID=${id} zIndex=${zIndex} 阶段=${phase}` +
    (description ? ` 描述=${description}` : '')
  logger.debug(line, { component, elementId: id, zIndex, phase, description })
  // 避免生产环境噪音：仅在 DEV 打 console
  if (typeof import.meta !== 'undefined' && ((import.meta as unknown as { env?: { DEV?: boolean } }).env?.DEV ?? false) === true) {
    // eslint-disable-next-line no-console
    console.debug(line)
  }
  return zIndex
}

/* ============================================================
 * 核心 2：记录 z-index 变更前后对比
 * ========================================================== */
export function logZIndexChange(
  component: string,
  element: HTMLElement | SVGElement | null | undefined,
  beforeZ: number | string | null | undefined,
  description = '',
): { before: number | string; after: number | string; changed: boolean } {
  const after = readComputedZIndex(element)
  const before = beforeZ === null || beforeZ === undefined ? 'unknown' : beforeZ
  const changed = String(before) !== String(after)
  const ts = new Date().toISOString()
  const id = element?.id ?? 'none'
  const line =
    `[${ts}] [Z-INDEX-CHG] 组件=${component} 元素ID=${id} 变更前=${before} 变更后=${after} 是否变化=${changed}` +
    (description ? ` 描述=${description}` : '')
  logger.debug(line, { component, elementId: id, before, after, changed, description })
  if (typeof import.meta !== 'undefined' && ((import.meta as unknown as { env?: { DEV?: boolean } }).env?.DEV ?? false) === true) {
    // eslint-disable-next-line no-console
    console.debug(line)
  }
  return { before, after, changed }
}

/* ============================================================
 * 核心 3：MutationObserver 追加器（仅 DEV 启用）
 *   监控 subtree：style / class / id 属性变化 → 若影响 stacking → 自动 log
 *   返回 uninstall 函数（空函数在非 DEV 环境，方便调用方不用判断）
 * ========================================================== */
export function installZIndexDebugAppender(
  root: HTMLElement | SVGElement | null | undefined,
  componentPrefix = 'App',
): () => void {
  if (!root) return () => {}
  if (typeof window === 'undefined') return () => {}
  if (typeof MutationObserver !== 'function') return () => {}
  const isDev =
    typeof import.meta !== 'undefined' &&
    ((import.meta as unknown as { env?: { DEV?: boolean } }).env?.DEV ?? false) === true
  if (!isDev) return () => {}

  const seen = new WeakSet<Node>()

  const scanNode = (node: Node): void => {
    if (!(node instanceof HTMLElement) && !(node instanceof SVGElement)) return
    if (seen.has(node)) return
    seen.add(node)
    // 只记录可能影响 stacking 的元素：有 z-index 或 有 position 非 static
    try {
      const cs = window.getComputedStyle(node)
      const position = cs.position || 'static'
      const zIndex = cs.zIndex || 'auto'
      const mayAffectStacking =
        zIndex !== 'auto' ||
        position !== 'static' ||
        (cs.transform && cs.transform !== 'none') ||
        (cs.opacity && cs.opacity !== '1') ||
        (cs.filter && cs.filter !== 'none') ||
        cs.isolation === 'isolate'
      if (!mayAffectStacking) return
      const id = node.id || node.tagName.toLowerCase()
      const line = `[${new Date().toISOString()}] [Z-INDEX] 组件=${componentPrefix}.Auto 元素ID=${id} zIndex=${zIndex} 阶段=auto-change 描述=MutationObserver 检测到 stacking 相关属性变化`
      // eslint-disable-next-line no-console
      console.debug(line)
      logger.debug(line, {
        component: `${componentPrefix}.Auto`,
        elementId: id,
        zIndex,
        phase: 'auto-change',
        position,
        transform: cs.transform,
        opacity: cs.opacity,
      })
    } catch {
      /* 忽略计算样式异常（例如跨域 iframe）*/
    }
  }

  const observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      // 属性变化：直接检查 target
      if (m.type === 'attributes') {
        const name = m.attributeName ?? ''
        const lower = name.toLowerCase()
        // 只有 style/class/id 相关变化才可能影响 stacking
        if (
          lower === 'style' ||
          lower === 'class' ||
          lower === 'id' ||
          STACKING_TRIGGERS.some((t) => lower.includes(t.replace('-', '')))
        ) {
          scanNode(m.target)
        }
        continue
      }
      // 子节点增减：扫一下新增节点的子树
      if (m.type === 'childList') {
        m.addedNodes.forEach((n) => {
          scanNode(n)
          if (n instanceof Element) {
            n.querySelectorAll<HTMLElement | SVGElement>('*').forEach(scanNode)
          }
        })
      }
    }
  })

  observer.observe(root, {
    attributes: true,
    attributeFilter: ['style', 'class', 'id'],
    childList: true,
    subtree: true,
    characterData: false,
  })

  // 首次全量扫一次
  scanNode(root)
  if (root instanceof Element) {
    root.querySelectorAll<HTMLElement | SVGElement>('*').forEach(scanNode)
  }

  return (): void => {
    try {
      observer.disconnect()
    } catch {
      /* ignore */
    }
  }
}

/**
 * MCP ACL 拦截器
 *
 * @description
 * 在 MCPClient.callTool / readResource / getPrompt 入口执行权限校验，
 * 拒绝未授权的调用并返回结构化错误。
 *
 * 与 `src/core/acl.ts` 的 AclEngine 设计对齐：
 *   - AclEngine.check() 校验数据层权限（module → store → operation）
 *   - McpAclInterceptor.check() 校验工具层权限（caller → server → tool）
 *
 * 权限校验流程：
 *   1. 从 MCP_ACL_MATRIX 获取调用方角色的权限规则
 *   2. 检查 serverName 是否在 allowedServers 中（支持 `'*'` 通配）
 *   3. 检查 resourceName 是否匹配 allowedTools 模式（支持 `'*'`、`'prefix_*'` 通配）
 *   4. 全部通过则放行，否则返回 AclDeniedResult
 *
 * @module mcp/core/mcpAclInterceptor
 * @created 2026-07-08 - P0 MCP 权限控制修复
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-002, V9-DOC-AI-007, V9-DOC-AI-005, V9-DOC-PROJ-003]
*/

import { getLogger } from '@/lib/logger'
import {
  MCP_ACL_MATRIX,
  DEFAULT_MCP_CALLER,
  type McpPermissionRule,
} from '@/config/mcpAclMatrix'
import type { McpCallerRole } from '@/types/modules/mcp.types'

const logger = getLogger()

/** 权限校验输入 */
export interface McpAclCheckInput {
  /** 调用方角色 */
  readonly caller: McpCallerRole
  /** 目标 Server 名称 */
  readonly serverName: string
  /** 目标 Tool/Resource/Prompt 名称 */
  readonly resourceName: string
}

/** 权限校验结果 */
export interface McpAclCheckResult {
  readonly allowed: boolean
  readonly reason: string
  readonly caller: McpCallerRole
  readonly serverName: string
  readonly resourceName: string
}

/**
 * 通配符匹配 —— 支持两种模式：
 *   - `'*'`：匹配任意字符串
 *   - `'prefix_*'`：匹配以 `prefix_` 开头的字符串（保留末尾下划线）
 *
 * @param pattern - 权限规则中的模式（如 `'*'`、`'list_*'`、`'health_check'`）
 * @param value - 待匹配的实际值（如 `'list_pool_items'`）
 * @returns 是否匹配
 */
function matchPattern(pattern: string, value: string): boolean {
  if (pattern === '*') return true
  if (pattern.endsWith('_*')) {
    const prefix = pattern.slice(0, -1) // 保留末尾下划线
    return value.startsWith(prefix)
  }
  if (pattern.endsWith('*')) {
    const prefix = pattern.slice(0, -1)
    return value.startsWith(prefix)
  }
  return pattern === value
}

/**
 * MCP ACL 拦截器 —— 工具层权限校验
 *
 * 使用方式：
 *   - `check(input)`：非抛出，返回 `{ allowed, reason }`
 *   - `assert(input)`：失败时抛出 `McpAclError`
 */
export class McpAclInterceptor {
  /**
   * 校验调用方是否有权访问指定 Server 的指定资源
   *
   * @returns `allowed=true` 放行；`allowed=false` 拒绝（含拒绝原因）
   */
  check({ caller, serverName, resourceName }: McpAclCheckInput): McpAclCheckResult {
    const rule: McpPermissionRule | undefined = MCP_ACL_MATRIX[caller]

    // 1. 角色不存在
    if (!rule) {
      logger.warn(`[MCP:ACL] caller role not found: ${caller}`)
      return {
        allowed: false,
        reason: `Caller role "${caller}" is not registered in MCP_ACL_MATRIX`,
        caller,
        serverName,
        resourceName,
      }
    }

    // 2. Server 级别校验
    const serverAllowed =
      rule.allowedServers.includes('*') || rule.allowedServers.includes(serverName)
    if (!serverAllowed) {
      logger.warn(
        `[MCP:ACL] server denied: caller="${caller}", server="${serverName}"`,
      )
      return {
        allowed: false,
        reason: `Caller "${caller}" is not allowed to access server "${serverName}"`,
        caller,
        serverName,
        resourceName,
      }
    }

    // 3. Tool/Resource 级别校验（通配符匹配）
    const toolAllowed = rule.allowedTools.some((pattern) =>
      matchPattern(pattern, resourceName),
    )
    if (!toolAllowed) {
      logger.warn(
        `[MCP:ACL] tool denied: caller="${caller}", server="${serverName}", tool="${resourceName}"`,
      )
      return {
        allowed: false,
        reason: `Caller "${caller}" is not allowed to call tool "${resourceName}" on server "${serverName}"`,
        caller,
        serverName,
        resourceName,
      }
    }

    logger.info(
      `[MCP:ACL] granted: caller="${caller}", server="${serverName}", tool="${resourceName}"`,
    )
    return {
      allowed: true,
      reason: 'Permission granted',
      caller,
      serverName,
      resourceName,
    }
  }

  /**
   * 断言权限（失败时抛出 McpAclError）
   *
   * @throws {McpAclError} 当权限校验失败
   */
  assert(input: McpAclCheckInput): void {
    const result = this.check(input)
    if (!result.allowed) {
      throw new McpAclError(result.reason, result)
    }
  }
}

/** MCP ACL 拒绝错误 —— 权限校验失败时抛出 */
export class McpAclError extends Error {
  constructor(
    message: string,
    public readonly detail: McpAclCheckResult,
  ) {
    super(message)
    this.name = 'McpAclError'
  }
}

/** 全局拦截器单例 */
export const mcpAclInterceptor = new McpAclInterceptor()

/**
 * 解析调用方角色（向后兼容：未传入 caller 时使用默认值）
 *
 * @param caller - 调用方角色（可选）
 * @returns 解析后的调用方角色（默认 `'agent'`）
 */
export function resolveCaller(caller?: McpCallerRole): McpCallerRole {
  return caller ?? DEFAULT_MCP_CALLER
}

/**
 * MCP Server 基类
 *
 * @description
 * 提供 MCPServer 接口的默认实现，内置 Tool/Resource/Prompt 的注册与查找。
 * 业务 Server 继承此类并重写 getTools/getResources/getPrompts 方法。
 *
 * **双端权限校验（金融级底线）**：
 *   - Client 端（防君子）：MCPClientImpl 在入口拦截，基于 caller 上下文校验
 *   - Server 端（防小人）：本基类在 callTool/readResource/getPrompt 执行前，
 *     调用 `assertServerPermission(role, resourceName)` 再次校验，
 *     防止绕过 Client 直接调用 Server 实例的越权访问
 *
 * @module mcp/core/server
 * @created 2026-07-04 - Phase 0 MCP 基础设施层建设
 * @updated 2026-07-08 - P0 新增 constructor 接收 defaultCallerRole + assertServerPermission 方法
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-002, V9-DOC-AI-007, V9-DOC-AI-005, V9-DOC-PROJ-003]
*/

import { getLogger } from '@/lib/logger'
import { safeRegex } from '@/lib/safeRegex'
import type {
  MCPServer,
  ServerInfo,
  ToolDescriptor,
  ToolResult,
  ResourceTemplate,
  ResourceContent,
  PromptTemplate,
  PromptMessage,
  McpCallerContext,
  McpCallerRole,
} from '@/types/modules/mcp.types'
import { mcpAclInterceptor, McpAclError } from './mcpAclInterceptor'

const logger = getLogger()

/** MCP Server 基类 —— 提供默认的工具/资源/Prompt 管理 + 服务端权限防御 */
export abstract class MCPServerBase implements MCPServer {
  abstract readonly info: ServerInfo

  /**
   * 该 Server 实例的默认调用方角色。
   *
   * 当 callTool/readResource/getPrompt 未传入 `context.caller` 时使用此默认值。
   * 子类可在构造时通过 `super('ui')` / `super('system')` 指定，
   * 默认 `'agent'`（向后兼容：现有 16 个 Server 子类无需修改）。
   */
  private readonly defaultCallerRole: McpCallerRole

  /** 工具缓存（按 name 索引） */
  private toolCache: Map<string, ToolDescriptor> | null = null

  /** 资源缓存（按 name 索引） */
  private resourceCache: Map<string, ResourceTemplate> | null = null

  /** Prompt 缓存（按 name 索引） */
  private promptCache: Map<string, PromptTemplate> | null = null

  /**
   * @param defaultCallerRole - 默认调用方角色（未传入 context 时使用），默认 `'agent'`
   */
  constructor(defaultCallerRole: McpCallerRole = 'agent') {
    this.defaultCallerRole = defaultCallerRole
  }

  // ============================================================
  // 子类重写方法
  // ============================================================

  /** 子类重写：返回工具列表 */
  protected getTools(): ToolDescriptor[] {
    return []
  }

  /** 子类重写：返回资源模板列表 */
  protected getResources(): ResourceTemplate[] {
    return []
  }

  /** 子类重写：返回 Prompt 模板列表 */
  protected getPrompts(): PromptTemplate[] {
    return []
  }

  // ============================================================
  // 服务端权限防御（防小人）
  // ============================================================

  /**
   * 服务端权限断言 —— 在执行工具/资源/Prompt 前校验调用方角色是否有权访问。
   *
   * **设计目的**：这是"Server 防小人"的防线。即使调用方绕过 MCPClient 直接拿到
   * Server 实例调用 callTool，Server 自身也会基于传入的 callerRole 进行权限校验，
   * 拒绝未授权的工具访问。
   *
   * **可重写**：子类可重写此方法实现自定义权限逻辑（如基于 Tool 元数据的细粒度控制、
   * 基于 args 内容的动态权限决策）。重写时建议保留 `super.assertServerPermission()`
   * 调用以维持基础 ACL 校验。
   *
   * @param role - 调用方角色（从 context.caller 或 defaultCallerRole 解析）
   * @param resourceName - 资源名称（Tool name / `readResource:xxx` / `getPrompt:xxx`）
   * @throws {McpAclError} 当权限校验失败
   */
  protected assertServerPermission(
    role: McpCallerRole,
    resourceName: string,
  ): void {
    mcpAclInterceptor.assert({
      caller: role,
      serverName: this.info.name,
      resourceName,
    })
  }

  /**
   * 解析当前调用的 caller 角色：
   * 优先使用 context.caller，未传入时回退到 this.defaultCallerRole。
   */
  private resolveCallerFromContext(context?: McpCallerContext): McpCallerRole {
    return context?.caller ?? this.defaultCallerRole
  }

  // ============================================================
  // 公共接口实现
  // ============================================================

  listTools(): ToolDescriptor[] {
    if (this.toolCache === null) {
      const tools = this.getTools()
      this.toolCache = new Map(tools.map((t) => [t.name, t]))
      logger.info(`[MCPServer:${this.info.name}] listTools() loaded ${tools.length} tools`)
    }
    return Array.from(this.toolCache.values())
  }

  async callTool(
    name: string,
    args: Record<string, unknown>,
    context?: McpCallerContext,
  ): Promise<ToolResult> {
    const startTime = performance.now()
    const caller = this.resolveCallerFromContext(context)

    // ── Server 端权限断言（防小人） ──
    // 即使调用方绕过 Client 直接调用 Server 实例，Server 自身也会拦截未授权调用
    try {
      this.assertServerPermission(caller, name)
    } catch (err) {
      if (err instanceof McpAclError) {
        logger.warn(
          `[MCPServer:${this.info.name}] callTool() ACL denied: caller="${caller}", tool="${name}"`,
        )
        return {
          content: [
            { type: 'text', text: `ACL_PERMISSION_DENIED: ${err.detail.reason}` },
          ],
          isError: true,
        }
      }
      throw err
    }

    const tools = this.listTools()
    const tool = tools.find((t) => t.name === name)

    if (!tool) {
      logger.error(`[MCPServer:${this.info.name}] callTool() tool not found: ${name}`)
      return {
        content: [{ type: 'text', text: `Tool not found: ${name}` }],
        isError: true,
      }
    }

    // P0-2 安全修复：调用前校验参数 schema，防止非法参数注入
    const validationErrors = this.validateToolArgs(tool, args)
    if (validationErrors.length > 0) {
      logger.error(`[MCPServer:${this.info.name}] callTool() validation failed: ${name}`, {
        errors: validationErrors,
      })
      return {
        content: [{ type: 'text', text: `Invalid parameters: ${validationErrors.join('; ')}` }],
        isError: true,
      }
    }

    try {
      logger.info(`[MCPServer:${this.info.name}] callTool() executing: ${name}`, {
        args,
        caller,
      })
      const result = await tool.handler(args)
      const duration = performance.now() - startTime
      logger.info(`[MCPServer:${this.info.name}] callTool() completed: ${name}`, {
        durationMs: Math.round(duration),
        isError: result.isError ?? false,
        caller,
      })
      return result
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.error(`[MCPServer:${this.info.name}] callTool() failed: ${name}`, { error: message })
      return {
        content: [{ type: 'text', text: `Tool execution error: ${message}` }],
        isError: true,
      }
    }
  }

  listResources(): ResourceTemplate[] {
    if (this.resourceCache === null) {
      const resources = this.getResources()
      this.resourceCache = new Map(resources.map((r) => [r.name, r]))
      logger.info(`[MCPServer:${this.info.name}] listResources() loaded ${resources.length} resources`)
    }
    return Array.from(this.resourceCache.values())
  }

  async readResource(uri: string, context?: McpCallerContext): Promise<ResourceContent> {
    const caller = this.resolveCallerFromContext(context)
    const resources = this.listResources()
    const matched = resources.find((r) => this.uriTemplateToRegex(r.uriTemplate).test(uri))

    if (!matched) {
      logger.error(`[MCPServer:${this.info.name}] readResource() not found: ${uri}`)
      return {
        uri,
        mimeType: 'text/plain',
        text: `Resource not found: ${uri}`,
      }
    }

    const permissionResult = this.checkResourcePermission(caller, matched, uri)
    if (permissionResult) return permissionResult

    return this.resolveResource(matched, uri, caller)
  }

  private checkResourcePermission(
    caller: McpCallerRole,
    resource: ResourceTemplate,
    uri: string,
  ): ResourceContent | null {
    try {
      this.assertServerPermission(caller, `readResource:${resource.name}`)
      return null
    } catch (err) {
      if (err instanceof McpAclError) {
        logger.warn(
          `[MCPServer:${this.info.name}] readResource() ACL denied: caller="${caller}", uri="${uri}"`,
        )
        return {
          uri,
          mimeType: 'text/plain',
          text: `ACL_PERMISSION_DENIED: ${err.detail.reason}`,
        }
      }
      throw err
    }
  }

  private async resolveResource(
    resource: ResourceTemplate,
    uri: string,
    caller: McpCallerRole,
  ): Promise<ResourceContent> {
    try {
      logger.info(`[MCPServer:${this.info.name}] readResource() reading: ${uri}`, { caller })
      return await resource.resolver(uri)
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.error(`[MCPServer:${this.info.name}] readResource() failed: ${uri}`, { error: message })
      return {
        uri,
        mimeType: 'text/plain',
        text: `Resource read error: ${message}`,
      }
    }
  }

  listPrompts(): PromptTemplate[] {
    if (this.promptCache === null) {
      const prompts = this.getPrompts()
      this.promptCache = new Map(prompts.map((p) => [p.name, p]))
      logger.info(`[MCPServer:${this.info.name}] listPrompts() loaded ${prompts.length} prompts`)
    }
    return Array.from(this.promptCache.values())
  }

  async getPrompt(
    name: string,
    args: Record<string, string>,
    context?: McpCallerContext,
  ): Promise<PromptMessage[]> {
    const caller = this.resolveCallerFromContext(context)

    // ── Server 端权限断言（防小人） ──
    try {
      this.assertServerPermission(caller, `getPrompt:${name}`)
    } catch (err) {
      if (err instanceof McpAclError) {
        logger.warn(
          `[MCPServer:${this.info.name}] getPrompt() ACL denied: caller="${caller}", prompt="${name}"`,
        )
        return [{
          role: 'user',
          content: {
            type: 'text',
            text: `ACL_PERMISSION_DENIED: ${err.detail.reason}`,
          },
        }]
      }
      throw err
    }

    const prompts = this.listPrompts()
    const prompt = prompts.find((p) => p.name === name)

    if (!prompt) {
      logger.error(`[MCPServer:${this.info.name}] getPrompt() not found: ${name}`)
      return [{ role: 'user', content: { type: 'text', text: `Prompt not found: ${name}` } }]
    }

    try {
      logger.info(`[MCPServer:${this.info.name}] getPrompt() generating: ${name}`, { args, caller })
      return await prompt.generator(args)
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      logger.error(`[MCPServer:${this.info.name}] getPrompt() failed: ${name}`, { error: message })
      return [{ role: 'user', content: { type: 'text', text: `Prompt generation error: ${message}` } }]
    }
  }

  // ============================================================
  // 工具方法
  // ============================================================

  /**
   * 校验工具调用参数是否符合 inputSchema 定义。
   * 检查项：必填字段、类型匹配、枚举值约束。
   *
   * @returns 错误信息数组，空数组表示校验通过
   */
  private validateToolArgs(
    tool: ToolDescriptor,
    args: Record<string, unknown>,
  ): string[] {
    const errors: string[] = []
    const schema = tool.inputSchema

    if (schema?.type !== 'object' || !schema.properties) {
      return errors // 无 schema 定义时跳过校验（向后兼容）
    }

    // 检查必填字段
    for (const required of schema.required ?? []) {
      if (!(required in args)) {
        errors.push(`missing required parameter: "${required}"`)
      }
    }

    // 检查类型与枚举
    for (const [key, value] of Object.entries(args)) {
      const prop = schema.properties[key]
      if (!prop) continue // 未知参数不阻断（允许扩展）

      const actualType = Array.isArray(value) ? 'array' : typeof value
      if (value !== null && value !== undefined && actualType !== prop.type) {
        errors.push(`parameter "${key}" expected ${prop.type}, got ${actualType}`)
      }

      if (prop.enum && !prop.enum.includes(value as string)) {
        errors.push(`parameter "${key}" must be one of [${prop.enum.join(', ')}]`)
      }
    }

    return errors
  }

  /** 将 URI 模板转换为正则表达式 */
  private uriTemplateToRegex(template: string): RegExp {
    const escaped = template
      .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      .replace(/\\\{([^}]+)\\}/g, '([^/]+)')
    return safeRegex(`^${escaped}$`)
  }
}

/**
 * MCP 传输层 —— 进程内零拷贝传输实现
 *
 * @description
 * 同进程内的 MCP Server 调用使用 InProcessTransport，直接传递引用而非序列化，
 * 确保性能不退化。未来扩展跨进程调用时，可新增 JSONRPCTransport 实现。
 *
 * @module mcp/core/transport
 * @created 2026-07-04 - Phase 0 MCP 基础设施层建设
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-002, V9-DOC-AI-007, V9-DOC-AI-005, V9-DOC-PROJ-003]
*/

import type { MCPTransport, MCPServer, NotificationMethod, SamplingRequest, McpCallerContext } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** Transport 层调用方上下文 —— 协议适配层属于系统内部调用 */
const TRANSPORT_CALLER_CONTEXT: McpCallerContext = {
  caller: 'system',
  callerId: 'InProcessTransport',
}

/**
 * 校验工具调用/提示模板请求是否包含 name 参数。
 * 抽成断言函数，避免 sendRequest 内重复 if 条件。
 */
function assertNameParam(params?: Record<string, unknown>): asserts params is { name: string; arguments?: Record<string, unknown> } {
  if (!params || typeof params.name !== 'string') {
    throw new Error('Missing required param: name')
  }
}

/** 进程内传输 —— 零拷贝，直接调用 Server 方法 */
export class InProcessTransport implements MCPTransport {
  private server: MCPServer
  private closed = false

  constructor(server: MCPServer) {
    this.server = server
    logger.info(`[InProcessTransport] created for server: ${server.info.name}`)
  }

  async sendRequest(method: string, params?: Record<string, unknown>): Promise<unknown> {
    if (this.closed) {
      throw new Error('Transport is closed')
    }

    const startTime = performance.now()

    switch (method) {
      case 'tools/list': {
        const tools = this.server.listTools()
        logger.info(`[InProcessTransport] tools/list returned ${tools.length} tools`)
        return { tools }
      }

      case 'tools/call': {
        assertNameParam(params)
        const args = (params.arguments as Record<string, unknown>) ?? {}
        const result = await this.server.callTool(params.name, args, TRANSPORT_CALLER_CONTEXT)
        const duration = performance.now() - startTime
        logger.info(`[InProcessTransport] tools/call ${params.name} completed in ${Math.round(duration)}ms`)
        return result
      }

      case 'resources/list': {
        const resources = this.server.listResources()
        return { resources }
      }

      case 'resources/read': {
        if (!params || typeof params.uri !== 'string') {
          throw new Error('Missing required param: uri')
        }
        return await this.server.readResource(params.uri, TRANSPORT_CALLER_CONTEXT)
      }

      case 'prompts/list': {
        const prompts = this.server.listPrompts()
        return { prompts }
      }

      case 'prompts/get': {
        assertNameParam(params)
        const args = (params.arguments as Record<string, string>) ?? {}
        return {
          messages: await this.server.getPrompt(params.name, args, TRANSPORT_CALLER_CONTEXT),
        }
      }

      case 'roots/list': {
        const { rootsManager: rm } = await import('./roots')
        return rm.listRoots()
      }

      case 'elicitation/request': {
        if (!params || typeof params.message !== 'string') {
          throw new Error('Missing required param: message')
        }
        const { elicitationManager: em } = await import('./elicitation')
        return em.request(params as unknown as import('@/types/modules/mcp.types').ElicitationRequest)
      }

      case 'sampling/createMessage': {
        const { samplingHandler } = await import('./sampling')
        return samplingHandler.createMessage(params as unknown as SamplingRequest)
      }

      default:
        throw new Error(`Unknown method: ${method}`)
    }
  }

  async sendNotification(method: string, params?: Record<string, unknown>): Promise<void> {
    const { notificationManager: nm } = await import('./notification')
    nm.emit(method as NotificationMethod, params)
  }

  close(): void {
    this.closed = true
    logger.info(`[InProcessTransport] closed for server: ${this.server.info.name}`)
  }
}

/**
 * MCP Server 配置驱动注册与热更新
 *
 * @description
 * 从 `src/config/mcpServerRegistry.ts` 读取 Server 清单，
 * 通过 import.meta.glob (lazy) 按需加载模块并按配置自动注册到 MCPRegistry。
 *
 * 核心能力：
 *   - `mcpReadyPromise` → 核心 Server 注册完成后 resolve，供 Agent 系统 await
 *   - `registerLazyServers()` → 后台加载非核心 Server，不阻塞首屏
 *   - `syncWithConfig()` → 增量同步（配置变更后调用，添加/移除 Server）
 *
 * @module mcp/register
 * @doc [V9-DOC-AI-005, V9-DOC-AI-007, V9-DOC-AI-013, V9-DOC-AI-021, V9-DOC-AI-022]
*/

import { mcpRegistry } from '@/mcp/core/registry'
import { MCP_SERVER_REGISTRY, type MCPServerConfigEntry, type MCPServerModule } from '@/config/mcpServerRegistry'
import type { RegisteredServer } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'
import type { MCPServer } from '@/types/modules/mcp.types'

const logger = getLogger()
const _mcpImportTs = Date.now()

// ============================================================
// Vite 静态模块扫描（lazy 模式，避免首屏加载所有 Server 模块）
// ============================================================

/**
 * 使用 import.meta.glob (lazy) 动态加载 Server 模块
 *
 * Vite 在构建时静态分析 glob 模式，将匹配文件打包为动态 import。
 * eager: false 确保模块不被首屏加载，仅在调用 loader 时才加载。
 */
const serverModuleLoaders = import.meta.glob<MCPServerModule>(
  './servers/**/*.ts',
  { eager: false },
)
logger.info(`[MCP:register] ▶ import.meta.glob(lazy) prepared ${Object.keys(serverModuleLoaders).length} module loaders`)

/** 缓存已加载的模块，避免重复 import */
const loadedModuleCache = new Map<string, MCPServerModule>()

/**
 * 将配置中的 modulePath（@/别名路径）映射为 glob key（相对路径）
 *
 * 例：`@/mcp/servers/fetcher/dataFetcherServer` → `./servers/fetcher/dataFetcherServer.ts`
 */
function configPathToGlobKey(modulePath: string): string {
  return modulePath.replace(/^@\/mcp\//, './').replace(/\.ts$/, '') + '.ts'
}

/**
 * 懒加载指定模块并缓存
 *
 * @param globKey - glob 匹配的相对路径
 * @returns 模块导出对象，加载失败返回 null
 */
async function loadModule(globKey: string): Promise<MCPServerModule | null> {
  if (loadedModuleCache.has(globKey)) {
    return loadedModuleCache.get(globKey)!
  }

  const loader = serverModuleLoaders[globKey]
  if (!loader) {
    logger.error(`[MCP:register] no loader for glob key: ${globKey}`, {
      availableKeys: Object.keys(serverModuleLoaders),
    })
    return null
  }

  try {
    const mod = (await loader()) as MCPServerModule
    loadedModuleCache.set(globKey, mod)
    return mod
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[MCP:register] failed to load module ${globKey}`, { error: message })
    return null
  }
}

/**
 * 从已加载模块中实例化 Server（同步版本，用于已缓存模块）
 *
 * @param modulePath - 配置中的模块路径（@/别名格式）
 * @param exportName - 导出类名
 * @param mod - 已加载的模块对象
 * @returns MCPServer 实例，加载失败返回 null
 */
function instantiateFromModule(
  modulePath: string,
  exportName: string,
  mod: MCPServerModule,
): MCPServer | null {
  try {
    const ServerCtor = mod[exportName]
    if (typeof ServerCtor !== 'function') {
      logger.error(`[MCP:register] export "${exportName}" not found in ${modulePath}`)
      return null
    }

    const instance = new ServerCtor() as MCPServer

    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
    if ((instance.info ?? null) === null || (instance.listTools ?? null) === null) {
      logger.error(`[MCP:register] "${exportName}" does not implement MCPServer interface`)
      return null
    }

    return instance
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[MCP:register] failed to instantiate ${modulePath}`, { error: message })
    return null
  }
}

/**
 * 异步实例化 Server（懒加载 + 实例化）
 *
 * @param entry - Server 配置条目
 * @returns MCPServer 实例，加载失败返回 null
 */
async function instantiateServerAsync(
  entry: MCPServerConfigEntry,
): Promise<MCPServer | null> {
  const globKey = configPathToGlobKey(entry.modulePath)
  const mod = await loadModule(globKey)
  if (!mod) return null
  return instantiateFromModule(entry.modulePath, entry.exportName, mod)
}

// ============================================================
// 分阶段注册：核心 Server 先注册，非核心 Server 懒加载
// ============================================================

/** 已注册的非核心 Server 条目（用于 lazy 加载） */
let lazyEntries: MCPServerConfigEntry[] | null = null

/** 懒加载注册互斥锁，防止重复调用 */
let lazyRegistrationStarted = false

/**
 * 注册核心 Server（enabled + !lazy）
 *
 * 核心 Server 阻塞后续 Agent 初始化，必须先完成。
 * 通过 mcpReadyPromise 对外暴露完成信号。
 */
async function registerCoreServers(): Promise<void> {
  const _regStart = performance.now()

  // 分离核心和非核心条目
  const coreEntries: MCPServerConfigEntry[] = []
  const lazyList: MCPServerConfigEntry[] = []
  let _skipped = 0

  for (const entry of MCP_SERVER_REGISTRY) {
    if (!entry.enabled) {
      _skipped++
      logger.info(`[MCP:register] ⏭ SKIP disabled server: ${entry.name} (module=${entry.modulePath})`)
      continue
    }
    if (entry.lazy) {
      lazyList.push(entry)
      logger.info(`[MCP:register] 📦 QUEUE lazy server: ${entry.name} (module=${entry.modulePath}, priority=${entry.priority})`)
    } else {
      coreEntries.push(entry)
      logger.info(`[MCP:register] 🔧 QUEUE core server: ${entry.name} (module=${entry.modulePath}, priority=${entry.priority})`)
    }
  }

  // 缓存 lazy 条目供后续 registerLazyServers() 使用
  lazyEntries = lazyList.length > 0 ? lazyList : null

  logger.info(`[MCP:register] ▶ core registration starting: ${coreEntries.length} core + ${lazyList.length} lazy (skipped=${_skipped})`, {
    coreCount: coreEntries.length,
    lazyCount: lazyList.length,
    skippedCount: _skipped,
  })

  // 逐个加载并注册核心 Server（含单条耗时）
  let _registered = 0
  let _failed = 0
  for (const entry of coreEntries) {
    const _srvStart = performance.now()
    logger.info(`[MCP:register]   loading core server: ${entry.name} ← ${entry.modulePath}`)
    try {
      const server = await instantiateServerAsync(entry)
      if (server) {
        mcpRegistry.register(server, { priority: entry.priority, modulePath: entry.modulePath })
        _registered++
        const _srvElapsed = (performance.now() - _srvStart).toFixed(1)
        logger.info(`[MCP:register]   ✅ registered: ${entry.name} (${_srvElapsed}ms, tools=${server.listTools().length})`)
      } else {
        _failed++
        logger.error(`[MCP:register]   ❌ instantiation failed (null): ${entry.name}`)
      }
    } catch (err) {
      _failed++
      logger.error(`[MCP:register]   ❌ exception loading ${entry.name}: ${String(err)}`)
    }
  }

  const stats = mcpRegistry.getStats()
  const _regElapsed = (performance.now() - _regStart).toFixed(1)
  logger.info(`[MCP:register] ▶ CORE REGISTRATION COMPLETE: ${_registered}/${coreEntries.length} servers in ${_regElapsed}ms (failed=${_failed})`, stats)
}

/**
 * 后台注册非核心 Server
 *
 * 非核心 Server 不阻塞首屏和 Agent 初始化，
 * 在核心注册完成后异步加载。
 *
 * @returns 已注册的非核心 Server 数量
 */
export async function registerLazyServers(): Promise<number> {
  if (lazyRegistrationStarted) {
    logger.info('[MCP:register] ⏭ lazy registration already started, skip (mutex guard)')
    return 0
  }
  if (!lazyEntries || lazyEntries.length === 0) {
    logger.info('[MCP:register] ⏭ no lazy entries to register (all core or disabled)')
    return 0
  }
  lazyRegistrationStarted = true

  const _lazyStart = performance.now()
  const entries = lazyEntries
  logger.info(`[MCP:register] ▶ lazy registration starting: ${entries.length} non-core servers...`)

  let registered = 0
  let _failed = 0
  for (const entry of entries) {
    const _srvStart = performance.now()
    logger.info(`[MCP:register]   loading lazy server: ${entry.name} ← ${entry.modulePath}`)
    try {
      const server = await instantiateServerAsync(entry)
      if (server) {
        mcpRegistry.register(server, { priority: entry.priority, modulePath: entry.modulePath })
        registered++
        const _srvElapsed = (performance.now() - _srvStart).toFixed(1)
        logger.info(`[MCP:register]   ✅ registered: ${entry.name} (${_srvElapsed}ms, tools=${server.listTools().length})`)
      } else {
        _failed++
        logger.error(`[MCP:register]   ❌ instantiation failed (null): ${entry.name}`)
      }
    } catch (err) {
      _failed++
      logger.error(`[MCP:register]   ❌ exception loading ${entry.name}: ${String(err)}`)
    }
  }

  const totalLazy = entries.length
  lazyEntries = null
  const _lazyElapsed = (performance.now() - _lazyStart).toFixed(1)
  logger.info(`[MCP:register] ▶ lazy registration complete: ${registered}/${totalLazy} servers in ${_lazyElapsed}ms (failed=${_failed})`,
    mcpRegistry.getStats())

  if (fullyReadyResolver) {
    fullyReadyResolver()
    fullyReadyResolver = null
  }
  logger.info(`[MCP:register] ▶ FULL REGISTRATION COMPLETE (total=${Date.now() - _mcpImportTs}ms from import)`)

  return registered
}

// ============================================================
// 对外信号：mcpReadyPromise
// ============================================================

let mcpReadyResolver: (() => void) | null = null

/**
 * 核心 Server 就绪信号
 *
 * Agent 系统初始化通过 `await mcpReadyPromise` 等待核心 MCP Server 注册完成。
 * 非核心 Server 的加载不影响此 Promise。
 */
export const mcpReadyPromise: Promise<void> = new Promise<void>((resolve) => {
  mcpReadyResolver = resolve
})

/**
 * 全量 Server 就绪信号（含 lazy 加载）
 *
 * 供需要所有 Server 都就绪的场景使用（如全量工具列表导出）。
 */
let fullyReadyResolver: (() => void) | null = null
export const mcpFullyReadyPromise: Promise<void> = new Promise<void>((resolve) => {
  fullyReadyResolver = resolve
})

// ============================================================
// 兼容同步调用场景
// ============================================================

/**
 * 从配置清单全量注册所有 MCP Server（同步版本，兼容旧调用方）
 *
 * 注意：此函数会阻塞直到所有 Server（包括 lazy）都注册完成。
 * 新代码建议使用 `ensureMCPRegistered()` + `mcpReadyPromise` 组合。
 */
export function registerAllServers(): void {
  const _regStart = performance.now()

  for (const entry of MCP_SERVER_REGISTRY) {
    if (!entry.enabled) continue

    const globKey = configPathToGlobKey(entry.modulePath)
    const mod = loadedModuleCache.get(globKey)
    if (!mod) {
      logger.warn(`[MCP:register] module not cached, skipping sync register: ${globKey}`)
      continue
    }

    const server = instantiateFromModule(entry.modulePath, entry.exportName, mod)
    if (server) {
      mcpRegistry.register(server, { priority: entry.priority, modulePath: entry.modulePath })
    }
  }

  const stats = mcpRegistry.getStats()
  const _regElapsed = (performance.now() - _regStart).toFixed(1)
  logger.info(`[MCP:register] sync registration complete (${_regElapsed}ms)`, stats)
}

// ============================================================
// 增量同步（热更新）
// ============================================================

/**
 * 增量同步：对比配置清单与当前 Registry，执行最小变更
 *
 * 比对键采用 `modulePath`（配置条目的稳定身份），而非 Server 的 `info.name`，
 * 因为配置 `name` 字段（如 `llm:main`）与 Server 实例 `info.name`（如 `llm`）
 * 可能不一致。若按 `info.name` 比对，热更新时会误将全部 Server 注销（F2 根因）。
 *
 * 操作逻辑：
 *   1. 配置中存在且enabled但Registry中不存在（按modulePath）→ 新增注册
 *   2. Registry 中存在但配置中不存在 → 注销
 *   3. 配置中 enabled: false 且 Registry 中存在 → 注销
 *   4. 其余情况 → 跳过（不重复注册）
 *
 * @returns 同步结果摘要（含 mismatched 防御性告警）
 */
export function syncWithConfig(): SyncResult {
  const result: SyncResult = {
    added: [],
    removed: [],
    skipped: [],
    failed: [],
    mismatched: [],
  }

  // 以 modulePath 作为配置 ↔ 运行时注册表的稳定身份标识。
  const registeredByModulePath = new Map<string, RegisteredServer>()
  for (const rs of mcpRegistry.listServers()) {
    const mp = rs.options.modulePath
    if ((mp ?? '') !== '') registeredByModulePath.set(mp!, rs)
  }

  const configByModulePath = new Map<string, (typeof MCP_SERVER_REGISTRY)[number]>()
  for (const e of MCP_SERVER_REGISTRY) configByModulePath.set(e.modulePath, e)

  // Step 1: 处理配置中的条目
  for (const entry of MCP_SERVER_REGISTRY) {
    const registered = registeredByModulePath.get(entry.modulePath)

    if (!entry.enabled) {
      if (registered) {
        mcpRegistry.unregister(registered.server.info.name)
        result.removed.push(entry.modulePath)
        logger.info(`[MCP:sync] disabled & unregistered: ${entry.modulePath}`)
      }
      continue
    }

    if (!registered) {
      // 尝试从缓存加载模块进行同步注册
      const globKey = configPathToGlobKey(entry.modulePath)
      const mod = loadedModuleCache.get(globKey)
      if (mod) {
        const server = instantiateFromModule(entry.modulePath, entry.exportName, mod)
        if (server) {
          mcpRegistry.register(server, { priority: entry.priority, modulePath: entry.modulePath })
          result.added.push(entry.modulePath)
          logger.info(`[MCP:sync] added: ${entry.modulePath}`)
        } else {
          result.failed.push(entry.modulePath)
        }
      } else {
        result.skipped.push(entry.modulePath)
      }
      continue
    }

    result.skipped.push(entry.modulePath)
  }

  // Step 2: 注销配置中已不存在的 Server
  for (const [mp, rs] of registeredByModulePath) {
    if (configByModulePath.has(mp)) continue
    mcpRegistry.unregister(rs.server.info.name)
    result.removed.push(mp)
    logger.info(`[MCP:sync] not in config & unregistered: ${mp}`)
  }

  // Step 3: 防御性不变量
  for (const mp of registeredByModulePath.keys()) {
    if (!configByModulePath.has(mp)) {
      result.mismatched.push(mp)
    }
  }

  logger.info('[MCP:sync] complete', {
    added: result.added.length,
    removed: result.removed.length,
    skipped: result.skipped.length,
    failed: result.failed.length,
    mismatched: result.mismatched.length,
  })

  return result
}

/** 增量同步结果 */
export interface SyncResult {
  added: string[]
  removed: string[]
  skipped: string[]
  failed: string[]
  mismatched: string[]
}

// ============================================================
// 延迟触发注册（由 Agent 系统首次交互时调用）
// ============================================================

let autoRegistered = false

/**
 * 触发 MCP Server 注册（核心 + 后台非核心）
 *
 * 调用后：
 * 1. 核心 Server 立即加载并注册 → `mcpReadyPromise` resolve
 * 2. 非核心 Server 在后台异步加载 → `mcpFullyReadyPromise` resolve
 *
 * 幂等：多次调用仅执行一次。
 */
export function ensureMCPRegistered(): void {
  if (autoRegistered) {
    logger.info('[MCP:register] ⏭ already registered, skip (idempotent guard)')
    return
  }
  autoRegistered = true
  const elapsed = Date.now() - _mcpImportTs
  logger.info(`[MCP:register] ▶ TRIGGER REGISTER (import→elapsed=${elapsed}ms)`)

  // 1. 注册核心 Server（阻塞 Promise 链）
  const _coreStart = performance.now()
  logger.info('[MCP:register]   starting core server registration (blocking)...')
  registerCoreServers()
    .then(() => {
      const _coreElapsed = (performance.now() - _coreStart).toFixed(1)
      logger.info(`[MCP:register]   ✅ core registration promise resolved in ${_coreElapsed}ms`)
      if (mcpReadyResolver) {
        mcpReadyResolver()
        mcpReadyResolver = null
      }
      logger.info(`[MCP:register] ▶ CORE REGISTRATION COMPLETE (total=${Date.now() - _mcpImportTs}ms from import)`)
    })
    .catch((err) => {
      logger.error('[MCP:register]   ❌ core registration failed', { error: String(err), stack: err instanceof Error ? err.stack : undefined })
      if (mcpReadyResolver) {
        mcpReadyResolver()
        mcpReadyResolver = null
      }
    })

  // 2. 后台注册非核心 Server（不阻塞）
  logger.info('[MCP:register]   starting lazy server registration (background)...')
  const _lazyStart = performance.now()
  registerLazyServers()
    .then((count) => {
      const _lazyElapsed = (performance.now() - _lazyStart).toFixed(1)
      logger.info(`[MCP:register]   ✅ lazy registration resolved: ${count} servers in ${_lazyElapsed}ms`)
    })
    .catch((err) => {
      logger.error('[MCP:register]   ❌ lazy registration failed', { error: String(err), stack: err instanceof Error ? err.stack : undefined })
      if (fullyReadyResolver) {
        fullyReadyResolver()
        fullyReadyResolver = null
      }
    })
}

// 模块加载日志
logger.info(`[MCP:register] ⧉ MODULE LOADED at ${new Date(_mcpImportTs).toISOString()} (dev=${import.meta.env.DEV})`)
logger.info('[MCP:register] ⧉ Waiting for trigger...')

/**
 * @module mcp/servers/backtest
 * @description 回测引擎 MCP Server — 策略回测、绩效分析
 * @created 2026-07-04
  * @doc [V9-DOC-AI-005, V9-DOC-AI-007, V9-DOC-AI-013, V9-DOC-AI-021, V9-DOC-AI-022]
*/

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor, ResourceTemplate } from '@/mcp/core/types'
import { getLogger } from '@/lib/logger'
import { BacktestEngine } from '@/services/backtest/BacktestEngine'
// 从 types 层导入类型（store 仅为 re-export）；mcp 层不应依赖 store 层
import type { BacktestStrategy } from '@/types/modules/backtest.types'

const logger = getLogger()

const DEFAULT_BACKTEST_CONFIG = {
  initialCapital: 100000,
  commissionRate: 0.0003,
  slippage: 0.001,
  maxPositionPct: 0.3,
}

export class BacktestServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'backtest',
    version: '1.0.0',
    description: '回测引擎 — 策略回测、绩效分析、风险指标',
    dependencies: ['fetcher', 'scoring:v6'],
  }

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'run_backtest',
        description: '执行策略回测',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
            startDate: { type: 'string', description: '开始日期 (YYYY-MM-DD)' },
            endDate: { type: 'string', description: '结束日期 (YYYY-MM-DD)' },
            strategy: { type: 'string', description: '策略名称', default: 'v6_scoring' },
            initialCapital: { type: 'number', description: '初始资金', default: 100000 },
          },
          required: ['symbol', 'startDate', 'endDate'],
        },
        handler: async (args) => {
          logger.info('[BacktestServer] run_backtest called', { symbol: args.symbol as string })
          const engine = new BacktestEngine()
          const result = await engine.run({
            strategy: ((args.strategy as string) ?? 'composite') as BacktestStrategy,
            startDate: args.startDate as string,
            endDate: args.endDate as string,
            initialCapital: (args.initialCapital as number) ?? DEFAULT_BACKTEST_CONFIG.initialCapital,
            commissionRate: DEFAULT_BACKTEST_CONFIG.commissionRate,
            slippage: DEFAULT_BACKTEST_CONFIG.slippage,
            maxPositionPct: DEFAULT_BACKTEST_CONFIG.maxPositionPct,
          })
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
    ]
  }

  protected getResources(): ResourceTemplate[] {
    return [
      {
        uriTemplate: 'backtest://config',
        name: '回测默认配置',
        description: '回测引擎默认配置参数',
        mimeType: 'application/json',
        resolver: (uri) => {
          return Promise.resolve({ uri, mimeType: 'application/json', text: JSON.stringify(DEFAULT_BACKTEST_CONFIG) })
        },
      },
    ]
  }
}

/**
 * @module mcp/servers/data-collector
 * @description 数据采集 MCP Server — 行情数据获取、缺失报告检测
 * @created 2026-07-05
  * @doc [V9-DOC-AI-005, V9-DOC-AI-007, V9-DOC-AI-013, V9-DOC-AI-021, V9-DOC-AI-022]
*/

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'
import { listUnresolved, listBySymbol } from '@/services/data-collector/missingReportDetector'
import { buildCollectionReport } from '@/services/data-collector/collectionReportService'

const logger = getLogger()

export class DataCollectorServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'data-collector',
    version: '1.0.0',
    description: '数据采集 — 行情数据获取、缺失报告检测',
    dependencies: ['fetcher'],
  }

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'fetch_market_data',
        description: '获取指定股票的行情数据',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
            days: { type: 'number', description: '回溯天数，默认 30', default: 30 },
          },
          required: ['symbol'],
        },
        handler: (args) => {
          const symbol = args.symbol as string
          const days = (args.days as number) ?? 30
          logger.info('[DataCollectorServer] fetch_market_data called', { symbol, days })
          // TODO[阻塞·#7]: MarketDataAdapter 仅有 adapt/merge，fetchMarketData 未实现；待接真实数据源（AKShare/HTTP）后补全。
          return Promise.resolve({ content: [{ type: 'text', text: JSON.stringify({ symbol, days, data: [], note: 'fetchMarketData 尚未实现' }) }] })
        },
      },
      {
        name: 'build_collection_report',
        description: '根据 traceSpans 与 taskStatuses 聚合生成采集报告',
        inputSchema: {
          type: 'object',
          properties: {
            traceSpans: {
              type: 'object',
              description: 'traceId -> CollectionTraceSpan 的运行时链路映射',
            },
            taskStatuses: {
              type: 'object',
              description: 'taskId -> CollectionTaskRuntime 的任务状态映射',
            },
          },
          required: ['traceSpans', 'taskStatuses'],
        },
        handler: (args) => {
          const traceSpans = (args.traceSpans as Record<string, unknown>) ?? {}
          const taskStatuses = (args.taskStatuses as Record<string, unknown>) ?? {}
          logger.info('[DataCollectorServer] build_collection_report called', {
            spanCount: Object.keys(traceSpans).length,
            taskCount: Object.keys(taskStatuses).length,
          })
          const report = buildCollectionReport(traceSpans as never, taskStatuses as never)
          return Promise.resolve({ content: [{ type: 'text', text: JSON.stringify(report) }] })
        },
      },
      {
        name: 'detect_missing_reports',
        description: '检测缺失的数据报告',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码（可选，不填则检测全部）' },
          },
        },
        handler: async (args) => {
          const symbol = args.symbol as string | undefined
          logger.info('[DataCollectorServer] detect_missing_reports called', { symbol })
          const result = symbol?.trim() ? await listBySymbol(symbol) : await listUnresolved()
          return { content: [{ type: 'text', text: JSON.stringify(result) }] }
        },
      },
    ]
  }
}

/**
 * @module mcp/servers/execution
 * @description 执行计划 MCP Server — 执行计划创建、查询、阶段更新、取消
 * @created 2026-07-05
  * @doc [V9-DOC-AI-005, V9-DOC-AI-007, V9-DOC-AI-013, V9-DOC-AI-021, V9-DOC-AI-022]
*/

import { MCPServerBase } from '@/mcp/core/server'
import type { ServerInfo, ToolDescriptor } from '@/types/modules/mcp.types'
import { getLogger } from '@/lib/logger'
import type { Signal } from '@/data/types'
import {
  listPlans,
  updatePhase,
  cancelPlan,
  getOrphanPlans,
} from '@/services/execution/executionPlanService'
import { createExecutionPlanUseCase } from '@/services/useCase/createExecutionPlan.useCase'

import { nanoid } from 'nanoid'
const logger = getLogger()

export class ExecutionServer extends MCPServerBase {
  readonly info: ServerInfo = {
    name: 'execution',
    version: '1.0.0',
    description: '执行计划 — 计划创建、查询、阶段更新、取消',
    dependencies: ['trading'],
  }

  protected getTools(): ToolDescriptor[] {
    return [
      {
        name: 'create_execution_plan',
        description: '为交易信号创建执行计划',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码' },
            direction: { type: 'string', enum: ['buy', 'sell'], description: '交易方向' },
            quantity: { type: 'number', description: '交易数量' },
            price: { type: 'number', description: '目标价格' },
            confidence: { type: 'number', description: '置信度（0-1），默认 0.5' },
          },
          required: ['symbol', 'direction', 'quantity', 'price'],
        },
        handler: async (args) => {
          logger.info('[ExecutionServer] create_execution_plan called', { symbol: args.symbol })

          // 尽早失败：校验 confidence 范围
          const confidence = (args.confidence as number) ?? 0.5
          if (confidence < 0 || confidence > 1) {
            return { content: [{ type: 'text', text: JSON.stringify({ error: '参数错误：confidence 必须在 0-1 之间' }) }] }
          }

          const signal: Signal = {
            id: `sig-mcp-${nanoid(8)}`,
            symbol: args.symbol as string,
            direction: args.direction as Signal['direction'],
            type: 'mcp_manual',
            strategy: 'manual',
            confidence,
            rationale: 'MCP 手动创建',
            snapshot: {},
            createdAt: Date.now(),
          }
          // 委托给完整 UseCase，走完整风控流程
          const result = await createExecutionPlanUseCase({ signal, source: 'mcp' })
          if (!result.success || !result.plan) {
            // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
            return { content: [{ type: 'text', text: JSON.stringify({ error: result.error || '创建失败', errorCode: result.errorCode }) }] }
          }
          return { content: [{ type: 'text', text: JSON.stringify(result.plan) }] }
        },
      },
      {
        name: 'list_execution_plans',
        description: '查询执行计划列表',
        inputSchema: {
          type: 'object',
          properties: {
            symbol: { type: 'string', description: '股票代码（可选）' },
          },
        },
        handler: async (args) => {
          const symbol = args.symbol as string | undefined
          logger.info('[ExecutionServer] list_execution_plans called', { symbol })
          const plans = await listPlans(symbol)
          return { content: [{ type: 'text', text: JSON.stringify(plans) }] }
        },
      },
      {
        name: 'update_execution_phase',
        description: '更新执行计划阶段',
        inputSchema: {
          type: 'object',
          properties: {
            planId: { type: 'string', description: '执行计划 ID' },
            phase: { type: 'string', description: '目标阶段' },
          },
          required: ['planId', 'phase'],
        },
        handler: async (args) => {
          const planId = args.planId as string
          const phase = args.phase as string
          logger.info('[ExecutionServer] update_execution_phase called', { planId, phase })
          const plan = await updatePhase(planId, phase as never)
          return { content: [{ type: 'text', text: JSON.stringify(plan ?? { error: '更新失败' }) }] }
        },
      },
      {
        name: 'cancel_execution_plan',
        description: '取消执行计划',
        inputSchema: {
          type: 'object',
          properties: {
            planId: { type: 'string', description: '执行计划 ID' },
          },
          required: ['planId'],
        },
        handler: async (args) => {
          const planId = args.planId as string
          logger.info('[ExecutionServer] cancel_execution_plan called', { planId })
          const plan = await cancelPlan(planId)
          return { content: [{ type: 'text', text: JSON.stringify(plan ?? { error: '取消失败' }) }] }
        },
      },
      {
        name: 'get_orphan_plans',
        description: '查询孤立的执行计划（无关联订单）',
        inputSchema: { type: 'object', properties: {} },
        handler: async () => {
          logger.info('[ExecutionServer] get_orphan_plans called')
          const plans = await getOrphanPlans()
          return { content: [{ type: 'text', text: JSON.stringify(plans) }] }
        },
      },
    ]
  }
}

/**
 * DataFetcherServer — 数据采集 MCP Server
 *
 * @description
 * 封装行情数据获取、K线数据采集、基础数据查询等数据采集能力。
