export interface ChipStrategyChartData {
  /** K 线数据 */
  klineData: CandlestickChartData[]
  /** K 线加载中 */
  klineLoading: boolean
  /** K 线数据源 */
  klineDataSource: 'real' | 'demo' | 'loading' | 'empty'
  /** 筹码分布数据 */
  chipData: CollectChipData | null
  /** 筹码数据加载中 */
  chipLoading: boolean
  /** 筹码数据源 */
  chipDataSource: 'real' | 'demo' | 'loading' | 'empty'
  /** K 线图买卖点 markers */
  markers: ChartMarker[]
  /** 筹码图买卖点标注 */
  chipTradePoints: ChipTradePoint[]
  /** 强制刷新 */
  refresh: () => void
}

export function useChipStrategyCharts(
  symbol: string | null,
  basePrice: number | undefined,
  turnover: number | undefined,
  return60d: number | undefined,
  tradeAction?: string,
): ChipStrategyChartData {
  const [klineData, setKlineData] = useState<CandlestickChartData[]>([])
  const [klineLoading, setKlineLoading] = useState(false)
  const [klineDataSource, setKlineDataSource] = useState<'real' | 'demo' | 'loading' | 'empty'>('loading')
  const [chipData, setChipData] = useState<CollectChipData | null>(null)
  const [chipLoading, setChipLoading] = useState(false)
  const [chipDataSource, setChipDataSource] = useState<'real' | 'demo' | 'loading' | 'empty'>('loading')
  const [refreshKey, setRefreshKey] = useState(0)

  const refresh = useCallback(() => setRefreshKey((k) => k + 1), [])

  // === K线数据加载 ===
  useEffect(() => {
    if (!symbol) {
      logger.info(`${LOG_TAG} [K线] symbol 为空，跳过加载`)
      setKlineData([])
      setKlineDataSource('empty')
      return
    }

    logger.info(`${LOG_TAG} [K线] 开始加载`, {
      symbol,
      period: 'daily',
      adjust: 'qfq',
      count: 120,
      basePrice,
      refreshKey,
    })

    let cancelled = false
    const startTs = Date.now()
    setKlineLoading(true)
    setKlineDataSource('loading')

    collectKline({
      symbol,
      period: 'daily',
      adjust: 'qfq',
      count: 120,
    })
      .then((response) => {
        if (cancelled) {
          logger.debug(`${LOG_TAG} [K线] 响应到达但已取消`, { symbol })
          return
        }
        const durationMs = Date.now() - startTs
        logger.info(`${LOG_TAG} [K线] 响应到达`, {
          symbol,
          success: response.success,
          durationMs,
          hasHistory: !!response.data?.history,
          historyCount: response.data?.history?.length ?? 0,
          error: response.error,
        })

        if (response.success && response.data?.history && response.data.history.length > 0) {
          const chartData = adaptKlineResponseToChartData(response.data.history)
          logger.info(`${LOG_TAG} [K线] 数据适配完成 → real`, {
            symbol,
            bars: chartData.length,
            firstDate: chartData[0]?.time,
            lastDate: chartData[chartData.length - 1]?.time,
            lastClose: chartData[chartData.length - 1]?.close,
          })
          setKlineData(chartData)
          setKlineDataSource('real')
        } else {
          // 后端无数据，生成模拟 K线
          const price = basePrice ?? 10
          logger.warn(`${LOG_TAG} [K线] 后端返回空数据，降级为模拟数据`, {
            symbol,
            success: response.success,
            hasHistory: !!response.data?.history,
            historyCount: response.data?.history?.length ?? 0,
            error: response.error,
            fallbackBasePrice: price,
          })
          reportFallbackEvent({
            symbol,
            eventType: 'kline_fallback',
            fallbackFrom: 'real_data',
            fallbackTo: 'demo_data',
            reason: `后端返回空数据（success=${response.success}，history=${response.data?.history?.length ?? 0}），error=${response.error ?? '无'}`,
          })
          setKlineData(generateDemoKlineData(symbol, price))
          setKlineDataSource('demo')
        }
      })
      .catch((err) => {
        if (cancelled) return
        const durationMs = Date.now() - startTs
        const errorMsg = err instanceof Error ? err.message : String(err)
        const errorStack = err instanceof Error ? err.stack : undefined
        logger.error(`${LOG_TAG} [K线] 加载失败，降级为模拟数据`, {
          symbol,
          durationMs,
          error: errorMsg,
          stack: errorStack,
          fallbackBasePrice: basePrice ?? 10,
        })
        reportFallbackEvent({
          symbol,
          eventType: 'kline_fallback',
          fallbackFrom: 'real_data',
          fallbackTo: 'demo_data',
          reason: `K线加载异常：${errorMsg}`,
          extra: { durationMs, stack: errorStack },
        })
        const price = basePrice ?? 10
        setKlineData(generateDemoKlineData(symbol, price))
        setKlineDataSource('demo')
      })
      .finally(() => {
        if (!cancelled) {
          setKlineLoading(false)
          logger.debug(`${LOG_TAG} [K线] 加载流程结束`, {
            symbol,
            totalDurationMs: Date.now() - startTs,
          })
        }
      })

    return () => {
      cancelled = true
      logger.debug(`${LOG_TAG} [K线] effect cleanup（symbol 变化或组件卸载）`, { symbol })
    }
  }, [symbol, basePrice, refreshKey])

  // === 筹码分布数据加载 ===
  useEffect(() => {
    if (!symbol) {
      logger.info(`${LOG_TAG} [筹码] symbol 为空，跳过加载`)
      setChipData(null)
      setChipDataSource('empty')
      return
    }

    logger.info(`${LOG_TAG} [筹码] 开始加载`, {
      symbol,
      endpoint: API_COLLECT_CHIP,
      count: 1000,
      price_bins: 30,
      basePrice,
      turnover,
      return60d,
      refreshKey,
    })

    let cancelled = false
    const startTs = Date.now()
    setChipLoading(true)
    setChipDataSource('loading')

    const reqBody: CollectChipRequest = {
      symbol,
      count: 1000,
      price_bins: 30,
    }

    fetch(API_COLLECT_CHIP, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(reqBody),
    })
      .then(async (resp) => {
        if (cancelled) {
          logger.debug(`${LOG_TAG} [筹码] 响应到达但已取消`, { symbol })
          return
        }
        const durationMs = Date.now() - startTs
        logger.info(`${LOG_TAG} [筹码] HTTP 响应到达`, {
          symbol,
          httpStatus: resp.status,
          httpOk: resp.ok,
          durationMs,
          contentType: resp.headers.get('content-type'),
        })

        if (!resp.ok) {
          throw new Error(`HTTP ${resp.status} ${resp.statusText}`)
        }

        const json = (await resp.json()) as CollectResponse<CollectChipData>
        logger.info(`${LOG_TAG} [筹码] JSON 解析完成`, {
          symbol,
          success: json.success,
          hasData: !!json.data,
          error: json.error,
          binsCount: json.data?.priceBins?.length ?? 0,
          coverageRatio: json.data?.coverageRatio,
          barsUsed: json.data?.barsUsed,
        })

        if (json.success && json.data) {
          // === 真实后端数据剖面日志（与模拟数据一致，便于对比单位）===
          const realChip = json.data
          const pctSum = (realChip.chipPercent ?? []).reduce((a, b) => a + b, 0)
          const pctMax = realChip.chipPercent?.length ? Math.max(...realChip.chipPercent) : 0
          const pctMin = realChip.chipPercent?.length ? Math.min(...realChip.chipPercent) : 0
          logger.info(`${LOG_TAG} [数据剖面] 真实筹码数据 (real)`, {
            symbol,
            binsCount: realChip.priceBins?.length ?? 0,
            chipPercent: {
              sum: pctSum,
              max: pctMax,
              min: pctMin,
            },
            stats: {
              profitRatio: realChip.profitRatio,
              concentration: realChip.concentration,
              coverageRatio: realChip.coverageRatio,
              currentPrice: realChip.currentPrice,
              avgCost: realChip.avgCost,
            },
            interpretation: {
              chipSumCloseTo100: '如果 sum≈100，则 chipPercent 是百分比（0-100）',
              chipSumCloseTo1: '如果 sum≈1，则 chipPercent 是小数（0-1）',
              profitGt1: '如果 profitRatio>1 则是百分比，<1 则是小数',
              coverageGt1: '如果 coverageRatio>1 则是百分比，<1 则是小数',
            },
          })
          logger.info(`${LOG_TAG} [筹码] 数据校验通过 → real`, {
            symbol,
            currentPrice: realChip.currentPrice,
            avgCost: realChip.avgCost,
            profitRatio: realChip.profitRatio,
            concentration: realChip.concentration,
            coverageRatio: realChip.coverageRatio,
            barsUsed: realChip.barsUsed,
          })
          setChipData(realChip)
          setChipDataSource('real')
        } else {
          throw new Error(json.error ?? '后端返回 success=false 或无 data')
        }
      })
      .catch((err) => {
        if (cancelled) return
        const durationMs = Date.now() - startTs
        const errorMsg = err instanceof Error ? err.message : String(err)
        const errorStack = err instanceof Error ? err.stack : undefined
        logger.error(`${LOG_TAG} [筹码] 加载失败，降级为模拟数据`, {
          symbol,
          durationMs,
          error: errorMsg,
          stack: errorStack,
          fallbackParams: {
            basePrice: basePrice ?? 10,
            turnover: turnover ?? 3,
            return60d: return60d ?? DEFAULT_NUMERIC,
          },
        })
        reportFallbackEvent({
          symbol,
          eventType: 'chip_fallback',
          fallbackFrom: 'real_data',
          fallbackTo: 'demo_data',
          reason: `筹码加载异常：${errorMsg}`,
          extra: {
            durationMs,
            stack: errorStack,
            fallbackParams: {
              basePrice: basePrice ?? 10,
              turnover: turnover ?? 3,
              return60d: return60d ?? DEFAULT_NUMERIC,
            },
          },
        })
        // 后端不可用，基于用户输入生成模拟筹码数据
        const price = basePrice ?? 10
        const t = turnover ?? 3
        const r60 = return60d ?? DEFAULT_NUMERIC
        const demoChip = generateDemoChipData(price, t, r60, symbol)
        // === 数据剖面日志：排查渲染异常的关键证据 ===
        const pctSum = demoChip.chipPercent.reduce((a, b) => a + b, 0)
        const pctMax = Math.max(...demoChip.chipPercent)
        const pctMin = Math.min(...demoChip.chipPercent)
        logger.info(`${LOG_TAG} [数据剖面] 模拟筹码数据 (demo)`, {
          symbol,
          binsCount: demoChip.priceBins.length,
          priceBins_range: {
            min: demoChip.priceMin,
            max: demoChip.priceMax,
            first: demoChip.priceBins[0],
            last: demoChip.priceBins[demoChip.priceBins.length - 1],
          },
          chipPercent: {
            sum: pctSum,
            max: pctMax,
            min: pctMin,
            mean: pctSum / demoChip.chipPercent.length,
          },
          stats: {
            profitRatio: demoChip.profitRatio,
            concentration: demoChip.concentration,
            coverageRatio: demoChip.coverageRatio,
            currentPrice: demoChip.currentPrice,
            avgCost: demoChip.avgCost,
            avgTurnoverRate: demoChip.avgTurnoverRate,
            maxTurnoverRate: demoChip.maxTurnoverRate,
          },
          expectedUnit: {
            chipPercent: '0-100 百分比（sum≈100）',
            profitRatio: '0-100 百分比（组件 L109 loss=100-profit 验证）',
            concentration: '0-100 百分比（组件 L185 +% 后缀）',
            coverageRatio: '0-100 百分比（组件 L200 +% 后缀，阈值 >=80）',
            avgTurnoverRate: '百分比（组件 L204 +% 后缀）',
          },
          checks: {
            chipSumApprox100: Math.abs(pctSum - 100) < 2, // ±2% 容忍
            chipMaxGt1: pctMax > 1,                          // 保证条形有宽度
            profitRatioIn0_100: demoChip.profitRatio! >= 0 && demoChip.profitRatio! <= 100,
            coverageRatioIn0_100: demoChip.coverageRatio! >= 0 && demoChip.coverageRatio! <= 100,
          },
        })
        setChipData(demoChip)
        setChipDataSource('demo')
      })
      .finally(() => {
        if (!cancelled) {
          setChipLoading(false)
          logger.debug(`${LOG_TAG} [筹码] 加载流程结束`, {
            symbol,
            totalDurationMs: Date.now() - startTs,
          })
        }
      })

    return () => {
      cancelled = true
      logger.debug(`${LOG_TAG} [筹码] effect cleanup（symbol 变化或组件卸载）`, { symbol })
    }
  }, [symbol, basePrice, turnover, return60d, refreshKey])

  // === K线 markers（基于交易动作生成） ===
  const markers = useMemo(() => {
    if (klineData.length === 0) {
      logger.debug(`${LOG_TAG} [markers] K线数据为空，跳过生成`)
      return []
    }
    const lastBar = klineData[klineData.length - 1]!
    const today = lastBar.time

    if (!tradeAction || tradeAction === 'watch') {
      logger.debug(`${LOG_TAG} [markers] tradeAction=${tradeAction ?? EMPTY_STRING}，不生成 marker`)
      return []
    }

    if (tradeAction === 'buy') {
      logger.info(`${LOG_TAG} [markers] 生成买入标记`, {
        time: today,
        shape: 'arrowUp',
        color: STOCK_COLOR_TOKENS.up.hex,
      })
      return [{
        time: today,
        position: 'belowBar' as const,
        shape: 'arrowUp' as const,
        color: STOCK_COLOR_TOKENS.up.hex,
        text: '买',
        size: 2,
      }]
    }
    if (tradeAction === 'sell' || tradeAction === 'escape') {
      logger.info(`${LOG_TAG} [markers] 生成卖出标记`, {
        time: today,
        shape: 'arrowDown',
        action: tradeAction,
        color: STOCK_COLOR_TOKENS.down.hex,
      })
      return [{
        time: today,
        position: 'aboveBar' as const,
        shape: 'arrowDown' as const,
        color: STOCK_COLOR_TOKENS.down.hex,
        text: tradeAction === 'escape' ? '逃' : '卖',
        size: 2,
      }]
    }
    if (tradeAction === 'hold') {
      logger.info(`${LOG_TAG} [markers] 生成持有标记`, {
        time: today,
        shape: 'circle',
        color: STOCK_COLOR_TOKENS.neutral.hex,
      })
      return [{
        time: today,
        position: 'inBar' as const,
        shape: 'circle' as const,
        color: STOCK_COLOR_TOKENS.neutral.hex,
        text: '持',
        size: 1,
      }]
    }
    return []
  }, [klineData, tradeAction])

  // === 筹码图买卖点标注（基于当前价格 + 交易动作） ===
  const chipTradePoints = useMemo<ChipTradePoint[]>(() => {
    if (!chipData?.currentPrice) {
      logger.debug(`${LOG_TAG} [chipTradePoints] chipData 或 currentPrice 为空，跳过生成`)
      return []
    }
    if (!tradeAction || tradeAction === 'watch') {
      logger.debug(`${LOG_TAG} [chipTradePoints] tradeAction=${tradeAction ?? EMPTY_STRING}，不生成标注`)
      return []
    }

    const price = chipData.currentPrice
    if (tradeAction === 'buy') {
      logger.info(`${LOG_TAG} [chipTradePoints] 生成买入标注`, { price, direction: 'buy' })
      return [
        { price, direction: 'buy', label: '买点', color: STOCK_COLOR_TOKENS.up.hex },
      ]
    }
    if (tradeAction === 'sell' || tradeAction === 'escape') {
      logger.info(`${LOG_TAG} [chipTradePoints] 生成卖出标注`, {
        price,
        direction: 'sell',
        action: tradeAction,
      })
      return [
        { price, direction: 'sell', label: tradeAction === 'escape' ? '逃离' : '卖点', color: STOCK_COLOR_TOKENS.down.hex },
      ]
    }
    if (tradeAction === 'hold') {
      logger.info(`${LOG_TAG} [chipTradePoints] 生成持有标注`, { price, direction: 'buy' })
      return [
        { price, direction: 'buy', label: '持有', color: STOCK_COLOR_TOKENS.neutral.hex },
      ]
    }
    return []
  }, [chipData, tradeAction])

  return {
    klineData,
    klineLoading,
    klineDataSource,
    chipData,
    chipLoading,
    chipDataSource,
    markers,
    chipTradePoints,
    refresh,
  }
}

/**
 * @fileoverview AI 中心健康评分策略接口与实现
 *
 * 职责：
 * - 定义 AI 中心健康度/诊断评分的获取策略（Strategy 模式）
 * - 将健康评分计算从 AI 中心数据提供器中解耦，支持 Mock / 真实实现注入
 *
 * 架构变更（P5-7）：
 * - 原 aiCenterProvider.ts 内含 Math.random 健康评分生成逻辑，现迁移到本策略实现
 * - MockAICenterProvider 通过 setAIHealthScoringStrategy() 注入策略
 * - 生产环境应注入真实策略，从运行时指标或后端 API 获取健康评分
 *
 * @see src/services/ai-center/aiCenterProvider.ts — 策略消费方
  * @doc [V9-DOC-BACK-012, V9-DOC-BACK-010, V9-DOC-ARCH-008, V9-DOC-BACK-003, V9-DOC-DATA-021]
*/

import { nanoid } from 'nanoid'
import type {
  AICenterData,
  AgentItem,
  AgentListData,
  AgentOverviewMetrics,
  DiagnosticReportItem,
  DiagnosticReportsData,
  HealthMetricItem,
  HealthMetricsData,
} from '@/types/modules/ai-center.types'
import {
  AGENT_STATUS,
  AGENT_TAG,
  AGENT_TYPE_MAP,
} from '@/constants/ai-center.constants'
import {
  DIAGNOSTIC_LEVEL,
  HEALTH_MODULE_CATEGORY,
  HEALTH_STATUS,
} from '@/constants/health.constants'

/** Mock 智能体调用次数的随机区间上限 */
const MOCK_AGENT_CALL_COUNT_RANGE = 900
/** Mock 智能体调用次数的随机区间下限 */
const MOCK_AGENT_CALL_COUNT_MIN = 50

const AGENT_TAG_VALUES = Object.values(AGENT_TAG)
const AGENT_STATUS_VALUES = Object.values(AGENT_STATUS)
const HEALTH_MODULE_VALUES = Object.values(HEALTH_MODULE_CATEGORY)

/** 模拟智能体名称池 */
const MOCK_AGENT_NAMES: Array<{ type: keyof typeof AGENT_TYPE_MAP; name: string }> = [
  { type: 'agentAssistant', name: '通用投研助手' },
  { type: 'stockStrategy', name: '量化选股智能体' },
  { type: 'stockStrategy', name: '板块轮动策略体' },
  { type: 'llmIntegration', name: '多模型路由编排' },
  { type: 'knowledgeRetrieval', name: '本地知识库检索' },
  { type: 'agentAssistant', name: '复盘写作助手' },
  { type: 'stockStrategy', name: '风险预警智能体' },
  { type: 'llmIntegration', name: '推理增强智能体' },
]

const HEALTH_MODULE_NAMES: Record<string, string> = {
  CORE: '核心引擎',
  SYSTEM: '系统服务',
  AGENT: '智能体运行时',
  DATA: '数据采集层',
}

/**
 * AI 中心健康评分策略接口
 */
export interface AIHealthScoringStrategy {
  /** 获取 AI 中心统一数据：智能体列表 + 健康监控 + 诊断分析 */
  getAICenterData(): Promise<AICenterData>
}

/**
 * Mock 健康评分策略
 * @description 开发/测试环境默认策略，保留原有随机数据生成行为
 */
export class MockAIHealthScoringStrategy implements AIHealthScoringStrategy {
  async getAICenterData(): Promise<AICenterData> {
    await this.delay(500)
    return this.generateAICenterData()
  }

  private generateAICenterData(): AICenterData {
    const agents = this.generateAgentList()
    const healthMetrics = this.generateHealthMetrics()
    const diagnosticReports = this.generateDiagnosticReports()

    return { agents, healthMetrics, diagnosticReports }
  }

  private generateAgentList(): AgentListData {
    const agents: AgentItem[] = MOCK_AGENT_NAMES.map((meta) => {
      const typeKey = meta.type
      const typeMeta = AGENT_TYPE_MAP[typeKey]
      const status = AGENT_STATUS_VALUES[Math.floor(Math.random() * AGENT_STATUS_VALUES.length)]!
      const tagCount = Math.random() > 0.5 ? 2 : 1
      const tags = AGENT_TAG_VALUES.slice(0, tagCount)

      return {
        id: `agent_${nanoid(6)}`,
        type: typeKey,
        name: meta.name,
        tags,
        description: typeMeta?.description ?? '',
        callCount: Math.floor(Math.random() * MOCK_AGENT_CALL_COUNT_RANGE) + MOCK_AGENT_CALL_COUNT_MIN,
        status,
        lastActiveAt: Date.now() - Math.floor(Math.random() * 1000 * 60 * 60 * 24),
        knowledgeUsage: Math.floor(Math.random() * 500),
      }
    })

    const overview: AgentOverviewMetrics = {
      totalAgents: agents.length,
      knowledgeUsage: agents.reduce((sum, a) => sum + (a.knowledgeUsage ?? 0), 0),
      taskExecutions: agents.reduce((sum, a) => sum + a.callCount, 0),
      monitorAlerts: agents.filter((a) => a.status === AGENT_STATUS.ERROR || a.status === AGENT_STATUS.WARNING).length,
    }

    return {
      agents,
      overview,
      total: agents.length,
      page: 1,
      pageSize: agents.length,
    }
  }

  private generateHealthMetrics(): HealthMetricsData {
    const metrics: HealthMetricItem[] = HEALTH_MODULE_VALUES.map((category) => {
      const healthScore = Math.floor(Math.random() * 35) + 65
      const status = healthScore >= 85 ? HEALTH_STATUS.HEALTHY : healthScore >= 70 ? HEALTH_STATUS.WARNING : HEALTH_STATUS.CRITICAL

      return {
        id: `health_${category.toLowerCase()}`,
        name: HEALTH_MODULE_NAMES[category] ?? category,
        category,
        healthScore,
        status,
        extra: {
          成功率: `${Math.floor(Math.random() * 20) + 80}%`,
          响应时间: `${Math.floor(Math.random() * 200) + 50}ms`,
        },
        checkedAt: Date.now() - Math.floor(Math.random() * 1000 * 60 * 5),
      }
    })

    const overallScore = Math.round(metrics.reduce((sum, m) => sum + m.healthScore, 0) / metrics.length)
    const overallStatus =
      overallScore >= 85 ? HEALTH_STATUS.HEALTHY : overallScore >= 70 ? HEALTH_STATUS.WARNING : HEALTH_STATUS.CRITICAL

    return {
      metrics,
      overallScore,
      overallStatus,
      lastUpdatedAt: Date.now(),
    }
  }

  private generateDiagnosticReports(): DiagnosticReportsData {
    const modules = ['量化选股', '板块轮动', '风险预警', '知识检索', '复盘生成']
    const reports: DiagnosticReportItem[] = modules.map((moduleName) => {
      const healthScore = Math.floor(Math.random() * 30) + 65
      const successRate = Math.floor(Math.random() * 20) + 78
      const stabilityScore = Math.floor(Math.random() * 25) + 70
      const level =
        healthScore >= 85
          ? DIAGNOSTIC_LEVEL.EXCELLENT
          : healthScore >= 75
            ? DIAGNOSTIC_LEVEL.GOOD
            : healthScore >= 60
              ? DIAGNOSTIC_LEVEL.AVERAGE
              : DIAGNOSTIC_LEVEL.POOR

      return {
        id: `diag_${nanoid(6)}`,
        name: `${moduleName}诊断`,
        module: moduleName,
        healthScore,
        successRate,
        stabilityScore,
        level,
        detail: `${moduleName}模块综合健康度${this.scoreLabel(healthScore)}，成功率${successRate}%，稳定性${this.scoreLabel(stabilityScore)}。`,
        reportedAt: Date.now() - Math.floor(Math.random() * 1000 * 60 * 30),
      }
    })

    const avg = reports.reduce((sum, r) => sum + r.healthScore, 0) / reports.length
    const overallLevel =
      avg >= 85 ? DIAGNOSTIC_LEVEL.EXCELLENT : avg >= 75 ? DIAGNOSTIC_LEVEL.GOOD : avg >= 60 ? DIAGNOSTIC_LEVEL.AVERAGE : DIAGNOSTIC_LEVEL.POOR

    return {
      reports,
      overallLevel,
      lastUpdatedAt: Date.now(),
    }
  }

  private scoreLabel(score: number): string {
    if (score >= 85) return '优秀'
    if (score >= 70) return '良好'
    if (score >= 55) return '一般'
    return '偏弱'
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
  }
}

/**
