/**
 * @module configExportService
 * @description 配置模板导出/导入服务
 *
 * 提供配置模板的 JSON 格式导出与导入功能，支持：
 * - 单配置导出（生成包含元数据的 JSON 文件）
 * - JSON 文件导入（校验格式版本、重名检测）
 * - 浏览器端文件下载
 *
 * 导出文件格式：
 * {
 *   "meta": { "exportVersion": "1.0", "exportedAt": 1234567890, "sourceName": "高频行情监控" },
 *   "config": { ...PersistedWizardConfig }
 * }
  * @doc [V9-DOC-BACK-012, V9-DOC-DATA-047, V9-DOC-BACK-021, V9-DOC-DATA-068, V9-DOC-FRONT-020]
*/

import { getLogger } from '@/lib/logger'
import type { PersistedWizardConfig, ExportedConfigFile, ConfigExportMeta } from '@/types/modules/collection.types'
import { validateConfigName } from '@/lib/validation'

const logger = getLogger()

const EXPORT_VERSION = '1.0'

/**
 * 将配置转换为导出文件结构
 */
export function buildExportFile(config: PersistedWizardConfig): ExportedConfigFile {
  const meta: ConfigExportMeta = {
    exportVersion: EXPORT_VERSION,
    exportedAt: Date.now(),
    sourceName: config.name,
  }
  return { meta, config }
}

/**
 * 将配置导出为 JSON Blob
 */
export function exportConfigToJSON(config: PersistedWizardConfig): Blob {
  const exportFile = buildExportFile(config)
  const jsonString = JSON.stringify(exportFile, null, 2)
  return new Blob([jsonString], { type: 'application/json' })
}

/**
 * 从文件解析导出的配置
 */
export async function importConfigFromJSON(file: File): Promise<ExportedConfigFile> {
  try {
    const text = await file.text()
    const parsed = JSON.parse(text) as ExportedConfigFile

    if (!parsed.meta || !parsed.config) {
      throw new Error('导入文件格式不正确')
    }

    if (parsed.meta.exportVersion !== EXPORT_VERSION) {
      logger.warn('[configExportService] 导入配置版本不匹配', {
        fileVersion: parsed.meta.exportVersion,
        currentVersion: EXPORT_VERSION,
      })
    }

    return parsed
  } catch (err) {
    logger.error('[configExportService] 导入配置解析失败', { error: err })
    throw new Error('导入文件解析失败')
  }
}

/**
 * 生成导出文件名
 */
export function generateExportFilename(config: PersistedWizardConfig): string {
  const name = config.name.replace(/[\\/:*?"<>|]/g, '_')
  const date = new Date().toISOString().split('T')[0]
  return `${name}_config_${date}.json`
}

/**
 * 触发浏览器下载文件
 */
export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
}

/**
 * 导出配置并自动下载
 */
export function exportAndDownloadConfig(config: PersistedWizardConfig): void {
  logger.info('[configExportService] 导出配置', {
    configId: config.id,
    name: config.name,
    format: 'json',
    version: EXPORT_VERSION,
  })

  const blob = exportConfigToJSON(config)
  const filename = generateExportFilename(config)
  downloadBlob(blob, filename)
}

/**
 * 导入配置前的校验
 * @returns { ok: true } 或 { ok: false, error: string }
 */
export function validateImportedConfig(
  config: PersistedWizardConfig,
  existingNames: string[],
): { ok: true } | { ok: false; error: string } {
  const nameValidation = validateConfigName(config.name)
  if (!nameValidation.valid) {
    return { ok: false, error: nameValidation.error ?? '名称校验失败' }
  }

  if (existingNames.includes(config.name)) {
    return { ok: false, error: `配置名称 "${config.name}" 已存在` }
  }

  return { ok: true }
}

/**
 * @module DataIntegrityGuard
 * @description 数据传输完整性守卫（P1 修复 R07：数据包丢失）
 *
 * 核心机制：
 * 1. 每次 DataBridge 发送带 traceId 和 sequenceNumber
 * 2. 接收端校验连续性，缺失则重试
 * 3. 统计发送/接收/重试次数
 *
 * traceId 格式：{source}-{timestamp}-{random}
 * 由发送方生成，接收方校验，确保每条数据可追溯
 *
 * @doc V9-DOC-QUALITY-007
 */

import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ── 类型定义 ──

/** 数据包追踪信息 */
export interface DataPacketTrace {
  /** 追踪 ID：{source}-{timestamp}-{random} */
  traceId: string
  /** 序列号：同一批次内的序号 */
  sequenceNumber: number
  /** 批次 ID */
  batchId: string
  /** 发送时间 */
  sentAt: number
  /** 数据维度 */
  dimension: string
  /** 股票代码 */
  symbol: string
}

/** 数据包信封 */
export interface DataPacketEnvelope {
  /** 追踪信息 */
  trace: DataPacketTrace
  /** 数据载荷 */
  payload: Record<string, unknown>
  /** 重试次数 */
  retryCount: number
}

/** 传输统计 */
export interface TransmissionStats {
  /** 发送总数 */
  sent: number
  /** 接收总数 */
  received: number
  /** 丢失数 */
  lost: number
  /** 重试总数 */
  retries: number
  /** 重试成功数 */
  retrySuccess: number
  /** 最近一次丢失的 traceId 列表 */
  missingTraces: string[]
  /** 最近一次传输时间 */
  lastTransmissionAt: number
}

/** 序列号追踪器 */
interface SequenceTracker {
  lastReceived: number
  gaps: number[]
  receivedSet: Set<number>
}

// ── 全局状态 ──

let stats: TransmissionStats = {
  sent: 0,
  received: 0,
  lost: 0,
  retries: 0,
  retrySuccess: 0,
  missingTraces: [],
  lastTransmissionAt: 0,
}

/** 维度 → 序列号追踪器 */
const sequenceTrackers = new Map<string, SequenceTracker>()

/** 待重试的数据包 */
const retryQueue: DataPacketEnvelope[] = []
const MAX_RETRY_QUEUE = 500

// ── 工具函数 ──

/**
 * 生成 traceId
 */
export function generateTraceId(source: string, symbol: string): string {
  const ts = Date.now()
  const rand = Math.random().toString(36).substring(2, 8)
  return `${source}-${ts}-${rand}-${symbol}`
}

/**
 * 生成批次 ID
 */
export function generateBatchId(): string {
  return `batch-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`
}

// ── 发送端 API ──

/**
 * 创建带追踪的数据包信封
 *
 * 使用方式：
 *   const envelope = createDataPacket('tencent', '000001.SZ', { close: 10.5, ... })
 *   await dataBridge.forward({ action: 'writeQuote', payload: envelope })
 */
export function createDataPacket(
  source: string,
  symbol: string,
  payload: Record<string, unknown>,
  batchId?: string,
): DataPacketEnvelope {
  const trace: DataPacketTrace = {
    traceId: generateTraceId(source, symbol),
    sequenceNumber: stats.sent + 1,
    batchId: batchId || generateBatchId(),
    sentAt: Date.now(),
    dimension: 'daily_quotes',
    symbol,
  }

  stats.sent++
  stats.lastTransmissionAt = Date.now()

  return {
    trace,
    payload: {
      ...payload,
      __trace: trace,
    },
    retryCount: 0,
  }
}

/**
 * 批量创建数据包
 */
export function createDataPackets(
  source: string,
  items: Array<{ symbol: string; payload: Record<string, unknown> }>,
): DataPacketEnvelope[] {
  const batchId = generateBatchId()
  return items.map((item) => createDataPacket(source, item.symbol, item.payload, batchId))
}

// ── 接收端 API ──

/**
 * 接收端校验数据包完整性
 *
 * 使用方式：
 *   const envelope = receivedData as DataPacketEnvelope
 *   const result = verifyDataPacket('daily_quotes', envelope)
 *   if (result.missing) {
 *     await requestRetry(envelope)
 *   }
 */
export function verifyDataPacket(
  dimension: string,
  envelope: DataPacketEnvelope,
): {
  valid: boolean
  missing: boolean
  gap: number[]
  isRetry: boolean
} {
  const { trace } = envelope
  stats.received++
  stats.lastTransmissionAt = Date.now()

  // 获取或创建序列号追踪器
  let tracker = sequenceTrackers.get(dimension)
  if (!tracker) {
    tracker = { lastReceived: 0, gaps: [], receivedSet: new Set() }
    sequenceTrackers.set(dimension, tracker)
  }

  const isRetry = tracker.receivedSet.has(trace.sequenceNumber)
  if (!isRetry) {
    tracker.receivedSet.add(trace.sequenceNumber)
  }

  // 检查序列号连续性
  if (tracker.lastReceived > 0 && trace.sequenceNumber > tracker.lastReceived + 1) {
    // 存在间隙
    for (let i = tracker.lastReceived + 1; i < trace.sequenceNumber; i++) {
      tracker.gaps.push(i)
    }
    stats.lost += trace.sequenceNumber - tracker.lastReceived - 1
    stats.missingTraces.push(trace.traceId)
    if (stats.missingTraces.length > 100) {
      stats.missingTraces = stats.missingTraces.slice(-50)
    }
    logger.warn(
      `[DataIntegrity] 序列号间隙: ${dimension} #${tracker.lastReceived} → #${trace.sequenceNumber}, 缺失 ${trace.sequenceNumber - tracker.lastReceived - 1} 条`,
    )
  }

  tracker.lastReceived = Math.max(tracker.lastReceived, trace.sequenceNumber)

  return {
    valid: true,
    missing: tracker.gaps.length > 0,
    gap: [...tracker.gaps],
    isRetry,
  }
}

// ── 重试机制 ──

/**
 * 将数据包加入重试队列
 */
export function enqueueRetry(envelope: DataPacketEnvelope): void {
  if (retryQueue.length >= MAX_RETRY_QUEUE) {
    retryQueue.shift()
  }
  envelope.retryCount++
  retryQueue.push(envelope)
  stats.retries++
}

/**
 * 获取重试队列
 */
export function getRetryQueue(): Readonly<DataPacketEnvelope[]> {
  return retryQueue
}

/**
 * 从重试队列中移除（重试成功）
 */
export function dequeueRetry(traceId: string): void {
  const idx = retryQueue.findIndex((e) => e.trace.traceId === traceId)
  if (idx >= 0) {
    retryQueue.splice(idx, 1)
    stats.retrySuccess++
    logger.info(`[DataIntegrity] 重试成功: ${traceId}`)
  }
}

/**
 * 清空重试队列
 */
export function clearRetryQueue(): void {
  retryQueue.length = 0
}

// ── 统计 API ──

/**
 * 获取传输统计
 */
export function getTransmissionStats(): Readonly<TransmissionStats> {
  return { ...stats }
}

/**
 * 获取序列号间隙
 */
export function getSequenceGaps(dimension: string): number[] {
  return sequenceTrackers.get(dimension)?.gaps ?? []
}

/**
 * 获取传输成功率
 */
export function getTransmissionSuccessRate(): number {
  if (stats.sent === 0) return 0
  return (stats.received / stats.sent)
}

/**
 * 重置统计
 */
export function resetTransmissionStats(): void {
  stats = {
    sent: 0,
    received: 0,
    lost: 0,
    retries: 0,
    retrySuccess: 0,
    missingTraces: [],
    lastTransmissionAt: 0,
  }
  sequenceTrackers.clear()
}

/**
 * 生成传输健康报告
 */
export function generateTransmissionReport(): string {
  const parts: string[] = [
    `发送: ${stats.sent} | 接收: ${stats.received}`,
    `丢失: ${stats.lost} (${stats.sent > 0 ? ((stats.lost / stats.sent) * 100).toFixed(2) : '0'}%)`,
    `接收率: ${(getTransmissionSuccessRate() * 100).toFixed(2)}%`,
  ]
  if (stats.retries > 0) {
    parts.push(`重试: ${stats.retries} (成功 ${stats.retrySuccess})`)
  }
  return parts.join(' | ')
}

/**
 * SourcePriorityManager — 数据源优先级策略
 *
 * 按维度定义数据源优先级顺序，提供最优数据源选择、降级回退、
 * 多源冲突检测以及各数据源的健康度追踪功能。
 *
 * @doc V9-DOC-QUALITY-015
 */

import { getLogger } from '@/lib/logger';

const logger = getLogger();

/** 数据维度 */
export type DataDimension =
  | 'realtime_quote'
  | 'daily_quotes'
  | 'fundamental'
  | 'news'
  | 'research';

/** 数据源标识 */
export type DataSource = string;

/** 冲突检测结果 */
export interface SourceConflict {
  dimension: DataDimension;
  field: string;
  sourceResults: Array<{ source: DataSource; value: unknown }>;
  detectedAt: number;
}

/** 数据源健康信息 */
export interface SourceHealth {
  source: DataSource;
  successRate: number;
  lastSuccess: number;
  lastFailure: number;
}

/** 数据源统计记录 */
interface SourceRecord {
  successCount: number;
  failureCount: number;
  lastSuccess: number;
  lastFailure: number;
}

/**
 * 各维度的数据源优先级顺序（从高到低）
 */
export const SOURCE_PRIORITY: Record<DataDimension, DataSource[]> = {
  realtime_quote: ['tencent', 'sina'],
  daily_quotes: ['tushare', 'tencent', 'sina'],
  fundamental: ['tushare', 'crawler'],
  news: ['crawler', 'llm'],
  research: ['tushare', 'llm'],
};

/**
 * 内部数据源统计
 */
const sourceRecords: Map<DataSource, SourceRecord> = new Map();

/**
 * 获取或创建数据源统计记录
 */
function getOrCreateRecord(source: DataSource): SourceRecord {
  if (!sourceRecords.has(source)) {
    sourceRecords.set(source, {
      successCount: 0,
      failureCount: 0,
      lastSuccess: 0,
      lastFailure: 0,
    });
  }
  return sourceRecords.get(source)!;
}

/**
 * 记录数据源调用成功
 */
function recordSuccess(source: DataSource): void {
  const record = getOrCreateRecord(source);
  record.successCount++;
  record.lastSuccess = Date.now();
}

/**
 * 记录数据源调用失败
 */
function recordFailure(source: DataSource): void {
  const record = getOrCreateRecord(source);
  record.failureCount++;
  record.lastFailure = Date.now();
}

/**
 * 根据维度和当前可用数据源，选择优先级最高的数据源
 *
 * @param dimension - 数据维度
 * @param availableSources - 当前可用的数据源列表
 * @returns 优先级最高的可用数据源，若无可用的则返回 null
 */
export function selectDataSource(
  dimension: DataDimension,
  availableSources: DataSource[],
): DataSource | null {
  const priorityList = SOURCE_PRIORITY[dimension];

  if (!priorityList || priorityList.length === 0) {
    logger.warn(`No priority list defined for dimension: ${dimension}`);
    return null;
  }

  const availableSet = new Set(availableSources.map((s) => s.toLowerCase()));

  for (const preferred of priorityList) {
    if (availableSet.has(preferred.toLowerCase())) {
      logger.debug(`Selected source "${preferred}" for dimension "${dimension}"`);
      return preferred;
    }
  }

  logger.warn(`No available source found for dimension "${dimension}". Available: ${availableSources.join(', ')}`);
  return null;
}

/**
 * 在某个数据源失败后，获取下一个可用的降级数据源
 *
 * @param dimension - 数据维度
 * @param failedSource - 已失败的数据源
 * @returns 下一个可用的数据源标识，若无则返回 null
 */
export function fallbackDataSource(
  dimension: DataDimension,
  failedSource: DataSource,
): DataSource | null {
  const priorityList = SOURCE_PRIORITY[dimension];

  if (!priorityList || priorityList.length === 0) {
    logger.warn(`No priority list defined for dimension: ${dimension}`);
    return null;
  }

  recordFailure(failedSource);

  const failedIndex = priorityList.findIndex(
    (s) => s.toLowerCase() === failedSource.toLowerCase(),
  );

  if (failedIndex === -1) {
    logger.warn(`Failed source "${failedSource}" not found in priority list for "${dimension}"`);
    return priorityList[0] ?? null;
  }

  // 从失败源的下一个开始依次尝试
  for (let i = failedIndex + 1; i < priorityList.length; i++) {
    const candidate = priorityList[i];
    if (!candidate) continue;
    // 检查该候选源是否处于健康状态（最近没有连续失败）
    const record = sourceRecords.get(candidate);
    if (record) {
      // 如果最近失败率过高（> 80%），跳过
      const total = record.successCount + record.failureCount;
      if (total > 0) {
        const failureRate = record.failureCount / total;
        if (failureRate > 0.8 && record.lastFailure > record.lastSuccess) {
          logger.debug(`Skipping unhealthy source "${candidate}" for "${dimension}"`);
          continue;
        }
      }
    }
    logger.info(`Falling back to source "${candidate}" for "${dimension}" after "${failedSource}" failed`);
    return candidate;
  }

  logger.error(`No fallback source available for "${dimension}" after "${failedSource}"`);
  return null;
}

/**
 * 检测多个数据源对同一字段返回不同数据时的冲突
 *
 * @param dimension - 数据维度
 * @param sourceResults - 各数据源的结果数组，每项包含 source 和 data
 * @returns 冲突记录数组
 */
export function detectSourceConflict(
  dimension: DataDimension,
  sourceResults: Array<{ source: DataSource; data: Record<string, unknown> }>,
): SourceConflict[] {
  const conflicts: SourceConflict[] = [];

  if (sourceResults.length < 2) {
    return conflicts;
  }

  // 收集所有字段名
  const allFields = new Set<string>();
  for (const result of sourceResults) {
    for (const key of Object.keys(result.data)) {
      allFields.add(key);
    }
  }

  for (const field of allFields) {
    const valuesMap = new Map<DataSource, unknown>();

    for (const result of sourceResults) {
      if (field in result.data) {
        valuesMap.set(result.source, result.data[field]);
      }
    }

    if (valuesMap.size < 2) {
      continue;
    }

    // 检查所有值是否一致
    const values = Array.from(valuesMap.values());
    const uniqueValues = new Set(values.map((v) => JSON.stringify(v)));

    if (uniqueValues.size > 1) {
      const conflict: SourceConflict = {
        dimension,
        field,
        sourceResults: Array.from(valuesMap.entries()).map(([source, value]) => ({
          source,
          value,
        })),
        detectedAt: Date.now(),
      };
      conflicts.push(conflict);
      logger.warn(
        `Source conflict detected for "${dimension}.${field}": ${conflict.sourceResults
          .map((r) => `${r.source}=${JSON.stringify(r.value)}`)
          .join(', ')}`,
      );
    }
  }

  return conflicts;
}

/**
 * 获取所有数据源的健康状态
 *
 * @returns 各数据源的健康信息数组
 */
export function getSourceHealth(): SourceHealth[] {
  const healthList: SourceHealth[] = [];

  for (const [source, record] of sourceRecords.entries()) {
    const total = record.successCount + record.failureCount;
    healthList.push({
      source,
      successRate: total > 0 ? record.successCount / total : 1,
      lastSuccess: record.lastSuccess,
      lastFailure: record.lastFailure,
    });
  }

  // 按成功率降序排列
  healthList.sort((a, b) => b.successRate - a.successRate);

  // 补充所有已定义但尚未有记录的数据源
  const recordedSources = new Set(healthList.map((h) => h.source));
  const allDefinedSources = new Set<DataSource>();
  for (const sources of Object.values(SOURCE_PRIORITY)) {
    for (const s of sources) {
      allDefinedSources.add(s);
    }
  }
  for (const s of allDefinedSources) {
    if (!recordedSources.has(s)) {
      healthList.push({
        source: s,
        successRate: 1,
        lastSuccess: 0,
        lastFailure: 0,
      });
    }
  }

  logger.info(`Source health report: ${healthList.length} sources tracked`);
  return healthList;
}

/**
 * 手动标记数据源调用成功
 *
 * @param source - 数据源标识
 */
export function markSourceSuccess(source: DataSource): void {
  recordSuccess(source);
}

/**
 * 手动标记数据源调用失败
 *
 * @param source - 数据源标识
 */
export function markSourceFailure(source: DataSource): void {
  recordFailure(source);
}

/**
 * 重置所有数据源统计
 */
export function resetSourceStats(): void {
  sourceRecords.clear();
  logger.info('All source stats have been reset');
}

