    expect(typeof unsubscribe).toBe('function')

    const dataSource = createMockDataSource({ mode: 'once' })
    const taskId = scheduler.registerTask('widget_1', 'instance_1', dataSource)
    scheduler.startTask(taskId)

    unsubscribe()
