      const cancelled = await cancelPlan('plan_001')
      expect(cancelled).toBeUndefined()
    })
  })

  describe('getOrphanPlans', () => {
    it('returns non-terminal plans', async () => {
      vi.mocked(dataBridge.query).mockResolvedValue({
