/**
 * @doc [V9-DOC-BACK-012, V9-DOC-BACK-023, V9-DOC-BACK-033, V9-DOC-BACK-021, V9-DOC-BACK-026]
 */
import { getLogger } from '@/lib/logger'
import type {
  HashVerifyRequest,
  HashVerifyResponse,
  HashBatchVerifyRequest,
  HashBatchVerifyResponse,
  RiskDetailsRequest,
  RiskDetailsResponse,
  RiskDetail,
  RulesSyncResult,
  PerformanceMetric,
} from '@/data/types'


const logger = getLogger()

const MOCK_RISKY_HASHES: Record<string, RiskDetail[]> = {
  'mock-risky-hash-1': [
    {
      hash: 'mock-risky-hash-1',
      cve_id: 'CVE-2024-12345',
      description: '发现高危安全漏洞：存在远程代码执行风险',
      remediation_advice: '请升级至最新安全版本，并审查相关代码逻辑',
      severity: 'critical',
      affected_version: '1.0.0',
      published_date: '2024-01-15',
    },
  ],
  'mock-risky-hash-2': [
    {
      hash: 'mock-risky-hash-2',
      cve_id: 'CVE-2024-67890',
      description: '发现中危安全漏洞：存在信息泄露风险',
      remediation_advice: '请检查敏感信息的处理方式，确保加密存储',
      severity: 'medium',
      affected_version: '2.1.0',
      published_date: '2024-02-20',
    },
  ],
}

/**
 * CloudSyncClient
 */
export class CloudSyncClient {
  constructor() {}

  async verifyHash(request: HashVerifyRequest): Promise<HashVerifyResponse> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] verifyHash - 开始验证哈希`, {
      file_hash: request.file_hash,
      file_type: request.file_type,
      project_id: request.project_id,
    })

    const risks = MOCK_RISKY_HASHES[request.file_hash]
    let response: HashVerifyResponse

    if (risks) {
      const maxSeverity = risks.reduce((max, r) => {
        const levels = { critical: 5, high: 4, medium: 3, low: 2, info: 1 }
        return Math.max(max, levels[r.severity])
      }, 0)

      response = {
        status: 'risky',
        risk_level: maxSeverity as HashVerifyResponse['risk_level'],
        cve_ids: risks.map((r) => r.cve_id),
      }

      logger.info(`[CloudSyncClient] verifyHash - 发现风险`, {
        file_hash: request.file_hash,
        status: response.status,
        risk_level: response.risk_level,
        cve_ids: response.cve_ids,
        duration_ms: Date.now() - startTime,
      })
    } else {
      response = {
        status: 'unknown',
        risk_level: 0,
      }

      logger.info(`[CloudSyncClient] verifyHash - 未发现风险`, {
        file_hash: request.file_hash,
        status: response.status,
        risk_level: response.risk_level,
        duration_ms: Date.now() - startTime,
      })
    }

    return response
  }

  async batchVerifyHashes(request: HashBatchVerifyRequest): Promise<HashBatchVerifyResponse> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] batchVerifyHashes - 开始批量验证`, {
      hash_count: request.hash_list.length,
      project_id: request.project_id,
      request_size_bytes: JSON.stringify(request).length,
    })

    const results: Record<string, HashVerifyResponse> = {}
    let riskyCount = 0
    let unknownCount = 0

    for (const hash of request.hash_list) {
      const risks = MOCK_RISKY_HASHES[hash]
      if (risks) {
        const maxSeverity = risks.reduce((max, r) => {
          const levels = { critical: 5, high: 4, medium: 3, low: 2, info: 1 }
          return Math.max(max, levels[r.severity])
        }, 0)

        results[hash] = {
          status: 'risky',
          risk_level: maxSeverity as HashVerifyResponse['risk_level'],
          cve_ids: risks.map((r) => r.cve_id),
        }
        riskyCount++
      } else {
        results[hash] = {
          status: 'unknown',
          risk_level: 0,
        }
        unknownCount++
      }
    }

    const duration = Date.now() - startTime
    logger.info(`[CloudSyncClient] batchVerifyHashes - 批量验证完成`, {
      total_hashes: request.hash_list.length,
      risky_count: riskyCount,
      unknown_count: unknownCount,
      duration_ms: duration,
      avg_per_hash_ms: request.hash_list.length > 0 ? (duration / request.hash_list.length).toFixed(2) : '0',
    })

    return { results }
  }

  async getRiskDetails(request: RiskDetailsRequest): Promise<RiskDetailsResponse> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] getRiskDetails - 开始获取风险详情`, {
      hash_count: request.hash_list.length,
    })

    const risks: RiskDetail[] = []

    for (const hash of request.hash_list) {
      const hashRisks = MOCK_RISKY_HASHES[hash]
      if (hashRisks) {
        risks.push(...hashRisks)
        logger.debug(`[CloudSyncClient] getRiskDetails - 找到风险条目`, {
          hash,
          cve_count: hashRisks.length,
          severities: hashRisks.map((r) => r.severity),
        })
      }
    }

    logger.info(`[CloudSyncClient] getRiskDetails - 获取风险详情完成`, {
      total_hashes: request.hash_list.length,
      total_risks: risks.length,
      unique_cves: [...new Set(risks.map((r) => r.cve_id))].length,
      duration_ms: Date.now() - startTime,
    })

    return { risks }
  }

  async checkRulesVersion(): Promise<{ version: string }> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] checkRulesVersion - 开始检查规则版本`)

    const response = { version: '1.0.0' }

    logger.info(`[CloudSyncClient] checkRulesVersion - 检查完成`, {
      version: response.version,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async downloadRules(version: string): Promise<{
    version: string
    rules: unknown[]
    checksum: string
  }> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] downloadRules - 开始下载规则`, {
      requested_version: version,
    })

    const response = {
      version,
      rules: [],
      checksum: '',
    }

    logger.info(`[CloudSyncClient] downloadRules - 下载完成`, {
      version: response.version,
      rule_count: response.rules.length,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async syncRules(): Promise<RulesSyncResult> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] syncRules - 开始同步规则`)

    const response = {
      current_version: '1.0.0',
      latest_version: '1.0.0',
      updated: false,
      downloaded_rules: 0,
      skipped_rules: 0,
    }

    logger.info(`[CloudSyncClient] syncRules - 同步完成`, {
      current_version: response.current_version,
      latest_version: response.latest_version,
      updated: response.updated,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async uploadPerformanceMetrics(metrics: PerformanceMetric[]): Promise<{ success: boolean }> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] uploadPerformanceMetrics - 开始上传性能指标`, {
      metric_count: metrics.length,
      request_size_bytes: JSON.stringify(metrics).length,
    })

    const response = { success: true }

    logger.info(`[CloudSyncClient] uploadPerformanceMetrics - 上传完成`, {
      success: response.success,
      metric_count: metrics.length,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async uploadHashBatch(hashes: HashVerifyRequest[]): Promise<HashBatchVerifyResponse> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] uploadHashBatch - 开始上传哈希批次`, {
      hash_count: hashes.length,
      project_id: hashes[0]?.project_id ?? 'N/A',
    })

    const hashList = hashes.map((h) => h.file_hash)
    const response = await this.batchVerifyHashes({ hash_list: hashList, project_id: hashes[0]?.project_id ?? '' })

    logger.info(`[CloudSyncClient] uploadHashBatch - 上传完成`, {
      hash_count: hashes.length,
      risky_count: Object.values(response.results).filter((r) => r.status === 'risky').length,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async healthCheck(): Promise<{ status: 'healthy' | 'unhealthy'; version?: string }> {
    const startTime = Date.now()
    logger.info(`[CloudSyncClient] healthCheck - 开始健康检查`)

    const response = { status: 'healthy' as const, version: '1.0.0' }

    logger.info(`[CloudSyncClient] healthCheck - 检查完成`, {
      status: response.status,
      version: response.version,
      duration_ms: Date.now() - startTime,
    })

    return response
  }
}

/**
 * cloudSyncClient
 */
export const cloudSyncClient = new CloudSyncClient()

/**
 * @doc [V9-DOC-BACK-012, V9-DOC-BACK-023, V9-DOC-BACK-033, V9-DOC-BACK-021, V9-DOC-BACK-026]
 */
import { getLogger } from '@/lib/logger'
import type { FileHash, FileType, HashVerifyRequest, HashVerifyResponse, HashBatchVerifyRequest, HashBatchVerifyResponse } from '@/data/types'
import { HYBRID_PROOFREAD_CONFIG } from '@/config/hybridProofreadConfig'

const logger = getLogger()

/**
 * HashService
 */
export class HashService {
  async computeHash(data: string | Buffer): Promise<string> {
    const crypto = await import('crypto')
    const hash = crypto.createHash(HYBRID_PROOFREAD_CONFIG.hash.algorithm)
      .update(data)
      .digest('hex')
    return hash
  }

  async computeFileHash(filePath: string): Promise<string> {
    const fs = await import('fs')
    const content = await fs.promises.readFile(filePath)
    return this.computeHash(content)
  }

  async computeMultipleHashes(filePaths: string[]): Promise<FileHash[]> {
    const results: FileHash[] = []
    const fs = await import('fs')

    for (const filePath of filePaths) {
      try {
        const content = await fs.promises.readFile(filePath)
        const hash = await this.computeHash(content)
        const stats = await fs.promises.stat(filePath)

        results.push({
          file_hash: hash,
          file_type: this.getFileType(filePath),
          file_path: filePath,
          project_id: '',
          last_modified: stats.mtime.getTime(),
          size_bytes: stats.size,
        })
      } catch (error) {
        logger.warn(`[HashService] 计算哈希失败: ${filePath}`, { error })
      }
    }

    return results
  }

  async batchComputeHashes(filePaths: string[], projectId: string, batchSize?: number): Promise<FileHash[]> {
    const effectiveBatchSize = batchSize ?? HYBRID_PROOFREAD_CONFIG.hash.batchSize
    const results: FileHash[] = []

    for (let i = 0; i < filePaths.length; i += effectiveBatchSize) {
      const batch = filePaths.slice(i, i + effectiveBatchSize)
      const batchResults = await this.computeMultipleHashes(batch)
      results.push(
        ...batchResults.map((h) => ({ ...h, project_id: projectId })),
      )
    }

    return results
  }

  async verifyHash(request: HashVerifyRequest): Promise<HashVerifyResponse> {
    logger.info(`[HashService] 验证哈希: ${request.file_hash}`)

    return {
      status: 'unknown',
      risk_level: 0,
    }
  }

  async batchVerifyHashes(request: HashBatchVerifyRequest): Promise<HashBatchVerifyResponse> {
    logger.info(`[HashService] 批量验证哈希: ${request.hash_list.length} 个`)

    const results: Record<string, HashVerifyResponse> = {}

    for (const hash of request.hash_list) {
      results[hash] = {
        status: 'unknown',
        risk_level: 0,
      }
    }

    return { results }
  }

  private getFileType(filePath: string): FileType {
    if (filePath.endsWith('.gradle')) return 'gradle_dep'
    if (filePath.endsWith('.keystore') || filePath.endsWith('.jks')) return 'keystore'
    if (filePath.startsWith('.env') || filePath.includes('.env.')) return 'env_file'
    if (filePath.match(/\.(ts|tsx|js|jsx|vue|java|kotlin|swift|py)$/)) return 'source_code'
    if (filePath.match(/\.(json|xml|yaml|yml|toml|ini)$/)) return 'config_file'
    if (filePath.match(/\.(apk|ipa|dylib|so|dll|exe)$/)) return 'binary'
    return 'other'
  }

  isValidHash(hash: string): boolean {
    const expectedLength = HYBRID_PROOFREAD_CONFIG.hash.algorithm === 'sha256' ? 64 : 40
    return hash.length === expectedLength && /^[0-9a-fA-F]+$/.test(hash)
  }
}

/**
 * hashService
 */
export const hashService = new HashService()

/**
 * @doc [V9-DOC-BACK-012, V9-DOC-BACK-023, V9-DOC-BACK-033, V9-DOC-BACK-021, V9-DOC-BACK-026]
 */
import { getLogger } from '@/lib/logger'
import { safeRegex } from '@/lib/safeRegex'
import type { RuleConfig, RulePackage, RuleMatchResult, RulesSyncResult } from '@/data/types'
import { HYBRID_PROOFREAD_CONFIG, HYBRID_PROOFREAD_DEFAULT_RULES } from '@/config/hybridProofreadConfig'
import { defaultStorage } from '@/lib/localStorageManager'

const logger = getLogger()

/**
 * RuleEngine
 */
export class RuleEngine {
  private rules: RuleConfig[] = []
  private currentVersion: string = HYBRID_PROOFREAD_CONFIG.rules.defaultVersion
  private lastSyncTime: number = 0

  constructor() {
    void this.loadRules()
  }

  async loadRules(): Promise<void> {
    const startTime = Date.now()
    logger.info(`[RuleEngine] loadRules - 开始加载规则`)

    try {
      const cachedRules = defaultStorage.get(HYBRID_PROOFREAD_CONFIG.rules.cacheKey)
      if (typeof cachedRules === 'string') {
        const parsed = JSON.parse(cachedRules) as RulePackage
        this.rules = parsed.rules
        this.currentVersion = parsed.version

        logger.info(`[RuleEngine] loadRules - 从缓存加载规则成功`, {
          version: parsed.version,
          rule_count: parsed.rules.length,
          cache_key: HYBRID_PROOFREAD_CONFIG.rules.cacheKey,
          duration_ms: Date.now() - startTime,
        })
      } else {
        this.rules = HYBRID_PROOFREAD_DEFAULT_RULES

        logger.info(`[RuleEngine] loadRules - 缓存未命中，使用默认规则`, {
          version: this.currentVersion,
          rule_count: this.rules.length,
          duration_ms: Date.now() - startTime,
        })
      }
    } catch (error) {
      logger.error(`[RuleEngine] loadRules - 加载规则失败，使用默认规则`, {
        error: error instanceof Error ? error.message : String(error),
        cache_key: HYBRID_PROOFREAD_CONFIG.rules.cacheKey,
        duration_ms: Date.now() - startTime,
      })
      this.rules = HYBRID_PROOFREAD_DEFAULT_RULES
    }
  }

  async syncRules(): Promise<RulesSyncResult> {
    const startTime = Date.now()
    const now = Date.now()

    if (now - this.lastSyncTime < HYBRID_PROOFREAD_CONFIG.rules.syncIntervalMs) {
      const timeUntilNextSync = HYBRID_PROOFREAD_CONFIG.rules.syncIntervalMs - (now - this.lastSyncTime)
      logger.info(`[RuleEngine] syncRules - 规则同步未到时间间隔`, {
        last_sync_time: new Date(this.lastSyncTime).toISOString(),
        sync_interval_ms: HYBRID_PROOFREAD_CONFIG.rules.syncIntervalMs,
        time_until_next_sync_ms: timeUntilNextSync,
        current_version: this.currentVersion,
      })

      return {
        current_version: this.currentVersion,
        latest_version: this.currentVersion,
        updated: false,
        downloaded_rules: 0,
        skipped_rules: 0,
      }
    }

    logger.info(`[RuleEngine] syncRules - 开始同步规则`, {
      current_version: this.currentVersion,
      last_sync_time: new Date(this.lastSyncTime).toISOString(),
      sync_interval_ms: HYBRID_PROOFREAD_CONFIG.rules.syncIntervalMs,
    })

    try {
      const versionStart = Date.now()
      const versionResponse = await this.fetchLatestVersion()
      const latestVersion = versionResponse.version
      const versionFetchDuration = Date.now() - versionStart

      logger.info(`[RuleEngine] syncRules - 获取最新版本完成`, {
        current_version: this.currentVersion,
        latest_version: latestVersion,
        fetch_duration_ms: versionFetchDuration,
      })

      if (latestVersion === this.currentVersion) {
        this.lastSyncTime = now

        logger.info(`[RuleEngine] syncRules - 当前规则已是最新版本`, {
          version: latestVersion,
          total_duration_ms: Date.now() - startTime,
        })

        return {
          current_version: this.currentVersion,
          latest_version: latestVersion,
          updated: false,
          downloaded_rules: 0,
          skipped_rules: 0,
        }
      }

      const downloadStart = Date.now()
      const rulesResponse = await this.downloadRules(latestVersion)
      const downloadDuration = Date.now() - downloadStart

      logger.info(`[RuleEngine] syncRules - 规则下载完成`, {
        version: rulesResponse.version,
        rule_count: rulesResponse.rules.length,
        download_duration_ms: downloadDuration,
        checksum: rulesResponse.checksum,
      })

      this.rules = rulesResponse.rules
      this.currentVersion = rulesResponse.version

      const cacheStart = Date.now()
      await this.cacheRules(rulesResponse)
      const cacheDuration = Date.now() - cacheStart

      logger.info(`[RuleEngine] syncRules - 规则缓存完成`, {
        cache_key: HYBRID_PROOFREAD_CONFIG.rules.cacheKey,
        cache_duration_ms: cacheDuration,
      })

      this.lastSyncTime = now

      const totalDuration = Date.now() - startTime
      logger.info(`[RuleEngine] syncRules - 规则更新成功`, {
        previous_version: this.currentVersion,
        new_version: latestVersion,
        rule_count: rulesResponse.rules.length,
        version_fetch_ms: versionFetchDuration,
        download_ms: downloadDuration,
        cache_ms: cacheDuration,
        total_duration_ms: totalDuration,
      })

      return {
        current_version: this.currentVersion,
        latest_version: latestVersion,
        updated: true,
        downloaded_rules: rulesResponse.rules.length,
        skipped_rules: 0,
      }
    } catch (error) {
      logger.error(`[RuleEngine] syncRules - 同步规则失败，继续使用当前规则`, {
        error: error instanceof Error ? error.message : String(error),
        current_version: this.currentVersion,
        total_duration_ms: Date.now() - startTime,
      })

      return {
        current_version: this.currentVersion,
        latest_version: this.currentVersion,
        updated: false,
        downloaded_rules: 0,
        skipped_rules: 0,
      }
    }
  }

  async fetchLatestVersion(): Promise<{ version: string }> {
    const startTime = Date.now()
    logger.debug(`[RuleEngine] fetchLatestVersion - 开始获取最新版本`)

    const response = { version: this.currentVersion }

    logger.debug(`[RuleEngine] fetchLatestVersion - 获取完成`, {
      version: response.version,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async downloadRules(version: string): Promise<RulePackage> {
    const startTime = Date.now()
    logger.debug(`[RuleEngine] downloadRules - 开始下载规则`, {
      version,
    })

    const response: RulePackage = {
      version,
      release_date: new Date().toISOString(),
      rules: HYBRID_PROOFREAD_DEFAULT_RULES,
      checksum: '',
    }

    logger.debug(`[RuleEngine] downloadRules - 下载完成`, {
      version: response.version,
      rule_count: response.rules.length,
      duration_ms: Date.now() - startTime,
    })

    return response
  }

  async cacheRules(packageData: RulePackage): Promise<void> {
    const startTime = Date.now()
    const cacheKey = HYBRID_PROOFREAD_CONFIG.rules.cacheKey

    logger.debug(`[RuleEngine] cacheRules - 开始缓存规则`, {
      cache_key: cacheKey,
      version: packageData.version,
      rule_count: packageData.rules.length,
    })

    defaultStorage.set(cacheKey, JSON.stringify(packageData))

    logger.debug(`[RuleEngine] cacheRules - 缓存完成`, {
      cache_key: cacheKey,
      duration_ms: Date.now() - startTime,
    })
  }

  async evaluateFile(filePath: string, content: string): Promise<RuleMatchResult[]> {
    const startTime = Date.now()
    logger.debug(`[RuleEngine] evaluateFile - 开始评估文件`, {
      file_path: filePath,
      content_length: content.length,
      rule_count: this.rules.length,
    })

    const results: RuleMatchResult[] = []
    let matchedRules = 0
    let skippedRules = 0

    for (const rule of this.rules) {
      if (rule.file_pattern && !this.matchesFilePattern(filePath, rule.file_pattern)) {
        skippedRules++
        continue
      }

      const matches = this.findMatches(content, rule.pattern)
      for (const match of matches) {
        results.push({
          rule_id: rule.rule_id,
          rule_name: rule.name,
          severity: rule.severity,
          category: rule.category,
          file_path: filePath,
          line_number: match.lineNumber,
          column_number: match.column,
          match_text: match.text,
          description: rule.description,
          action_type: rule.action_type,
        })
      }

      if (matches.length > 0) {
        matchedRules++
        logger.debug(`[RuleEngine] evaluateFile - 规则匹配`, {
          rule_id: rule.rule_id,
          rule_name: rule.name,
          match_count: matches.length,
          severity: rule.severity,
        })
      }
    }

    const duration = Date.now() - startTime
    logger.debug(`[RuleEngine] evaluateFile - 评估完成`, {
      file_path: filePath,
      total_rules: this.rules.length,
      matched_rules: matchedRules,
      skipped_rules: skippedRules,
      total_matches: results.length,
      duration_ms: duration,
      avg_rule_ms: this.rules.length > 0 ? (duration / this.rules.length).toFixed(2) : '0',
    })

    return results
  }

  private matchesFilePattern(filePath: string, filePattern: string): boolean {
    const regex = safeRegex(filePattern.replace(/\*\*/g, '.*').replace(/\*/g, '[^/]*'))
    return regex.test(filePath)
  }

  private findMatches(content: string, pattern: string): Array<{ text: string; lineNumber: number; column: number }> {
    const results: Array<{ text: string; lineNumber: number; column: number }> = []
    const regex = safeRegex(pattern, 'g')
    let match: RegExpExecArray | null

    while ((match = regex.exec(content)) !== null) {
      const beforeMatch = content.substring(0, match.index)
      const lineNumber = beforeMatch.split('\n').length
      const lastNewlineIndex = beforeMatch.lastIndexOf('\n')
      const column = match.index - (lastNewlineIndex === -1 ? 0 : lastNewlineIndex + 1) + 1

      results.push({
        text: match[0],
        lineNumber,
        column,
      })
    }

    return results
  }

  getRules(): RuleConfig[] {
    return [...this.rules]
  }

  getCurrentVersion(): string {
    return this.currentVersion
  }

  getRuleById(ruleId: string): RuleConfig | undefined {
    return this.rules.find((r) => r.rule_id === ruleId)
  }

  getRulesByCategory(category: RuleConfig['category']): RuleConfig[] {
    return this.rules.filter((r) => r.category === category)
  }

  getRulesBySeverity(severity: RuleConfig['severity']): RuleConfig[] {
    return this.rules.filter((r) => r.severity === severity)
  }
}

