/**
 * @fileoverview 催化事件追踪器 — 监听新闻事件，自动识别并记录催化事件
 *
 * 通过关键词匹配解析新闻标题和内容，识别催化类型（财报/政策/行业/公告/技术突破/管理层），
 * 评估影响方向（positive/negative/neutral）和影响程度（1-5），记录并广播催化事件。
 *
 * @module services/orchestration/catalystTracker
 * @created 2026-07-25 - P1 编排器扩展
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ---- 类型定义 ----

export type CatalystType = 'earnings' | 'policy' | 'industry' | 'announcement' | 'tech_breakthrough' | 'management'
export type CatalystImpact = 'positive' | 'negative' | 'neutral'

export interface CatalystEvent {
  id: string
  symbol: string
  type: CatalystType
  title: string
  impact: CatalystImpact
  impactScore: number       // 1-5
  detectedAt: number
  source: string
  description: string
  strategyResponse?: string
}

export interface CatalystTrackerConfig {
  /** 是否自动检测催化事件（默认 true） */
  autoDetect?: boolean
  /** 最低记录阈值（默认 3），低于此分数的催化事件不记录 */
  minImpactScore?: number
  /** 关注的股票列表，空数组表示关注全部（默认 []） */
  watchSymbols?: string[]
}

// ---- 关键词映射 ----

/** 催化类型关键词映射 */
const CATALYST_TYPE_KEYWORDS: Record<CatalystType, string[]> = {
  earnings: ['财报', '业绩', '营收', '利润', 'EPS', '业绩预告', '业绩修正'],
  policy: ['政策', '监管', '审批', '许可', '法规', '补贴', '税收'],
  industry: ['行业', '板块', '趋势', '竞争', '市场', '份额'],
  announcement: ['公告', '公示', '声明', '决议', '计划'],
  tech_breakthrough: ['技术', '研发', '专利', '突破', '创新', '芯片', '算法'],
  management: ['管理层', '董事', '高管', '人事', '变动', '辞职', '任命'],
}

/** 正面影响关键词 */
const POSITIVE_KEYWORDS = ['增长', '超预期', '突破', '上涨', '利好', '提升', '创新高']

/** 负面影响关键词 */
const NEGATIVE_KEYWORDS = ['下降', '低预期', '下跌', '利空', '减持', '风险', '预警', '处罚']

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<CatalystTrackerConfig> = {
  autoDetect: true,
  minImpactScore: 3,
  watchSymbols: [],
}

// ---- 催化事件追踪器 ----

export class CatalystTracker {
  private config: Required<CatalystTrackerConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 按 symbol 索引的催化事件列表 */
  private catalysts: Map<string, CatalystEvent[]> = new Map()
  /** 全量催化事件列表（保持插入顺序） */
  private allCatalystsList: CatalystEvent[] = []

  constructor(config?: CatalystTrackerConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动追踪器 — 订阅新闻加载事件 */
  start(): void {
    if (this._active) return
    this._active = true

    const unsub = eventBus.on(EVENT_NAMES.NEWS_ARTICLE_LOADED, (payload: unknown) => {
      if (!this.config.autoDetect) return
      this.handleNewsLoaded(payload)
    })

    this.unsubscribers.push(unsub)
    logger.info('[CatalystTracker] 已启动，监听新闻事件')
  }

  /** 停止追踪器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[CatalystTracker] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 事件处理 ----

  /** 处理新闻加载事件 */
  private handleNewsLoaded(payload: unknown): void {
    const p = payload as {
      articles?: Array<{
        symbol?: string
        title?: string
        content?: string
        source?: string
        publishTime?: string | number
      }>
      article?: {
        symbol?: string
        title?: string
        content?: string
        source?: string
        publishTime?: string | number
      }
    }

    const articles = p.articles ?? (p.article ? [p.article] : [])
    if (articles.length === 0) return

    for (const article of articles) {
      const symbol = article.symbol ?? ''
      const title = article.title ?? ''
      const content = article.content ?? ''

      // 如果配置了关注列表且 symbol 不在列表中，跳过
      if (this.config.watchSymbols.length > 0 && symbol && !this.config.watchSymbols.includes(symbol)) {
        continue
      }

      const detected = this.detectCatalyst(symbol, title, content, article.source ?? '')
      if (detected) {
        this.recordCatalyst(detected)
      }
    }
  }

  /** 通过关键词匹配识别催化事件 */
  private detectCatalyst(
    symbol: string,
    title: string,
    content: string,
    source: string,
  ): CatalystEvent | null {
    const text = `${title} ${content}`.toLowerCase()

    // 识别催化类型
    let matchedType: CatalystType | null = null
    let matchCount = 0

    for (const [type, keywords] of Object.entries(CATALYST_TYPE_KEYWORDS) as [CatalystType, string[]][]) {
      const count = keywords.reduce((acc, kw) => acc + (text.includes(kw) ? 1 : 0), 0)
      if (count > matchCount) {
        matchCount = count
        matchedType = type
      }
    }

    if (!matchedType || matchCount === 0) return null

    // 评估影响方向
    const positiveHits = POSITIVE_KEYWORDS.filter((kw) => text.includes(kw)).length
    const negativeHits = NEGATIVE_KEYWORDS.filter((kw) => text.includes(kw)).length

    let impact: CatalystImpact = 'neutral'
    if (positiveHits > negativeHits) {
      impact = 'positive'
    } else if (negativeHits > positiveHits) {
      impact = 'negative'
    }

    // 评估影响程度（1-5）
    const impactScore = this.calculateImpactScore(impact, matchCount, positiveHits, negativeHits)

    // 低于阈值不记录
    if (impactScore < this.config.minImpactScore) return null

    return {
      id: nanoid(12),
      symbol,
      type: matchedType,
      title,
      impact,
      impactScore,
      detectedAt: Date.now(),
      source,
      description: content.slice(0, 200),
    }
  }

  /** 计算影响程度分数 */
  private calculateImpactScore(
    impact: CatalystImpact,
    typeMatchCount: number,
    positiveHits: number,
    negativeHits: number,
  ): number {
    let score = 1

    // 基础分：类型关键词命中数
    score += Math.min(typeMatchCount, 3)

    // 方向一致性加分
    if (impact === 'positive' && positiveHits >= 2) {
      score += 1
    } else if (impact === 'negative' && negativeHits >= 2) {
      score += 1
    }

    // neutral 类型的催化事件分数上限为 2
    if (impact === 'neutral') {
      score = Math.min(score, 2)
    }

    return Math.min(Math.max(score, 1), 5)
  }

  /** 记录催化事件并广播 */
  private recordCatalyst(event: CatalystEvent): void {
    // 存入 symbol 索引
    if (!this.catalysts.has(event.symbol)) {
      this.catalysts.set(event.symbol, [])
    }
    this.catalysts.get(event.symbol)!.push(event)

    // 存入全量列表
    this.allCatalystsList.push(event)

    logger.info('[CatalystTracker] 检测到催化事件', {
      symbol: event.symbol,
      type: event.type,
      impact: event.impact,
      score: event.impactScore,
      title: event.title.slice(0, 30),
    })

    // 广播催化事件
    eventBus.emit(EVENT_NAMES.CATALYST_DETECTED, event)

    // 如果有策略响应，额外广播
    if (event.strategyResponse) {
      eventBus.emit(EVENT_NAMES.CATALYST_STRATEGY_RESPONSE, event)
    }
  }

  // ---- 查询接口 ----

  /** 获取指定股票的催化事件列表 */
  getCatalysts(symbol: string): CatalystEvent[] {
    return this.catalysts.get(symbol) ?? []
  }

  /** 获取全部催化事件列表 */
  getAllCatalysts(): CatalystEvent[] {
    return [...this.allCatalystsList]
  }

  /** 获取高影响催化事件 */
  getHighImpactCatalysts(minScore: number): CatalystEvent[] {
    return this.allCatalystsList.filter((e) => e.impactScore >= minScore)
  }

  /** 清空所有催化事件 */
  clear(): void {
    this.catalysts.clear()
    this.allCatalystsList = []
    logger.info('[CatalystTracker] 已清空催化事件')
  }
}

// ---- 全局单例 ----

let _instance: CatalystTracker | null = null

export function getCatalystTracker(config?: CatalystTrackerConfig): CatalystTracker {
  if (!_instance) _instance = new CatalystTracker(config)
  return _instance
}

export function startCatalystTracker(config?: CatalystTrackerConfig): CatalystTracker {
  const tracker = getCatalystTracker(config)
  tracker.start()
  return tracker
}

/**
 * @fileoverview 筹码异动检测器 — 股东人数和筹码集中度异常变化检测
 *
 * 监听 chip 维度数据采集完成事件，对比前一次 chip 数据，
 * 检测股东人数变化、筹码集中度变化和机构持仓变化，
 * 当变化超过阈值时广播异动事件。
 *
 * @module services/orchestration/chipAnomalyDetector
 * @created 2026-07-25 - P2 高级功能模块
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ---- 类型定义 ----

export interface ChipAnomalyEvent {
  id: string
  symbol: string
  /** 异常类型 */
  type: 'holder_count_change' | 'concentration_change' | 'institutional_change'
  /** 变化方向 */
  direction: 'increase' | 'decrease'
  /** 变化幅度（百分比） */
  changePct: number
  /** 变化前的值 */
  previousValue: number
  /** 变化后的值 */
  newValue: number
  /** 异常级别 */
  severity: 'info' | 'warning' | 'critical'
  detectedAt: number
  description: string
}

export interface ChipAnomalyConfig {
  /** 股东人数变化阈值（百分比），默认 10% */
  holderCountThreshold?: number
  /** 筹码集中度变化阈值（百分比），默认 15% */
  concentrationThreshold?: number
  /** 是否自动检测，默认 true */
  autoDetect?: boolean
  /** 关注的股票列表，空=全部 */
  watchSymbols?: string[]
}

// ---- chip 数据快照接口 ----

interface ChipDataSnapshot {
  symbol: string
  /** 股东人数 */
  holderCount?: number
  /** 筹码集中度（0-100） */
  concentration?: number
  /** 机构持仓比例（0-1） */
  institutionalRatio?: number
  /** 数据采集时间 */
  collectedAt?: number
}

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<ChipAnomalyConfig> = {
  holderCountThreshold: 10,
  concentrationThreshold: 15,
  autoDetect: true,
  watchSymbols: [],
}

// ---- 筹码异动检测器 ----

export class ChipAnomalyDetector {
  private config: Required<ChipAnomalyConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 按 symbol 索引的异动事件 */
  private anomalies: Map<string, ChipAnomalyEvent[]> = new Map()
  /** 全量异动事件列表 */
  private allAnomaliesList: ChipAnomalyEvent[] = []
  /** 按 symbol 索引的上一次 chip 数据快照 */
  private previousSnapshots: Map<string, ChipDataSnapshot> = new Map()

  constructor(config?: ChipAnomalyConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动检测器 — 订阅 chip 采集完成事件 */
  start(): void {
    if (this._active) return
    this._active = true

    // 监听采集完成事件（当 dimensionCode === 'chip'）
    let unsub = eventBus.on(EVENT_NAMES.REGISTRATION_COLLECT_COMPLETE, (payload: unknown) => {
      if (!this.config.autoDetect) return
      this.handleCollectComplete(payload)
    })
    this.unsubscribers.push(unsub)

    // 监听股票数据变更（备用，可能包含 chip 数据更新）
    unsub = eventBus.on(EVENT_NAMES.STOCKS_CHANGED, (payload: unknown) => {
      if (!this.config.autoDetect) return
      this.handleStocksChanged(payload)
    })
    this.unsubscribers.push(unsub)

    logger.info('[ChipAnomalyDetector] 已启动', {
      holderCountThreshold: `${this.config.holderCountThreshold}%`,
      concentrationThreshold: `${this.config.concentrationThreshold}%`,
    })
  }

  /** 停止检测器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[ChipAnomalyDetector] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 事件处理 ----

  /** 处理采集完成事件 */
  private handleCollectComplete(payload: unknown): void {
    const p = payload as {
      dimensionCode?: string
      results?: Array<{
        symbol?: string
        data?: Record<string, unknown>
      }>
    }

    // 仅处理 chip 维度的采集
    if ((p.dimensionCode ?? '') !== '' && p.dimensionCode !== 'chip') return

    if (!p?.results) return

    for (const result of p.results) {
      const sym = result.symbol ?? ''
      if (sym === '') continue

      // 检查关注列表
      if (this.config.watchSymbols.length > 0 && !this.config.watchSymbols.includes(sym)) {
        continue
      }

      const chipData = this.extractChipData(sym, result.data ?? {})
      if (chipData) {
        this.detectAnomalies(chipData)
      }
    }
  }

  /** 处理股票数据变更（备用） */
  private handleStocksChanged(payload: unknown): void {
    const p = payload as {
      stocks?: Array<{
        symbol?: string
        holderCount?: number
        concentration?: number
        institutionalRatio?: number
      }>
      symbol?: string
      holderCount?: number
      concentration?: number
      institutionalRatio?: number
    }

    if (p.stocks) {
      for (const stock of p.stocks) {
        const stockSymbol = stock.symbol ?? ''
        if (stockSymbol !== '') {
          const chipData: ChipDataSnapshot = {
            symbol: stockSymbol,
            holderCount: stock.holderCount,
            concentration: stock.concentration,
            institutionalRatio: stock.institutionalRatio,
            collectedAt: Date.now(),
          }
          this.detectAnomalies(chipData)
        }
      }
    } else {
      const pSymbol = p.symbol ?? ''
      if (pSymbol !== '' && (p.holderCount !== undefined || p.concentration !== undefined)) {
        const chipData: ChipDataSnapshot = {
          symbol: pSymbol,
          holderCount: p.holderCount,
          concentration: p.concentration,
          institutionalRatio: p.institutionalRatio,
          collectedAt: Date.now(),
        }
        this.detectAnomalies(chipData)
      }
    }
  }

  /** 从原始数据中提取 chip 维度字段 */
  private extractChipData(symbol: string, data: Record<string, unknown>): ChipDataSnapshot | null {
    // 尝试多种字段命名
    const holderCount = this.extractNumber(data, [
      'holderCount', 'holder_count', 'shareholderCount', 'shareholder_count',
    ])
    const concentration = this.extractNumber(data, [
      'concentration', 'chipConcentration', 'chip_concentration',
    ])
    const institutionalRatio = this.extractNumber(data, [
      'institutionalRatio', 'institutional_ratio', 'instRatio', 'inst_ratio',
    ])

    // 至少有一个 chip 维度的数据才有效
    if (holderCount === null && concentration === null && institutionalRatio === null) {
      return null
    }

    return {
      symbol,
      holderCount: holderCount ?? undefined,
      concentration: concentration ?? undefined,
      institutionalRatio: institutionalRatio ?? undefined,
      collectedAt: Date.now(),
    }
  }

  /** 从对象中按候选字段名提取数字 */
  private extractNumber(data: Record<string, unknown>, candidates: string[]): number | null {
    for (const key of candidates) {
      if (key in data && typeof data[key] === 'number') {
        return data[key]
      }
    }
    return null
  }

  // ---- 异动检测 ----

  /** 检测异动 */
  private detectAnomalies(current: ChipDataSnapshot): void {
    const previous = this.previousSnapshots.get(current.symbol)

    if (!previous) {
      // 首次记录快照，不做异动检测
      this.previousSnapshots.set(current.symbol, { ...current })
      return
    }

    // 检测股东人数变化
    if (current.holderCount !== undefined && previous.holderCount !== undefined && previous.holderCount > 0) {
      const changePct = ((current.holderCount - previous.holderCount) / previous.holderCount) * 100
      if (Math.abs(changePct) >= this.config.holderCountThreshold) {
        const severity = this.computeSeverity(Math.abs(changePct), this.config.holderCountThreshold)
        const direction: 'increase' | 'decrease' = changePct > 0 ? 'increase' : 'decrease'

        this.recordAnomaly({
          type: 'holder_count_change',
          direction,
          changePct: Math.round(Math.abs(changePct) * 100) / 100,
          previousValue: previous.holderCount,
          newValue: current.holderCount,
          severity,
          symbol: current.symbol,
          description: `股东人数${direction === 'increase' ? '增加' : '减少'} ${Math.abs(changePct).toFixed(1)}%` +
            `（${previous.holderCount.toLocaleString()} → ${current.holderCount.toLocaleString()}）`,
        })
      }
    }

    // 检测筹码集中度变化
    if (current.concentration !== undefined && previous.concentration !== undefined && previous.concentration > 0) {
      const changePct = ((current.concentration - previous.concentration) / previous.concentration) * 100
      if (Math.abs(changePct) >= this.config.concentrationThreshold) {
        const severity = this.computeSeverity(Math.abs(changePct), this.config.concentrationThreshold)
        const direction: 'increase' | 'decrease' = changePct > 0 ? 'increase' : 'decrease'

        this.recordAnomaly({
          type: 'concentration_change',
          direction,
          changePct: Math.round(Math.abs(changePct) * 100) / 100,
          previousValue: previous.concentration,
          newValue: current.concentration,
          severity,
          symbol: current.symbol,
          description: `筹码集中度${direction === 'increase' ? '提升' : '下降'} ${Math.abs(changePct).toFixed(1)}%` +
            `（${previous.concentration.toFixed(1)} → ${current.concentration.toFixed(1)}）`,
        })
      }
    }

    // 检测机构持仓变化（使用集中度阈值的1.5倍）
    if (
      current.institutionalRatio !== undefined &&
      previous.institutionalRatio !== undefined &&
      previous.institutionalRatio > 0
    ) {
      const instThreshold = this.config.concentrationThreshold * 1.5
      const changePct = ((current.institutionalRatio - previous.institutionalRatio) / previous.institutionalRatio) * 100
      if (Math.abs(changePct) >= instThreshold) {
        const severity = this.computeSeverity(Math.abs(changePct), instThreshold)
        const direction: 'increase' | 'decrease' = changePct > 0 ? 'increase' : 'decrease'

        this.recordAnomaly({
          type: 'institutional_change',
          direction,
          changePct: Math.round(Math.abs(changePct) * 100) / 100,
          previousValue: previous.institutionalRatio,
          newValue: current.institutionalRatio,
          severity,
          symbol: current.symbol,
          description: `机构持仓${direction === 'increase' ? '增持' : '减持'} ${Math.abs(changePct).toFixed(1)}%` +
            `（${(previous.institutionalRatio * 100).toFixed(1)}% → ${(current.institutionalRatio * 100).toFixed(1)}%）`,
        })
      }
    }

    // 更新快照
    this.previousSnapshots.set(current.symbol, { ...current })
  }

  /** 计算异动严重级别 */
  private computeSeverity(changePct: number, threshold: number): 'info' | 'warning' | 'critical' {
    if (changePct >= threshold * 3) {
      return 'critical'
    } else if (changePct >= threshold * 2) {
      return 'warning'
    }
    return 'info'
  }

  /** 记录异动事件并广播 */
  private recordAnomaly(params: {
    type: ChipAnomalyEvent['type']
    direction: ChipAnomalyEvent['direction']
    changePct: number
    previousValue: number
    newValue: number
    severity: ChipAnomalyEvent['severity']
    symbol: string
    description: string
  }): void {
    const event: ChipAnomalyEvent = {
      id: nanoid(12),
      symbol: params.symbol,
      type: params.type,
      direction: params.direction,
      changePct: params.changePct,
      previousValue: params.previousValue,
      newValue: params.newValue,
      severity: params.severity,
      detectedAt: Date.now(),
      description: params.description,
    }

    // 存入 symbol 索引
    if (!this.anomalies.has(params.symbol)) {
      this.anomalies.set(params.symbol, [])
    }
    this.anomalies.get(params.symbol)!.push(event)

    // 存入全量列表
    this.allAnomaliesList.push(event)

    logger.info('[ChipAnomalyDetector] 检测到筹码异动', {
      symbol: params.symbol,
      type: params.type,
      direction: params.direction,
      changePct: `${params.changePct}%`,
      severity: params.severity,
    })

    // 广播异动事件
    eventBus.emit(EVENT_NAMES.CHIP_ANOMALY_DETECTED, event)
  }

  // ---- 查询接口 ----

  /** 获取指定股票的异动事件列表 */
  getAnomalies(symbol: string): ChipAnomalyEvent[] {
    return this.anomalies.get(symbol) ?? []
  }

  /** 获取全部异动事件列表 */
  getAllAnomalies(): ChipAnomalyEvent[] {
    return [...this.allAnomaliesList]
  }

  /** 获取严重级别异动列表 */
  getCriticalAnomalies(): ChipAnomalyEvent[] {
    return this.allAnomaliesList.filter((a) => a.severity === 'critical')
  }

  /** 清空所有数据 */
  clear(): void {
    this.anomalies.clear()
    this.allAnomaliesList = []
    this.previousSnapshots.clear()
    logger.info('[ChipAnomalyDetector] 已清空')
  }
}

// ---- 全局单例 ----

let _instance: ChipAnomalyDetector | null = null

export function getChipAnomalyDetector(config?: ChipAnomalyConfig): ChipAnomalyDetector {
  if (!_instance) _instance = new ChipAnomalyDetector(config)
  return _instance
}

export function startChipAnomalyDetector(config?: ChipAnomalyConfig): ChipAnomalyDetector {
  const detector = getChipAnomalyDetector(config)
  detector.start()
  return detector
}

/**
 * @fileoverview 假突破实时预警器 — 监控自选列表中的假突破信号
 *
 * 监听行情数据更新，当股票满足假突破技术条件（换手率≥8% & 量比<1.5）
 * 时发出预警。结合 v4.7 资金流向二次确认，主力净流入时降级不预警。
 *
 * 预警级别：
 * - critical: L5 能量级别假突破（能量≥0.15）+ 主力净流出
 * - warning: L4 能量级别假突破（能量≥0.08）+ 主力净流出
 * - info: 假突破技术条件满足但资金流向数据不足
 *
 * @module services/orchestration/fakeBreakoutAlert
 * @created 2026-08-10 - v4.7 假突破监控
 */

import { eventBus } from '@/lib/eventBus'
