export type OrchestratorStatus = 'idle' | 'starting' | 'running' | 'failed'

export interface OrchestratorHealth {
  name: string
  status: OrchestratorStatus
  lastStartTime: number | null
  errorMessage: string | null
}

const orchestratorStates = new Map<string, OrchestratorHealth>()

interface OrchestratorEntry {
  name: string
  fn: () => void
}

function buildOrchestratorList(): OrchestratorEntry[] {
  return [
    { name: 'RegistrationOrchestrator', fn: () => getRegistrationOrchestrator().start() },
    { name: 'QualityGate', fn: () => getQualityGate().start() },
    { name: 'ScoreCalibrator', fn: () => getScoreCalibrator().start() },
    { name: 'CatalystTracker', fn: () => getCatalystTracker().start() },
    { name: 'WatchListTrigger', fn: () => getWatchListTrigger().start() },
    { name: 'StrategyReportGenerator', fn: () => getStrategyReportGenerator().start() },
    { name: 'TimelinessSyncAnalyzer', fn: () => getTimelinessSyncAnalyzer().start() },
    { name: 'WeeklyReviewScheduler', fn: () => getWeeklyReviewScheduler().start() },
    { name: 'VolatilityAlertPush', fn: () => getVolatilityAlertPush().start() },
    { name: 'ChipAnomalyDetector', fn: () => getChipAnomalyDetector().start() },
  ]
}

export function initOrchestration(): void {
  console.log('[Orchestration] 初始化编排器...')

  const orchestrators = buildOrchestratorList()
  let successCount = 0
  let failCount = 0

  for (const { name, fn } of orchestrators) {
    try {
      orchestratorStates.set(name, { name, status: 'starting', lastStartTime: null, errorMessage: null })
      fn()
      orchestratorStates.set(name, {
        name,
        status: 'running',
        lastStartTime: Date.now(),
        errorMessage: null,
      })
      successCount++
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err)
      orchestratorStates.set(name, {
        name,
        status: 'failed',
        lastStartTime: null,
        errorMessage,
      })
      console.error(`[Orchestration] ${name} 启动失败:`, errorMessage)
      failCount++
    }
  }

  console.log(`[Orchestration] 编排器启动完成: ${successCount} 成功, ${failCount} 失败`)

  if (failCount > 0) {
    const failedNames = orchestrators
      .filter((o) => orchestratorStates.get(o.name)?.status === 'failed')
      .map((o) => o.name)
    console.warn(`[Orchestration] 编排器部分启动失败: ${failedNames.join(', ')}`)
  }
}

export function getOrchestratorHealth(): OrchestratorHealth[] {
  return Array.from(orchestratorStates.values())
}

export function getRunningOrchestrators(): string[] {
  return Array.from(orchestratorStates.entries())
    .filter(([, state]) => state.status === 'running')
    .map(([name]) => name)
}

export function isCriticalOrchestratorAvailable(name: string): boolean {
  return orchestratorStates.get(name)?.status === 'running'
}

/** 停止全部编排器 */
export function stopOrchestration(): void {
  const stopEntries = [
    { name: 'RegistrationOrchestrator', fn: () => getRegistrationOrchestrator().stop() },
    { name: 'QualityGate', fn: () => getQualityGate().stop() },
    { name: 'ScoreCalibrator', fn: () => getScoreCalibrator().stop() },
    { name: 'CatalystTracker', fn: () => getCatalystTracker().stop() },
    { name: 'WatchListTrigger', fn: () => getWatchListTrigger().stop() },
    { name: 'StrategyReportGenerator', fn: () => getStrategyReportGenerator().stop() },
    { name: 'TimelinessSyncAnalyzer', fn: () => getTimelinessSyncAnalyzer().stop() },
    { name: 'WeeklyReviewScheduler', fn: () => getWeeklyReviewScheduler().stop() },
    { name: 'VolatilityAlertPush', fn: () => getVolatilityAlertPush().stop() },
    { name: 'ChipAnomalyDetector', fn: () => getChipAnomalyDetector().stop() },
  ]

  for (const { name, fn } of stopEntries) {
    try {
      fn()
      orchestratorStates.set(name, { name, status: 'idle', lastStartTime: null, errorMessage: null })
    } catch {
      // 停止阶段的异常仅记录日志，不影响其他编排器停止
      orchestratorStates.set(name, { name, status: 'idle', lastStartTime: null, errorMessage: null })
    }
  }

  console.log('[Orchestration] 编排器已停止')
}

/**
 * @fileoverview 质量门禁 — 监听采集完成事件，校验采集质量后触发分析引擎
 *
 * @module services/orchestration/qualityGate
 * @created 2026-07-25 - P0 数据链路打通
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getQualityMetrics } from '@/services/data-collector/qualityMetricsCollector'
import { runBatchTrace, createDefaultCollectionConfig } from '@/services/data-collector/collectionPipeline'
import { dataBridge, ENVELOPE_ACTION, STORE_NAME } from '@/core/databridge'
import { runFullIndustryAnalysis } from '@/services/analysis/industryAnalysisService'
import { runV6ScoreBatch } from '@/services/scoring/v6ScoreService'
import { getLogger } from '@/lib/logger'
import type { QualityMetrics } from '@/services/data-collector/qualityMetricsCollector'

const logger = getLogger()

/** 质量门禁阈值配置 */
export interface QualityGateThresholds {
  requiredSuccessRate: number
  requiredCompleteness: number
  requiredWriteRate: number
  dimensionCompletenessMap: Record<string, number>
}

/** 质量检查结果 */
export interface QualityGateResult {
  passed: boolean
  metrics: Readonly<QualityMetrics>
  missingDimensions: string[]
  missingReports: number
  timestamp: number
  reason?: string
}

const DEFAULT_THRESHOLDS: QualityGateThresholds = {
  requiredSuccessRate: 0.95,
  requiredCompleteness: 0.90,
  requiredWriteRate: 0.95,
  dimensionCompletenessMap: {
    quote: 1.0,
    kline: 1.0,
    news: 0.8,
    research: 0.8,
    competitor: 0.6,
    index: 0.6,
    chip: 0.6,
    'research-detail': 0.6,
  },
}

export class QualityGate {
  private thresholds: QualityGateThresholds
  private unsubscribers: (() => void)[] = []
  private _active = false
  private dimensionTracker: Map<string, Set<string>> = new Map()
  private retryCount = 0
  private readonly maxRetries = 2

  constructor(thresholds?: Partial<QualityGateThresholds>) {
    this.thresholds = { ...DEFAULT_THRESHOLDS, ...thresholds }
  }

  start(): void {
    if (this._active) return
    this._active = true

    const unsub1 = eventBus.on('collect:complete', (payload: unknown) => {
      const p = payload as { symbol: string; dimensionCode: string; success: boolean }
      this.trackDimensionComplete(p)
    })

    const unsub2 = eventBus.on(EVENT_NAMES.REGISTRATION_COLLECT_COMPLETE, (payload: unknown) => {
      const p = payload as { symbols: string[] }
      void this.evaluateAndProceed(p)
    })

    this.unsubscribers.push(unsub1, unsub2)
    logger.info('[QualityGate] 已启动')
  }

  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    this.dimensionTracker.clear()
    this.retryCount = 0
    logger.info('[QualityGate] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  private trackDimensionComplete(payload: { symbol: string; dimensionCode: string; success: boolean }): void {
    const { symbol, dimensionCode, success } = payload
    if (!success) return
    if (!this.dimensionTracker.has(symbol)) {
      this.dimensionTracker.set(symbol, new Set())
    }
    this.dimensionTracker.get(symbol)!.add(dimensionCode)
  }

  private async evaluateAndProceed(payload: { symbols: string[] }): Promise<void> {
    const symbols = payload.symbols ?? []
    const metrics = getQualityMetrics().snapshot()
    const qualityResult = this.checkQuality(metrics)

    eventBus.emit(EVENT_NAMES.QUALITY_GATE_CHECKED, qualityResult)

    if (!qualityResult.passed) {
      eventBus.emit(EVENT_NAMES.QUALITY_GATE_FAILED, qualityResult)
      logger.warn('[QualityGate] 质量未达标', { reason: qualityResult.reason })

      if (this.retryCount < this.maxRetries) {
        this.retryCount++
        logger.info(`[QualityGate] 第 ${this.retryCount} 次补采`)
        await this.retryMissingDimensions(symbols, qualityResult.missingDimensions)
        setTimeout(() => void this.evaluateAndProceed(payload), 3000)
      } else {
        logger.error('[QualityGate] 补采次数耗尽，放行已有数据')
        this.retryCount = 0
        await this.triggerAnalysis(symbols)
      }
      return
    }

    eventBus.emit(EVENT_NAMES.QUALITY_GATE_PASSED, qualityResult)
    logger.info('[QualityGate] 质量达标，触发分析引擎')
    this.retryCount = 0
    await this.triggerAnalysis(symbols)
  }

  checkQuality(metrics: Readonly<QualityMetrics>): QualityGateResult {
    const missingDimensions: string[] = []

    if (metrics.successRate < this.thresholds.requiredSuccessRate) {
      return {
        passed: false, metrics, missingDimensions, missingReports: 0,
        timestamp: Date.now(),
        reason: `采集成功率 ${(metrics.successRate * 100).toFixed(1)}% < ${(this.thresholds.requiredSuccessRate * 100).toFixed(1)}%`,
      }
    }

    if (metrics.completeness < this.thresholds.requiredCompleteness) {
      return {
        passed: false, metrics, missingDimensions, missingReports: 0,
        timestamp: Date.now(),
        reason: `字段完整率 ${(metrics.completeness * 100).toFixed(1)}% < ${(this.thresholds.requiredCompleteness * 100).toFixed(1)}%`,
      }
    }

    const allDimensions = Object.keys(this.thresholds.dimensionCompletenessMap)
    for (const _symbol of this.dimensionTracker.keys()) {
      const completed = this.dimensionTracker.get(_symbol)!
      for (const dim of allDimensions) {
        if (!completed.has(dim) && !missingDimensions.includes(dim)) {
          missingDimensions.push(dim)
        }
      }
    }

    const requiredMissing = missingDimensions.filter(
      (d) => (this.thresholds.dimensionCompletenessMap[d] ?? 0) >= 1.0,
    )
    if (requiredMissing.length > 0) {
      return {
        passed: false, metrics, missingDimensions: requiredMissing, missingReports: 0,
        timestamp: Date.now(),
        reason: `必须维度缺失: ${requiredMissing.join(', ')}`,
      }
    }

    return { passed: true, metrics, missingDimensions: [], missingReports: 0, timestamp: Date.now() }
  }

  private async retryMissingDimensions(symbols: string[], dimensions: string[]): Promise<void> {
    if (dimensions.length === 0) return
    const config = createDefaultCollectionConfig()
    await Promise.allSettled(
      dimensions.map((dim) => runBatchTrace({ symbols, dimensionCode: dim, config })),
    )
  }

  private async triggerAnalysis(symbols: string[]): Promise<void> {
    const stockData = await this.loadStocksWithData(symbols)
    if (stockData.length === 0) {
      logger.warn('[QualityGate] 无可分析的股票数据')
      return
    }

    try {
      const analysisResult = await runFullIndustryAnalysis(
        stockData as Parameters<typeof runFullIndustryAnalysis>[0],
      )
      eventBus.emit(EVENT_NAMES.ANALYSIS_INDUSTRY_COMPLETED, analysisResult)
      logger.info('[QualityGate] 行业分析完成')

      // P0-2: 行业分析完成后触发 V6 批量评分
      try {
        const batchResult = await runV6ScoreBatch(symbols)
        eventBus.emit(EVENT_NAMES.V6_BATCH_SCORE_COMPLETED, batchResult)
        logger.info('[QualityGate] V6 批量评分完成', {
          total: batchResult.data?.stats?.total ?? 0,
          completed: batchResult.data?.stats?.completed ?? 0,
        })
      } catch (e) {
        logger.error('[QualityGate] V6 批量评分失败', { error: e instanceof Error ? e.message : String(e) })
      }
    } catch (e) {
      logger.error('[QualityGate] 行业分析失败', { error: e instanceof Error ? e.message : String(e) })
    }
  }

  /**
   * 加载股票基础数据 + 行情数据 + 财务数据
   * P0-3 修复：不再传空 financials/quotes，而是从 DB 查询真实数据
   * 每只股票的三个数据源查询均记录耗时，用于性能监控和瓶颈定位
   */
  private async loadStocksWithData(
    symbols: string[],
  ): Promise<Array<{ stock: unknown; financials: Record<string, unknown>; quotes: Record<string, unknown> }>> {
    const results: Array<{ stock: unknown; financials: Record<string, unknown>; quotes: Record<string, unknown> }> = []
    const batchStart = performance.now()

    for (const symbol of symbols) {
      const symbolStart = performance.now()
      try {
        // 1. 查询股票基础数据
        const t0 = performance.now()
        const stockRes = await dataBridge.query({
          action: ENVELOPE_ACTION.queryGet,
          store: STORE_NAME.stocks,
          key: symbol,
        })
        const stockMs = performance.now() - t0
        if ((stockRes.success ?? false) !== true || stockRes.data == null) {
          logger.warn(`[QualityGate] 股票 ${symbol} 不存在于DB，跳过`, { stockMs: Math.round(stockMs) })
          continue
        }
        const stock = stockRes.data

        // 2. 查询行情数据（可缺失，不阻断流程）
        let quotes: Record<string, unknown> = {}
        const t1 = performance.now()
        try {
          const quotesRes = await dataBridge.query({
            action: ENVELOPE_ACTION.queryGet,
            store: STORE_NAME.dailyQuotes,
            key: symbol,
          })
          if (quotesRes.success === true && quotesRes.data != null) {
            quotes = quotesRes.data as Record<string, unknown>
          }
        } catch {
          /* quotes 可缺失 */
        }
        const quotesMs = performance.now() - t1

        // 3. 查询财务数据（可缺失，不阻断流程）
        let financials: Record<string, unknown> = { dataStatus: 'missing' }
        const t2 = performance.now()
        try {
          const finRes = await dataBridge.query({
            action: ENVELOPE_ACTION.queryGet,
            store: STORE_NAME.financialReports,
            key: symbol,
          })
          if (finRes.success === true && finRes.data != null) {
            financials = { ...(finRes.data as Record<string, unknown>), dataStatus: 'complete' }
          }
        } catch {
          /* financials 可缺失 */
        }
        const financialsMs = performance.now() - t2

        const totalMs = performance.now() - symbolStart
        logger.info(`[QualityGate] 数据加载完成 ${symbol}`, {
          stockMs: Math.round(stockMs),
          quotesMs: Math.round(quotesMs),
          financialsMs: Math.round(financialsMs),
          totalMs: Math.round(totalMs),
          finStatus: financials.dataStatus,
          quotesLoaded: Object.keys(quotes).length > 0,
        })

        results.push({ stock, financials, quotes })
      } catch {
        const totalMs = performance.now() - symbolStart
        logger.error(`[QualityGate] 股票 ${symbol} 数据加载异常`, { totalMs: Math.round(totalMs) })
      }
    }

    const batchMs = performance.now() - batchStart
    logger.info('[QualityGate] 批量数据加载完成', {
      symbolCount: symbols.length,
      loadedCount: results.length,
      batchMs: Math.round(batchMs),
    })

    return results
  }
}

let _instance: QualityGate | null = null

export function getQualityGate(thresholds?: Partial<QualityGateThresholds>): QualityGate {
  if (!_instance) _instance = new QualityGate(thresholds)
  return _instance
}

export function startQualityGate(thresholds?: Partial<QualityGateThresholds>): QualityGate {
  const gate = getQualityGate(thresholds)
  gate.start()
  return gate
}

/**
 * @fileoverview 注册编排器 — 监听批量导入完成事件，自动触发数据采集管道
 *
 * 断点位置：batchImportExecutor.ts emit('BATCH_IMPORT_COMPLETED') 无消费者
 * 本模块消费该事件，调用 collectionPipeline.runBatchTrace 启动 8 维度采集。
 *
 * @module services/orchestration/registrationOrchestrator
 * @created 2026-07-25 - P0 数据链路打通
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { runBatchTrace, createDefaultCollectionConfig } from '@/services/data-collector/collectionPipeline'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 采集维度代码 */
const COLLECTION_DIMENSIONS = [
  'quote',
  'kline',
  'news',
  'research',
  'competitor',
  'index',
  'chip',
  'research-detail',
] as const

export type CollectionDimensionCode = (typeof COLLECTION_DIMENSIONS)[number]

/** 编排器配置 */
export interface RegistrationOrchestratorConfig {
  /** 是否自动触发采集（默认 true） */
  autoCollect?: boolean
  /** 采集维度白名单（默认全部 8 个维度） */
  dimensions?: CollectionDimensionCode[]
}

/** 注册编排器 — 监听 BATCH_IMPORT_COMPLETED 事件，自动触发采集管道 */
export class RegistrationOrchestrator {
  private config: { autoCollect: boolean; dimensions: CollectionDimensionCode[] }
  private unsubscribers: (() => void)[] = []
  private _active = false

  constructor(config?: RegistrationOrchestratorConfig) {
    this.config = {
      autoCollect: config?.autoCollect ?? true,
      dimensions: config?.dimensions ?? [...COLLECTION_DIMENSIONS],
    }
  }

  /** 启动编排器 — 订阅 BATCH_IMPORT_COMPLETED 事件 */
  start(): void {
    if (this._active) return
    this._active = true

    const unsub = eventBus.on(
      'BATCH_IMPORT_COMPLETED',
      (payload: unknown) => {
        if (!this.config.autoCollect) return
        void this.handleBatchImport(payload as BatchImportCompletedPayload)
      },
    )
    this.unsubscribers.push(unsub)
    logger.info('[RegistrationOrchestrator] 已启动，监听 BATCH_IMPORT_COMPLETED')
  }

  /** 停止编排器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[RegistrationOrchestrator] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  /** 处理批量导入完成事件 */
  private async handleBatchImport(payload: BatchImportCompletedPayload): Promise<void> {
    const symbols: string[] = payload.successSymbols ?? []
    if (symbols.length === 0) {
      logger.warn('[RegistrationOrchestrator] 无成功导入的股票代码，跳过采集')
      return
    }

    const dimensions = this.config.dimensions
    logger.info('[RegistrationOrchestrator] 触发采集')

    eventBus.emit(EVENT_NAMES.REGISTRATION_COLLECT_START, {
      symbols,
      dimensions,
      timestamp: Date.now(),
    })

    const collectionConfig = createDefaultCollectionConfig()

    const results = await Promise.allSettled(
      dimensions.map((dim) =>
        runBatchTrace({
          symbols,
          dimensionCode: dim,
          config: collectionConfig,
        }),
      ),
    )

    const succeeded = results.filter((r) => r.status === 'fulfilled').length
    const failed = results.filter((r) => r.status === 'rejected').length

    logger.info('[RegistrationOrchestrator] 采集完成')

    eventBus.emit(EVENT_NAMES.REGISTRATION_COLLECT_COMPLETE, {
      symbols,
      dimensions,
      totalDimensions: dimensions.length,
      succeeded,
      failed,
      timestamp: Date.now(),
    })
  }

  /** 手动触发采集 */
  async triggerCollect(
    symbols: string[],
    dimensions?: CollectionDimensionCode[],
  ): Promise<{ triggered: boolean; symbols: string[]; dimensions: CollectionDimensionCode[]; timestamp: number }> {
    const dims = dimensions ?? this.config.dimensions
    const collectionConfig = createDefaultCollectionConfig()

    eventBus.emit(EVENT_NAMES.REGISTRATION_COLLECT_START, {
      symbols,
      dimensions: dims,
      timestamp: Date.now(),
    })

    await Promise.allSettled(
      dims.map((dim) => runBatchTrace({ symbols, dimensionCode: dim, config: collectionConfig })),
    )

    return { triggered: true, symbols, dimensions: dims, timestamp: Date.now() }
  }
}

/** 批量导入完成事件载荷 */
interface BatchImportCompletedPayload {
  total: number
  success: number
  failed: number
  successSymbols?: string[]
}

// ---- 全局单例 ----
let _instance: RegistrationOrchestrator | null = null

export function getRegistrationOrchestrator(
  config?: RegistrationOrchestratorConfig,
): RegistrationOrchestrator {
  if (!_instance) _instance = new RegistrationOrchestrator(config)
  return _instance
}

export function startRegistrationOrchestrator(
  config?: RegistrationOrchestratorConfig,
): RegistrationOrchestrator {
  const orchestrator = getRegistrationOrchestrator(config)
  orchestrator.start()
  return orchestrator
}

/**
 * @fileoverview 双轨校对器 — 监听评分完成事件，校对后触发策略分层
 *
 * @module services/orchestration/scoreCalibrator
 * @created 2026-07-25 - P0 数据链路打通
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { dataBridge, ENVELOPE_ACTION, STORE_NAME } from '@/core/databridge'
import { runDualStrategyUseCase } from '@/services/useCase/runDualStrategy.useCase'
import { getLogger } from '@/lib/logger'
import type { IntelligentScore } from '@/data/types'
import { scoreToTier as scoreToTierPublic, scoreToRating as scoreToRatingPublic } from './scoreTier'

const logger = getLogger()

/** 校对配置 */
export interface ScoreCalibratorConfig {
  maxDeviation: number
  v6Weight: number
  autoTriggerStrategy: boolean
}

/** 校对结果 */
export interface CalibrationResult {
  symbol: string
  v6Score: number | null
  llmScore: number | null
  deviation: number | null
  needsManualReview: boolean
  finalScore: number
  rating: string
  strategyTier: string
}

const DEFAULT_CONFIG: Required<ScoreCalibratorConfig> = {
  maxDeviation: 0.5,
  v6Weight: 0.6,
  autoTriggerStrategy: true,
}

export class ScoreCalibrator {
  private config: Required<ScoreCalibratorConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  private calibratedScores: Map<string, CalibrationResult> = new Map()
  private pendingSymbols: Set<string> = new Set()

  constructor(config?: Partial<ScoreCalibratorConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  start(): void {
    if (this._active) return
    this._active = true

    const unsub1 = eventBus.on(EVENT_NAMES.QUALITY_GATE_PASSED, () => {
      // 质量门禁放行 — 后续由 ANALYSIS_SCORE_COMPLETED 驱动
    })

    const unsub2 = eventBus.on(EVENT_NAMES.ANALYSIS_INDUSTRY_COMPLETED, () => {
      logger.info('[ScoreCalibrator] 行业分析完成，等待个股评分...')
    })

    const unsub3 = eventBus.on(EVENT_NAMES.ANALYSIS_SCORE_COMPLETED, (payload: unknown) => {
      const p = payload as { symbol: string; score: IntelligentScore }
      this.calibrateSingle(p.symbol, p.score)
    })

    this.unsubscribers.push(unsub1, unsub2, unsub3)
    logger.info('[ScoreCalibrator] 已启动')
  }

  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    this.calibratedScores.clear()
    this.pendingSymbols.clear()
    logger.info('[ScoreCalibrator] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  private calibrateSingle(symbol: string, score: IntelligentScore): void {
    const v6Score = this.extractV6Score(score)
    const llmScore = score.overallScore ?? null

    let deviation: number | null = null
    let needsManualReview = false
    let finalScore: number

    if (v6Score !== null && llmScore !== null) {
      deviation = Math.abs(v6Score - llmScore)
      needsManualReview = deviation >= this.config.maxDeviation
      const w = this.config.v6Weight
      finalScore = v6Score * w + llmScore * (1 - w)
    } else if (v6Score !== null) {
      finalScore = v6Score
    } else if (llmScore !== null) {
      finalScore = llmScore
    } else {
      finalScore = 0
    }

    const result: CalibrationResult = {
      symbol,
      v6Score,
      llmScore,
      deviation,
      needsManualReview,
      finalScore,
      rating: this.scoreToRating(finalScore),
      strategyTier: this.scoreToTier(finalScore),
    }

    this.calibratedScores.set(symbol, result)
    this.pendingSymbols.delete(symbol)

    logger.info('[ScoreCalibrator] 校对完成', {
      symbol,
      finalScore: finalScore.toFixed(2),
      rating: result.rating,
      tier: result.strategyTier,
    })

    eventBus.emit(EVENT_NAMES.SCORE_CALIBRATOR_ITEM, result)

    if (this.config.autoTriggerStrategy && this.pendingSymbols.size === 0) {
      this.triggerStrategyClassification()
    }
  }

  /** V6 评分在 configSnapshot.v6Score */
  private extractV6Score(score: IntelligentScore): number | null {
    return score.configSnapshot?.v6Score ?? null
  }

  private async triggerStrategyClassification(): Promise<void> {
    const allResults = Array.from(this.calibratedScores.values())
    if (allResults.length === 0) return

    logger.info('[ScoreCalibrator] 触发策略分层')

    eventBus.emit(EVENT_NAMES.STRATEGY_CLASSIFICATION_START, {
      count: allResults.length,
      timestamp: Date.now(),
    })

    try {
      const stocks = await this.loadStocksFromDB(allResults.map((r) => r.symbol))
      if (stocks.length === 0) {
        logger.warn('[ScoreCalibrator] 无股票数据，跳过策略分层')
        return
      }

      const result = await runDualStrategyUseCase({ stocks: stocks as unknown as Parameters<typeof runDualStrategyUseCase>[0]['stocks'] })

      eventBus.emit(EVENT_NAMES.STRATEGY_CLASSIFICATION_DONE, {
        calibrations: allResults,
        strategy: result.data,
        timestamp: Date.now(),
      })
      logger.info('[ScoreCalibrator] 策略分层完成')
    } catch (e) {
      logger.error('[ScoreCalibrator] 策略分层失败', { error: e instanceof Error ? e.message : String(e) })
      eventBus.emit(EVENT_NAMES.STRATEGY_CLASSIFICATION_ERROR, {
        error: String(e),
        timestamp: Date.now(),
      })
    }
  }

  private scoreToRating(score: number): string {
    return scoreToRatingPublic(score)
  }

  private scoreToTier(score: number): string {
    return scoreToTierPublic(score)
  }

  getAllCalibrations(): CalibrationResult[] {
    return Array.from(this.calibratedScores.values())
  }

  getManualReviewList(): CalibrationResult[] {
    return this.getAllCalibrations().filter((r) => r.needsManualReview)
  }

  reset(): void {
    this.calibratedScores.clear()
    this.pendingSymbols.clear()
  }

  private async loadStocksFromDB(symbols: string[]): Promise<unknown[]> {
    const results: unknown[] = []
    for (const symbol of symbols) {
      try {
        const res = await dataBridge.query({
          action: ENVELOPE_ACTION.queryList,
          store: STORE_NAME.stocks,
        })
        const list = (res.data ?? []) as unknown[]
        const match = list.find((s) => (s as { symbol?: string } | null)?.symbol === symbol)
        if (match) results.push(match)
      } catch {
        /* skip */
      }
    }
    return results
  }
}

let _instance: ScoreCalibrator | null = null

export function getScoreCalibrator(config?: Partial<ScoreCalibratorConfig>): ScoreCalibrator {
  if (!_instance) _instance = new ScoreCalibrator(config)
  return _instance
}

export function startScoreCalibrator(config?: Partial<ScoreCalibratorConfig>): ScoreCalibrator {
  const cal = getScoreCalibrator(config)
  cal.start()
  return cal
}

/**
 * @fileoverview 策略报告生成器 — 监听策略分层完成事件，聚合校对结果和策略数据，生成标准报告
 *
 * 报告包含 6 个 section：
 *   1. summary       — 整体概要
 *   2. buy_signals   — 买入信号（评分 >= 3.5）
 *   3. sell_signals  — 卖出信号（评分 < 3.0）
 *   4. event_drivers — 催化事件汇总
 *   5. volatility_alerts — 波动预警（预留接口）
 *   6. score_changes — 评分变动记录
 *
 * @module services/orchestration/strategyReportGenerator
 * @created 2026-07-25 - P1 编排器扩展
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'
import { getCatalystTracker } from './catalystTracker'
import type { CatalystEvent } from './catalystTracker'
import type { CalibrationResult } from './scoreCalibrator'

const logger = getLogger()

// ---- 类型定义 ----

export interface StrategyReportSection {
  id: string
  title: string
  type: 'summary' | 'buy_signals' | 'sell_signals' | 'event_drivers' | 'volatility_alerts' | 'score_changes'
  content: string
  data?: Record<string, unknown>
  timestamp: number
}

export interface StrategyReport {
  id: string
  generatedAt: number
  title: string
  sections: StrategyReportSection[]
  metadata: {
    totalStocks: number
    coreScarceCount: number
    valueBargainCount: number
    hotMomentumCount: number
    watchCount: number
    manualReviewCount: number
    catalystCount: number
  }
}

export interface StrategyReportGeneratorConfig {
  /** 是否自动生成报告（默认 true） */
  autoGenerate?: boolean
  /** 是否包含买入信号 section（默认 true） */
  includeBuySignals?: boolean
  /** 是否包含卖出信号 section（默认 true） */
  includeSellSignals?: boolean
  /** 是否包含事件驱动 section（默认 true） */
  includeEventDrivers?: boolean
  /** 是否包含波动预警 section（默认 true） */
  includeVolatilityAlerts?: boolean
  /** 是否包含评分变动 section（默认 true） */
  includeScoreChanges?: boolean
}

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<StrategyReportGeneratorConfig> = {
  autoGenerate: true,
  includeBuySignals: true,
  includeSellSignals: true,
  includeEventDrivers: true,
  includeVolatilityAlerts: true,
  includeScoreChanges: true,
}

// ---- 策略报告生成器 ----

export class StrategyReportGenerator {
  private config: Required<StrategyReportGeneratorConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 上一次校对结果（用于评分变动对比） */
  private previousCalibrations: Map<string, number> = new Map()
  /** 历史报告列表 */
  private reports: StrategyReport[] = []

  constructor(config?: StrategyReportGeneratorConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动报告生成器 — 订阅策略分层完成事件 */
  start(): void {
    if (this._active) return
    this._active = true

    const unsub = eventBus.on(EVENT_NAMES.STRATEGY_CLASSIFICATION_DONE, (payload: unknown) => {
      if (!this.config.autoGenerate) return
      this.handleClassificationDone(payload)
    })

    this.unsubscribers.push(unsub)
    logger.info('[StrategyReportGenerator] 已启动，监听策略分层完成事件')
  }

  /** 停止报告生成器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[StrategyReportGenerator] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 事件处理 ----

  /** 处理策略分层完成事件 */
  private handleClassificationDone(payload: unknown): void {
    const p = payload as {
      calibrations?: CalibrationResult[]
      strategy?: unknown
      timestamp?: number
    }

    const calibrations = p.calibrations ?? []
    const strategyData = p.strategy

    try {
      const report = this.generateReport(calibrations, strategyData)
      this.reports.push(report)

      logger.info('[StrategyReportGenerator] 报告已生成', {
        reportId: report.id,
        totalStocks: report.metadata.totalStocks,
      })

      eventBus.emit(EVENT_NAMES.STRATEGY_REPORT_GENERATED, report)
    } catch (e) {
      logger.error('[StrategyReportGenerator] 报告生成失败', { error: e instanceof Error ? e.message : String(e) })
    }
  }

  // ---- 报告生成 ----

  /** 生成标准策略报告 */
  generateReport(calibrations: CalibrationResult[], _strategyData: unknown): StrategyReport {
    const sections: StrategyReportSection[] = []
    const now = Date.now()

    // 统计各 tier 数量
    const coreScarceCount = calibrations.filter((c) => c.strategyTier === 'core-scarce').length
    const valueBargainCount = calibrations.filter((c) => c.strategyTier === 'value-bargain').length
    const hotMomentumCount = calibrations.filter((c) => c.strategyTier === 'hot-momentum').length
    const watchCount = calibrations.filter((c) => c.strategyTier === 'watch').length
    const manualReviewCount = calibrations.filter((c) => c.needsManualReview).length

    // 获取催化事件
    let catalystCount = 0
    try {
      const tracker = getCatalystTracker()
      catalystCount = tracker.getAllCatalysts().length
    } catch {
      // CatalystTracker 可能未启动
    }

    // 1. summary — 整体概要
    sections.push(this.buildSummarySection(calibrations, {
      coreScarceCount,
      valueBargainCount,
      hotMomentumCount,
      watchCount,
      manualReviewCount,
    }, now))

    // 2. buy_signals — 买入信号
    if (this.config.includeBuySignals) {
      sections.push(this.buildBuySignalsSection(calibrations, now))
    }

    // 3. sell_signals — 卖出信号
    if (this.config.includeSellSignals) {
      sections.push(this.buildSellSignalsSection(calibrations, now))
    }

    // 4. event_drivers — 催化事件汇总
    if (this.config.includeEventDrivers) {
      sections.push(this.buildEventDriversSection(now))
    }

    // 5. volatility_alerts — 波动预警（预留）
    if (this.config.includeVolatilityAlerts) {
      sections.push(this.buildVolatilityAlertsSection(now))
    }

    // 6. score_changes — 评分变动
    if (this.config.includeScoreChanges) {
      sections.push(this.buildScoreChangesSection(calibrations, now))
    }

    // 保存本次校对结果用于下次对比
    for (const cal of calibrations) {
      this.previousCalibrations.set(cal.symbol, cal.finalScore)
    }

    const report: StrategyReport = {
      id: nanoid(12),
      generatedAt: now,
      title: `策略分析报告 — ${new Date(now).toLocaleDateString('zh-CN')}`,
      sections,
      metadata: {
        totalStocks: calibrations.length,
        coreScarceCount,
        valueBargainCount,
        hotMomentumCount,
        watchCount,
        manualReviewCount,
        catalystCount,
      },
    }

    return report
  }

  /** 构建 summary section */
  private buildSummarySection(
    calibrations: CalibrationResult[],
    tierCounts: {
      coreScarceCount: number
      valueBargainCount: number
      hotMomentumCount: number
      watchCount: number
      manualReviewCount: number
    },
    now: number,
  ): StrategyReportSection {
    const avgScore = calibrations.length > 0
      ? calibrations.reduce((sum, c) => sum + c.finalScore, 0) / calibrations.length
      : 0

    const content = [
      `本次分析共涵盖 ${calibrations.length} 只股票，平均评分 ${(avgScore).toFixed(2)}。`,
      `核心稀缺 ${tierCounts.coreScarceCount} 只，价值洼地 ${tierCounts.valueBargainCount} 只，`,
      `热门动量 ${tierCounts.hotMomentumCount} 只，观察舱 ${tierCounts.watchCount} 只。`,
      tierCounts.manualReviewCount > 0 ? `其中 ${tierCounts.manualReviewCount} 只需要人工复核。` : '',
    ].filter(Boolean).join('')

    return {
      id: nanoid(12),
      title: '整体概要',
      type: 'summary',
      content,
      data: {
        totalStocks: calibrations.length,
        averageScore: Number(avgScore.toFixed(2)),
        ...tierCounts,
      },
      timestamp: now,
    }
  }

  /** 构建 buy_signals section */
  private buildBuySignalsSection(calibrations: CalibrationResult[], now: number): StrategyReportSection {
    const buyCandidates = calibrations
      .filter((c) => c.finalScore >= 3.5)
      .sort((a, b) => b.finalScore - a.finalScore)

    const content = buyCandidates.length > 0
      ? buyCandidates.map((c) =>
          `${c.symbol}: 评分 ${c.finalScore.toFixed(2)}，评级 ${c.rating}，分层 ${c.strategyTier}`,
        ).join('\n')
      : '当前无买入信号。'

    return {
      id: nanoid(12),
      title: '买入信号',
      type: 'buy_signals',
      content,
      data: {
        count: buyCandidates.length,
        stocks: buyCandidates.map((c) => ({
          symbol: c.symbol,
          score: c.finalScore,
          rating: c.rating,
          tier: c.strategyTier,
        })),
      },
      timestamp: now,
    }
  }

  /** 构建 sell_signals section */
  private buildSellSignalsSection(calibrations: CalibrationResult[], now: number): StrategyReportSection {
    const sellCandidates = calibrations
      .filter((c) => c.finalScore < 3.0)
      .sort((a, b) => a.finalScore - b.finalScore)

    const content = sellCandidates.length > 0
      ? sellCandidates.map((c) =>
          `${c.symbol}: 评分 ${c.finalScore.toFixed(2)}，评级 ${c.rating}，风险提示：评分低于 3.0 阈值`,
        ).join('\n')
      : '当前无卖出信号。'

    return {
      id: nanoid(12),
      title: '卖出信号',
      type: 'sell_signals',
      content,
      data: {
        count: sellCandidates.length,
        stocks: sellCandidates.map((c) => ({
          symbol: c.symbol,
          score: c.finalScore,
          rating: c.rating,
        })),
      },
      timestamp: now,
    }
  }

  /** 构建 event_drivers section */
  private buildEventDriversSection(now: number): StrategyReportSection {
    let catalysts: CatalystEvent[] = []

    try {
      const tracker = getCatalystTracker()
      catalysts = tracker.getHighImpactCatalysts(3)
    } catch {
      // CatalystTracker 可能未启动
    }

    const content = catalysts.length > 0
      ? catalysts.slice(0, 20).map((c) =>
          `[${c.type}] ${c.symbol}: ${c.title}（影响 ${c.impact}，分数 ${c.impactScore}）`,
        ).join('\n')
      : '当前无高影响催化事件。'

    return {
      id: nanoid(12),
      title: '催化事件汇总',
      type: 'event_drivers',
      content,
      data: {
        count: catalysts.length,
        catalysts: catalysts.slice(0, 20).map((c) => ({
          id: c.id,
          symbol: c.symbol,
          type: c.type,
          impact: c.impact,
          score: c.impactScore,
          title: c.title,
        })),
      },
      timestamp: now,
    }
  }

  /** 构建 volatility_alerts section（预留接口） */
  private buildVolatilityAlertsSection(now: number): StrategyReportSection {
    return {
      id: nanoid(12),
      title: '波动预警',
      type: 'volatility_alerts',
      content: '波动预警模块尚未接入，后续将基于日间波动率、成交量异常等指标提供预警信息。',
      data: { count: 0, alerts: [] },
      timestamp: now,
    }
  }

  /** 构建 score_changes section */
  private buildScoreChangesSection(calibrations: CalibrationResult[], now: number): StrategyReportSection {
    const changes: Array<{
      symbol: string
      previousScore: number
      newScore: number
      delta: number
    }> = []

    for (const cal of calibrations) {
      const prev = this.previousCalibrations.get(cal.symbol)
      if (prev !== undefined && Math.abs(cal.finalScore - prev) > 0.01) {
        changes.push({
          symbol: cal.symbol,
          previousScore: prev,
          newScore: cal.finalScore,
          delta: cal.finalScore - prev,
        })
      }
    }

    // 按变动幅度排序
    changes.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))

    const content = changes.length > 0
      ? changes.map((c) => {
          const direction = c.delta > 0 ? '+' : ''
          return `${c.symbol}: ${c.previousScore.toFixed(2)} → ${c.newScore.toFixed(2)}（${direction}${c.delta.toFixed(2)}）`
        }).join('\n')
      : '本次无评分变动记录（首次生成报告）。'

    return {
      id: nanoid(12),
      title: '评分变动',
      type: 'score_changes',
      content,
      data: {
        count: changes.length,
        changes,
      },
      timestamp: now,
    }
  }

  // ---- 查询接口 ----

  /** 获取最新报告 */
  getLatestReport(): StrategyReport | null {
    return this.reports.length > 0 ? (this.reports[this.reports.length - 1] ?? null) : null
  }

  /** 获取全部报告 */
  getReports(): StrategyReport[] {
    return [...this.reports]
  }

  /** 清空所有数据 */
  clear(): void {
    this.previousCalibrations.clear()
    this.reports = []
    logger.info('[StrategyReportGenerator] 已清空')
  }
}

// ---- 全局单例 ----

let _instance: StrategyReportGenerator | null = null

export function getStrategyReportGenerator(config?: StrategyReportGeneratorConfig): StrategyReportGenerator {
  if (!_instance) _instance = new StrategyReportGenerator(config)
  return _instance
}

export function startStrategyReportGenerator(config?: StrategyReportGeneratorConfig): StrategyReportGenerator {
  const generator = getStrategyReportGenerator(config)
  generator.start()
  return generator
}

/**
 * @fileoverview 择时协同度量化器 — 量化买卖点与股价极值的偏差天数，计算择时准确率
 *
 * 监听交易执行事件，结合历史行情数据查找回溯窗口内的最高/最低价日期，
 * 计算买卖时点与极值的偏差天数，汇总为择时准确率与协同度指标。
 *
 * @module services/orchestration/timelinessSyncAnalyzer
 * @created 2026-07-25 - P2 高级功能模块
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ---- 类型定义 ----

export interface TradeRecord {
  symbol: string
  action: 'buy' | 'sell'
  price: number
  quantity: number
  timestamp: number
  /** 标注：manual=手动标记, signal=信号触发, strategy=策略驱动 */
  source: 'manual' | 'signal' | 'strategy'
}

export interface TimelinessMetrics {
  id: string
  symbol: string
  totalTrades: number
  /** 买点距近期最低点的偏差天数（负=在最低点前，正=在最低点后） */
  buyTimingDeviationDays: number[]
  /** 卖点距近期最高点的偏差天数 */
  sellTimingDeviationDays: number[]
  /** 平均择时偏差（天数绝对值的平均） */
  avgDeviationDays: number
  /** 择时准确率（偏差<=accuracyThresholdDays视为准确） */
  timingAccuracyRate: number
  /** 择时收益率 vs 持有收益率 */
  timingReturnVsHold: number
  /** 周线复盘协同度（0-1，买卖时点与周线趋势的协同程度） */
  weeklyCorrelation: number
}

export interface TimelinessSyncConfig {
  /** 准确率阈值（偏差天数<=此值视为准确），默认3 */
  accuracyThresholdDays?: number
  /** 回溯天数（查找极值的范围），默认30 */
  lookbackDays?: number
  /** 是否自动分析，默认 true */
  autoAnalyze?: boolean
}

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<TimelinessSyncConfig> = {
  accuracyThresholdDays: 3,
  lookbackDays: 30,
  autoAnalyze: true,
}

// ---- 辅助：行情数据接口 ----

/** 行情数据点（由外部数据源提供） */
interface QuotePoint {
  date: string | number
  close: number
  high: number
  low: number
}

// ---- 择时协同度量化器 ----

export class TimelinessSyncAnalyzer {
  private config: Required<TimelinessSyncConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 按 symbol 索引的交易记录 */
  private trades: Map<string, TradeRecord[]> = new Map()
  /** 按 symbol 索引的择时指标 */
  private metrics: Map<string, TimelinessMetrics> = new Map()
  /** 按 symbol 索引的历史行情（用于查找极值） */
  private quoteHistory: Map<string, QuotePoint[]> = new Map()

  constructor(config?: TimelinessSyncConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动量化器 — 订阅交易执行事件 */
  start(): void {
    if (this._active) return
    this._active = true

    // 监听交易执行事件（优先 trade:action:executed）
    let unsub = eventBus.on(EVENT_NAMES.TRADE_ACTION_EXECUTED, (payload: unknown) => {
      if (!this.config.autoAnalyze) return
      this.handleTradeExecuted(payload)
    })
    this.unsubscribers.push(unsub)

    // 同时监听订单变更作为备用
    unsub = eventBus.on(EVENT_NAMES.ORDERS_CHANGED, (payload: unknown) => {
      if (!this.config.autoAnalyze) return
      this.handleOrdersChanged(payload)
    })
    this.unsubscribers.push(unsub)

    // 监听行情数据变更，更新历史行情
    unsub = eventBus.on(EVENT_NAMES.MARKET_DATA_CHANGED, (payload: unknown) => {
      this.handleMarketDataChanged(payload)
    })
    this.unsubscribers.push(unsub)

    logger.info('[TimelinessSyncAnalyzer] 已启动，监听交易执行事件')
  }

  /** 停止量化器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[TimelinessSyncAnalyzer] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 事件处理 ----

  /** 处理交易执行事件 */
  private handleTradeExecuted(payload: unknown): void {
    const record = this.parseTradeRecord(payload)
    if (!record) return

    this.addTradeRecord(record)
    this.analyzeSymbol(record.symbol)
  }

  /** 处理订单变更事件（备用） */
  private handleOrdersChanged(payload: unknown): void {
    const p = payload as {
      orders?: Array<{
        symbol?: string
        side?: string
        price?: number
        quantity?: number
        timestamp?: number
      }>
    }

    if (!p?.orders) return

    for (const order of p.orders) {
      const action = order.side === 'buy' ? 'buy' as const : 'sell' as const
      if (order.symbol && order.price) {
        const record: TradeRecord = {
          symbol: order.symbol,
          action,
          price: order.price,
          quantity: order.quantity ?? 0,
          timestamp: order.timestamp ?? Date.now(),
          source: 'strategy',
        }
        this.addTradeRecord(record)
        this.analyzeSymbol(record.symbol)
      }
    }
  }

  /** 处理行情数据变更 */
  private handleMarketDataChanged(payload: unknown): void {
    const p = payload as {
      symbol?: string
      quotes?: QuotePoint[]
      quote?: QuotePoint
    }

    if (!p?.symbol) return

    const quotes = p.quotes ?? (p.quote ? [p.quote] : [])
    if (quotes.length === 0) return

    if (!this.quoteHistory.has(p.symbol)) {
      this.quoteHistory.set(p.symbol, [])
    }
    const history = this.quoteHistory.get(p.symbol)!

    // 追加新行情点（去重）
    for (const q of quotes) {
      const exists = history.some((h) => String(h.date) === String(q.date))
      if (!exists) {
        history.push(q)
      }
    }

    // 按日期排序
    history.sort((a, b) => Number(a.date) - Number(b.date))

    // 仅保留 lookbackDays * 1.5 的数据量
    const maxLen = Math.ceil(this.config.lookbackDays * 1.5)
    if (history.length > maxLen) {
      this.quoteHistory.set(p.symbol, history.slice(-maxLen))
    }
  }

  /** 解析交易记录 */
  private parseTradeRecord(payload: unknown): TradeRecord | null {
    const p = payload as Partial<TradeRecord>
    if (!p.symbol || !p.price) return null
    if (p.action !== 'buy' && p.action !== 'sell') return null

    return {
      symbol: p.symbol,
      action: p.action,
      price: p.price,
      quantity: p.quantity ?? 0,
      timestamp: p.timestamp ?? Date.now(),
      source: p.source ?? 'strategy',
    }
  }

  /** 添加交易记录 */
  private addTradeRecord(record: TradeRecord): void {
    if (!this.trades.has(record.symbol)) {
      this.trades.set(record.symbol, [])
    }
    this.trades.get(record.symbol)!.push(record)
    logger.info('[TimelinessSyncAnalyzer] 记录交易', {
      symbol: record.symbol,
      action: record.action,
      price: record.price,
    })
  }

  /** 分析单只股票的择时指标 */
  private analyzeSymbol(symbol: string): void {
    const symbolTrades = this.trades.get(symbol)
    const quotes = this.quoteHistory.get(symbol)

    if (!symbolTrades || symbolTrades.length === 0) return

    const buyDeviations: number[] = []
    const sellDeviations: number[] = []

    for (const trade of symbolTrades) {
      const deviation = this.calculateDeviation(trade, quotes)
      if (deviation === null) continue

      if (trade.action === 'buy') {
        buyDeviations.push(deviation)
      } else {
        sellDeviations.push(deviation)
      }
    }

    // 合并所有偏差
    const allDeviations = [...buyDeviations, ...sellDeviations]
    const avgDeviation = allDeviations.length > 0
      ? allDeviations.reduce((sum, d) => sum + Math.abs(d), 0) / allDeviations.length
      : 0

    // 择时准确率
    const accurateCount = allDeviations.filter((d) => Math.abs(d) <= this.config.accuracyThresholdDays).length
    const timingAccuracyRate = allDeviations.length > 0 ? accurateCount / allDeviations.length : 0

    // 择时收益率 vs 持有收益率
    const timingReturnVsHold = this.calculateTimingReturnVsHold(symbolTrades)

    // 周线协同度
    const weeklyCorrelation = this.calculateWeeklyCorrelation(symbolTrades, quotes)

    const metrics: TimelinessMetrics = {
      id: nanoid(12),
      symbol,
      totalTrades: symbolTrades.length,
      buyTimingDeviationDays: buyDeviations,
      sellTimingDeviationDays: sellDeviations,
      avgDeviationDays: Math.round(avgDeviation * 100) / 100,
      timingAccuracyRate: Math.round(timingAccuracyRate * 10000) / 10000,
      timingReturnVsHold: Math.round(timingReturnVsHold * 100) / 100,
      weeklyCorrelation: Math.round(weeklyCorrelation * 10000) / 10000,
    }

    this.metrics.set(symbol, metrics)

    logger.info('[TimelinessSyncAnalyzer] 择时分析完成', {
      symbol,
      totalTrades: metrics.totalTrades,
      avgDeviation: metrics.avgDeviationDays,
      accuracy: `${(metrics.timingAccuracyRate * 100).toFixed(1)}%`,
    })

    eventBus.emit(EVENT_NAMES.TIMELINESS_ANALYSIS_COMPLETED, metrics)
  }

  /** 计算单笔交易的偏差天数 */
  private calculateDeviation(trade: TradeRecord, quotes?: QuotePoint[]): number | null {
    if (!quotes || quotes.length === 0) return null

    const tradeDate = Number(trade.timestamp)
    const lookbackMs = this.config.lookbackDays * 24 * 60 * 60 * 1000
    const windowStart = tradeDate - lookbackMs

    // 筛选回溯窗口内的行情
    const windowQuotes = quotes.filter((q) => {
      const qDate = Number(q.date)
      return qDate >= windowStart && qDate <= tradeDate
    })

    if (windowQuotes.length === 0) return null

    const MS_PER_DAY = 24 * 60 * 60 * 1000

    if (trade.action === 'buy') {
      // 找窗口内最低点
      const lowestQuote = windowQuotes.reduce((min, q) => (q.low < (min?.low ?? Infinity) ? q : min ?? q), windowQuotes[0])
      if (!lowestQuote) return null
      const lowestDate = Number(lowestQuote.date)
      return Math.round((tradeDate - lowestDate) / MS_PER_DAY)
    } else {
      // 找窗口内最高点
      const highestQuote = windowQuotes.reduce((max, q) => (q.high > (max?.high ?? -Infinity) ? q : max ?? q), windowQuotes[0])
      if (!highestQuote) return null
      const highestDate = Number(highestQuote.date)
      return Math.round((tradeDate - highestDate) / MS_PER_DAY)
    }
  }

  /** 计算择时收益率 vs 持有收益率 */
  private calculateTimingReturnVsHold(trades: TradeRecord[]): number {
    if (trades.length < 2) return 0

    // 配对买卖
    const buys = trades.filter((t) => t.action === 'buy').sort((a, b) => a.timestamp - b.timestamp)
    const sells = trades.filter((t) => t.action === 'sell').sort((a, b) => a.timestamp - b.timestamp)

    let timingReturn = 0
    let holdReturn = 0
    let pairCount = 0

    const pairLen = Math.min(buys.length, sells.length)
    for (let i = 0; i < pairLen; i++) {
      const buy = buys[i]!
      const sell = sells[i]!
      if (sell.timestamp <= buy.timestamp) continue

      const tradeReturn = (sell.price - buy.price) / buy.price

      // 持有收益率：买入价到卖出期间的简单假设（首尾价差）
      const holdReturnEstimate = tradeReturn * 0.8 // 近似假设
      timingReturn += tradeReturn
      holdReturn += holdReturnEstimate
      pairCount++
    }

    if (pairCount === 0) return 0

    const avgTiming = timingReturn / pairCount
    const avgHold = holdReturn / pairCount

    return avgHold !== 0 ? ((avgTiming - avgHold) / Math.abs(avgHold)) * 100 : avgTiming * 100
  }

  /** 计算周线协同度 */
  private calculateWeeklyCorrelation(trades: TradeRecord[], quotes?: QuotePoint[]): number {
    if (!quotes || quotes.length < 5) return 0

    const MS_PER_DAY = 24 * 60 * 60 * 1000
    const MS_PER_WEEK = 5 * MS_PER_DAY // 5个交易日为一周

    let correlationSum = 0
    let tradeCount = 0

    for (const trade of trades) {
      const tradeWeek = Math.floor(trade.timestamp / MS_PER_WEEK)

      // 找该周的行情
      const weekQuotes = quotes.filter((q) => {
        const qWeek = Math.floor(Number(q.date) / MS_PER_WEEK)
        return qWeek === tradeWeek
      })

      if (weekQuotes.length < 2) continue

      const weekStart = weekQuotes[0]!.close
      const weekEnd = weekQuotes[weekQuotes.length - 1]!.close
      const weekTrend = weekEnd - weekStart

      // 买入与上升趋势协同，卖出与下降趋势协同
      const tradeDirection = trade.action === 'buy' ? 1 : -1
      const trendDirection = weekTrend >= 0 ? 1 : -1

      // 协同度 = 方向一致为1，不一致为0，按趋势幅度加权
      const magnitude = Math.min(Math.abs(weekTrend) / weekStart, 1)
      const synergy = tradeDirection === trendDirection ? magnitude : -magnitude * 0.5

      correlationSum += synergy
      tradeCount++
    }

    return tradeCount > 0
      ? Math.max(0, Math.min(1, (correlationSum / tradeCount + 1) / 2))
      : 0
  }

  // ---- 公开查询接口 ----

  /** 获取指定股票的择时指标 */
  getMetrics(symbol: string): TimelinessMetrics | null {
    return this.metrics.get(symbol) ?? null
  }

  /** 获取全部择时指标 */
  getAllMetrics(): Map<string, TimelinessMetrics> {
    return new Map(this.metrics)
  }

  /** 获取综合择时报告 */
  getCorrelationReport(): {
    avgAccuracy: number
    avgDeviation: number
    bestTimers: string[]
    worstTimers: string[]
  } {
    const allMetrics = Array.from(this.metrics.values())
    if (allMetrics.length === 0) {
      return { avgAccuracy: 0, avgDeviation: 0, bestTimers: [], worstTimers: [] }
    }

    const avgAccuracy = allMetrics.reduce((s, m) => s + m.timingAccuracyRate, 0) / allMetrics.length
    const avgDeviation = allMetrics.reduce((s, m) => s + m.avgDeviationDays, 0) / allMetrics.length

    // 按准确率排序
    const sorted = [...allMetrics].sort((a, b) => b.timingAccuracyRate - a.timingAccuracyRate)

    const bestTimers = sorted.slice(0, Math.min(5, sorted.length)).map((m) => m.symbol)
    const worstTimers = sorted.slice(-Math.min(5, sorted.length)).reverse().map((m) => m.symbol)

    return {
      avgAccuracy: Math.round(avgAccuracy * 10000) / 10000,
      avgDeviation: Math.round(avgDeviation * 100) / 100,
      bestTimers,
      worstTimers,
    }
  }

  /** 手动注入行情数据 */
  injectQuoteHistory(symbol: string, quotes: QuotePoint[]): void {
    if (!this.quoteHistory.has(symbol)) {
      this.quoteHistory.set(symbol, [])
    }
    const existing = this.quoteHistory.get(symbol)!
    for (const q of quotes) {
      const exists = existing.some((h) => String(h.date) === String(q.date))
      if (!exists) {
        existing.push(q)
      }
    }
    existing.sort((a, b) => Number(a.date) - Number(b.date))
  }

  /** 清空所有数据 */
  clear(): void {
    this.trades.clear()
    this.metrics.clear()
    this.quoteHistory.clear()
    logger.info('[TimelinessSyncAnalyzer] 已清空')
  }
}

// ---- 全局单例 ----

let _instance: TimelinessSyncAnalyzer | null = null

export function getTimelinessSyncAnalyzer(config?: TimelinessSyncConfig): TimelinessSyncAnalyzer {
  if (!_instance) _instance = new TimelinessSyncAnalyzer(config)
  return _instance
}

export function startTimelinessSyncAnalyzer(config?: TimelinessSyncConfig): TimelinessSyncAnalyzer {
  const analyzer = getTimelinessSyncAnalyzer(config)
  analyzer.start()
  return analyzer
}

/**
 * @fileoverview 实时波动预警器 — 日波动率超过2标准差时发出预警
 *
 * 监听行情数据更新，维护滚动窗口的日收益率标准差，
 * 当日波动超过 alertThreshold 倍标准差时发出预警，
 * 超过 criticalThreshold 时发出严重预警。
 *
 * @module services/orchestration/volatilityAlert
 * @created 2026-07-25 - P2 高级功能模块
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ---- 类型定义 ----

export interface VolatilityAlert {
  id: string
  symbol: string
  currentPrice: number
  previousClose: number
  dailyChangePct: number
  /** 波动率（日收益率标准差的倍数） */
  sigmaLevel: number
  direction: 'up' | 'down'
  detectedAt: number
  /** 预警级别 */
  level: 'info' | 'warning' | 'critical'
}

export interface VolatilityConfig {
  /** 预警阈值（sigma 倍数），默认 2.0 */
  alertThreshold?: number
  /** critical 阈值，默认 3.0 */
  criticalThreshold?: number
  /** 计算波动率的历史天数，默认 20 */
  lookbackDays?: number
  /** 是否自动预警，默认 true */
  autoAlert?: boolean
  /** 关注的股票列表，空=全部 */
  watchSymbols?: string[]
}

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<VolatilityConfig> = {
  alertThreshold: 2.0,
  criticalThreshold: 3.0,
  lookbackDays: 20,
  autoAlert: true,
  watchSymbols: [],
}

// ---- 行情更新数据接口 ----

interface QuoteUpdate {
  symbol: string
  price: number
  previousClose?: number
  open?: number
  high?: number
  low?: number
  timestamp?: number
}

// ---- 实时波动预警器 ----

export class VolatilityAlertPush {
  private config: Required<VolatilityConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 按 symbol 索引的预警列表 */
  private alerts: Map<string, VolatilityAlert[]> = new Map()
  /** 全量预警列表 */
  private allAlertsList: VolatilityAlert[] = []
  /** 按 symbol 索引的历史收盘价序列（用于计算收益率） */
  private priceHistory: Map<string, number[]> = new Map()
  /** 按 symbol 索引的前一收盘价 */
  private previousClose: Map<string, number> = new Map()

  constructor(config?: VolatilityConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动预警器 — 订阅行情数据更新事件 */
  start(): void {
    if (this._active) return
    this._active = true

    // 监听行情数据更新
    let unsub = eventBus.on(EVENT_NAMES.MARKET_QUOTE_UPDATE, (payload: unknown) => {
      if (!this.config.autoAlert) return
      this.handleQuoteUpdate(payload)
    })
    this.unsubscribers.push(unsub)

    // 监听市场数据变更作为备用
    unsub = eventBus.on(EVENT_NAMES.MARKET_DATA_CHANGED, (payload: unknown) => {
      if (!this.config.autoAlert) return
      this.handleMarketDataChanged(payload)
    })
    this.unsubscribers.push(unsub)

    logger.info('[VolatilityAlertPush] 已启动', {
      alertThreshold: this.config.alertThreshold,
      criticalThreshold: this.config.criticalThreshold,
      lookbackDays: this.config.lookbackDays,
    })
  }

  /** 停止预警器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[VolatilityAlertPush] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 事件处理 ----

  /** 处理行情数据更新 */
  private handleQuoteUpdate(payload: unknown): void {
    const quotes = this.parseQuoteUpdate(payload)
    for (const quote of quotes) {
      this.processQuote(quote)
    }
  }

  /** 处理市场数据变更（备用） */
  private handleMarketDataChanged(payload: unknown): void {
    const p = payload as {
      symbol?: string
      quotes?: Array<{ close?: number; date?: string | number }>
      quote?: { close?: number; date?: string | number }
    }

    const symbol = p?.symbol
    if (!symbol) return

    const quotes = p.quotes ?? (p.quote ? [p.quote] : [])
    if (quotes.length === 0) return

    const lastQuote = quotes[quotes.length - 1]
    const close = lastQuote?.close
    if (close !== undefined && close !== 0) {
      const date = lastQuote?.date
      this.processQuote({
        symbol,
        price: close,
        timestamp: typeof date === 'number' ? date : Date.now(),
      })
    }
  }

  /** 解析行情更新数据 */
  private parseQuoteUpdate(payload: unknown): QuoteUpdate[] {
    const p = payload as {
      symbol?: string
      price?: number
      previousClose?: number
      timestamp?: number
      quotes?: Array<{
        symbol?: string
        price?: number
        previousClose?: number
        timestamp?: number
      }>
    }

    if (p.quotes !== undefined && p.quotes.length > 0) {
      return p.quotes
        .filter((q): q is { symbol: string; price: number; previousClose?: number; timestamp?: number } =>
          typeof q.symbol === 'string' && q.symbol !== '' && typeof q.price === 'number' && q.price !== 0)
        .map((q) => ({
          symbol: q.symbol,
          price: q.price,
          previousClose: q.previousClose,
          timestamp: q.timestamp,
        }))
    }

    const sym = p.symbol
    const pri = p.price
    if (sym !== undefined && sym !== '' && pri !== undefined && pri !== 0) {
      return [{
        symbol: sym,
        price: pri,
        previousClose: p.previousClose,
        timestamp: p.timestamp ?? Date.now(),
      }]
    }

    return []
  }

  /** 处理单条行情 */
  private processQuote(quote: QuoteUpdate): void {
    // 检查关注列表
    if (this.config.watchSymbols.length > 0 && !this.config.watchSymbols.includes(quote.symbol)) {
      return
    }

    // 更新价格历史
    this.updatePriceHistory(quote.symbol, quote.price)

    // 计算波动率
    const sigmaLevel = this.calculateSigmaLevel(quote.symbol, quote.price)

    if (sigmaLevel === null) {
      // 数据不足，仅更新 previousClose
      return
    }

    // 记录 previousClose
    const prevClose = quote.previousClose ?? 0
    if (prevClose !== 0) {
      this.previousClose.set(quote.symbol, prevClose)
    }

    // 判断是否需要预警
    if (Math.abs(sigmaLevel) >= this.config.criticalThreshold) {
      this.emitAlert(quote.symbol, quote.price, sigmaLevel, 'critical')
    } else if (Math.abs(sigmaLevel) >= this.config.alertThreshold) {
      this.emitAlert(quote.symbol, quote.price, sigmaLevel, 'warning')
    }
  }

  /** 更新价格历史 */
  private updatePriceHistory(symbol: string, price: number): void {
    if (!this.priceHistory.has(symbol)) {
      this.priceHistory.set(symbol, [])
    }

    const history = this.priceHistory.get(symbol)!
    history.push(price)

    // 保持最大长度
    const maxLen = this.config.lookbackDays + 5
    if (history.length > maxLen) {
      this.priceHistory.set(symbol, history.slice(-maxLen))
    }
  }

  /** 计算当前价格的 sigma 级别 */
  private calculateSigmaLevel(symbol: string, currentPrice: number): number | null {
    const history = this.priceHistory.get(symbol)
    if (!history || history.length < 2) return null

    // 取最近 lookbackDays 个收盘价（不包括当前价格）
    const lookback = history.slice(-(this.config.lookbackDays + 1))
    if (lookback.length < 2) return null

    // 计算日收益率序列
    const returns: number[] = []
    for (let i = 1; i < lookback.length; i++) {
      const prev = lookback[i - 1]!
      const curr = lookback[i]!
      if (prev !== 0) {
        returns.push((curr - prev) / prev)
      }
    }

    if (returns.length < 2) return null

    // 计算收益率均值
    const mean = returns.reduce((sum, r) => sum + r, 0) / returns.length

    // 计算收益率标准差
    const variance = returns.reduce((sum, r) => sum + (r - mean) ** 2, 0) / (returns.length - 1)
    const stdDev = Math.sqrt(variance)

    if (stdDev === 0) return null

    // 计算当前日收益率
    const prevPrice = lookback[lookback.length - 1]!
    if (prevPrice === 0) return null

    const currentReturn = (currentPrice - prevPrice) / prevPrice
    const sigmaLevel = currentReturn / stdDev

    return Math.round(sigmaLevel * 100) / 100
  }

  /** 发射预警 */
  private emitAlert(
    symbol: string,
    currentPrice: number,
    sigmaLevel: number,
    level: 'warning' | 'critical',
  ): void {
    const prevClose = this.previousClose.get(symbol) ?? 0
    const dailyChangePct = prevClose !== 0
      ? Math.round(((currentPrice - prevClose) / prevClose) * 10000) / 100
      : 0

    const alert: VolatilityAlert = {
      id: nanoid(12),
      symbol,
      currentPrice,
      previousClose: prevClose,
      dailyChangePct,
      sigmaLevel: Math.abs(sigmaLevel),
      direction: sigmaLevel >= 0 ? 'up' : 'down',
      detectedAt: Date.now(),
      level,
    }

    // 存入 symbol 索引
    if (!this.alerts.has(symbol)) {
      this.alerts.set(symbol, [])
    }
    this.alerts.get(symbol)!.push(alert)

    // 存入全量列表
    this.allAlertsList.push(alert)

    logger.info(`[VolatilityAlertPush] ${level === 'critical' ? '严重预警' : '波动预警'}`, {
      symbol,
      sigmaLevel: alert.sigmaLevel,
      direction: alert.direction,
      dailyChange: `${dailyChangePct}%`,
    })

    // 广播预警事件
    if (level === 'critical') {
      eventBus.emit(EVENT_NAMES.VOLATILITY_CRITICAL, alert)
    } else {
      eventBus.emit(EVENT_NAMES.VOLATILITY_ALERT, alert)
    }
  }

  // ---- 查询接口 ----

  /** 获取指定股票的预警列表 */
  getAlerts(symbol: string): VolatilityAlert[] {
    return this.alerts.get(symbol) ?? []
  }

  /** 获取全部活跃预警（最近24小时内的） */
  getActiveAlerts(): VolatilityAlert[] {
    const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000
    return this.allAlertsList.filter((a) => a.detectedAt >= oneDayAgo)
  }

  /** 获取预警总数 */
  getAlertCount(): number {
    return this.allAlertsList.length
  }

  /** 获取严重预警列表 */
  getCriticalAlerts(): VolatilityAlert[] {
    return this.allAlertsList.filter((a) => a.level === 'critical')
  }

  /** 清空所有预警数据 */
  clear(): void {
    this.alerts.clear()
    this.allAlertsList = []
    this.priceHistory.clear()
    this.previousClose.clear()
    logger.info('[VolatilityAlertPush] 已清空')
  }
}

// ---- 全局单例 ----

let _instance: VolatilityAlertPush | null = null

export function getVolatilityAlertPush(config?: VolatilityConfig): VolatilityAlertPush {
  if (!_instance) _instance = new VolatilityAlertPush(config)
  return _instance
}

export function startVolatilityAlertPush(config?: VolatilityConfig): VolatilityAlertPush {
  const pusher = getVolatilityAlertPush(config)
  pusher.start()
  return pusher
}

/**
 * @fileoverview 观察舱事件触发器 — 监听评分校对事件，当观察舱股票评分提升时触发重新评估
 *
 * 观察舱（watch tier）定义：评分在 2.5-3.2 之间的股票。
 * 当评分提升超过阈值时触发重评，当评分超过 minTriggerScore 时升级 tier。
 *
 * @module services/orchestration/watchListTrigger
 * @created 2026-07-25 - P1 编排器扩展
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ---- 类型定义 ----

export interface WatchListTriggerConfig {
  /** 评分提升超过此阈值时触发重评（默认 0.3） */
  scoreUpgradeThreshold?: number
  /** 最低触发评分，低于此分值不触发（默认 3.2） */
  minTriggerScore?: number
  /** 是否自动触发（默认 true） */
  autoTrigger?: boolean
}

export interface WatchListTriggerEvent {
  id: string
  symbol: string
  previousScore: number
  newScore: number
  reason: string
  timestamp: number
}

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<WatchListTriggerConfig> = {
  scoreUpgradeThreshold: 0.3,
  minTriggerScore: 3.2,
  autoTrigger: true,
}

/** 观察舱评分区间下限 */
const WATCH_TIER_LOWER = 2.5
/** 观察舱评分区间上限 */
const WATCH_TIER_UPPER = 3.2

// ---- 观察舱事件触发器 ----

export class WatchListTrigger {
  private config: Required<WatchListTriggerConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 每只股票的上次评分记录 */
  private previousScores: Map<string, number> = new Map()
  /** 触发事件历史 */
  private triggerEvents: WatchListTriggerEvent[] = []
  /** 待重新评估的股票列表 */
  private pendingReevaluations: Set<string> = new Set()

  constructor(config?: WatchListTriggerConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动触发器 — 订阅评分校对完成事件 */
  start(): void {
    if (this._active) return
    this._active = true

    const unsub = eventBus.on(EVENT_NAMES.SCORE_CALIBRATOR_ITEM, (payload: unknown) => {
      if (!this.config.autoTrigger) return
      this.handleCalibrationItem(payload)
    })

    this.unsubscribers.push(unsub)
    logger.info('[WatchListTrigger] 已启动，监听评分校对事件')
  }

  /** 停止触发器 */
  stop(): void {
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[WatchListTrigger] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 事件处理 ----

  /** 处理评分校对完成事件 */
  private handleCalibrationItem(payload: unknown): void {
    const p = payload as {
      symbol: string
      finalScore: number
      strategyTier?: string
    }

    const { symbol, finalScore } = p
    const previousScore = this.previousScores.get(symbol)

    // 首次记录评分
    if (previousScore === undefined) {
      this.previousScores.set(symbol, finalScore)
      // 首次评分如果在观察舱区间，记录下来
      if (finalScore >= WATCH_TIER_LOWER && finalScore <= WATCH_TIER_UPPER) {
        logger.info('[WatchListTrigger] 股票进入观察舱', { symbol, score: finalScore })
      }
      return
    }

    // 检查是否在观察舱区间（基于 previousScore）
    const wasInWatchTier = previousScore >= WATCH_TIER_LOWER && previousScore <= WATCH_TIER_UPPER

    if (wasInWatchTier) {
      const scoreDelta = finalScore - previousScore

      // 评分提升超过阈值，触发重新评估
      if (scoreDelta >= this.config.scoreUpgradeThreshold && finalScore >= WATCH_TIER_LOWER) {
        this.emitReEvaluate(symbol, previousScore, finalScore, `评分提升 ${scoreDelta.toFixed(2)} 超过阈值 ${this.config.scoreUpgradeThreshold}`)
      }

      // 评分超过 minTriggerScore，升级 tier
      if (finalScore >= this.config.minTriggerScore) {
        this.emitTierUpgrade(symbol, previousScore, finalScore, `评分 ${finalScore.toFixed(2)} 达到升级阈值 ${this.config.minTriggerScore}`)
      }
    }

    // 更新上次评分
    this.previousScores.set(symbol, finalScore)
  }

  /** 发射重新评估事件 */
  private emitReEvaluate(symbol: string, previousScore: number, newScore: number, reason: string): void {
    const event: WatchListTriggerEvent = {
      id: nanoid(12),
      symbol,
      previousScore,
      newScore,
      reason,
      timestamp: Date.now(),
    }

    this.triggerEvents.push(event)
    this.pendingReevaluations.add(symbol)

    logger.info('[WatchListTrigger] 触发重新评估', {
      symbol,
      previousScore: previousScore.toFixed(2),
      newScore: newScore.toFixed(2),
      reason,
    })

    eventBus.emit(EVENT_NAMES.WATCHLIST_REEVALUATE, event)
  }

  /** 发射 tier 升级事件 */
  private emitTierUpgrade(symbol: string, previousScore: number, newScore: number, reason: string): void {
    const event: WatchListTriggerEvent = {
      id: nanoid(12),
      symbol,
      previousScore,
      newScore,
      reason,
      timestamp: Date.now(),
    }

    this.triggerEvents.push(event)

    logger.info('[WatchListTrigger] 触发 tier 升级', {
      symbol,
      previousScore: previousScore.toFixed(2),
      newScore: newScore.toFixed(2),
      reason,
    })

    eventBus.emit(EVENT_NAMES.WATCHLIST_TIER_UPGRADE, event)
  }

  // ---- 查询接口 ----

  /** 获取全部触发事件历史 */
  getTriggers(): WatchListTriggerEvent[] {
    return [...this.triggerEvents]
  }

  /** 获取待重新评估的股票列表 */
  getPendingReevaluations(): string[] {
    return Array.from(this.pendingReevaluations)
  }

  /** 清空所有数据 */
  clear(): void {
    this.previousScores.clear()
    this.triggerEvents = []
    this.pendingReevaluations.clear()
    logger.info('[WatchListTrigger] 已清空')
  }
}

// ---- 全局单例 ----

let _instance: WatchListTrigger | null = null

export function getWatchListTrigger(config?: WatchListTriggerConfig): WatchListTrigger {
  if (!_instance) _instance = new WatchListTrigger(config)
  return _instance
}

export function startWatchListTrigger(config?: WatchListTriggerConfig): WatchListTrigger {
  const trigger = getWatchListTrigger(config)
  trigger.start()
  return trigger
}

/**
 * @fileoverview 周线自动复盘调度器 — 周五收盘后自动触发复盘分析
 *
 * 检查当前是否为周五且已过执行时间，满足条件时自动执行复盘：
 * 收集本周交易记录、对比评分变动、计算择时准确率、汇总策略执行情况。
 * 支持手动触发，复盘结果通过事件广播。
 *
 * @module services/orchestration/weeklyReviewScheduler
 * @created 2026-07-25 - P2 高级功能模块
 */

import { eventBus } from '@/lib/eventBus'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { getLogger } from '@/lib/logger'
import { nanoid } from 'nanoid'

const logger = getLogger()

// ---- 类型定义 ----

export interface WeeklyReviewConfig {
  /** 是否启用自动复盘，默认 false */
  enabled?: boolean
  /** 复盘执行时间（小时，0-23），默认 17（周五下午5点） */
  executeHour?: number
  /** 复盘执行分钟，默认 0 */
  executeMinute?: number
  /** 复盘覆盖天数，默认 5（一周交易日） */
  reviewDays?: number
}

export interface WeeklyReviewResult {
  id: string
  weekStart: number
  weekEnd: number
  generatedAt: number
  /** 本周交易记录汇总 */
  tradeSummary: {
    totalTrades: number
    buyCount: number
    sellCount: number
    symbols: string[]
  }
  /** 评分变动汇总 */
  scoreChanges: { symbol: string; previousScore: number; newScore: number }[]
  /** 择时复盘结果 */
  timelinessSummary: { avgAccuracy: number; avgDeviation: number } | null
  /** 策略执行情况 */
  strategyExecution: {
    coreScarceActions: number
    valueBargainActions: number
    hotMomentumActions: number
  }
}

// ---- 默认配置 ----

const DEFAULT_CONFIG: Required<WeeklyReviewConfig> = {
  enabled: false,
  executeHour: 17,
  executeMinute: 0,
  reviewDays: 5,
}

// ---- 周线自动复盘调度器 ----

export class WeeklyReviewScheduler {
  private config: Required<WeeklyReviewConfig>
  private unsubscribers: (() => void)[] = []
  private _active = false
  /** 定时器句柄 */
  private checkTimer: ReturnType<typeof setInterval> | null = null
  /** 复盘结果历史 */
  private reviews: WeeklyReviewResult[] = []
  /** 本周收集的交易记录（临时缓存） */
  private weekTrades: Array<{
    symbol: string
    action: 'buy' | 'sell'
    price: number
    timestamp: number
  }> = []
  /** 本周评分快照（symbol -> score） */
  private weekScores: Map<string, number> = new Map()
  /** 本周策略执行记录 */
  private strategyActions: Array<{
    strategy: string
    action: string
    timestamp: number
  }> = []

  constructor(config?: WeeklyReviewConfig) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /** 启动调度器 */
  start(): void {
    if (this._active) return
    this._active = true

    // 订阅交易事件以收集本周交易
    let unsub = eventBus.on(EVENT_NAMES.TRADE_ACTION_EXECUTED, (payload: unknown) => {
      this.collectTrade(payload)
    })
    this.unsubscribers.push(unsub)

    unsub = eventBus.on(EVENT_NAMES.ORDERS_CHANGED, (payload: unknown) => {
      this.collectOrdersChanged(payload)
    })
    this.unsubscribers.push(unsub)

    // 订阅评分变更以追踪评分变动
    unsub = eventBus.on(EVENT_NAMES.SCORES_CHANGED, (payload: unknown) => {
      this.collectScoreChange(payload)
    })
    this.unsubscribers.push(unsub)

    // 订阅评分校对完成
    unsub = eventBus.on(EVENT_NAMES.SCORE_CALIBRATOR_ITEM, (payload: unknown) => {
      this.collectScoreCalibration(payload)
    })
    this.unsubscribers.push(unsub)

    // 订阅策略分类事件
    unsub = eventBus.on(EVENT_NAMES.STRATEGY_CLASSIFICATION_DONE, (payload: unknown) => {
      this.collectStrategyAction(payload)
    })
    this.unsubscribers.push(unsub)

    // 设置定时检查（每分钟检查一次是否到了周五执行时间）
    if (this.config.enabled) {
      this.startCheckTimer()
    }

    logger.info('[WeeklyReviewScheduler] 已启动', {
      autoEnabled: this.config.enabled,
      executeTime: `${String(this.config.executeHour).padStart(2, '0')}:${String(this.config.executeMinute).padStart(2, '0')}`,
    })
  }

  /** 停止调度器 */
  stop(): void {
    this.stopCheckTimer()
    this.unsubscribers.forEach((fn) => fn())
    this.unsubscribers = []
    this._active = false
    logger.info('[WeeklyReviewScheduler] 已停止')
  }

  get active(): boolean {
    return this._active
  }

  // ---- 定时检查 ----

  /** 启动定时检查器 */
  private startCheckTimer(): void {
    if (this.checkTimer) return
    this.checkTimer = setInterval(() => {
      this.checkAndExecute()
    }, 60 * 1000) // 每分钟检查一次
    logger.info('[WeeklyReviewScheduler] 定时检查器已启动')
  }

  /** 停止定时检查器 */
  private stopCheckTimer(): void {
    if (this.checkTimer) {
      clearInterval(this.checkTimer)
      this.checkTimer = null
    }
  }

  /** 检查并执行复盘 */
  checkAndExecute(): void {
    if (!this.config.enabled) return

    const now = new Date()
    // 检查是否为周五（getDay() === 5）
    if (now.getDay() !== 5) return

    // 检查是否已过执行时间
    const currentMinutes = now.getHours() * 60 + now.getMinutes()
    const targetMinutes = this.config.executeHour * 60 + this.config.executeMinute

    if (currentMinutes < targetMinutes) return

    // 检查本周是否已经执行过
    const weekStart = this.getWeekStartTimestamp(now)
    const alreadyDone = this.reviews.some((r) => r.weekStart === weekStart)
    if (alreadyDone) return

    logger.info('[WeeklyReviewScheduler] 满足自动复盘条件，开始执行')
    this.executeReview()
  }

  // ---- 数据收集 ----

  /** 收集交易执行记录 */
  private collectTrade(payload: unknown): void {
    const p = payload as {
      symbol?: string
      action?: string
      price?: number
      timestamp?: number
    }

    if ((p.symbol ?? '') !== '' && (p.price ?? 0) !== 0 && (p.action === 'buy' || p.action === 'sell')) {
      this.weekTrades.push({
        symbol: p.symbol ?? '',
        action: p.action,
        price: p.price ?? 0,
        timestamp: p.timestamp ?? Date.now(),
      })
    }
  }

  /** 收集订单变更中的交易记录 */
  private collectOrdersChanged(payload: unknown): void {
    const p = payload as {
      orders?: Array<{
        symbol?: string
        side?: string
        price?: number
        timestamp?: number
      }>
    }

    if (!p?.orders) return

    for (const order of p.orders) {
      if ((order.symbol ?? '') !== '' && (order.price ?? 0) !== 0 && (order.side === 'buy' || order.side === 'sell')) {
        this.weekTrades.push({
          symbol: order.symbol ?? '',
          action: order.side,
          price: order.price ?? 0,
          timestamp: order.timestamp ?? Date.now(),
        })
      }
    }
  }

  /** 收集评分变更 */
  private collectScoreChange(payload: unknown): void {
    const p = payload as {
      scores?: Array<{ symbol?: string; score?: number }>
      symbol?: string
      score?: number
    }

    if (p.scores) {
      for (const s of p.scores) {
        if ((s.symbol ?? '') !== '' && s.score !== undefined) {
          this.weekScores.set(s.symbol ?? '', s.score)
        }
      }
    } else if ((p.symbol ?? '') !== '' && p.score !== undefined) {
      this.weekScores.set(p.symbol ?? '', p.score)
    }
  }

  /** 收集评分校对结果 */
  private collectScoreCalibration(payload: unknown): void {
    const p = payload as {
      symbol?: string
      finalScore?: number
    }

    if ((p.symbol ?? '') !== '' && p.finalScore !== undefined) {
      this.weekScores.set(p.symbol ?? '', p.finalScore)
    }
  }

  /** 收集策略执行记录 */
  private collectStrategyAction(payload: unknown): void {
    const p = payload as {
      strategy?: string
      action?: string
      symbol?: string
    }

    if ((p.strategy ?? '') !== '' || (p.action ?? '') !== '') {
      this.strategyActions.push({
        strategy: p.strategy ?? '',
        action: p.action ?? '',
        timestamp: Date.now(),
      })
    }
  }

  // ---- 复盘执行 ----

  /** 手动触发复盘 */
  manualTrigger(): WeeklyReviewResult {
    logger.info('[WeeklyReviewScheduler] 手动触发复盘')
    return this.executeReview()
  }

  /** 执行复盘分析 */
  private executeReview(): WeeklyReviewResult {
    const now = Date.now()
    const weekEnd = now
    const weekStartMs = this.config.reviewDays * 24 * 60 * 60 * 1000
    const weekStart = weekEnd - weekStartMs

    // 1. 本周交易记录汇总
    const weekTradeRecords = this.weekTrades.filter(
      (t) => t.timestamp >= weekStart && t.timestamp <= weekEnd,
    )

    const tradeSummary = {
      totalTrades: weekTradeRecords.length,
      buyCount: weekTradeRecords.filter((t) => t.action === 'buy').length,
      sellCount: weekTradeRecords.filter((t) => t.action === 'sell').length,
      symbols: [...new Set(weekTradeRecords.map((t) => t.symbol))],
    }

    // 2. 评分变动汇总
    const scoreChanges = this.computeScoreChanges()

    // 3. 择时准确率（尝试获取 TimelinessSyncAnalyzer 的数据）
    const timelinessSummary = this.getTimelinessSummary()

    // 4. 策略执行情况
    const strategyExecution = this.computeStrategyExecution()

    const result: WeeklyReviewResult = {
      id: nanoid(12),
      weekStart,
      weekEnd,
      generatedAt: now,
      tradeSummary,
      scoreChanges,
      timelinessSummary,
      strategyExecution,
    }

    this.reviews.push(result)

    logger.info('[WeeklyReviewScheduler] 复盘完成', {
      totalTrades: tradeSummary.totalTrades,
      scoreChangesCount: scoreChanges.length,
    })

    eventBus.emit(EVENT_NAMES.WEEKLY_REVIEW_COMPLETED, result)

    // 清空本周临时数据
    this.weekTrades = []
    this.strategyActions = []

    return result
  }

  /** 计算评分变动 */
  private computeScoreChanges(): WeeklyReviewResult['scoreChanges'] {
    const changes: WeeklyReviewResult['scoreChanges'] = []

    // 基于本周收集到的评分数据，与上一次复盘中相同 symbol 的评分对比
    const lastReview = this.reviews[this.reviews.length - 1]

    if (lastReview) {
      for (const [symbol, newScore] of this.weekScores) {
        const prevEntry = lastReview.scoreChanges.find((c) => c.symbol === symbol)
        if (prevEntry) {
          changes.push({
            symbol,
            previousScore: prevEntry.newScore,
            newScore,
          })
        } else {
          // 本周新出现的评分
          changes.push({
            symbol,
            previousScore: 0,
            newScore,
          })
        }
      }
    } else {
      // 首次复盘，直接记录
      for (const [symbol, score] of this.weekScores) {
        changes.push({
          symbol,
          previousScore: 0,
          newScore: score,
        })
      }
    }

    return changes
  }

  /** 获取择时复盘摘要 */
  private getTimelinessSummary(): WeeklyReviewResult['timelinessSummary'] {
    // 监听择时分析完成事件的数据
    // 简单实现：从 eventBus 获取最新分析数据
    try {
      // 使用动态 import 避免循环依赖风险
      const metrics = this.tryGetTimelinessMetrics()
      if (metrics) {
        return {
          avgAccuracy: metrics.avgAccuracy,
          avgDeviation: metrics.avgDeviation,
        }
      }
    } catch {
      logger.debug('[WeeklyReviewScheduler] 无法获取择时数据，跳过择时汇总')
    }

    return null
  }

  /** 尝试获取择时指标（非耦合方式） */
  private tryGetTimelinessMetrics(): { avgAccuracy: number; avgDeviation: number } | null {
    // 由于我们不能强依赖 TimelinessSyncAnalyzer 的单例，
    // 这里通过 getCorrelationReport 事件数据来获取
    // 实际数据由 TIMELINESS_ANALYSIS_COMPLETED 事件的最新 payload 提供
    return null
  }

  /** 计算策略执行情况 */
  private computeStrategyExecution(): WeeklyReviewResult['strategyExecution'] {
    let coreScarceActions = 0
    let valueBargainActions = 0
    let hotMomentumActions = 0

    for (const action of this.strategyActions) {
      const strategy = action.strategy.toLowerCase()
      if (strategy.includes('core') || strategy.includes('scarce')) {
        coreScarceActions++
      } else if (strategy.includes('value') || strategy.includes('bargain')) {
        valueBargainActions++
      } else if (strategy.includes('hot') || strategy.includes('momentum')) {
        hotMomentumActions++
      }
    }

    return {
      coreScarceActions,
      valueBargainActions,
      hotMomentumActions,
    }
  }

  /** 获取本周起始时间戳 */
  private getWeekStartTimestamp(date: Date): number {
    const day = date.getDay()
    const diff = day === 0 ? 6 : day - 1 // 周一为一周起始
    const monday = new Date(date)
    monday.setDate(date.getDate() - diff)
    monday.setHours(0, 0, 0, 0)
    return monday.getTime()
  }

  // ---- 查询接口 ----

  /** 获取最近一次复盘结果 */
  getLastReview(): WeeklyReviewResult | null {
    return this.reviews.length > 0 ? (this.reviews[this.reviews.length - 1] ?? null) : null
  }

  /** 获取全部复盘结果 */
  getAllReviews(): WeeklyReviewResult[] {
    return [...this.reviews]
  }

  /** 清空所有数据 */
  clear(): void {
    this.reviews = []
    this.weekTrades = []
    this.weekScores.clear()
    this.strategyActions = []
    logger.info('[WeeklyReviewScheduler] 已清空')
  }
}

// ---- 全局单例 ----

let _instance: WeeklyReviewScheduler | null = null

export function getWeeklyReviewScheduler(config?: WeeklyReviewConfig): WeeklyReviewScheduler {
  if (!_instance) _instance = new WeeklyReviewScheduler(config)
  return _instance
}

export function startWeeklyReviewScheduler(config?: WeeklyReviewConfig): WeeklyReviewScheduler {
  const scheduler = getWeeklyReviewScheduler(config)
  scheduler.start()
  return scheduler
}

/**
 * @fileoverview 数据处理能力压力测试服务
 *
 * 对 V6 评分引擎、双策略分析、轮动检测等计算密集型任务执行集中压力测试，
 * 随机抽取指定数量标的，采集执行耗时、成功率、百分位分布等关键性能指标。
 *
 * @module services/perf/stressTestService
 * @created 2026-07-13 P2-6
  * @doc [V9-DOC-BACK-012, V9-DOC-BACK-023, V9-DOC-BACK-033, V9-DOC-BACK-021, V9-DOC-BACK-026]
*/

import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { nanoid } from 'nanoid'
import { ENVELOPE_ACTION, STORE_NAME } from '@/config/dbConfig'
import type { Stock } from '@/data/types'
import type { StressTestConfig, StressTestResult, PerfMetric, StressTestSummary, TaskStatSummary } from '@/types/modules/perf.types'

/**
 * 压测指标写入接口（依赖注入契约）。
 * services 层禁止直接依赖 store 层，因此服务不再 import 任何 store，
 * 而是由调用方（页面 / 测试桩）注入一个实现了本接口的 sink 适配器。
 */
export interface PerfMetricsSink {
  clearCurrent(): void
  setRunning(running: boolean): void
  addMetric(metric: PerfMetric): void
  saveResult(result: StressTestResult): void
}

/** 默认 no-op sink：无 UI 订阅时的安全降级，避免空引用 */
const noopSink: PerfMetricsSink = {
  clearCurrent() {},
  setRunning() {},
  addMetric() {},
  saveResult() {},
}

const logger = getLogger()

const DEFAULT_CONFIG: Required<StressTestConfig> = {
  symbolCount: 20,
  includeV6Score: true,
  includeDualStrategy: true,
  includeRotationDetection: true,
  parallelMode: true,
  thresholdMs: 3000,
}

/** 随机抽取 N 只股票 */
async function randomPickStocks(count: number): Promise<Stock[]> {
  const result = await dataBridge.query<Stock[]>({
    action: ENVELOPE_ACTION.queryList,
    store: STORE_NAME.stocks,
    source: 'system',
  })
  const all = result.success ? result.data ?? [] : []
  // Fisher-Yates 洗牌取前 N 个
  const shuffled = [...all]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    const si = shuffled[i]
    const sj = shuffled[j]
    if (si == null || sj == null) continue
    shuffled[i] = sj
    shuffled[j] = si
  }
  return shuffled.slice(0, count)
}

/**
 * 执行单次压测。
 * @param cfg 压测配置（可选）
 * @param sink 指标写入适配器（依赖注入）。页面传入 usePerfMetricsStore.getState()，
 *             使服务在零 store 依赖的前提下仍可驱动实时 UI；缺省为 no-op 安全降级。
 */
export async function runStressTest(cfg?: StressTestConfig, sink: PerfMetricsSink = noopSink): Promise<StressTestResult> {
  const config = { ...DEFAULT_CONFIG, ...cfg }
  sink.clearCurrent()
  sink.setRunning(true)

  const runId = `stress-${Date.now()}-${nanoid(6)}`
  const startTs = Date.now()
  const metrics: PerfMetric[] = []
  const symbols = (await randomPickStocks(config.symbolCount)).map((s) => s.symbol)

  logger.info(`[stressTest] 开始压测: runId=${runId}, symbols=${symbols.length}, parallel=${config.parallelMode}`)

  if (config.parallelMode) {
    // === 并行模式：所有标的 × 所有任务并行 ===
    const tasks: Array<{ symbol: string; taskName: string; fn: () => Promise<void> }> = []

    for (const symbol of symbols) {
      if (config.includeV6Score) {
        tasks.push({ symbol, taskName: 'v6Score', fn: () => runV6Score(symbol) })
      }
      if (config.includeDualStrategy) {
        tasks.push({ symbol, taskName: 'dualStrategy', fn: () => runDualStrategy(symbol) })
      }
      if (config.includeRotationDetection) {
        tasks.push({ symbol, taskName: 'rotationDetection', fn: () => runRotationDetection(symbol) })
      }
    }

    const results = await Promise.allSettled(
      tasks.map(async (t) => {
        const startedAt = Date.now()
        try {
          await t.fn()
          const durationMs = Date.now() - startedAt
          const metric: PerfMetric = {
            taskName: t.taskName,
            symbol: t.symbol,
            durationMs,
            startedAt,
            success: true,
          }
          sink.addMetric(metric)
          return metric
        } catch (err) {
          const durationMs = Date.now() - startedAt
          const metric: PerfMetric = {
            taskName: t.taskName,
            symbol: t.symbol,
            durationMs,
            startedAt,
            success: false,
            error: err instanceof Error ? err.message : String(err),
          }
          sink.addMetric(metric)
          return metric
        }
      }),
    )

    for (const r of results) {
      if (r.status === 'fulfilled') metrics.push(r.value)
    }
  } else {
    // === 串行模式：逐标的顺序执行 ===
    for (const symbol of symbols) {
      if (config.includeV6Score) {
        const m = await measureTask('v6Score', symbol, () => runV6Score(symbol))
        metrics.push(m)
        sink.addMetric(m)
      }
      if (config.includeDualStrategy) {
        const m = await measureTask('dualStrategy', symbol, () => runDualStrategy(symbol))
        metrics.push(m)
        sink.addMetric(m)
      }
      if (config.includeRotationDetection) {
        const m = await measureTask('rotationDetection', symbol, () => runRotationDetection(symbol))
        metrics.push(m)
        sink.addMetric(m)
      }
    }
  }

  const summary = computeSummary(metrics, Date.now() - startTs, symbols.length)
  const taskSummaries = computeTaskSummaries(metrics)

  const result: StressTestResult = {
    runId,
    timestamp: Date.now(),
    symbols,
    metrics,
    summary,
    taskSummaries,
  }

  sink.saveResult(result)

  logger.info(`[stressTest] 压测完成: runId=${runId}, total=${summary.totalDurationMs}ms, p95=${summary.p95Ms}ms, success=${summary.successCount}/${metrics.length}`)

  // 门限告警
  if (summary.p95Ms > config.thresholdMs) {
    logger.warn(`[stressTest] ⚠️ P95(${summary.p95Ms}ms) 超出门限(${config.thresholdMs}ms)`)
  }

  return result
}

/** 测量单次任务 */
async function measureTask(
  taskName: string,
  symbol: string,
  fn: () => Promise<void>,
): Promise<PerfMetric> {
  const startedAt = Date.now()
  try {
    await fn()
    return { taskName, symbol, durationMs: Date.now() - startedAt, startedAt, success: true }
  } catch (err) {
    return {
      taskName, symbol,
      durationMs: Date.now() - startedAt,
      startedAt, success: false,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

