/**
 * L0 STEEP 宏观扫描 + L1 护城河 + L2 竞品 计算器
 *
 * 按 SKILL v4.3 评分 rubric 实现。
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-053, V9-DOC-PROJ-113, V9-DOC-PROJ-066, V9-DOC-FRONT-012]
*/

import { getLogger } from '@/lib/logger'
import type { LayerInput, LayerScore, LayerCalculator } from '../types'
import type { LayerId } from '../types'
import { LAYER_LABELS } from '../types'
import { V6_CALCULATOR_THRESHOLDS } from '@/config/thresholds'
import { safeArrayGet, safeFirst, safeLast } from '@/lib/precision'

const logger = getLogger()

// ============================================================
// L0 STEEP 宏观扫描 — 权重 8%
// ============================================================

interface SteepSubItem {
  name: string
  score: number  // 0-10
  evidence: string
}

function evaluateSTEEP(input: LayerInput): { subs: SteepSubItem[]; score: number; summary: string } {
  const { stock, financials } = input
  const sector = (stock.sector ?? '').toLowerCase()
  const subs: SteepSubItem[] = []

  // S-社会：人口结构/消费习惯/ESG
  const isPharma = sector.includes('医药') || sector.includes('药') || sector.includes('生物')
  const isTech = sector.includes('ai') || sector.includes('芯片') || sector.includes('半导体') || sector.includes('科技')
  const isFinance = sector.includes('金融') || sector.includes('银行') || sector.includes('保险')

  subs.push({ name: 'S-人口结构', score: isPharma ? 8 : 6, evidence: isPharma ? '老龄化利好医药' : '中性影响' })
  subs.push({ name: 'S-消费习惯', score: isTech ? 7 : 6, evidence: isTech ? '科技消费升级' : '中性' })
  subs.push({ name: 'S-ESG', score: isTech ? 8 : 6, evidence: isTech ? '科技企业ESG表现较好' : '中性' })

  // T-技术：成熟度/迭代速度/替代风险
  subs.push({ name: 'T-技术成熟度', score: isTech ? 8 : 6, evidence: isTech ? '核心技术处于商业化阶段' : '一般' })
  subs.push({ name: 'T-技术迭代速度', score: isTech ? 7 : 5, evidence: isTech ? '迭代周期1-3年' : '较慢' })
  subs.push({ name: 'T-技术替代风险', score: isTech ? 7 : 6, evidence: isTech ? '远期存在替代风险' : '风险较低' })

  // E-经济：GDP相关性/利率敏感性/通胀传导
  subs.push({ name: 'E-GDP相关性', score: isFinance ? 6 : 5, evidence: isFinance ? '与GDP中等相关' : '弱相关' })
  subs.push({ name: 'E-利率敏感性', score: 6, evidence: '当前利率环境中性' })
  subs.push({ name: 'E-通胀传导', score: isTech ? 7 : 5, evidence: isTech ? '强传导能力' : '一般' })

  // E-环境：碳达峰/碳中和
  subs.push({ name: 'E-双碳政策', score: isTech ? 7 : 6, evidence: isTech ? '间接受益于双碳政策' : '中性' })

  // P-政策：国家战略/财政支持/监管风险
  subs.push({ name: 'P-国家战略', score: isTech ? 9 : 6, evidence: isTech ? '纳入国家战略规划' : '未明确提及' })
  subs.push({ name: 'P-财政支持', score: isTech ? 8 : 5, evidence: isTech ? '有专项资金支持' : '无明确支持' })
  subs.push({ name: 'P-监管风险', score: isFinance ? 5 : 7, evidence: isFinance ? '强监管收紧风险' : '监管风险较低' })

  const avg = subs.reduce((s, x) => s + x.score, 0) / subs.length
  const score = Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(V6_CALCULATOR_THRESHOLDS.SCORE_MIN, avg / V6_CALCULATOR_THRESHOLDS.L0_STEEP_NORMALIZE_DIVISOR)) // 归一化 0-10 → 0-5

  const topPos = subs.filter((s) => s.score >= V6_CALCULATOR_THRESHOLDS.L0_STEEP_POSITIVE_THRESHOLD).slice(0, 3).map((s) => s.name)
  const topNeg = subs.filter((s) => s.score <= V6_CALCULATOR_THRESHOLDS.L0_STEEP_NEGATIVE_THRESHOLD).slice(0, 2).map((s) => s.name)

  let summary = `STEEP 均值 ${avg.toFixed(1)}/10`
  if (topPos.length > 0) summary += `, 利好: ${topPos.join('、')}`
  if (topNeg.length > 0) summary += `, 风险: ${topNeg.join('、')}`

  // 财务数据补充
  if (financials.revenueYoY !== undefined && financials.revenueYoY > V6_CALCULATOR_THRESHOLDS.L0_REVENUE_YOY_HIGH) {
    summary += ', 营收高增印证行业景气'
  }

  return { subs, score, summary }
}

/**
 * L0MacroCalculator
 */
export const L0MacroCalculator: LayerCalculator = {
  layerId: 'l0',
  async calculate(input: LayerInput): Promise<LayerScore> {
    const { config } = input
    const weight = config.weights.l0
    const { subs, score, summary } = evaluateSTEEP(input)

    logger.info(`[L0] ${input.stock.symbol}: STEEP score=${score.toFixed(2)}`)

    return {
      layerId: 'l0' as LayerId,
      layerName: LAYER_LABELS.l0 ?? 'L0 STEEP 宏观扫描',
      score: Math.round(score * 100) / 100,
      summary,
      risks: subs.filter((s) => s.score <= V6_CALCULATOR_THRESHOLDS.L0_STEEP_NEGATIVE_THRESHOLD).map((s) => `${s.name}: ${s.evidence}`),
      evidence: subs.slice(0, 5).map((s) => `${s.name}: ${s.score}/10`),
      weight,
      weightedScore: score * weight,
      dataSources: ['宏观数据', '行业报告'],
      participated: true,
    }
  },
}

// ============================================================
// L1 护城河分析 — 权重 15%
// ============================================================

function evaluateMoat(input: LayerInput): { score: number; summary: string; evidence: string[] } {
  const { stock, financials } = input
  const sector = (stock.sector ?? '').toLowerCase()
  const evidence: string[] = []
  let criteriaMet = 0

  // 技术独占性：研发/营收>10%, 顶尖团队
  if (financials.rdRatio !== undefined && financials.rdRatio > V6_CALCULATOR_THRESHOLDS.L1_MOAT_RD_HIGH) {
    criteriaMet++
    evidence.push(`研发/营收=${(financials.rdRatio * 100).toFixed(1)}%>8%`)
  } else if (financials.rdRatio !== undefined && financials.rdRatio > V6_CALCULATOR_THRESHOLDS.L1_MOAT_RD_MEDIUM) {
    criteriaMet += 0.5
    evidence.push(`研发/营收=${(financials.rdRatio * 100).toFixed(1)}%>5%`)
  }

  // 客户锁定：NRR>120% 或 使用年限>5年 或 深度嵌入流程
  if (financials.customerConcentration !== undefined && financials.customerConcentration < V6_CALCULATOR_THRESHOLDS.L1_MOAT_CUSTOMER_CONCENTRATION_LOW) {
    criteriaMet += 0.5
    evidence.push(`客户集中度低=${(financials.customerConcentration * 100).toFixed(0)}%`)
  }

  // 规模效应：翻倍成本降>15% 或 固定资产竞品3倍+ 或 渠道密度远超
  if (stock.marketCap !== undefined) {
    if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L1_MOAT_MARKET_CAP_LARGE) {
      criteriaMet++
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿，行业龙头`)
    } else if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L1_MOAT_MARKET_CAP_MEDIUM) {
      criteriaMet += 0.5
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿`)
    }
  }

  // 网络效应：双边/多边效应，份额>50%且提升
  const isTech = sector.includes('ai') || sector.includes('芯片') || sector.includes('半导体') || sector.includes('科技')
  if (isTech) {
    criteriaMet += 0.5
    evidence.push('科技行业存在网络效应')
  }

  // 资源独占：稀缺资源垄断/牌照/不可复制区位
  const isPharma = sector.includes('医药') || sector.includes('药') || sector.includes('生物')
  if (isPharma) {
    criteriaMet += 0.5
    evidence.push('医药行业存在专利/牌照壁垒')
  }

  // 满足4条=5分, 3条=4分, 2条=3分, 1条=2分, 0条=1分
  const scoreMap = V6_CALCULATOR_THRESHOLDS.L1_MOAT_CRITERIA_SCORE_MAP
  const score = scoreMap[Math.min(4, criteriaMet)] ?? 1

  const strengths = evidence.filter((e) => !e.includes('中性'))
  const summary = `护城河评估: ${criteriaMet.toFixed(1)}/4条标准满足, ${score >= 4 ? '强护城河' : score >= 3 ? '中等护城河' : '弱护城河'}`

  return { score, summary, evidence: strengths }
}

/**
 * L1MoatCalculator
 */
export const L1MoatCalculator: LayerCalculator = {
  layerId: 'l1',
  async calculate(input: LayerInput): Promise<LayerScore> {
    const { config } = input
    const weight = config.weights.l1
    const { score, summary, evidence } = evaluateMoat(input)

    logger.info(`[L1] ${input.stock.symbol}: 护城河 score=${score.toFixed(2)}`)

    return {
      layerId: 'l1' as LayerId,
      layerName: LAYER_LABELS.l1 ?? 'L1 护城河分析',
      score: Math.round(score * 100) / 100,
      summary,
      risks: score < V6_CALCULATOR_THRESHOLDS.L1_MOAT_RISK_THRESHOLD ? ['护城河较弱，需关注竞争压力'] : [],
      evidence,
      weight,
      weightedScore: score * weight,
      dataSources: ['财报数据', '行业分析'],
      participated: true,
    }
  },
}

// ============================================================
// L2 竞品格局 — 权重 10%
// ============================================================

function evaluatePeer(input: LayerInput): { score: number; summary: string; evidence: string[] } {
  const { stock, financials } = input
  const evidence: string[] = []
  let dimensionScore = V6_CALCULATOR_THRESHOLDS.L2_PEER_BASELINE_SCORE // 基础分

  // 技术代差：领先2代+2.0, 1代+1.0, 持平0, 落后-1.0
  const sector = (stock.sector ?? '').toLowerCase()
  if (sector.includes('芯片') || sector.includes('半导体') || sector.includes('ai')) {
    dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_TECH_BOOST
    evidence.push('科技赛道，技术领先推断+1.0')
  }

  // 市场份额：龙头>30%扩大+1.5, 稳定+0.5
  if (stock.marketCap !== undefined) {
    if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L2_PEER_LARGE_CAP) {
      dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_LARGE_CAP_BOOST
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿，行业龙头+1.0`)
    } else if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L2_PEER_MEDIUM_CAP) {
      dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_MEDIUM_CAP_BOOST
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿，稳定份额+0.5`)
    }
  }

  // 客户认证：量产供货+1.5, 小批量+0.5
  if (financials.revenue !== undefined && financials.revenue > V6_CALCULATOR_THRESHOLDS.L2_PEER_REVENUE_THRESHOLD) {
    dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_REVENUE_BOOST
    evidence.push(`营收=${financials.revenue.toFixed(0)}亿，量产阶段+0.5`)
  }

  const score = Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(1, dimensionScore))
  const tier = score >= 4 ? '第一梯队领先' : score >= 3.5 ? '并列第一梯队' : score >= 3 ? '第二梯队' : '落后'

  return { score, summary: `竞品评估: ${tier}`, evidence }
}

/**
 * L2PeerCalculator
 */
export const L2PeerCalculator: LayerCalculator = {
  layerId: 'l2',
  async calculate(input: LayerInput): Promise<LayerScore> {
    const { config } = input
    const weight = config.weights.l2
    const { score, summary, evidence } = evaluatePeer(input)

    logger.info(`[L2] ${input.stock.symbol}: 竞品 score=${score.toFixed(2)}`)

    return {
      layerId: 'l2' as LayerId,
      layerName: LAYER_LABELS.l2 ?? 'L2 竞品格局',
      score: Math.round(score * 100) / 100,
      summary,
      risks: score < V6_CALCULATOR_THRESHOLDS.L2_PEER_RISK_THRESHOLD ? ['竞品格局偏弱，需关注竞争压力'] : [],
      evidence,
      weight,
      weightedScore: score * weight,
      dataSources: ['市值数据', '财报数据', '行业分析'],
      participated: true,
    }
  },
}

// ============================================================
// 可测试纯函数 — 趋势 / 评分板 / 估值
// ============================================================

import type { StockBasicData, FinancialData } from '../types'

/** 判断长期趋势 */
export function judgeLongTermTrend(priceHistory: number[], days: number): string {
  if (priceHistory.length === 0 || days < V6_CALCULATOR_THRESHOLDS.L0_TREND_MIN_DAYS) return '无数据'
  if (priceHistory.length < days) return '无数据'
  const slice = priceHistory.slice(-days)
  const first = safeFirst(slice)
  const last = safeLast(slice)
  if (first !== undefined && last !== undefined && last > first * V6_CALCULATOR_THRESHOLDS.L0_TREND_RISE_MULTIPLIER) return '上升'
  if (first !== undefined && last !== undefined && last < first * V6_CALCULATOR_THRESHOLDS.L0_TREND_FALL_MULTIPLIER) return '下降'
  return '横盘'
}

/** 长期趋势评分 */
export function scoreLongTermTrend(input: LayerInput): number {
  const { quotes } = input
  const history = quotes.history ?? []
  const days = history.length
  const trend = judgeLongTermTrend(history, days)

  const TREND_SCORES: Record<string, number> = {
    上升: V6_CALCULATOR_THRESHOLDS.L0_TREND_UP_SCORE,
    横盘: V6_CALCULATOR_THRESHOLDS.L0_TREND_SIDEWAYS_SCORE,
    下降: V6_CALCULATOR_THRESHOLDS.L0_TREND_DOWN_SCORE,
    无数据: 0,
  }

  if (trend === '无数据') return 0
  const score = TREND_SCORES[trend] ?? V6_CALCULATOR_THRESHOLDS.L0_TREND_BASELINE_SCORE

  // 日线连续3天同向且>=3% 额外加分/减分
  if (history.length >= 3) {
    const last3 = history.slice(-3)
    const v0 = safeArrayGet(last3, 0, 1)
    const v1 = safeArrayGet(last3, 1, 1)
    const v2 = safeArrayGet(last3, 2, 1)
    const d1 = (v1 - v0) / v0
    const d2 = (v2 - v1) / v1
    if (d1 >= V6_CALCULATOR_THRESHOLDS.L0_TREND_ACCELERATION && d2 >= V6_CALCULATOR_THRESHOLDS.L0_TREND_ACCELERATION) {
      return Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(V6_CALCULATOR_THRESHOLDS.SCORE_MIN, score + V6_CALCULATOR_THRESHOLDS.L0_TREND_ACCELERATION_DELTA))
    }
    if (d1 <= -V6_CALCULATOR_THRESHOLDS.L0_TREND_ACCELERATION && d2 <= -V6_CALCULATOR_THRESHOLDS.L0_TREND_ACCELERATION) {
      return Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(V6_CALCULATOR_THRESHOLDS.SCORE_MIN, score - V6_CALCULATOR_THRESHOLDS.L0_TREND_ACCELERATION_DELTA))
    }
  }

  return Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(V6_CALCULATOR_THRESHOLDS.SCORE_MIN, score))
}

/** 构建评分板（10项指标，每项1-5分） */
export function buildScoreBoard(stock: StockBasicData, financials: FinancialData): Record<string, number> {
  const board: Record<string, number> = {}

  board['ROE'] = stock.roe !== undefined && stock.roe > 0 ? Math.min(5, Math.max(1, stock.roe / 0.05)) : 3
  board['PE'] = stock.pe !== undefined && stock.pe > 0 ? (stock.pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_LOW ? 5 : stock.pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_MEDIUM ? 3 : 1) : 3
  board['PB'] = stock.pb !== undefined && stock.pb > 0 ? (stock.pb < V6_CALCULATOR_THRESHOLDS.PB_TIER1 ? 5 : stock.pb < V6_CALCULATOR_THRESHOLDS.PB_TIER2 ? 3 : 1) : 3
  board['营收增速'] = financials.revenueYoY !== undefined ? Math.min(5, Math.max(1, 2 + financials.revenueYoY * 10)) : 3
  board['净利增速'] = financials.netProfitYoY !== undefined ? Math.min(5, Math.max(1, 2 + financials.netProfitYoY * 10)) : 3
  board['毛利率'] = financials.grossMargin !== undefined ? Math.min(5, Math.max(1, financials.grossMargin * 10)) : 3
  board['净利率'] = financials.netMargin !== undefined ? Math.min(5, Math.max(1, financials.netMargin * 20)) : 3
  board['现金流'] = financials.operatingCF !== undefined ? (financials.operatingCF > 0 ? 4 : 2) : 3
  board['负债率'] = financials.interestBearingDebt !== undefined && financials.netAssets !== undefined && financials.netAssets > 0
    ? (financials.interestBearingDebt / financials.netAssets < 0.5 ? 4 : 2) : 3
  board['研发占比'] = financials.rdRatio !== undefined ? Math.min(5, Math.max(1, financials.rdRatio * 50)) : 3

  return board
}

/** 评分板打分 */
export function scoreScoreBoard(board: Record<string, number>, filters?: string[]): number {
  if (filters?.length === 0) return 0
  const keys = filters !== undefined && filters.length > 0
    ? Object.keys(board).filter(k => filters.includes(k))
    : Object.keys(board)
  if (keys.length === 0) return 0
  const missingBoardKeys = keys.filter((k) => board[k] == null)
  if (missingBoardKeys.length > 0) {
    logger.warn('[l0_l1_l2] 评分板字段缺失，使用默认值', { field: missingBoardKeys.join(','), context: 'scoreScoreBoard' })
  }
  const sum = keys.reduce((s, k) => s + (board[k] ?? 0), 0)
  return Math.min(5, Math.max(1, sum / keys.length))
}

/** 估值判断 */
export function judgeValuation(
  pe: number | undefined,
  revenueYoY: number | undefined,
  netProfitYoY: number | undefined,
  sector?: string,
): string {
  if (pe === undefined) return '无PE'
  if (pe < 0) return '亏损'

  const sectorLower = sector?.toLowerCase() ?? ''
  const isChip = sectorLower !== ''
    ? sectorLower.includes('芯片') || sectorLower.includes('半导体')
    : false

  const highGrowth = (revenueYoY !== undefined && revenueYoY > 0.5) ||
                     (netProfitYoY !== undefined && netProfitYoY > 0.5)

  if (isChip) {
    if (pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_MEDIUM && highGrowth) return '低估'
    if (pe < V6_CALCULATOR_THRESHOLDS.PE_TIER_CHIP2) return '合理'
    if (pe < V6_CALCULATOR_THRESHOLDS.PE_TIER_CHIP3) return '高估'
    return '极高'
  }

  if (pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_LOW && highGrowth) return '低估'
  if (pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_MEDIUM) return '合理'
  if (pe < V6_CALCULATOR_THRESHOLDS.PE_TIER_GENERAL3) return '高估'
  return '极高'
}

/** 估值评分 */
export function scoreValuation(input: LayerInput): number {
  const { stock, financials } = input
  const judgement = judgeValuation(stock.pe, financials.revenueYoY, financials.netProfitYoY, stock.sector)

  switch (judgement) {
    case '低估': return 5
    case '合理': return 3.5
    case '高估': return 2
    case '极高': return 1
    case '亏损': return 1.5
    case '无PE': return 0
    default: return 3
  }
}

/**
 * L3a 财务健康计算器
 * 
 * 五维度财务因子：
 * - 营收增长（营收 YoY）
 * - 盈利能力（净利率/净利润）
 * - 现金流质量（经营现金流/净利润）
 * - 订单覆盖（在手订单/营收）
 * 
 * 权重：10%
 * 类型：确定性层（程序直算）
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-053, V9-DOC-PROJ-113, V9-DOC-PROJ-066, V9-DOC-FRONT-012]
*/

import { getLogger } from '@/lib/logger'
import type { LayerInput, LayerScore, LayerCalculator, RiskWarningResult, IPCResult } from '../../types'
import { LAYER_LABELS } from '../../types'
import { V6_CALCULATOR_THRESHOLDS } from '@/config/thresholds'
import { RISK_WARNINGS, IPC_CONFIG } from '../../config'
import { safeArrayGet } from '@/lib/precision'
import { clamp, type FinancialDimensionScore } from './utils'

const logger = getLogger()

interface ScoreTier {
  threshold: number
  score: number
}

function scoreByTiers(value: number | undefined, defaultScore: number, tiers: ScoreTier[]): number {
  if (value === undefined) return defaultScore
  return tiers.find((tier) => value > tier.threshold)?.score ?? defaultScore
}

function scoreCashFlow(f: LayerInput['financials']): number {
  if (f.operatingCF !== undefined && f.netProfit !== undefined && f.netProfit > 0) {
    const ratio = f.operatingCF / f.netProfit
    return scoreByTiers(ratio, 2, [
      { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_CASH_FLOW_RATIO_TIER1, score: 5 },
      { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_CASH_FLOW_RATIO_TIER2, score: 4 },
      { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_CASH_FLOW_RATIO_TIER3, score: 3 },
      { threshold: Number.NEGATIVE_INFINITY, score: 2 },
    ])
  }
  if (f.operatingCF !== undefined && f.operatingCF < 0) return 1.5
  return 3
}

function scoreOrders(f: LayerInput['financials']): number {
  if (f.ordersInHand !== undefined && f.revenue !== undefined) {
    const ocr = f.ordersInHand / (f.revenue || 1)
    return scoreByTiers(ocr, 2, [
      { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_OCR_TIER1, score: 5 },
      { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_OCR_TIER2, score: 4 },
      { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_OCR_TIER3, score: 3 },
      { threshold: Number.NEGATIVE_INFINITY, score: 2 },
    ])
  }
  if (f.newOrders !== undefined && f.newOrders > 0) return 3.5
  return 3
}

/**
 * 财务多维度评分
 */
function scoreFinancialDimensions(input: LayerInput): FinancialDimensionScore {
  const { financials: f } = input

  const revenueScore = scoreByTiers(f.revenueYoY, 3, [
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_REVENUE_YOY_TIER1, score: 5 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_REVENUE_YOY_TIER2, score: 4 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_REVENUE_YOY_TIER3, score: 3 },
    { threshold: 0, score: 2.5 },
    { threshold: Number.NEGATIVE_INFINITY, score: 2 },
  ])

  const netProfitYoYScore = scoreByTiers(f.netProfitYoY, 3, [
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_NET_PROFIT_YOY_TIER1, score: 5 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_NET_PROFIT_YOY_TIER2, score: 4 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_NET_PROFIT_YOY_TIER3, score: 3 },
    { threshold: 0, score: 2.5 },
    { threshold: Number.NEGATIVE_INFINITY, score: 2 },
  ])

  let profitabilityScore = scoreByTiers(f.netMargin, 3, [
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_NET_MARGIN_TIER1, score: 5 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_NET_MARGIN_TIER2, score: 4 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_NET_MARGIN_TIER3, score: 3 },
    { threshold: 0, score: 2.5 },
    { threshold: Number.NEGATIVE_INFINITY, score: 2 },
  ])
  if (f.netMargin === undefined && f.netProfit !== undefined && f.netProfit < 0) {
    profitabilityScore = 2
  }

  const grossMarginScore = scoreByTiers(f.grossMargin, 3, [
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_GROSS_MARGIN_TIER1, score: 5 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_GROSS_MARGIN_TIER2, score: 4 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_GROSS_MARGIN_TIER3, score: 3 },
    { threshold: 0, score: 2.5 },
    { threshold: Number.NEGATIVE_INFINITY, score: 2 },
  ])

  const rdRatioScore = scoreByTiers(f.rdRatio, 3, [
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_RD_RATIO_TIER1, score: 5 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_RD_RATIO_TIER2, score: 4 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_FINANCE_RD_RATIO_TIER3, score: 3 },
    { threshold: 0, score: 2.5 },
    { threshold: Number.NEGATIVE_INFINITY, score: 2 },
  ])

  // 现金流
  const cashFlowScore = scoreCashFlow(f)

  // 订单
  const ordersScore = scoreOrders(f)

  return {
    revenue: revenueScore,
    netProfitYoY: netProfitYoYScore,
    profitability: profitabilityScore,
    grossMargin: grossMarginScore,
    rdRatio: rdRatioScore,
    cashFlow: cashFlowScore,
    orders: ordersScore,
  }
}

/**
 * 风险预警评估
 */
function evaluateRiskWarnings(input: LayerInput): RiskWarningResult {
  const { financials: f } = input
  const redDetails: string[] = []
  const yellowDetails: string[] = []

  // 红色预警
  // 经营现金流连续两季为负
  if (f.operatingCF !== undefined && f.operatingCF < 0) {
    redDetails.push(safeArrayGet(RISK_WARNINGS.red, 0, ''))
  }

  // 应收账款增速 > 营收增速50%+
  if (f.receivables !== undefined && f.revenue !== undefined && f.revenueYoY !== undefined) {
    const arRatio = f.receivables / (f.revenue || 1)
    if (arRatio > V6_CALCULATOR_THRESHOLDS.L3_RISK_AR_RATIO) {
      redDetails.push(safeArrayGet(RISK_WARNINGS.red, 1, ''))
    }
  }

  // 存货周转天数同比延长 > 30天
  if (f.inventoryTurnoverDays !== undefined && f.inventoryTurnoverDays > V6_CALCULATOR_THRESHOLDS.L3_RISK_INVENTORY_DAYS) {
    redDetails.push(safeArrayGet(RISK_WARNINGS.red, 2, ''))
  }

  // 大股东质押 > 50%
  if (f.shareholderPledge !== undefined && f.shareholderPledge > V6_CALCULATOR_THRESHOLDS.L3_RISK_PLEDGE_RATIO) {
    redDetails.push(safeArrayGet(RISK_WARNINGS.red, 3, ''))
  }

  // 审计非标意见
  const opinion = f.auditOpinion ?? ''
  if (opinion.includes('非标准') || opinion.includes('否定意见') || opinion.includes('无法表示') ||
      (opinion.includes('保留意见') && !opinion.includes('无保留意见'))) {
    redDetails.push(safeArrayGet(RISK_WARNINGS.red, 4, ''))
  }

  // 黄色预警
  // 毛利率连续两季下滑
  if (f.grossMargin !== undefined && f.grossMargin < V6_CALCULATOR_THRESHOLDS.L3_RISK_GROSS_MARGIN_LOW) {
    yellowDetails.push(safeArrayGet(RISK_WARNINGS.yellow, 0, ''))
  }

  // 有息负债增速 > 资产增速
  if (f.interestBearingDebt !== undefined && f.netAssets !== undefined && f.interestBearingDebt > f.netAssets * V6_CALCULATOR_THRESHOLDS.L3_RISK_DEBT_ASSET_RATIO) {
    yellowDetails.push(safeArrayGet(RISK_WARNINGS.yellow, 1, ''))
  }

  // 商誉/净资产 > 30%
  if (f.goodwill !== undefined && f.netAssets !== undefined && f.netAssets > 0) {
    if (f.goodwill / f.netAssets > V6_CALCULATOR_THRESHOLDS.L3_RISK_GOODWILL_NET_ASSETS) {
      yellowDetails.push(safeArrayGet(RISK_WARNINGS.yellow, 2, ''))
    }
  }

  // 客户集中度TOP5 > 50%
  if (f.customerConcentration !== undefined && f.customerConcentration > V6_CALCULATOR_THRESHOLDS.L3_RISK_CUSTOMER_CONCENTRATION) {
    yellowDetails.push(safeArrayGet(RISK_WARNINGS.yellow, 3, ''))
  }

  return {
    redCount: redDetails.length,
    yellowCount: yellowDetails.length,
    redDetails,
    yellowDetails,
  }
}

/**
 * IPC 业绩兑现临界点评估
 */
function evaluateIPC(input: LayerInput, l1Score: number, l2Score: number): IPCResult {
  const { financials: f } = input
  const events = input.zeroToOneEvents ?? []
  const cfg = IPC_CONFIG

  // --- OCR 维度 ---
  let ocrScore = 0
  if (f.ordersInHand !== undefined && f.revenue !== undefined && f.revenue > 0) {
    const ocr = f.ordersInHand / f.revenue
    ocrScore = scoreByTiers(ocr, 1, [
      { threshold: cfg.ocr.superStrong, score: 5 },
      { threshold: cfg.ocr.strong, score: 4 },
      { threshold: cfg.ocr.medium, score: 3 },
      { threshold: cfg.ocr.weak, score: 2 },
    ])
  }

  // --- MCE 维度 ---
  let mceScore = 0
  if (events.length > 0) {
    for (const evt of events) {
      const mce = evt.mce ?? 1
      // 时效性衰减
      const decayTiers = [
        { threshold: V6_CALCULATOR_THRESHOLDS.L3_IPC_MONTHS_DECAY_12M, score: 0 },
        { threshold: V6_CALCULATOR_THRESHOLDS.L3_IPC_MONTHS_DECAY_6M, score: cfg.mce.decay12m },
        { threshold: V6_CALCULATOR_THRESHOLDS.L3_IPC_MONTHS_DECAY_3M, score: cfg.mce.decay6m },
      ]
      const decay = scoreByTiers(evt.monthsAgo, 1.0, decayTiers)

      const rawScore = scoreByTiers(mce, 2, [
        { threshold: cfg.mce.trackLevel, score: 5 },
        { threshold: cfg.mce.categoryLevel, score: 4 },
        { threshold: cfg.mce.segmentLevel, score: 3 },
      ])

      const adjusted = rawScore * decay
      if (adjusted > mceScore) mceScore = adjusted
    }
  }

  // --- TIMS 维度 ---
  const sector = (input.stock.sector ?? '').toLowerCase()
  const isTech = sector.includes('芯片') || sector.includes('半导体') || sector.includes('ai') || sector.includes('科技')

  const timsTiers = [
    { predicate: () => isTech && l1Score >= 4, score: 5 },
    { predicate: () => isTech && l1Score >= 3, score: 4 },
    { predicate: () => l1Score >= 4, score: 4 },
    { predicate: () => l1Score >= 3, score: 3 },
  ]
  let timsScore = timsTiers.find((tier) => tier.predicate())?.score ?? 2

  // L2 竞品压制：竞品得分 ≤ 2.5 → 市占率上限
  if (l2Score <= V6_CALCULATOR_THRESHOLDS.L3_IPC_L2_SUPPRESS_THRESHOLD && timsScore > 3) {
    timsScore = Math.max(3, timsScore - 1)
  }

  // L1 护城河 ≥ 4 → TIMS 技术迭代系数自动 +0.5
  if (l1Score >= V6_CALCULATOR_THRESHOLDS.L3_IPC_L1_MOAT_BOOST_THRESHOLD && timsScore < 5) {
    timsScore += 0.5
  }

  // --- IPC 综合 ---
  const ipcScore = ocrScore * cfg.ipcWeights.ocr + mceScore * cfg.ipcWeights.mce + timsScore * cfg.ipcWeights.tims

  const ipcStages = [
    { threshold: cfg.ipcStages.broken, stage: 'broken' as const, label: '✅ 临界点已突破 — 订单充裕+事件落地+技术转化，业绩加速确认', bonus: 1.0 },
    { threshold: cfg.ipcStages.near, stage: 'near' as const, label: '🔶 临界点附近（最佳击球区） — 2/3维度共振，业绩拐点在未来1-2季', bonus: 0.5 },
    { threshold: cfg.ipcStages.before, stage: 'before' as const, label: '🔸 临界点前夜 — 单一维度发出信号，需等待第二重确认', bonus: 0.0 },
    { threshold: cfg.ipcStages.far, stage: 'far' as const, label: '🔹 临界点遥远 — 各维度暂无明显信号，业绩兑现路径模糊', bonus: -0.5 },
  ]
  const matchedStage = ipcStages.find((s) => ipcScore >= s.threshold)
  const stage = matchedStage?.stage ?? 'none'
  const stageLabel = matchedStage?.label ?? '⬜ 未到临界点 — 无订单、无事件、无技术优势'
  const l3Bonus = matchedStage?.bonus ?? -1.0

  return {
    ocrScore: Math.round(ocrScore * 100) / 100,
    mceScore: Math.round(mceScore * 100) / 100,
    timsScore: Math.round(timsScore * 100) / 100,
    ipcScore: Math.round(ipcScore * 100) / 100,
    stage,
    stageLabel,
    l3Bonus,
  }
}

/**
 * L3a 财务健康计算器
 */
export const L3aFinancialCalculator: LayerCalculator = {
  layerId: 'l3f' as const,

  async calculate(input: LayerInput): Promise<LayerScore> {
    const { stock, config } = input
    const weight = config.weights.l3f
    const risks: string[] = []
    const evidence: string[] = []

    try {
      // 1. 多维度评分（7维度）
      const dims = scoreFinancialDimensions(input)
      const baseScore = (dims.revenue + dims.netProfitYoY + dims.profitability + dims.grossMargin + dims.rdRatio + dims.cashFlow + dims.orders) / 7

      evidence.push(
        `营收增长: ${dims.revenue}/5`,
        `净利润增速: ${dims.netProfitYoY}/5`,
        `盈利: ${dims.profitability}/5`,
        `毛利率: ${dims.grossMargin}/5`,
        `研发强度: ${dims.rdRatio}/5`,
        `现金流: ${dims.cashFlow}/5`,
        `订单: ${dims.orders}/5`,
      )

      // 2. 风险预警
      const riskResult = evaluateRiskWarnings(input)
      const riskPenalty = riskResult.redCount * V6_CALCULATOR_THRESHOLDS.L3_FINANCE_RISK_RED_PENALTY + riskResult.yellowCount * V6_CALCULATOR_THRESHOLDS.L3_FINANCE_RISK_YELLOW_PENALTY
      risks.push(...riskResult.redDetails.map((r: string) => `[红色预警] ${r}`))
      risks.push(...riskResult.yellowDetails.map((r: string) => `[黄色预警] ${r}`))

      // 3. IPC 临界点（P0 修复：使用真实 L1/L2 得分，缺失时降级为 3）
      const l1Score = input.peerScores?.l1 ?? 3
      const l2Score = input.peerScores?.l2 ?? 3
      const ipc = evaluateIPC(input, l1Score, l2Score)

      // 最终得分
      const score = clamp(baseScore - riskPenalty + ipc.l3Bonus)

      logger.info(`[L3a] ${stock.symbol}: base=${baseScore.toFixed(2)}, risk=${riskPenalty.toFixed(2)}, ipc=${ipc.ipcScore.toFixed(2)}(+${ipc.l3Bonus}), score=${score.toFixed(2)}`)

      const summaryParts: string[] = [
        `财务五维均值 ${baseScore.toFixed(1)}/5`,
        riskResult.redCount > 0 ? `红色预警 ${riskResult.redCount} 项` : '',
        riskResult.yellowCount > 0 ? `黄色预警 ${riskResult.yellowCount} 项` : '',
        ipc.stage !== 'none' ? `${ipc.stageLabel}` : '',
      ]
      const summary = summaryParts.filter(Boolean).join(' | ')

      if (ipc.stage !== 'none') {
        evidence.push(`IPC: OCR=${ipc.ocrScore}, MCE=${ipc.mceScore}, TIMS=${ipc.timsScore}, IPC=${ipc.ipcScore}, 阶段=${ipc.stage}`)
      }

      // 判断该层是否真实参与：至少存在一项核心财务字段
      const hasFinancialData = [
        input.financials.revenue,
        input.financials.netProfit,
        input.financials.grossMargin,
        input.financials.operatingCF,
      ].some((v) => v !== undefined && Number.isFinite(v))

      return {
        layerId: 'l3f',
        layerName: LAYER_LABELS.l3f ?? 'L3a 财务健康',
        score: Math.round(score * 100) / 100,
        summary,
        risks,
        evidence,
        weight,
        weightedScore: score * weight,
        dataSources: ['财报API', '行情数据', '公司公告'],
        participated: hasFinancialData,
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      logger.error(`[L3a] ${stock.symbol}: 计算失败: ${msg}`)
      return {
        layerId: 'l3f',
        layerName: LAYER_LABELS.l3f ?? 'L3a 财务健康',
        score: Number.NaN,
        summary: `财务评分计算失败: ${msg}`,
        risks: [],
        evidence: [],
        weight,
        weightedScore: Number.NaN,
        dataSources: [],
        participated: false,
      }
    }
  }
}

/**
 * L3v 估值水平计算器
 * 
 * 行业基准校准估值：
 * - PEG 评分（优先）
 * - PE 评分（PEG 缺失时）
 * - 行业基准校准
 * 
 * 权重：8%
 * 类型：确定性层（程序直算）
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-053, V9-DOC-PROJ-113, V9-DOC-PROJ-066, V9-DOC-FRONT-012]
*/

import { getLogger } from '@/lib/logger'
import type { LayerInput, LayerScore, LayerCalculator } from '../../types'
import { LAYER_LABELS } from '../../types'
import { V6_CALCULATOR_THRESHOLDS } from '@/config/thresholds'
import { matchIndustryBenchmark, clamp } from './utils'

const logger = getLogger()

function scorePeg(peg: number): number {
  const PEG_TIERS = [
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PEG_TIER1, score: 5 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PEG_TIER2, score: 4 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PEG_TIER3, score: 3 },
    { threshold: V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PEG_TIER4, score: 2.5 },
  ]
  const matched = PEG_TIERS.find((t) => peg < t.threshold)
  return matched?.score ?? 2
}

function scorePeRelative(pe: number, benchmark: { peLow: number; peHigh: number } | null): number {
  if (benchmark) {
    if (pe < benchmark.peLow) return 4.5
    if (pe < benchmark.peHigh) return 3.5
    return 2.5
  }
  if (pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_LOW) return 4.5
  if (pe < V6_CALCULATOR_THRESHOLDS.L3_VALUATION_PE_MEDIUM) return 3.5
  return 2.5
}

/**
 * 估值评分
 */
function scoreValuation(input: LayerInput): { score: number; summary: string; evidence: string[] } {
  const { stock } = input
  const evidence: string[] = []
  const benchmark = matchIndustryBenchmark(stock.sector)

  let pegScore = 3 // 默认合理

  if (stock.peg !== undefined && stock.peg > 0) {
    pegScore = scorePeg(stock.peg)
    evidence.push(`PEG=${stock.peg.toFixed(2)}`)
  } else if (stock.pe !== undefined && stock.pe > 0) {
    // PEG 缺失时用 PE 做粗略判断
    pegScore = scorePeRelative(stock.pe, benchmark)
    evidence.push(`PE=${stock.pe.toFixed(1)}`)
  }

  // 行业基准校准
  let industryAdjust = 0
  if (benchmark && stock.pe !== undefined && stock.pe > 0) {
    if (stock.pe < benchmark.peLow) {
      industryAdjust = V6_CALCULATOR_THRESHOLDS.L3_VALUATION_INDUSTRY_ADJUST // 低于行业区间下限 → 低估
      evidence.push(`PE ${stock.pe.toFixed(1)} < 行业下限 ${benchmark.peLow}x → 低估 +0.5`)
    } else if (stock.pe > benchmark.peHigh) {
      industryAdjust = -V6_CALCULATOR_THRESHOLDS.L3_VALUATION_INDUSTRY_ADJUST // 高于行业区间上限 → 高估
      evidence.push(`PE ${stock.pe.toFixed(1)} > 行业上限 ${benchmark.peHigh}x → 高估 -0.5`)
    } else {
      evidence.push(`PE ${stock.pe.toFixed(1)} 在行业区间 ${benchmark.peLow}-${benchmark.peHigh}x 内`)
    }
    evidence.push(`行业基准: ${benchmark.sector} PEG ${benchmark.peglow}-${benchmark.pegHigh}`)
  }

  const score = clamp(pegScore + industryAdjust)
  const summary = benchmark
    ? `${benchmark.sector}行业基准校准 | PEG ${score >= 4 ? '低估' : score >= 3 ? '合理' : '高估'}`
    : `PEG 评分 ${score >= 4 ? '低估' : score >= 3 ? '合理' : '高估'}`

  return { score, summary, evidence }
}

/**
 * L3v 估值水平计算器
 */
export const L3vValuationCalculator: LayerCalculator = {
  layerId: 'l3v' as const,

  async calculate(input: LayerInput): Promise<LayerScore> {
