      const hasValuationData = (stock.pe !== undefined && stock.pe > 0) || (stock.peg !== undefined && stock.peg > 0)

      return {
        layerId: 'l3v',
        layerName: LAYER_LABELS.l3v ?? 'L3b 估值水平',
