/**
 * 旧版匹配函数（保留用于向后兼容）
 */
export function matchIndustry(symbol: string, sector = '', name = ''): { sectorName: string; relevance: number } | null {
  const coreMatch = CORE_STOCK_MAP[symbol]
  if (coreMatch) return { sectorName: coreMatch.sector, relevance: coreMatch.relevance }

  const searchText = `${sector} ${name}`.toLowerCase()
  for (const entry of KEYWORD_SECTOR_MAP) {
    if (entry.keywords.some((kw) => searchText.includes(kw.toLowerCase()))) {
      return { sectorName: entry.sector, relevance: entry.relevance }
    }
  }

  return null
}

/**
 * 计算 SKILL-N 额外加分
 */
export function calcSkillNBonus(allocationBias: string): number {
  if (allocationBias.includes('极度超配')) return 0.30
  if (allocationBias.includes('超配')) return 0.15
  return 0.00
}

/**
 * 获取 V4 评级标签
 */
function getV4Rating(score: number): string {
  if (score >= 4.2) return 'S级'
  if (score >= 3.6) return 'A级'
  if (score >= 3.0) return 'B+级'
  if (score >= 2.4) return 'B级'
  if (score >= 1.8) return 'C级'
  return 'D级'
}

/**
 * 获取配置建议
 */
function getAllocationAdvice(score: number): string {
  if (score >= 4.2) return '超配'
  if (score >= 3.6) return '标配偏多'
  if (score >= 3.0) return '标配'
  if (score >= 2.4) return '标配偏空'
  return '低配'
}

/**
 * LMinus1Calculator
 *
 * v2.9.0 支持三级行业分类和 V4 维度分析
 */
export const LMinus1Calculator: LayerCalculator & {
  matchIndustry: typeof matchIndustry
  calcSkillNBonus: typeof calcSkillNBonus
} = {
  layerId: 'lMinus1',

  async calculate(input: LayerInput): Promise<LayerScore> {
    const { stock, industryScore, config } = input
    const weight = config.weights.lMinus1

    // 优先级 1：外部已传入 V4 行业分析数据
    const v4Analysis = (input as LayerInput & { industryV4Analysis?: IndustryV4Analysis }).industryV4Analysis
    if (v4Analysis && v4Analysis.v4Composite !== null) {
      const v4Score = v4Analysis.v4Composite
      const rating = getV4Rating(v4Score)
      const advice = getAllocationAdvice(v4Score)
      const bonus = calcSkillNBonus(advice)
      const finalScore = Math.min(5, v4Score + bonus)

      const tierLabel = v4Analysis.tier === 'tier3' ? '三级' : v4Analysis.tier === 'tier2' ? '二级' : '一级'

      logger.info(`[L-1] ${stock.symbol}: V4行业分析, score=${finalScore.toFixed(2)}`)

      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: Math.round(finalScore * 100) / 100,
        summary: `${v4Analysis.industryName}(${tierLabel}) | V4综合分 ${v4Score.toFixed(2)} | ${rating} | ${advice}`,
        risks: v4Analysis.dataCompleteness < 0.5 ? ['行业数据完整度较低，评分参考性有限'] : [],
        evidence: [
          `V4综合分: ${v4Score.toFixed(2)}/5 (${rating})`,
          `景气度: ${v4Analysis.dimensions.prosperity.score?.toFixed(1) ?? 'N/A'}`,
          `竞争格局: ${v4Analysis.dimensions.competition.score?.toFixed(1) ?? 'N/A'}`,
          `政策环境: ${v4Analysis.dimensions.policy.score?.toFixed(1) ?? 'N/A'}`,
          `技术成熟度: ${v4Analysis.dimensions.technology.score?.toFixed(1) ?? 'N/A'}`,
          `成分股: ${v4Analysis.constituentCount}只`,
          `配置建议: ${advice}`,
        ],
        weight,
        weightedScore: finalScore * weight,
        dataSources: ['V4 行业分析', '个股数据聚合'],
        participated: true,
      }
    }

    // 优先级 2：外部已传入行业评分数据
    if (industryScore) {
      const bonus = LMinus1Calculator.calcSkillNBonus(industryScore.allocationBias ?? '')
      const score = Math.min(5, industryScore.skillCScore * industryScore.relevance + bonus)

      logger.info(`[L-1] ${stock.symbol}: 外部行业评分, score=${score.toFixed(2)}`)

      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: Math.round(score * 100) / 100,
        summary: `${industryScore.sectorName} | SKILL-C ${industryScore.skillCRating}(${industryScore.skillCScore}) | SKILL-N ${industryScore.skillNScore} | 关联度 ${industryScore.relevance}`,
        risks: [],
        evidence: [
          `SKILL-C: ${industryScore.skillCRating}(${industryScore.skillCScore})`,
          `SKILL-N: ${industryScore.skillNScore}`,
          `关联度: ${industryScore.relevance}`,
        ],
        weight,
        weightedScore: score * weight,
        dataSources: ['行业 SKILL 分析报告'],
        participated: true,
      }
    }

    // 优先级 3：旧版速查表匹配（已验证的硬编码评分）
    const matched = LMinus1Calculator.matchIndustry(stock.symbol, stock.sector, stock.name)

    if (matched) {
      // 尝试匹配三级行业分类，用于补充行业路径信息
      let industryPathInfo = ''
      const industryMatch = matchStockIndustry({
        name: stock.name,
        sector: stock.sector,
      })
      if (industryMatch.tier3 || industryMatch.tier2) {
        const path = getIndustryPath((industryMatch.tier3 ?? industryMatch.tier2)!.code)
        industryPathInfo = path.map((p) => p.name).join(' → ') + ' | '
      }

      const sectorData = INDUSTRY_SCORES[matched.sectorName]
      if (!sectorData) {
        logger.warn(`[L-1] ${stock.symbol}: 匹配到行业 ${matched.sectorName} 但无评分数据`)
        return {
          layerId: 'lMinus1' as LayerId,
          layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
          score: Number.NaN,
          summary: `匹配到行业 ${matched.sectorName} 但无评分数据，L-1不纳入`,
          risks: [],
          evidence: [],
          weight,
          weightedScore: Number.NaN,
          dataSources: [],
          participated: false,
        }
      }

      const bonus = LMinus1Calculator.calcSkillNBonus(sectorData.allocationBias ?? '')
      const score = Math.min(5, sectorData.skillC * matched.relevance + bonus)

      logger.info(`[L-1] ${stock.symbol}: 速查表匹配 ${matched.sectorName}, score=${score.toFixed(2)}`)

      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: Math.round(score * 100) / 100,
        summary: `${industryPathInfo}${matched.sectorName} | SKILL-C ${sectorData.skillCRating}(${sectorData.skillC}) | SKILL-N ${sectorData.skillN} | 关联度 ${matched.relevance}`,
        risks: [],
        evidence: [
          `SKILL-C: ${sectorData.skillCRating}(${sectorData.skillC})`,
          `SKILL-N: ${sectorData.skillN}`,
          `关联度: ${matched.relevance}`,
        ],
        weight,
        weightedScore: score * weight,
        dataSources: ['行业 SKILL 分析速查表'],
        participated: true,
      }
    }

    // 优先级 4：三级行业分类启发式估算（最细粒度降级方案）
    const industryMatch = matchStockIndustry({
      name: stock.name,
      sector: stock.sector,
    })

    if (industryMatch.tier3 || industryMatch.tier2 || industryMatch.tier1) {
      const matchedIndustry = industryMatch.tier3 ?? industryMatch.tier2 ?? industryMatch.tier1!
      const path = getIndustryPath(matchedIndustry.code)
      const pathNames = path.map((p) => p.name).join(' → ')

      let baseScore = 3.0
      let relevance = 0.7

      if (industryMatch.tier3) {
        relevance = 0.9
        baseScore = 3.2
      } else if (industryMatch.tier2) {
        relevance = 0.8
        baseScore = 3.0
      } else {
        relevance = 0.6
        baseScore = 2.8
      }

      const { financials } = input
      if (financials.revenueYoY !== undefined && financials.revenueYoY > 20) {
        baseScore += 0.3
      }
      if (financials.rdRatio !== undefined && financials.rdRatio > 0.1) {
        baseScore += 0.2
      }
      if (financials.grossMargin !== undefined && financials.grossMargin > 0.4) {
        baseScore += 0.2
      }

      baseScore = Math.max(1, Math.min(5, baseScore))
      const finalScore = baseScore * relevance
      const rating = getV4Rating(finalScore)
      const advice = getAllocationAdvice(finalScore)

      logger.info(`[L-1] ${stock.symbol}: 三级行业估算 ${matchedIndustry.name}, score=${finalScore.toFixed(2)}`)

      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: Math.round(finalScore * 100) / 100,
        summary: `${pathNames} | 匹配度 ${(relevance * 100).toFixed(0)}% | 估算分 ${finalScore.toFixed(2)} | ${rating}`,
        risks: [
          '行业评分为基于分类的启发式估算，非完整V4分析',
          '建议补充行业数据采集以获得更准确评分',
        ],
        evidence: [
          `行业路径: ${pathNames}`,
          `匹配度: ${(relevance * 100).toFixed(0)}%`,
          `估算分: ${finalScore.toFixed(2)}/5 (${rating})`,
          `配置建议: ${advice}`,
          `数据来源: 三级行业分类体系`,
        ],
        weight,
        weightedScore: finalScore * weight,
        dataSources: ['三级行业分类体系', '个股财务数据'],
        participated: true,
      }
    }

    // 未匹配到任何行业
    logger.info(`[L-1] ${stock.symbol}: 未匹配到行业评分覆盖范围，L-1不纳入`)

    return {
      layerId: 'lMinus1' as LayerId,
      layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
      score: Number.NaN,
      summary: '未匹配到行业评分覆盖范围，L-1不纳入综合评分',
      risks: [],
      evidence: [],
      weight,
      weightedScore: Number.NaN,
      dataSources: [],
      participated: false,
    }
  },

  matchIndustry,
  calcSkillNBonus,
}

/**
 * @module crossValidator
 * @description V6 评分引擎交叉验证规则引擎。
 *
 * 检测多维度评分之间的矛盾与不一致，防止"数据好看但逻辑冲突"的评分误导决策。
 * 纯规则引擎，零 LLM 依赖，完全离线运行。
 *
 * 验证规则（可配置阈值）：
 * 1. 财务好但估值高（L3f 高分 + L3v 低分）→ 矛盾
 * 2. 增长好但财务差（L7 高分 + L3f 低分）→ 矛盾
 * 3. Hype 泡沫期 + 情景积极（L6 泡沫/纯概念 + L4 高分）→ 高风险组合
 * 4. 综合分高但覆盖率低（score ≥ 4.0 + coverageRate ≤ 0.5）→ 低置信度
 * 5. 行业评分与个股评分严重背离（L-1 与综合分差 > 2.0）→ 背离
 *
 * @see src/services/scoring/v6-engine/engine.ts - aggregate() 中调用
  * @doc [V9-DOC-ARCH-008, V9-DOC-PROJ-053, V9-DOC-PROJ-113, V9-DOC-PROJ-066, V9-DOC-FRONT-012]
*/

import type { CompositeScore, LayerId } from './types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

/** 验证告警级别 */
export type ValidationSeverity = 'info' | 'warning' | 'critical'

/** 单条交叉验证结果 */
export interface CrossValidationIssue {
  /** 规则 ID */
  ruleId: string
  /** 告警级别 */
  severity: ValidationSeverity
  /** 告警标题 */
  title: string
  /** 详细说明 */
  description: string
  /** 涉及的层 */
  layers: LayerId[]
  /** 相关分值（用于调试） */
  scores: Record<string, number | string>
}

/** 交叉验证总结果 */
export interface CrossValidationResult {
  /** 是否通过（无任何 critical） */
  passed: boolean
  /** 所有检测到的 issue */
  issues: CrossValidationIssue[]
  /** 告警统计 */
  summary: {
    critical: number
    warning: number
    info: number
  }
}

/** 可配置的验证阈值 */
export interface CrossValidatorConfig {
  /** 财务好但估值高：L3f ≥ 此值且 L3v ≤ 此值为矛盾 */
  financialGoodValuationHigh: { l3fMin: number; l3vMax: number }
  /** 增长好但财务差：L7 ≥ 此值且 L3f ≤ 此值为矛盾 */
  growthGoodFinancialBad: { l7Min: number; l3fMax: number }
  /** Hype 泡沫 + 情景积极：L6 关键词 + L4 ≥ 此值为高风险 */
  hypeBubbleScenarioPositive: { l4Min: number; l6Keywords: string[] }
  /** 综合分高但覆盖率低 */
  highScoreLowCoverage: { scoreMin: number; coverageRateMax: number }
  /** 行业与个股背离 */
  industryDivergence: { maxDiff: number }
}

// ============================================================
// 默认配置
// ============================================================

/**
 * DEFAULT_CROSS_VALIDATOR_CONFIG
 */
export const DEFAULT_CROSS_VALIDATOR_CONFIG: CrossValidatorConfig = {
  financialGoodValuationHigh: { l3fMin: 4.0, l3vMax: 2.5 },
  growthGoodFinancialBad: { l7Min: 4.0, l3fMax: 2.5 },
  hypeBubbleScenarioPositive: {
    l4Min: 4.0,
    l6Keywords: ['泡沫', '纯概念', '期望膨胀期（纯概念）'],
  },
  highScoreLowCoverage: { scoreMin: 4.0, coverageRateMax: 0.5 },
  industryDivergence: { maxDiff: 2.0 },
}

// ============================================================
// 规则引擎
// ============================================================

function getLayerScore(composite: CompositeScore, layerId: LayerId): number | undefined {
  const layer = composite.layers[layerId]
  if (!layer) return undefined
  return Number.isFinite(layer.score) ? layer.score : undefined
}

function getLayerSummary(composite: CompositeScore, layerId: LayerId): string {
  return composite.layers[layerId]?.summary ?? ''
}

/** 规则 1：财务好但估值高 */
function checkFinancialGoodValuationHigh(
  composite: CompositeScore,
  config: CrossValidatorConfig,
): CrossValidationIssue | undefined {
  const l3f = getLayerScore(composite, 'l3f')
  const l3v = getLayerScore(composite, 'l3v')
  const { l3fMin, l3vMax } = config.financialGoodValuationHigh

  if (l3f !== undefined && l3v !== undefined && l3f >= l3fMin && l3v <= l3vMax) {
    return {
      ruleId: 'R001',
      severity: 'warning',
      title: '财务健康但估值偏高',
      description: `L3a 财务健康评分 ${l3f.toFixed(2)}（优秀），但 L3b 估值水平 ${l3v.toFixed(2)}（偏高），存在"财务好但买贵了"的矛盾风险。建议重新审视估值安全边际。`,
      layers: ['l3f', 'l3v'],
      scores: { l3f, l3v, thresholdL3f: l3fMin, thresholdL3v: l3vMax },
    }
  }
  return undefined
}

/** 规则 2：增长好但财务差 */
function checkGrowthGoodFinancialBad(
  composite: CompositeScore,
  config: CrossValidatorConfig,
): CrossValidationIssue | undefined {
  const l7 = getLayerScore(composite, 'l7')
  const l3f = getLayerScore(composite, 'l3f')
  const { l7Min, l3fMax } = config.growthGoodFinancialBad

  if (l7 !== undefined && l3f !== undefined && l7 >= l7Min && l3f <= l3fMax) {
    return {
      ruleId: 'R002',
      severity: 'critical',
      title: '第二曲线强但财务差',
      description: `L7 第二曲线评分 ${l7.toFixed(2)}（强催化），但 L3a 财务健康 ${l3f.toFixed(2)}（差），存在"增长故事好但基本面不支撑"的高风险矛盾。可能存在财务造假或激进会计。`,
      layers: ['l7', 'l3f'],
      scores: { l7, l3f, thresholdL7: l7Min, thresholdL3f: l3fMax },
    }
  }
  return undefined
}

/** 规则 3：Hype 泡沫期 + 情景积极 */
function checkHypeBubbleScenarioPositive(
  composite: CompositeScore,
  config: CrossValidatorConfig,
): CrossValidationIssue | undefined {
  const l4 = getLayerScore(composite, 'l4')
  const l6Summary = getLayerSummary(composite, 'l6')
  const { l4Min, l6Keywords } = config.hypeBubbleScenarioPositive

  const isHypeBubble = l6Summary && l6Keywords.some((kw) => l6Summary.includes(kw))

  if (l4 !== undefined && isHypeBubble && l4 >= l4Min) {
    return {
      ruleId: 'R003',
      severity: 'critical',
      title: 'Hype 泡沫期 + 情景乐观',
      description: `L6 处于 Hype 泡沫期（${l6Summary}），但 L4 情景推演 ${l4.toFixed(2)}（乐观），存在"概念炒作 + 乐观预期"的高风险组合。建议回避或极小仓位。`,
      layers: ['l4', 'l6'],
      scores: { l4, l6Summary, thresholdL4: l4Min },
    }
  }
  return undefined
}

/** 规则 4：综合分高但覆盖率低 */
function checkHighScoreLowCoverage(
  composite: CompositeScore,
  config: CrossValidatorConfig,
): CrossValidationIssue | undefined {
  const { scoreMin, coverageRateMax } = config.highScoreLowCoverage
  const score = composite.score
  const coverageRate = composite.coverageRate ?? 1

  if (Number.isFinite(score) && score >= scoreMin && coverageRate <= coverageRateMax) {
    return {
      ruleId: 'R004',
      severity: 'warning',
      title: '高分但数据覆盖不足',
      description: `综合评分 ${score.toFixed(2)}（高），但数据覆盖率仅 ${(coverageRate * 100).toFixed(0)}%（低于 ${(coverageRateMax * 100).toFixed(0)}%），高分可能由"幸存者偏差"导致（缺失层多为低分层）。建议补充数据后重评。`,
      layers: ALL_LAYERS,
      scores: { score, coverageRate, thresholdScore: scoreMin, thresholdCoverage: coverageRateMax },
    }
  }
  return undefined
}

/** 规则 5：行业评分与个股评分严重背离 */
function checkIndustryDivergence(
  composite: CompositeScore,
  config: CrossValidatorConfig,
): CrossValidationIssue | undefined {
  const lMinus1 = getLayerScore(composite, 'lMinus1')
  const score = composite.score
  const { maxDiff } = config.industryDivergence

  if (lMinus1 !== undefined && Number.isFinite(score)) {
    const diff = Math.abs(lMinus1 - score)
    if (diff > maxDiff) {
      return {
        ruleId: 'R005',
        severity: 'info',
        title: '行业评分与个股评分背离',
        description: `L-1 行业评分 ${lMinus1.toFixed(2)} 与综合评分 ${score.toFixed(2)} 差距 ${diff.toFixed(2)}（阈值 ${maxDiff}），存在行业与个股表现背离。${lMinus1 > score ? '个股跑输行业，需排查个股特有风险。' : '个股跑赢行业，需确认是否有 alpha 来源。'}`,
        layers: ['lMinus1'],
        scores: { lMinus1, compositeScore: score, diff, threshold: maxDiff },
      }
    }
  }
  return undefined
}

// ============================================================
// 入口
// ============================================================

const ALL_LAYERS: LayerId[] = [
  'lMinus1', 'l0', 'l1', 'l2', 'l3f', 'l3v', 'l4', 'l5', 'l6', 'l7', 'l8',
]

/**
 * 对 CompositeScore 执行交叉验证。
 *
 * @param composite - V6 综合评分结果
 * @param config - 验证阈值配置（可选，默认使用 DEFAULT_CROSS_VALIDATOR_CONFIG）
 * @returns 验证结果
 */
export function crossValidate(
  composite: CompositeScore,
  config: CrossValidatorConfig = DEFAULT_CROSS_VALIDATOR_CONFIG,
): CrossValidationResult {
  const issues: CrossValidationIssue[] = []

  const checks = [
    checkFinancialGoodValuationHigh(composite, config),
    checkGrowthGoodFinancialBad(composite, config),
    checkHypeBubbleScenarioPositive(composite, config),
    checkHighScoreLowCoverage(composite, config),
    checkIndustryDivergence(composite, config),
  ]

  for (const issue of checks) {
    if (issue) issues.push(issue)
  }

  const summary = {
    critical: issues.filter((i) => i.severity === 'critical').length,
    warning: issues.filter((i) => i.severity === 'warning').length,
    info: issues.filter((i) => i.severity === 'info').length,
  }

  const passed = summary.critical === 0

  if (issues.length > 0) {
    logger.warn(`[CrossValidator] 检测到 ${issues.length} 项交叉验证问题`, {
      critical: summary.critical,
      warning: summary.warning,
      info: summary.info,
    })
  }

  return { passed, issues, summary }
}

/**
 * @module services/skills/entrySignalSkill
 * @description S-13 入场信号 SKILL（Batch E 交易集成）
 *
 * 基于 signalGenerator 的纯函数生成买入/入场信号，并挑选最强信号。
  * @doc [V9-DOC-BACK-012, V9-DOC-ARCH-007, V9-DOC-BACK-015, V9-DOC-BACK-023, V9-DOC-BACK-033]
*/

import { z } from 'zod'
import { getLogger } from '@/lib/logger'
import { buildSnapshot, generateBuySignals, type TradingSignal } from '@/services/trading/signalGenerator'
import type { DailyQuotes, Stock } from '@/data/types'
import type { SkillContext, SkillDefinition, SkillResult } from './skillTypes'

const logger = getLogger()

const SignalSchema = z.object({
  id: z.string(),
  symbol: z.string(),
  direction: z.enum(['buy', 'sell', 'hold', 'watch']),
  type: z.string(),
  strategy: z.string(),
  confidence: z.number(),
  rationale: z.string(),
  snapshot: z.record(z.string(), z.unknown()),
  createdAt: z.number(),
})

/**
 * EntrySignalInputSchema
 */
export const EntrySignalInputSchema = z.object({
  symbol: z.string(),
  stockName: z.string().optional(),
  userIntent: z.string().optional(),
  params: z.object({
    /** 股票基础数据 */
    stock: z.record(z.string(), z.unknown()),
    /** 日线行情数据 */
    quotes: z.record(z.string(), z.unknown()),
  }).optional(),
})

export type EntrySignalInput = z.infer<typeof EntrySignalInputSchema>

/**
 * EntrySignalOutputSchema
 */
export const EntrySignalOutputSchema = z.object({
  /** 最强买入信号 */
  strongestSignal: SignalSchema,
  /** 所有买入信号（按置信度降序） */
  signals: z.array(SignalSchema),
  /** 技术指标快照 */
  snapshot: z.record(z.string(), z.unknown()),
  /** 买入信号数量 */
  signalCount: z.number().int().min(0),
})

export type EntrySignalOutput = z.infer<typeof EntrySignalOutputSchema>

function isValidQuotes(value: unknown): value is DailyQuotes {
  if (typeof value !== 'object' || value === null) return false
  const q = value as Partial<DailyQuotes>
  return (
    typeof q.symbol === 'string' &&
    q.latest !== undefined &&
    Array.isArray(q.history) &&
    q.history.length > 0
  )
}

function isValidStock(value: unknown): value is Stock {
  if (typeof value !== 'object' || value === null) return false
  const s = value as Partial<Stock>
  return typeof s.symbol === 'string' && typeof s.name === 'string'
}

function pickStrongestEntrySignal(signals: TradingSignal[]): TradingSignal | undefined {
  if (signals.length === 0) return undefined
  return signals
    .filter((s) => s.direction === 'buy')
    .sort((a, b) => b.confidence - a.confidence)[0]
}

function normalizeSignal(signal: TradingSignal): z.infer<typeof SignalSchema> {
  return {
    ...signal,
    snapshot: signal.snapshot as Record<string, unknown>,
  }
}

/**
 * executeEntrySignalSkill
 */
export async function executeEntrySignalSkill(
  ctx: SkillContext,
): Promise<SkillResult<EntrySignalOutput>> {
  const startedAt = Date.now()
  const params = ctx.params ?? {}
  const stockCandidate = params.stock
  const quotesCandidate = params.quotes

  logger.info('[entrySignalSkill] 开始生成入场信号', {
    symbol: ctx.symbol,
    hasStock: !!stockCandidate,
    hasQuotes: !!quotesCandidate,
  })

  if (!isValidStock(stockCandidate)) {
    return {
      skillId: entrySignalSkill.name,
      status: 'failed',
      evidence: [],
      error: '缺少合法的股票基础数据（stock）',
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  }

  if (!isValidQuotes(quotesCandidate)) {
    return {
      skillId: entrySignalSkill.name,
      status: 'failed',
      evidence: [],
      error: '缺少合法的日线行情数据（quotes）或历史数据为空',
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  }

  try {
    const stock = stockCandidate
    const quotes = quotesCandidate

    if (quotes.history.length < 20) {
      return {
        skillId: entrySignalSkill.name,
        status: 'failed',
        evidence: [],
        error: `历史 K 线数据不足，至少需要 20 条，当前 ${quotes.history.length} 条`,
        meta: { startedAt, durationMs: Date.now() - startedAt },
      }
    }

    const snapshot = buildSnapshot(stock, quotes)
    const rawSignals = generateBuySignals(snapshot).map((s) => ({
      ...s,
      id: s.id || `entry-${ctx.symbol}-${Date.now()}`,
      symbol: s.symbol || ctx.symbol,
      createdAt: s.createdAt || Date.now(),
    }))
    const signals = rawSignals.map(normalizeSignal)

    const strongest = pickStrongestEntrySignal(rawSignals)

    if (!strongest) {
      return {
        skillId: entrySignalSkill.name,
        status: 'success',
        data: {
          strongestSignal: {
            id: `hold-${ctx.symbol}-${Date.now()}`,
            symbol: ctx.symbol,
            direction: 'hold',
            type: 'hold',
            strategy: 'signal',
            confidence: 0.15,
            rationale: '未触发任何买入信号，建议持有/观望',
            snapshot: snapshot as Record<string, unknown>,
            createdAt: Date.now(),
          },
          signals: [],
          snapshot: snapshot as Record<string, unknown>,
          signalCount: 0,
        },
        evidence: ['signal-generator', 'no-entry-signal'],
        meta: { startedAt, durationMs: Date.now() - startedAt },
      }
    }

    const output: EntrySignalOutput = {
      strongestSignal: normalizeSignal(strongest),
      signals: signals.sort((a, b) => b.confidence - a.confidence),
      snapshot: snapshot as Record<string, unknown>,
      signalCount: signals.length,
    }

    logger.info('[entrySignalSkill] 入场信号生成完成', {
      symbol: ctx.symbol,
      signalCount: output.signalCount,
      strongestType: output.strongestSignal.type,
      confidence: output.strongestSignal.confidence,
    })

    return {
      skillId: entrySignalSkill.name,
      status: 'success',
      data: output,
      evidence: [
        'signal-generator',
        `strongest:${output.strongestSignal.type}`,
        `confidence:${output.strongestSignal.confidence}`,
      ],
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[entrySignalSkill] 入场信号生成失败: ${message}`, { symbol: ctx.symbol })
    return {
      skillId: entrySignalSkill.name,
      status: 'failed',
      evidence: [],
      error: message,
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  }
}

/**
 * entrySignalSkill
 */
export const entrySignalSkill: SkillDefinition<EntrySignalOutput> = {
  name: 'entry-signal',
  title: '入场信号',
  description: '基于技术指标生成买入信号并挑选最强入场信号',
  inputSchema: EntrySignalInputSchema,
  outputSchema: EntrySignalOutputSchema,
  executor: executeEntrySignalSkill,
  requiresLlm: false,
  version: '1.0.0',
}

/**
 * @module services/skills/exitSignalSkill
 * @description S-14 出场信号 SKILL（Batch E 交易集成）
 *
 * 基于 signalGenerator 的纯函数生成卖出/出场信号，并附加固定止损与移动止损建议。
  * @doc [V9-DOC-BACK-012, V9-DOC-ARCH-007, V9-DOC-BACK-015, V9-DOC-BACK-023, V9-DOC-BACK-033]
*/

import { z } from 'zod'
import { getLogger } from '@/lib/logger'
import { buildSnapshot, generateSellSignals, type TradingSignal } from '@/services/trading/signalGenerator'
import { getEffectiveTradingConfig } from '@/config/tradingConfig'
import type { DailyQuotes, Stock } from '@/data/types'
import type { SkillContext, SkillDefinition, SkillResult } from './skillTypes'

const logger = getLogger()

const SignalSchema = z.object({
  id: z.string(),
  symbol: z.string(),
  direction: z.enum(['buy', 'sell', 'hold', 'watch']),
  type: z.string(),
  strategy: z.string(),
  confidence: z.number(),
  rationale: z.string(),
  snapshot: z.record(z.string(), z.unknown()),
  createdAt: z.number(),
})

/**
 * ExitSignalInputSchema
 */
export const ExitSignalInputSchema = z.object({
  symbol: z.string(),
  stockName: z.string().optional(),
  userIntent: z.string().optional(),
  params: z.object({
    /** 股票基础数据 */
    stock: z.record(z.string(), z.unknown()),
    /** 日线行情数据 */
    quotes: z.record(z.string(), z.unknown()),
    /** 持仓成本价（用于固定止损计算） */
    costPrice: z.number().positive().optional(),
  }).optional(),
})

export type ExitSignalInput = z.infer<typeof ExitSignalInputSchema>

/**
 * ExitSignalOutputSchema
 */
export const ExitSignalOutputSchema = z.object({
  /** 最强卖出信号 */
  strongestSignal: SignalSchema,
  /** 所有卖出信号（按置信度降序） */
  signals: z.array(SignalSchema),
  /** 技术指标快照 */
  snapshot: z.record(z.string(), z.unknown()),
  /** 卖出信号数量 */
  signalCount: z.number().int().min(0),
  /** 止损建议 */
  stopLossSuggestion: z.object({
    /** 是否触发止损 */
    triggered: z.boolean(),
    /** 止损类型：固定止损 / 移动止损 / 无 */
    type: z.enum(['fixed', 'trailing', 'none']).optional(),
    /** 建议止损价 */
    stopPrice: z.number().optional(),
    /** 触发理由 */
    rationale: z.string().optional(),
  }),
})

export type ExitSignalOutput = z.infer<typeof ExitSignalOutputSchema>

function isValidQuotes(value: unknown): value is DailyQuotes {
  if (typeof value !== 'object' || value === null) return false
  const q = value as Partial<DailyQuotes>
  return (
    typeof q.symbol === 'string' &&
    q.latest !== undefined &&
    Array.isArray(q.history) &&
    q.history.length > 0
  )
}

function isValidStock(value: unknown): value is Stock {
  if (typeof value !== 'object' || value === null) return false
  const s = value as Partial<Stock>
  return typeof s.symbol === 'string' && typeof s.name === 'string'
}

function pickStrongestExitSignal(signals: TradingSignal[]): TradingSignal | undefined {
  if (signals.length === 0) return undefined
  return signals
    .filter((s) => s.direction === 'sell')
    .sort((a, b) => b.confidence - a.confidence)[0]
}

function normalizeSignal(signal: TradingSignal): z.infer<typeof SignalSchema> {
  return {
    ...signal,
    snapshot: signal.snapshot as Record<string, unknown>,
  }
}

function calculateStopLossSuggestion(
  quotes: DailyQuotes,
  costPrice?: number,
): ExitSignalOutput['stopLossSuggestion'] {
  const config = getEffectiveTradingConfig().signalThresholds
  const latest = quotes.latest.close

  // 移动止损：从近期高点回撤达到阈值
  const recentHistory = quotes.history.slice(-60)
  const highest = recentHistory.length > 0 ? Math.max(...recentHistory.map((bar) => bar.high)) : latest
  const trailingStopPrice = highest * (1 - config.trailingStopDrawdownPct / 100)
  const trailingTriggered = latest <= trailingStopPrice

  // 固定止损：从成本价回撤达到阈值
  const fixedStopPrice = costPrice !== undefined ? costPrice * (1 - config.fixedStopLossPct / 100) : undefined
  const fixedTriggered = fixedStopPrice !== undefined && latest <= fixedStopPrice

  if (fixedTriggered && trailingTriggered) {
    return {
      triggered: true,
      type: 'fixed',
      stopPrice: fixedStopPrice,
      rationale: `价格 ${latest.toFixed(2)} 同时触发固定止损（成本价回撤 ${config.fixedStopLossPct}%）与移动止损（高点回撤 ${config.trailingStopDrawdownPct}%）`,
    }
  }

  if (fixedTriggered) {
    return {
      triggered: true,
      type: 'fixed',
      stopPrice: fixedStopPrice,
      rationale: `价格 ${latest.toFixed(2)} 触发固定止损：成本价 ${costPrice!.toFixed(2)} 回撤 ${config.fixedStopLossPct}%`,
    }
  }

  if (trailingTriggered) {
    return {
      triggered: true,
      type: 'trailing',
      stopPrice: trailingStopPrice,
      rationale: `价格 ${latest.toFixed(2)} 触发移动止损：从近期高点 ${highest.toFixed(2)} 回撤 ${config.trailingStopDrawdownPct}%`,
    }
  }

  return {
    triggered: false,
    type: 'none',
    rationale: `未触发止损：最新价 ${latest.toFixed(2)}，移动止损价 ${trailingStopPrice.toFixed(2)}${fixedStopPrice !== undefined ? `，固定止损价 ${fixedStopPrice.toFixed(2)}` : ''}`,
  }
}

/**
 * executeExitSignalSkill
 */
export async function executeExitSignalSkill(
  ctx: SkillContext,
): Promise<SkillResult<ExitSignalOutput>> {
  const startedAt = Date.now()
  const params = ctx.params ?? {}
  const stockCandidate = params.stock
  const quotesCandidate = params.quotes
  const costPrice = params.costPrice as number | undefined

  logger.info('[exitSignalSkill] 开始生成出场信号', {
    symbol: ctx.symbol,
    hasStock: !!stockCandidate,
    hasQuotes: !!quotesCandidate,
    costPrice,
  })

  if (!isValidStock(stockCandidate)) {
    return {
      skillId: exitSignalSkill.name,
      status: 'failed',
      evidence: [],
      error: '缺少合法的股票基础数据（stock）',
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  }

  if (!isValidQuotes(quotesCandidate)) {
    return {
      skillId: exitSignalSkill.name,
      status: 'failed',
      evidence: [],
      error: '缺少合法的日线行情数据（quotes）或历史数据为空',
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  }

  try {
    const stock = stockCandidate
    const quotes = quotesCandidate

    if (quotes.history.length < 20) {
      return {
        skillId: exitSignalSkill.name,
        status: 'failed',
        evidence: [],
        error: `历史 K 线数据不足，至少需要 20 条，当前 ${quotes.history.length} 条`,
        meta: { startedAt, durationMs: Date.now() - startedAt },
      }
    }

    const snapshot = buildSnapshot(stock, quotes)
    const rawSignals = generateSellSignals(snapshot, quotes.history).map((s) => ({
      ...s,
      id: s.id || `exit-${ctx.symbol}-${Date.now()}`,
      symbol: s.symbol || ctx.symbol,
      createdAt: s.createdAt || Date.now(),
    }))
    const signals = rawSignals.map(normalizeSignal)

    const strongest = pickStrongestExitSignal(rawSignals)
    const stopLossSuggestion = calculateStopLossSuggestion(quotes, costPrice)

    if (!strongest) {
      return {
        skillId: exitSignalSkill.name,
        status: 'success',
        data: {
          strongestSignal: {
            id: `hold-${ctx.symbol}-${Date.now()}`,
            symbol: ctx.symbol,
            direction: 'hold',
            type: 'hold',
            strategy: 'signal',
            confidence: 0.15,
            rationale: '未触发任何卖出信号，建议持有/观望',
            snapshot: snapshot as Record<string, unknown>,
            createdAt: Date.now(),
          },
          signals: [],
          snapshot: snapshot as Record<string, unknown>,
          signalCount: 0,
          stopLossSuggestion,
        },
        evidence: ['signal-generator', 'no-exit-signal'],
        meta: { startedAt, durationMs: Date.now() - startedAt },
      }
    }

    const output: ExitSignalOutput = {
      strongestSignal: normalizeSignal(strongest),
      signals: signals.sort((a, b) => b.confidence - a.confidence),
      snapshot: snapshot as Record<string, unknown>,
      signalCount: signals.length,
      stopLossSuggestion,
    }

    logger.info('[exitSignalSkill] 出场信号生成完成', {
      symbol: ctx.symbol,
      signalCount: output.signalCount,
      strongestType: output.strongestSignal.type,
      confidence: output.strongestSignal.confidence,
      stopLossTriggered: output.stopLossSuggestion.triggered,
    })

    return {
      skillId: exitSignalSkill.name,
      status: 'success',
      data: output,
      evidence: [
        'signal-generator',
        `strongest:${output.strongestSignal.type}`,
        `confidence:${output.strongestSignal.confidence}`,
        `stopLoss:${output.stopLossSuggestion.triggered ? 'triggered' : 'none'}`,
      ],
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[exitSignalSkill] 出场信号生成失败: ${message}`, { symbol: ctx.symbol })
    return {
      skillId: exitSignalSkill.name,
      status: 'failed',
      evidence: [],
      error: message,
      meta: { startedAt, durationMs: Date.now() - startedAt },
    }
  }
}

