/**
 * DataCleanupService — 数据清理策略
 *
 * 提供基于保留策略的过期数据清理机制。每个存储区可配置独立的保留天数，
 * 支持查找过期记录、批量清理、存储用量估算与清理统计追踪。
 *
 * @doc V9-DOC-QUALITY-019
 * @module services/storage/DataCleanupService
 */

import { getLogger } from '@/lib/logger';

const logger = getLogger();

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** 存储区名称 */
export type StoreName =
  | 'dailyQuotes'
  | 'researchReports'
  | 'intelligentScores'
  | 'realtimeQuotes';

/** 保留策略定义 */
export interface RetentionPolicy {
  /** 最大保留天数 */
  maxAge: number;
  /** 时间单位 */
  unit: 'days';
}

/** 过期记录 */
export interface ExpiredRecord {
  key: string;
  /** 记录时间戳（毫秒） */
  timestamp: number;
  /** 距今已过天数 */
  ageInDays: number;
}

/** 清理结果 */
export interface CleanupResult {
  deleted: number;
  freedBytes: number;
  errors: string[];
}

/** 存储用量估算 */
export interface StorageEstimate {
  store: StoreName;
  estimatedSize: number;
  recordCount: number;
}

/** 抽象存储接口 — 支持清理操作 */
export interface CleanupStore {
  /** 返回所有 key */
  keys(): Promise<string[]>;
  /** 读取记录 */
  get(key: string): Promise<{ timestamp?: number; __size?: number; [key: string]: unknown } | undefined>;
  /** 删除记录 */
  delete(key: string): Promise<void>;
  /** 获取存储估算 */
  estimate?(): Promise<{ usage: number; quota: number }>;
  /** 记录数 */
  count?(): Promise<number>;
}

// ---------------------------------------------------------------------------
// Retention Policies
// ---------------------------------------------------------------------------

/**
 * 各存储区默认保留策略。
 *
 * | 存储区           | 保留天数 |
 * |------------------|----------|
 * | dailyQuotes      | 365      |
 * | researchReports  | 730      |
 * | intelligentScores| 90       |
 * | realtimeQuotes   | 7        |
 */
const DEFAULT_POLICIES: Record<StoreName, RetentionPolicy> = {
  dailyQuotes: { maxAge: 365, unit: 'days' },
  researchReports: { maxAge: 730, unit: 'days' },
  intelligentScores: { maxAge: 90, unit: 'days' },
  realtimeQuotes: { maxAge: 7, unit: 'days' },
};

// ---------------------------------------------------------------------------
// Cleanup Stats
// ---------------------------------------------------------------------------

interface CleanupStats {
  lastCleanupAt: string | null;
  totalDeleted: number;
  totalFreedBytes: number;
}

const cleanupStats: CleanupStats = {
  lastCleanupAt: null,
  totalDeleted: 0,
  totalFreedBytes: 0,
};

/**
 * 获取清理统计信息。
 *
 * @returns 当前清理统计快照
 */
export function getCleanupStats(): Readonly<CleanupStats> {
  return { ...cleanupStats };
}

// ---------------------------------------------------------------------------
// Policy Retrieval
// ---------------------------------------------------------------------------

/**
 * 获取指定存储区的保留策略。
 *
 * @param store - 存储区名称
 * @returns 保留策略（maxAge 与 unit）
 */
export function getRetentionPolicy(store: StoreName): RetentionPolicy {
  const policy = DEFAULT_POLICIES[store];
  if (!policy) {
    logger.warn(`Unknown store "${store}", falling back to 30-day default`);
    return { maxAge: 30, unit: 'days' };
  }
  return { ...policy };
}

// ---------------------------------------------------------------------------
// Expired Records
// ---------------------------------------------------------------------------

/** 一天对应的毫秒数 */
const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * 查找存储区中所有已过期的记录。
 *
 * 根据策略中的 `maxAge` 判断记录是否过期。记录需包含 `timestamp` 字段
 * 以确定其写入时间。
 *
 * @param store  - 支持 keys/get 的存储实例
 * @param policy - 保留策略
 * @returns 过期记录列表
 */
export async function findExpiredRecords(
  store: CleanupStore,
  policy: RetentionPolicy,
): Promise<ExpiredRecord[]> {
  const now = Date.now();
  const maxAgeMs = policy.maxAge * DAY_MS;
  const cutoff = now - maxAgeMs;

  logger.debug(
    `Finding expired records: maxAge=${policy.maxAge}${policy.unit}, cutoff=${new Date(cutoff).toISOString()}`,
  );

  const keys = await store.keys();
  const expired: ExpiredRecord[] = [];

  for (const key of keys) {
    const record = await store.get(key);
    if (!record) continue;

    const ts = record.timestamp;
    if (typeof ts !== 'number') {
      logger.debug(`Skipping key="${key}": no timestamp field`);
      continue;
    }

    if (ts < cutoff) {
      const ageInDays = Math.round((now - ts) / DAY_MS);
      expired.push({ key, timestamp: ts, ageInDays });
    }
  }

  logger.info(`Found ${expired.length} expired records out of ${keys.length}`);
  return expired;
}

// ---------------------------------------------------------------------------
// Cleanup
// ---------------------------------------------------------------------------

/**
 * 清理存储区中的过期记录。
 *
 * 遍历所有记录，删除超过 `policy.maxAge` 天的记录，并统计删除数量与释放空间。
 *
 * @param store  - 支持 keys/get/delete 的存储实例
 * @param policy - 保留策略
 * @returns 清理结果，包含删除数、释放字节数与错误列表
 */
export async function cleanupExpiredRecords(
  store: CleanupStore,
  policy: RetentionPolicy,
): Promise<CleanupResult> {
  const now = Date.now();
  const maxAgeMs = policy.maxAge * DAY_MS;
  const cutoff = now - maxAgeMs;

  logger.info(`Starting cleanup: maxAge=${policy.maxAge}${policy.unit}`);

  const keys = await store.keys();
  let deleted = 0;
  let freedBytes = 0;
  const errors: string[] = [];

  for (const key of keys) {
    try {
      const record = await store.get(key);
      if (!record) continue;

      const ts = record.timestamp;
      if (typeof ts !== 'number' || ts >= cutoff) continue;

      const recordSize = typeof record.__size === 'number' ? record.__size : 0;

      await store.delete(key);
      deleted++;
      freedBytes += recordSize;
    } catch (err) {
      const msg = `Failed to delete key="${key}": ${(err as Error)?.message ?? err}`;
      errors.push(msg);
      logger.error(msg);
    }
  }

  // 更新统计
  cleanupStats.lastCleanupAt = new Date().toISOString();
  cleanupStats.totalDeleted += deleted;
  cleanupStats.totalFreedBytes += freedBytes;

  logger.info(
    `Cleanup complete: deleted=${deleted}, freedBytes=${freedBytes}, errors=${errors.length}`,
  );

  return { deleted, freedBytes, errors };
}

// ---------------------------------------------------------------------------
// Storage Estimate
// ---------------------------------------------------------------------------

/**
 * 估算各存储区的空间占用。
 *
 * 遍历所有存储区名称，查询每个存储区的记录数与估算大小。
 *
 * @param stores - 存储区名称到存储实例的映射
 * @returns 各存储区的用量估算列表
 */
export async function getStorageEstimate(
  stores: Record<StoreName, CleanupStore>,
): Promise<StorageEstimate[]> {
  const results: StorageEstimate[] = [];

  for (const [storeName, store] of Object.entries(stores) as [StoreName, CleanupStore][]) {
    try {
      let estimatedSize = 0;
      let recordCount = 0;

      if (store.estimate) {
        const est = await store.estimate();
        estimatedSize = est.usage;
      }

      if (store.count) {
        recordCount = await store.count();
      }

      results.push({
        store: storeName,
        estimatedSize,
        recordCount,
      });
    } catch (err) {
      logger.error(`Failed to estimate storage for "${storeName}": ${(err as Error)?.message ?? err}`);
      results.push({
        store: storeName,
        estimatedSize: 0,
        recordCount: 0,
      });
    }
  }

  return results;
}

/**
 * duckDBProvider — DuckDB 时序数据存储实现
 *
 * 基于 @duckdb/duckdb-wasm 在浏览器中运行 DuckDB 列式数据库，
 * 专用于高频行情数据的写入与 OHLCV 聚合查询。
 *
 * 使用方式：
 * ```typescript
 * import { duckDbProvider } from './duckDBProvider'
 * await duckDbProvider.init()
 * await duckDbProvider.writePoints('600519.SH', points)
 * const ohlcv = await duckDbProvider.aggregate('600519.SH', 3600000)
 * ```
  * @doc [V9-DOC-BACK-012, V9-DOC-BACK-023, V9-DOC-BACK-033, V9-DOC-BACK-021, V9-DOC-BACK-026]
*/

import { getLogger } from '@/lib/logger'
import type {
  AsyncDuckDB,
  AsyncDuckDBConnection,
  DuckDBBundle,
  DuckDBBundles,
} from '@duckdb/duckdb-wasm'
import type {
  GetOptions,
  ListOptions,
  SaveOptions,
  DeleteOptions,
  TimeSeriesProvider,
  TimeSeriesPoint,
  TimeSeriesQuery,
  QueryResult,
  ListResult,
} from './storageProvider'

const logger = getLogger()

// ============================================================
// DuckDB Provider
// ============================================================

/**
 * DuckDBProvider — DuckDB 时序存储
 *
 * 设计说明：
 * - 惰性初始化：首次调用 init() 时加载 DuckDB WebAssembly 引擎
 * - 自动建表：每个 symbol 自动建表（quotes_{normalizedSymbol}）
 * - 预聚合：支持按时间窗口做 OHLCV 聚合
 *
 * 注意：DuckDB 在浏览器中运行于 Web Worker，初始化需 ~1-3s。
 */
export class DuckDBProviderImpl implements TimeSeriesProvider {
  readonly backend = 'duckdb' as const
  readonly morphologies: ['time_series'] = ['time_series']

  // DuckDB 实例（惰性初始化）
  private db: AsyncDuckDB | null = null
  private conn: AsyncDuckDBConnection | null = null
  private initialized = false

  /** 已建表缓存 */
  private tablesCreated = new Set<string>()

  // ============================================================
  // 初始化
  // ============================================================

  /**
   * 初始化 DuckDB 引擎
   * @returns true 表示初始化成功
   */
  async init(): Promise<boolean> {
    if (this.initialized && this.db) return true

    try {
      // 动态导入 duckdb-wasm（首次调用时加载 ~15MB wasm）
      // 使用 unknown 中转避免类型断言与模块版本不兼容
      const ddbModule = await import('@duckdb/duckdb-wasm')
      const ddb = ddbModule as unknown as {
        getJsDelivrBundles(): DuckDBBundles
        selectBundle(bundles: DuckDBBundles): Promise<DuckDBBundle>
        ConsoleLogger: new (...args: unknown[]) => unknown
        AsyncDuckDB: new (logger: unknown, worker: Worker) => AsyncDuckDB
      }
      const bundles = ddb.getJsDelivrBundles()
      const bundle = await ddb.selectBundle(bundles)

      const workerUrl = bundle.mainWorker
      if ((workerUrl ?? '') === '') {
        throw new Error('DuckDB bundle 不包含 worker URL')
      }
      const worker = new Worker(workerUrl!)
      const logger_ = new ddb.ConsoleLogger()
      this.db = new ddb.AsyncDuckDB(logger_, worker)
      await this.db.instantiate(bundle.mainModule, bundle.pthreadWorker)

      this.conn = await this.db.connect()
      this.initialized = true

      getLogger().info('[DuckDBProvider] 引擎初始化完成')
      return true
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      getLogger().error('[DuckDBProvider] 引擎初始化失败', { error: msg })
      return false
    }
  }

  // ============================================================
  // SQL 查询（仅允许 SELECT，防注入）
  // ============================================================

  /**
   * 执行 SQL 查询（安全受限：仅允许 SELECT，拒绝 INSERT/UPDATE/DELETE/DROP 等写操作）
   * @returns 成功时 success=true；被拒绝或出错时 success=false 并附带 error
   */
  async querySQL(sql: string): Promise<QueryResult<unknown>> {
    if (!this.initialized) {
      logger.warn('[duckDB] querySQL: DuckDB 未初始化')
      return { success: false, error: 'DuckDB 未初始化' }
    }

    const trimmed = sql ? sql.trim() : ''
    if (!trimmed) {
      logger.debug('[duckDB] querySQL: 空 SQL 被拒绝')
      return { success: false, error: '仅允许 SELECT 查询' }
    }

    // 安全校验：必须以 SELECT 开头（大小写不敏感），否则拒绝
    if (!/^SELECT\s/i.test(trimmed)) {
      logger.warn(`[duckDB] querySQL: 非 SELECT 查询被拒绝, sql="${trimmed.substring(0, 50)}..."`)
      return { success: false, error: '仅允许 SELECT 查询，禁止 INSERT/UPDATE/DELETE/DROP 等操作' }
    }

    const queryStart = performance.now()
    try {
      const result = await this.conn!.query(trimmed)
      const duration = (performance.now() - queryStart).toFixed(2)
      logger.info(`[duckDB] querySQL: 执行成功, 耗时 ${duration}ms, 结果行数=${(result as unknown as { rowCount?: number })?.rowCount ?? 'unknown'}`)
      return { success: true }
    } catch (err) {
      const duration = (performance.now() - queryStart).toFixed(2)
      const errorMsg = err instanceof Error ? err.message : String(err)
      logger.error(`[duckDB] querySQL: 执行失败, 耗时 ${duration}ms, error="${errorMsg}"`)
      return { success: false, error: errorMsg }
    }
  }

  /**
   * 关闭 DuckDB 引擎连接，释放资源
   */
  async close(): Promise<void> {
    try {
      this.conn = null
      this.db = null
      this.initialized = false
      this.tablesCreated.clear()
    } catch {
      // 关闭失败不抛出，仅重置状态
    }
  }

  /**
   * 返回已创建的表名列表（去重）
   */
  async getAvailableTables(): Promise<string[]> {
    return Array.from(this.tablesCreated)
  }

  // ============================================================
  // 表管理
  // ============================================================

  private tableName(symbol: string): string {
    const clean = symbol.replace(/[^a-zA-Z0-9_]/g, '_')
    return `quotes_${clean}`
  }

  private async ensureTable(symbol: string): Promise<void> {
    const table = this.tableName(symbol)
    if (this.tablesCreated.has(table)) return

    await this.conn!.query(`
      CREATE TABLE IF NOT EXISTS ${table} (
        timestamp BIGINT,
        value DOUBLE,
        volume DOUBLE DEFAULT 0,
        metadata TEXT
      )
    `)
    this.tablesCreated.add(table)
  }

  // ============================================================
  // StorageProvider 接口
  // ============================================================

  async get<T>(_options: GetOptions): Promise<QueryResult<T>> {
    return { success: false, error: 'DuckDBProvider: 请使用 queryTimeSeries 查询时序数据' }
  }

  async list<T>(_options?: ListOptions): Promise<ListResult<T>> {
    return { success: false, data: [], error: 'DuckDBProvider: 请使用 queryTimeSeries 查询时序数据' }
  }

  async save<T>(_data: T, _options?: SaveOptions): Promise<QueryResult<void>> {
    return { success: false, error: 'DuckDBProvider: 请使用 writePoints 写入时序数据' }
  }

  async delete(options: DeleteOptions): Promise<QueryResult<void>> {
    if (!this.initialized) {
      const ok = await this.init()
      if (!ok) return { success: false, error: 'DuckDB 未初始化' }
    }

    try {
      const table = this.tableName(String(options.key))
      await this.conn!.query(`DROP TABLE IF EXISTS ${table}`)
      this.tablesCreated.delete(table)
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : String(err) }
    }
  }

  async healthCheck(): Promise<boolean> {
    if (!this.initialized) return false
    try {
      await this.conn!.query('SELECT 1')
      return true
    } catch (err) { console.warn('[duckDBProvider.ts]', err);
      return false
    }
  }

  // ============================================================
  // TimeSeriesProvider 专有方法
  // ============================================================

  /**
   * 批量写入时序数据点
   */
  async writePoints(symbol: string, points: TimeSeriesPoint[]): Promise<QueryResult<void>> {
    if (!this.initialized) {
      const ok = await this.init()
      if (!ok) return { success: false, error: 'DuckDB 未初始化' }
    }

    if (points.length === 0) return { success: true }

    try {
      await this.ensureTable(symbol)
      const table = this.tableName(symbol)

      // 批量准备 values
      const values = points
        .map((p) => `(${p.timestamp}, ${p.value}, ${(p.metadata?.volume as number) ?? 0}, '${JSON.stringify(p.metadata ?? {})}')`)
        .join(',\n')

      await this.conn!.query(`INSERT INTO ${table} (timestamp, value, volume, metadata) VALUES ${values}`)

      logger.info('[DuckDBProvider] 写入完成', { symbol, points: points.length })
      return { success: true }
    } catch (err) {
      return { success: false, error: err instanceof Error ? err.message : String(err) }
    }
  }

  /**
   * 查询时序数据
   */
  async queryTimeSeries(query: TimeSeriesQuery): Promise<ListResult<TimeSeriesPoint>> {
    if (!this.initialized) {
      const ok = await this.init()
      if (!ok) return { success: false, data: [], error: 'DuckDB 未初始化' }
    }

    try {
      const table = this.tableName(query.symbol)
      let sql = `SELECT timestamp, value FROM ${table} WHERE 1=1`

      if ((query.startTime ?? 0) !== 0) sql += ` AND timestamp >= ${query.startTime}`
      if ((query.endTime ?? 0) !== 0) sql += ` AND timestamp <= ${query.endTime}`
      sql += ' ORDER BY timestamp ASC'
      if ((query.limit ?? 0) > 0) sql += ` LIMIT ${query.limit}`

      const result = await this.conn!.query(sql)

      const points: TimeSeriesPoint[] = []
      for (let i = 0; i < result.numRows; i++) {
        points.push({
          timestamp: Number(result.getChild('timestamp')?.get(i) ?? 0),
          value: Number(result.getChild('value')?.get(i) ?? 0),
        })
      }

      return { success: true, data: points }
    } catch (err) {
      return { success: false, data: [], error: err instanceof Error ? err.message : String(err) }
    }
  }

  /**
   * OHLCV 聚合查询
   */
  async aggregate(symbol: string, windowMs: number): Promise<ListResult<OHLCVRow>> {
    if (!this.initialized) {
      const ok = await this.init()
      if (!ok) return { success: false, data: [], error: 'DuckDB 未初始化' }
    }

    try {
      const table = this.tableName(symbol)
      const sql = `
        SELECT
          FLOOR(timestamp / ${windowMs}) * ${windowMs} AS bucket,
          FIRST(value) AS open,
          MAX(value) AS high,
          MIN(value) AS low,
          LAST(value) AS close,
          SUM(volume) AS volume
        FROM ${table}
        GROUP BY bucket
        ORDER BY bucket ASC
      `

      const result = await this.conn!.query(sql)
      const rows: OHLCVRow[] = []
      for (let i = 0; i < result.numRows; i++) {
        rows.push({
          timestamp: Number(result.getChild('bucket')?.get(i) ?? 0),
          open: Number(result.getChild('open')?.get(i) ?? 0),
          high: Number(result.getChild('high')?.get(i) ?? 0),
          low: Number(result.getChild('low')?.get(i) ?? 0),
          close: Number(result.getChild('close')?.get(i) ?? 0),
          volume: Number(result.getChild('volume')?.get(i) ?? 0),
        })
      }

      return { success: true, data: rows }
    } catch (err) {
      return { success: false, data: [], error: err instanceof Error ? err.message : String(err) }
    }
  }
}

/** OHLCV 聚合结果行 */
interface OHLCVRow {
  timestamp: number
  open: number
  high: number
  low: number
  close: number
  volume: number
}

/**
 * HNSW 向量索引 — 纯 JavaScript 实现
 *
 * API 对齐 Python hnswlib（https://github.com/nmslib/hnswlib），
 * 以便未来无缝替换为 WASM/原生绑定版本。
 *
 * 对齐接口：
 *   const index = new HNSWIndex('cosine', 384)
 *   index.initIndex(10000, { M: 16, efConstruction: 200 })
 *   index.addItems(vectors, ids)
 *   const { ids, distances } = index.searchKnn(query, 10)
 *   index.setEf(64)
 *
 * 参考：Malkov & Yashunin, "Efficient and robust approximate nearest neighbor
 *       search using Hierarchical Navigable Small World graphs", 2018.
  * @doc [V9-DOC-BACK-012, V9-DOC-BACK-023, V9-DOC-BACK-033, V9-DOC-BACK-021, V9-DOC-BACK-026]
*/

import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ─── 类型 ────────────────────────────────────────────────────

export type HNSWSpace = 'l2' | 'cosine' | 'ip'

export interface HNSWInitOptions {
  /** 每层最大邻居数（默认 16） */
  M?: number
  /** 构建时搜索宽度（默认 200） */
  efConstruction?: number
  /** 随机种子 */
  randomSeed?: number
}

export interface HNSWSearchResult {
  ids: string[]
  distances: number[]
}

export interface SerializedHNSW {
  version: number
  space: HNSWSpace
  dim: number
  maxElements: number
  M: number
  efConstruction: number
  efSearch: number
  randomSeed: number
  nodes: Array<{
    id: string
    vector: number[]
    neighbors: string[][]
  }>
  entryPoint: string | null
  deleted: string[]
}

// ─── 距离函数 ────────────────────────────────────────────────

function l2Distance(a: number[], b: number[]): number {
  let sum = 0
  for (let i = 0; i < a.length; i++) {
    const diff = a[i]! - b[i]!
    sum += diff * diff
  }
  return Math.sqrt(sum)
}

function cosineDistance(a: number[], b: number[]): number {
  let dot = 0
  let normA = 0
  let normB = 0
  for (let i = 0; i < a.length; i++) {
    dot += a[i]! * b[i]!
    normA += a[i]! * a[i]!
    normB += b[i]! * b[i]!
  }
  if (normA === 0 || normB === 0) return 2
  const sim = dot / (Math.sqrt(normA) * Math.sqrt(normB))
  return 1 - sim
}

function ipDistance(a: number[], b: number[]): number {
  let dot = 0
  for (let i = 0; i < a.length; i++) {
    dot += a[i]! * b[i]!
  }
  return -dot
}

function getDistanceFn(space: HNSWSpace): (a: number[], b: number[]) => number {
  switch (space) {
    case 'l2': return l2Distance
    case 'cosine': return cosineDistance
    case 'ip': return ipDistance
  }
}

// ─── 最小堆 ──────────────────────────────────────────────────

interface HeapItem {
  id: string
  distance: number
}

class MinHeap {
  private heap: HeapItem[] = []
  push(item: HeapItem): void {
    this.heap.push(item)
    this.bubbleUp(this.heap.length - 1)
  }
  pop(): HeapItem | undefined {
    if (this.heap.length === 0) return undefined
    const root = this.heap[0]
    const last = this.heap.pop()!
    if (this.heap.length > 0) {
      this.heap[0] = last
      this.bubbleDown(0)
    }
    return root
  }
  peek(): HeapItem | undefined {
    return this.heap[0]
  }
  get size(): number {
    return this.heap.length
  }
  private bubbleUp(i: number): void {
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2)
      if (this.heap[parent]!.distance <= this.heap[i]!.distance) break
      ;[this.heap[parent], this.heap[i]] = [this.heap[i]!, this.heap[parent]!]
      i = parent
    }
  }
  private bubbleDown(i: number): void {
    const n = this.heap.length
    while (true) {
      let smallest = i
      const left = 2 * i + 1
      const right = 2 * i + 2
      if (left < n && this.heap[left]!.distance < this.heap[smallest]!.distance) smallest = left
      if (right < n && this.heap[right]!.distance < this.heap[smallest]!.distance) smallest = right
      if (smallest === i) break
      ;[this.heap[i], this.heap[smallest]] = [this.heap[smallest]!, this.heap[i]!]
      i = smallest
    }
  }
}

// ─── HNSW 索引 ───────────────────────────────────────────────

/**
 * HNSWIndex
 */
export class HNSWIndex {
  private space: HNSWSpace
  dim: number
  private distanceFn: (a: number[], b: number[]) => number
  private maxElements = 0
  private M = 16
  private mL = 1 / Math.log(16)
  private efConstruction = 200
  private efSearch = 64
  private randomSeed = 100
  private nodes = new Map<string, { id: string; vector: number[]; neighbors: string[][] }>()
  private entryPoint: string | null = null
  private deletedSet = new Set<string>()
  private initialized = false

  constructor(space: HNSWSpace, dim: number) {
    this.space = space
    this.dim = dim
    this.distanceFn = getDistanceFn(space)
  }

  // ─── 生命周期 ──────────────────────────────────────────────

  /**
   * 初始化索引容量。对标 hnswlib.init_index(max_elements, M, ef_construction, random_seed)
   */
  initIndex(maxElements: number, options?: HNSWInitOptions): void {
    this.maxElements = maxElements
    this.M = options?.M ?? 16
    this.mL = 1 / Math.log(this.M)
    this.efConstruction = options?.efConstruction ?? 200
    this.randomSeed = options?.randomSeed ?? 100
    this.initialized = true
    logger.info('[HNSW] initIndex', { space: this.space, dim: this.dim, maxElements, M: this.M, efConstruction: this.efConstruction })
  }

  /**
   * 扩容索引。对标 hnswlib.resize_index(new_size)
   */
  resizeIndex(newSize: number): void {
    this.maxElements = Math.max(this.maxElements, newSize)
    logger.info('[HNSW] resizeIndex', { newSize })
  }

  /**
   * 设置搜索参数。对标 hnswlib.set_ef(ef)
   */
  setEf(ef: number): void {
    this.efSearch = ef
  }

  getEf(): number {
    return this.efSearch
  }

  // ─── 写入 ──────────────────────────────────────────────────

  /**
   * 批量添加向量。对标 hnswlib.add_items(data, ids)
   *
   * @param vectors 向量数组（二维数组）
   * @param ids 对应 ID 数组
   */
  addItems(vectors: number[][], ids: string[]): void {
    if (!this.initialized) throw new Error('HNSWIndex not initialized. Call initIndex() first.')
    if (vectors.length !== ids.length) throw new Error('vectors and ids must have the same length')

    for (let i = 0; i < ids.length; i++) {
      this.addItem(ids[i]!, vectors[i]!)
    }
  }

  private addItem(id: string, vector: number[]): void {
    if (vector.length !== this.dim) {
      logger.warn(`[HNSW] addItem: dimension mismatch, skipping ${id}`)
      return
    }
    if (this.nodes.size >= this.maxElements) {
      logger.warn('[HNSW] addItem: maxElements reached, skipping')
      return
    }

    // 已存在则先删除
    if (this.nodes.has(id)) this.deleteNode(id)

    const level = this.randomLevel()
    const node = { id, vector, neighbors: Array.from({ length: level + 1 }, () => [] as string[]) }
    this.nodes.set(id, node)
    this.deletedSet.delete(id)

    if (this.entryPoint === null) {
      this.entryPoint = id
      return
    }

    const entryNode = this.nodes.get(this.entryPoint)!
    const entryMaxLayer = entryNode.neighbors.length - 1

    let currentEntry = this.entryPoint
    for (let layer = entryMaxLayer; layer > level; layer--) {
      currentEntry = this.searchLayer(vector, currentEntry, 1, layer)[0]?.id ?? currentEntry
    }

    for (let layer = Math.min(level, entryMaxLayer); layer >= 0; layer--) {
      const neighbors = this.searchLayer(vector, currentEntry, this.efConstruction, layer)
      const selected = this.selectNeighbors(vector, neighbors, this.M)
      node.neighbors[layer] = selected.map((n) => n.id)

      for (const n of selected) {
        const neighborNode = this.nodes.get(n.id)
        if (!neighborNode) continue
        if (!neighborNode.neighbors[layer]) neighborNode.neighbors[layer] = []
        neighborNode.neighbors[layer]!.push(id)
        if (neighborNode.neighbors[layer]!.length > this.M * 2) {
          neighborNode.neighbors[layer] = this.shrinkConnections(neighborNode, layer, this.M)
        }
      }
      currentEntry = selected[0]?.id ?? currentEntry
    }

    if (level > entryMaxLayer) this.entryPoint = id
  }

  // ─── 读取 ──────────────────────────────────────────────────

  /**
   * 搜索 k 近邻。对标 hnswlib.search_knn(data, k)
   *
   * @returns { ids: string[], distances: number[] }
   */
  searchKnn(vector: number[], k: number): HNSWSearchResult {
    if (!this.initialized) throw new Error('HNSWIndex not initialized. Call initIndex() first.')
    if (vector.length !== this.dim) {
      logger.warn(`[HNSW] searchKnn: dimension mismatch`)
      return { ids: [], distances: [] }
    }
    if (this.entryPoint === null || this.nodes.size === 0) return { ids: [], distances: [] }

    const entryNode = this.nodes.get(this.entryPoint)!
    const maxLayer = entryNode.neighbors.length - 1

    let currentEntry = this.entryPoint
    for (let layer = maxLayer; layer > 0; layer--) {
      const nearest = this.searchLayer(vector, currentEntry, 1, layer)
      if (nearest.length > 0) currentEntry = nearest[0]!.id
    }

    const results = this.searchLayer(vector, currentEntry, this.efSearch, 0)
    const filtered = results.filter((r) => !this.deletedSet.has(r.id)).slice(0, k)

    return {
      ids: filtered.map((r) => r.id),
      distances: filtered.map((r) => r.distance),
    }
  }

  /**
   * 当前元素数量。对标 hnswlib.get_current_count()
   */
  getCurrentCount(): number {
    return this.nodes.size - this.deletedSet.size
  }

  // ─── 删除 ──────────────────────────────────────────────────

  /**
   * 标记删除（软删除）。对标 hnswlib.mark_deleted(label)
   */
  markDeleted(id: string): void {
    if (this.nodes.has(id)) this.deletedSet.add(id)
  }

  /**
   * 取消删除标记。对标 hnswlib.unmark_deleted(label)
   */
  unmarkDeleted(id: string): void {
    this.deletedSet.delete(id)
  }

  /**
   * 物理删除节点。
   */
  deleteNode(id: string): void {
    const node = this.nodes.get(id)
    if (!node) return

    for (let layer = 0; layer < node.neighbors.length; layer++) {
      for (const neighborId of node.neighbors[layer] ?? []) {
        const neighbor = this.nodes.get(neighborId)
        if (neighbor?.neighbors[layer]) {
          neighbor.neighbors[layer] = neighbor.neighbors[layer]!.filter((n) => n !== id)
        }
      }
    }

    this.nodes.delete(id)
    this.deletedSet.delete(id)

    if (this.entryPoint === id) {
      let maxLayer = -1
      let newEntry: string | null = null
      for (const [nid, n] of this.nodes) {
        const layer = n.neighbors.length - 1
        if (layer > maxLayer) { maxLayer = layer; newEntry = nid }
      }
      this.entryPoint = newEntry
    }
  }

  // ─── 序列化 ────────────────────────────────────────────────

  /**
   * 序列化索引。对标 hnswlib.save_index() 的内存版本。
   */
  saveIndex(): SerializedHNSW {
    return {
      version: 1,
      space: this.space,
      dim: this.dim,
      maxElements: this.maxElements,
      M: this.M,
      efConstruction: this.efConstruction,
      efSearch: this.efSearch,
      randomSeed: this.randomSeed,
      nodes: Array.from(this.nodes.values()).map((n) => ({
        id: n.id,
        vector: n.vector,
        neighbors: n.neighbors,
      })),
      entryPoint: this.entryPoint,
      deleted: Array.from(this.deletedSet),
    }
  }

  /**
   * 反序列化索引。对标 hnswlib.load_index() 的内存版本。
   */
  loadIndex(data: SerializedHNSW): void {
    this.space = data.space
    this.dim = data.dim
    this.maxElements = data.maxElements
    this.M = data.M
    this.mL = 1 / Math.log(data.M)
    this.efConstruction = data.efConstruction
    this.efSearch = data.efSearch
    this.randomSeed = data.randomSeed
    this.distanceFn = getDistanceFn(data.space)
    this.entryPoint = data.entryPoint
    this.deletedSet = new Set(data.deleted ?? [])
    this.initialized = true

    this.nodes.clear()
    for (const n of data.nodes) {
      this.nodes.set(n.id, { id: n.id, vector: n.vector, neighbors: n.neighbors })
    }
  }

  // ─── 内部方法 ──────────────────────────────────────────────

  private searchLayer(query: number[], entryId: string, ef: number, layer: number): Array<{ id: string; distance: number }> {
    const visited = new Set<string>()
    const candidates = new MinHeap()
    const results = new MinHeap()

    const entryDist = this.distanceFn(query, this.nodes.get(entryId)!.vector)
    candidates.push({ id: entryId, distance: entryDist })
    results.push({ id: entryId, distance: entryDist })
    visited.add(entryId)

    while (candidates.size > 0) {
      const current = candidates.pop()!
      const farthestResult = results.peek()
      if (farthestResult && current.distance > farthestResult.distance && results.size >= ef) break

      const node = this.nodes.get(current.id)
      if (!node) continue
      const neighbors = node.neighbors[layer] ?? []

      for (const neighborId of neighbors) {
        if (visited.has(neighborId)) continue
        visited.add(neighborId)
        const neighbor = this.nodes.get(neighborId)
        if (!neighbor) continue
        const dist = this.distanceFn(query, neighbor.vector)

        const farthest = results.peek()
        if (results.size < ef || dist < farthest!.distance) {
          candidates.push({ id: neighborId, distance: dist })
          results.push({ id: neighborId, distance: dist })
          if (results.size > ef) {
            const arr: HeapItem[] = []
            while (results.size > 0) arr.push(results.pop()!)
            arr.pop()
            for (const item of arr) results.push(item)
          }
        }
      }
    }

    const output: Array<{ id: string; distance: number }> = []
    while (results.size > 0) {
      const item = results.pop()!
      output.push({ id: item.id, distance: item.distance })
    }
    return output.sort((a, b) => a.distance - b.distance)
  }

  private selectNeighbors(_query: number[], candidates: Array<{ id: string; distance: number }>, M: number): Array<{ id: string; distance: number }> {
    return candidates.slice(0, M)
  }

  private shrinkConnections(node: { id: string; vector: number[]; neighbors: string[][] }, layer: number, M: number): string[] {
    const neighborIds = node.neighbors[layer] ?? []
    if (neighborIds.length <= M) return neighborIds

    const distances = neighborIds
      .map((nid) => {
        const neighbor = this.nodes.get(nid)
        if (!neighbor) return null
        return { id: nid, distance: this.distanceFn(node.vector, neighbor.vector) }
      })
      .filter((d): d is { id: string; distance: number } => d !== null)

    distances.sort((a, b) => a.distance - b.distance)
    return distances.slice(0, M).map((d) => d.id)
  }

  private randomLevel(): number {
    let level = 0
    while (Math.random() < Math.exp(-1 / this.mL) && level < 16) level++
    return level
  }
}

