      '基本面稳定，暂无明显催化',
      '技术面中性，建议观望',
    ],
  }

  const reasonList = reasons[direction as keyof typeof reasons] || reasons.hold
  const reason = randomChoice(reasonList)
  return `${reason}（置信度：${(confidence * 100).toFixed(1)}%）`
}

