      // 验证 query 总共被调用 6 次（2次调用 × 3张表）
      expect(mockQuery).toHaveBeenCalledTimes(6)
      expect(mockRunFullIndustryAnalysisEnhanced).toHaveBeenCalledTimes(2)
      expect(mockGenerateRotationSignals).toHaveBeenCalledTimes(2)
    })
