    await usePositionPoolStore.getState().refresh()

    const { items } = usePositionPoolStore.getState()
    expect(items).toHaveLength(1)
    expect(items[0]!.symbol).toBe('600519')
    expect(items[0]!.pool).toBe('position')
  })
})

